#define M 1000000000
#define N 200005  //check the limits, man
int ar[4*N];
int step[N];
void pull(int p)
{
    ar[p]=min(ar[2*p],ar[2*p+1]);
}
void build(int l,int h,int p)
{
    if(l==h)
    {
        ar[p]=M;
        return ;
    }
    int m=((l+h)>>1);
    build(l,m,2*p);
    build(m+1,h,2*p+1);
    pull(p);
}
int query(int a,int b,int l,int h,int p)
{
    if(a<=l && b>=h)
        return ar[p];
    else if(a>h || b<l)
        return M;
    int m=((l+h)>>1);
    return min(query(a,b,l,m,2*p),query(a,b,m+1,h,2*p+1));
}
void update(int a,int x,int l,int h,int p)
{
    if(a<l || a>h)
        return ;
    if(l==h)
    {
        ar[p]=x;
        return ;
    }
    int m=((l+h)>>1);
    update(a,x,l,m,2*p);
    update(a,x,m+1,h,2*p+1);
    pull(p);
}
