const int N = (int)2e5 + 123;
const int mod = (int)1e9 + 7;
const ll INF = (ll)1e18 + 7;
int n, m;
string a;
int dp[N], par[N];
pii d[N * 4];
pii uu;
pii merge (pii f, pii s) {
	if (f.F != -1 && s.F != -1) {
		if (f.F == s.F) {
			return (s.S < f.S ? s : f);
		}
		else {
			return (f.F > s.F ? s : f);
		}
	}
	else if (f.F != -1) return f;
	else if (s.F != -1) return s;
	else return uu;
}
void build (int v, int l, int r) {
	if (l == r) {
		d[v].F = dp[l];
		d[v].S = l;
		return;
	}
	int mid = l + r >> 1;
	build (v * 2, l, mid);
	build (v * 2 + 1, mid + 1, r);
	d[v] = merge (d[v * 2], d[v * 2 + 1]);
}
pii get (int v, int l, int r, int nl, int nr) {
	if (l > nr || nl > r) return uu;
	if (nl <= l && r <= nr) return d[v];
	int mid = l + r >> 1;
	return merge (get (v * 2, l, mid, nl, nr), get (v * 2 + 1, mid + 1, r, nl, nr));	
}
void update (int v, int l, int r, int pos, int x) {
	if (l == r) {
		d[v].F = x;
		d[v].S = l;
		return;
	}
	int mid = l + r >> 1;
	if (pos <= mid) update (v * 2, l, mid, pos, x);
	else update (v * 2 + 1, mid + 1, r, pos, x);
	d[v] = merge (d[v * 2], d[v * 2 + 1]);
}
void solve () {
	uu.F = -1, uu.S = -1;	
	cin >> n >> m >> a;
	for (int i = 0; i <= n; i ++) dp[i] = -1, par[i] = -1;
