		cout << -1;
		return;
	}
	dp[n] = 0;	
	par[n] = -1;
	build (1, 0, n);
	for (int i = n - 1; i >= 0; i --) {
		if (a[i] == '0') {
			pii o = get (1, 0, n, i + 1, min (n, i + m));
			if (o.F != -1) {
				dp[i] = o.F + 1;
				par[i] = o.S;
				update (1, 0, n, i, dp[i]);
			}
		}
	}
	if (dp[0] == -1) {
		cout << -1;
		return;
	}
	int pos = 0;
	while (par[pos] != -1) {	
		cout << par[pos] - pos << " ";
		pos = par[pos];	
	}
}

