using namespace std;
constexpr int mod=1e9+7;
class SegTree{
private:
    int n;
    vector<int>node;
public:
    SegTree(int n_){
        n=1;
        while(n<n_)
            n*=2;
        node.resize(2*n-1,mod*mod);
        for(int i=0;i<n_;i++)
            node[i+n-1]=0;
        for(int i=n-2;i>=0;i--)
            node[i]=min(node[2*i+1],node[2*i+2]);
    }
    void update(int x,int val){
        x+=n-1;
        node[x]=val;
        while(x>0){
            x=(x-1)/2;
            node[x]=min(node[2*x+1],node[2*x+2]);
        }
    }
    int getmin(int a,int b,int k=0,int l=0,int r=-1){
        if(r<0)
            r=n;
        if(r<=a||b<=l)
            return mod*mod;
        if(a<=l&&r<=b)
            return node[k];
        int vl=getmin(a,b,2*k+1,l,(l+r)/2);
        int vr=getmin(a,b,2*k+2,(l+r)/2,r);
        return min(vl,vr);
    }
};
signed main(){
    int n,m;
