struct SegmentTree{
private:
    int n;
    vector<int> node;

public:
    SegmentTree(vector<int> v){
        int sz = v.size();
        n = 1;
        while(n < sz) n *= 2;
        node.resize(2*n-1,INF);
        for (int i = 0; i < sz; i++) node[i+n-1] = v[i];
        for (int i = n-2; i >= 0; i--) node[i] = min(node[2*i+1],node[2*i+2]);
    }

    void update(int x,int val){
        x += n-1;
        node[x] = val;
        while(x > 0){
            x = (x - 1) / 2;
            node[x] = min(node[2*x+1],node[2*x+2]);
        }
    }

    int getmin(int a, int b, int k=0, int l=0, int r=-1){
        if (r < 0) r = n;
        if(r <= a || b <= l) return INF;
        if(a <= l && r <= b) return node[k];
        int vl = getmin(a, b, 2*k+1, l , (l+r)/2);
        int vr = getmin(a, b, 2*k+2, (l+r)/2,r);
        return min(vl, vr);
    }
};



int main(){
    int n,m;cin >> n >> m;
    string s;cin >> s;
    vector<int> x(n+2,-1);
    int l = 0;
    SegmentTree seg(vector<int> (n+2,INF));
    seg.update(0,0);
    for (int i = 1; i <= n; i++) {
        if(s[i]=='1') continue;
        int t = seg.getmin(max(l,max(0,i-m)),i);
        if(t==INF) continue;
        while(seg.getmin(l,l+1)!=t) l++;
        seg.update(i,t+1);
        x[i] = l;
    }
    if(seg.getmin(n,n+1) >= INF){
        cout << -1 << endl;
        return 0;
    }
    vector<int> ans;
    int t = n,now=n;
    while(now != 0){
        t = x[now];
        ans.pb(now-t);
        now = t;
    }
    reverse(ALL(ans));
    for (int i = 0; i < ans.size(); i++) {
        cout << ans[i] << (i+1==ans.size()?"\n":" ");
    }
    return 0;
}

