// [b, ..., e] must be a shuffle of [0, 1, ..., len - 1] (len = e - b)
template <class RanIt>
std::vector<std::vector<typename std::iterator_traits<RanIt>::value_type>> to_cycles(RanIt b, RanIt e)
{
	using T = typename std::iterator_traits<RanIt>::value_type;
	std::vector<std::vector<T>> cycs;
	T len = e - b;
	std::vector<bool> done(len, false);
	for (T i = 0; i < len; ++i)
	{
		if (done[i]) continue;
		std::vector<T> cyc;
		cyc.push_back(i);
		auto j = b[i];
		while (j != i)
		{
			cyc.push_back(j);
			done[j] = true;
			j = b[j];
		}
		cycs.push_back(std::move(cyc));
	}
	return cycs;
}

template <class T>
auto to_cycles(const T& v)
{
	return to_cycles(std::begin(v), std::end(v));
}

template <class T, size_t n>
double norm(const std::array<T, n>& p)
{
	auto s = 0.0;
	for (int i = 0; i < n; ++i) s += double(p[i]) * p[i];
	return std::sqrt(s);
}
template <class T, size_t n>
double dist(const std::array<T, n>& p, const std::array<T, n>& q)
{
	std::array<T, n> d;
	for (int i = 0; i < n; ++i) d[i] = p[i] - q[i];
	return norm(d);
}

int64_t gcd(int64_t n, int64_t m)
{
	while (m > 0)
	{
		auto t = n % m;
		n = m;
		m = t;
	}
	return n;
}

std::array<int64_t, 2> solve_linear(int64_t n, int64_t m)
{
	auto A = std::array<std::array<int64_t, 2>, 2>{std::array<int64_t, 2>{n < 0 ? -1 : 1, 0}, std::array<int64_t, 2>{0, m < 0 ? -1 : 1}};
	n = std::abs(n);
	m = std::abs(m);
	while (m > 0)
	{
		auto q = n / m, r = n % m;
		n = m;
		m = r;
		for (int i = 0; i < 2; ++i)
		{
			auto x = A[i][1];
			A[i][1] = A[i][0] - q * x;
			A[i][0] = x;
		}
	}
	return std::array<int64_t, 2>{A[0][0], A[1][0]};
}

int64_t mod(int64_t a, int64_t mod) { return (a % mod + mod) % mod; }

int64_t inverse(int64_t a, int64_t M) { return mod(solve_linear(mod(a, M), M)[0], M); }

int64_t pow(int64_t a, int64_t p, int64_t mod)
{
	int64_t y = 1L;
	int64_t x = a;
	while (p > 0)
	{
		if ((p & 1) == 1) y = (y * x) % mod;
		p >>= 1;
		x = (x * x) % mod;
	}
	return y;
}

void calc(int N, int M, std::string S)
{
	using std::cout;
	using std::endl;
	using std::string;
	using std::vector;
	constexpr int INF = MOD;
	vector<int> d(N + 1, INF);
	d[N] = 0;
	std::multiset<int> s{0};
	for (int i = N - 1; i >= 0; --i)
	{
		d[i] = S[i] == '1' ? INF : 1 + *s.begin();
		if (i + M <= N) s.erase(s.find(d[i + M]));
		s.insert(d[i]);
	}
	if (d[0] >= INF)
	{
		cout << -1 << endl;
		return;
	}
	vector<vector<int>> ds(d[0] + 1);
	for (int i = 0; i <= N; ++i)
		if (d[i] < INF) ds[d[i]].push_back(i);
	vector<int> step;
	int cur = 0;
	while (cur < N)
		for (const auto& p : ds[d[cur] - 1])
			if (cur < p)
			{
				step.push_back(p - cur);
				cur = p;
				break;
			}
	cout << step << endl;
}

