#include "bits/stdc++.h"
using namespace std;
typedef long long ll;
typedef pair<ll, ll> P;
const ll MOD = 1e9 + 7;
class BiOp {
public:
	P operator()(P a, P b) const {
		return min(a, b);
	}
};

template<typename T, typename BiOp>
struct SegmentTree {
	vector<T> data;
	T e;
	BiOp op;
	int size;

	SegmentTree(int n, T e, BiOp op) : e(e), op(op) {
		size = 1;
		while (size < n) size *= 2;
		data.resize(2 * size - 1);
		for (int i = 0; i < 2 * size - 1; i++) data[i] = e;
	}

	void update(int k, T v) {
		k += size - 1;
		data[k] = v;
		while (k > 0) {
			k = (k - 1) / 2;
			data[k] = op(data[k * 2 + 1], data[k * 2 + 2]);
		}
	}

	T query(int a, int b, int k, int l, int r) const {
		if (b <= l || r <= a) return e;
		if (a <= l && r <= b) return data[k];
		return op(query(a, b, k * 2 + 1, l, (l + r) / 2), query(a, b, k * 2 + 2, (l + r) / 2, r));
	}

	T query(int a, int b) {
		return query(a, b, 0, 0, size);
	}

	T get(int i) {
		return data[i + size - 1];
	}
};
int main() {
	int N, M;
	cin >> N >> M;
	string S;
	cin >> S;
	SegmentTree<P, BiOp> seg(N + 1, P(1 << 30, -1), BiOp());
	seg.update(N, P(0, N));
	for (int i = N - 1; i >= 0; i--) {
		if (S[i] == '1') continue;
		P e = seg.query(i + 1, min(i + M, N) + 1);
		seg.update(i, P(min(e.first + 1, 1LL << 30), i));
	}
	P e = seg.get(0);
	if (e.first == (1 << 30)) {
		cout << -1 << endl;
		return 0;
	}
	int pos = 0;
	while (pos < N) {
		P e = seg.query(pos + 1, min(pos + M, N) + 1);
		cout << e.second - pos << " ";
		pos = e.second;
	}
	cout << endl;
}

