using ii = pair<int, int>;

int main(){
	ios::sync_with_stdio(0);
	int n, m;
	cin >> n >> m;
	string st;
	cin >> st;
	vector<int> prev(n+1, 0);
	vector<int> post(n+1, 0);

	for(int i=0; i<=n; ++i){
		if(st[i]=='0') prev[i] = i;
		else prev[i] = prev[i-1];
	}
	for(int i=n; i>=0; --i){
		if(st[i]=='0') post[i] = i;
		else post[i] = post[i+1];
	}
	vector<int> path;
	int pos = 0;
	while(pos<n){
		path.push_back(pos);
		if(n-pos<=m){
			path.push_back(n);
			break;
		}
		int k = prev[pos+m];
		if(k==pos){
			cout << -1 << endl;
			return 0;
		}
		pos = k;
	}
	priority_queue<ii> pq;
	for(int i=1; i<len(path)-1; ++i)
		pq.push(ii(-(path[i+1]-path[i]), i));

	while(not pq.empty()){
		int i = pq.top().ss; 
		int dr = path[i+1]-path[i];
		pq.pop();
		int d = m-dr;
		int k = post[max(0, path[i]-d)];
		if(path[i]!=k){
			path[i] = k;
			pq.push(ii(-(path[i+1]-path[i]), i));
		}
	}
	for(int i=1; i<len(path); ++i)
		cout << path[i]-path[i-1] << " ";
	cout << endl;
}

