int leftbit(int L, int R) {
	if (bit.sum(R) - bit.sum(L) == 0)return inf;
	int LD = L;
	R++;
//	cout << L << ' ' << R << endl;
	while (R - L > 1) {
		int mi = (R + L) / 2;
		if (bit.sum(mi) - bit.sum(LD))R = mi;
		else L = mi;
	}
	return L;
}

