    int ans = n+1;
    for(int i = max(0, v-m);i!=v;i++){
      int tmp = solve(i);
      if(tmp != -1 && tmp + 1 < ans){
        ans = tmp + 1;
        prev[v] = i;
      }
    }
    return t[v] = (ans == n+1 ? -1 : ans);
  };
  int f = solve(n);
  if(f != -1){
    vector<int> ret;
    while(n){
      ret.emplace_back(n - prev[n]);
      n = prev[n];
    }
    reverse(ret.begin(), ret.end());
    for(auto&& x:ret)cout << x << " ";
    cout << endl;
  }else cout << -1 << endl;
  return 0;
}

