	//~ ios::sync_with_stdio(0);
	//~ cin.tie(0);
	int n, m;
	scanf("%d%d", &n, &m);
	scanf("%s", s);

	for (int i = 1; i <= n; i++) dp[i] = {INF, INF};
	for (int i = 1; i <= n; i++) {
		if (s[i] == '1')
			dp[i] = {INF, -1};
		else if (i <= m)
			dp[i] = {1, 0};
		else {
			dp[i] = query(1, 1, n, i - m, i - 1);
			if (dp[i].first < INF) ++dp[i].first;
		}
		update(1, 1, n, i, dp[i]);
	}

	if (dp[n].first == INF) {
		puts("-1");
		return 0;
	}

	vi ans;
	for (int x = n; x != 0; x = dp[x].second) {
		ans.push_back(x - dp[x].second);
	}
	for (int i = ans.size() - 1; i >= 0; i--) printf("%d ", ans[i]);
	puts("");
}

