    seg.update_query(n, 0);
    for (int i = n - 1; i >= 0; i--) {
        if (s[i] == '1') continue;
        int t = seg.get_query(i + 1, min(n + 1, i + m + 1));
        if (t == INF) break;
        seg.update_query(i, t + 1);
    }
