int main()
{
  int n, m;
  cin >> n >> m;
  string is_game_over;
  cin >> is_game_over;
  if (is_game_over.back() == '1') {
    cout << "-1\n";
    return 0;
  }
  is_game_over.pop_back();
  vector<pair<int, int>> step(n+1, pair<int, int>(0, 0));
  step.back().first = n;
  queue<int> idx;
  idx.push(n);
  for (int i = 0; i < n; i++) {
    if (idx.empty()) {
      break;
    }
    if (idx.front() == n-i+m) {
      idx.pop();
    }
    if (is_game_over.at(n-i-1) == '0') {
      int id = idx.front();
      step.at(n-1-i).first = id;
      step.at(n-1-i).second = step.at(id).second + 1;
      idx.push(n-1-i);
    }
  }
  if (step.front().first == 0) {
    cout << "-1\n";
    return 0;
  }
  print_vec(step);
  int i = 0;
  vector<int> res;
  int cost = 0;
  while (i < n) {
    int cost = step.at(i).second;
    int s = step.at(i).first;
    for (int j = i+1; j < s; j++) {
      if (step.at(j).second == cost - 1) {
        i = j;
        res.push_back(j - i);
        break;
      }
    }
  }
  cout << res.front();
  for (int id = 1; id < (int)res.size(); id++) {
    cout << ' ' << res.at(id);
  }
  cout << '\n';
  return 0;
}

