        NV = 1;
        while (NV < N) NV = NV << 1;
        dat.resize(NV*2 -1);
        //cout << "sg init: NV = " << NV << endl; 
        for (int i = 0; i < NV; i++) {
          dat[i+NV-1] = make_pair(INV, i);
        }
        for (int i = NV - 2; i >=0; i--) {
          dat[i] = min(dat[i*2+1], dat[i*2+2]);
        }
      }

      void update(int idx, int val) {
        //cout << "update called: " << idx << "," << val << endl;
        if (idx < 0) return;
        idx += NV - 1;
        dat[idx] = make_pair(val, idx - NV + 1);
        //cout << idx << ":" << dat[idx].first << "," << dat[idx].second << endl;
