int N, M;
string S;

string solve(){
    int index = N, next = 0;
    string ret;
    while(index > 0){
        next = max(0, index - M);
        while(S[next] == '1') next++;
        if(index == next) break;
        ret = ret + to_string(index - next) + " ";
        index = next;
    }
    if(index != 0) return "-1";
    ret.pop_back();
    reverse(ALL(ret));
    return ret;
}

string bfs(){
    queue<pair<int, string>> que;
    que.push(pair<int, string>(0, ""));
    int depth = 0;
    while(!que.empty()){
        int i = que.front().first;
        string h = que.front().second;
        que.pop();
        if(i > N || S[i] == '1') continue;
        if(i == N){
            h.pop_back();
            return h;
        }
        FOR(j, 1, M + 1){
            que.push(pair<int, string>(i + j, h + to_string(j) + " "));
        }
    }
    return "-1";
}


