int N,M;
string S;

const int Inf=1e8;
void solve() {
  VI A(N+1,Inf);
  REPE(i,N) A[i]=S[i]=='1'?Inf:i;
  RMQ<int> rmq(A,Inf);
  VI res;
  int i=N;
  while(i>0) {
    int ii=rmq.query(max(0,i-M), i);
    if(ii==Inf) {
      cout<<-1<<endl;
      return;
    }
//    dump(ii,A[ii],i-ii);
    res.push_back(i-ii);
    i=ii;
  }
  assert(i==0);
  reverse(ALL(res));
  REP(i,SZ(res)) printf("%d%c",res[i]," \n"[i==SZ(res)-1]);
}

