		//cout << mn << " ";
		if(dp[mn]==(1LL<<50)) continue;
		dp[i]=dp[mn]+1;
		seg.update(i,dp[i]);
		nex[i]=mn;
		//cout << i << " " << dp[i] << "\n";
	}
	if(dp[0]>=(1LL<<40)){
		cout << -1 << "\n";
		return 0;
	}

	int cur=0;
