#include<bits/stdc++.h>
#define inf 0x3f3f3f3f
using namespace std;
const int N=1e5+5;
int n,m,xx,yy,bk[N],t[N<<2];
char s[N];
void fix(int l,int r,int k,int x,int v)
{
    if(l==r)
    {
        t[k]=v;return;
    }
    int m=l+r>>1;
    if(x<=m) fix(l,m,k<<1,x,v);
    else fix(m+1,r,k<<1|1,x,v);
    t[k]=min(t[k<<1],t[k<<1|1]);
}
void query(int l,int r,int k,int x,int y)
{
    if(r<x||l>y||t[k]>=xx) return;
    if(l==r)
    {
        xx=t[k];yy=l;return;
    }
    int m=l+r>>1;
    query(l,m,k<<1,x,y);
    query(m+1,r,k<<1|1,x,y);
}
int main()
{
    memset(t,inf,sizeof(t));
    scanf("%d%d",&n,&m);
    scanf("%s",s);
    fix(1,n,1,n,0);
    for(int i=n-1;i>=0;i--)
    {
        if(s[i]=='1') continue;
        xx=inf;yy=-1;
        query(1,n,1,i+1,min(n,i+m));
        if(xx!=inf)
        {
            bk[i]=yy;
            fix(1,n,1,i,xx+1);
        }
    }
    if(!bk[0]) printf("-1\n");
    else
    {
        queue<int>q;
        int now=0;
        while(now!=n)
        {
            q.push(bk[now]-now);
            now=bk[now];
        }
        while(!q.empty())
        {
            printf("%d",q.front());q.pop();
            if(q.empty()) printf("\n");
            else printf(" ");
        }
    }
}

