// 0-indexed bottom up Segment Tree
// UNIT is the identity element of operation func
template <typename T = int>
struct SegmentTree {
    using F = function<T(T, T)>;
    int n;
    vector<T> dat;
    F func;
    T UNIT;

    SegmentTree(int n_, F func_, T UNIT_) : func(func_), UNIT(UNIT_) {
        n = 1;
        // full binary tree: num of leaves = n = 2^k >= n_
        while (n < n_)
            n *= 2;
        dat.assign(2 * n - 1, UNIT);
    }
    SegmentTree(vector<T> v_, F func_, T UNIT_) : func(func_), UNIT(UNIT_) {
        n = 1;
        while (n < v_.size())
            n *= 2;
        dat.assign(2 * n - 1, UNIT);
        for (int i = 0; i < v_.size(); ++i) {
            dat[n - 1 + i] = v_[i];
        }
        for (int i = n - 2; i >= 0; --i) {
            dat[i] = func(dat[2 * i + 1], dat[2 * i + 2]);
        }
    }
    void update(int k, T a) {
        // leaves are at index n-1 to 2*n-2
        k += n - 1;
        dat[k] = a;
        while (k > 0) {
            // k -> parent node
            k = (k - 1) / 2;
            // func(child nodes)
            dat[k] = func(dat[2 * k + 1], dat[2 * k + 2]);
        }
    }
    // get result of func() in [l, r)
    T query(int l, int r) {
        l += n - 1;
        r += n - 1;
        T ret = UNIT;
        while (l < r) {
            if ((l & 1) == 0)
                ret = func(ret, dat[l]);
            if ((r & 1) == 0)
                ret = func(ret, dat[r - 1]);
            l = l / 2;
            r = (r - 1) / 2;
        }
        return ret;
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n, m;
    cin >> n >> m;
    string s;
    cin >> s;
    auto f = [](ll l, ll r) { return min(l, r); };
    SegmentTree<ll> st(n + 1, f, INF);
    st.update(n, 0);
    for (int i = n - 1; i >= 0; --i) {
        if (s[i] == '1')
            continue;
        ll mini = st.query(i, min(i + m + 1, n + 1));
        st.update(i, mini + 1);
    }
    if (st.query(0, 1) > n) {
        cout << -1 << "\n";
        return 0;
    }
    ll curr     = 0;
    ll currstep = st.query(0, 1);
    ll num      = (st.dat.size() + 1) / 2 - 1;
    while (curr < n) {
        for (int i = 1; i <= m; ++i) {
            // ll nxt = st.query(curr + i, curr + i + 1);
            ll nxt = st.dat[curr + i + num];
            if (nxt == currstep - 1) {
                cout << i << " ";
                curr = curr + i;
                currstep--;
                break;
            }
        }
    }
