const static int N = 100005;
string Dice[N];
int Prev[N];
bool GameOver[N];

int n, m;

void Calc() {
    for (int i = n; i > 0; --i) {
        if (GameOver[i]) continue;
        for(int j = 1; j <= m; ++j) {
            if (i - j < 0) continue;
            string word = to_string(j) + Dice[i];
            if (Dice[i - j].empty()) {
                Dice[i - j] = word;
                Prev[i - j] = i;
                continue;
            }
            if (Dice[i - j].size() == word.size()) {
                if (Dice[i - j] > word) {
                    Dice[i - j] = word;
                    Prev[i - j] = i;
                }
                continue;
            }
            if (Dice[i - j].size() < word.size()) {
                continue;
            } else {
                Dice[i - j] = word;
                Prev[i - j] = i;
            }
        }
    }
