const int INF = 1e9;

struct SegmentTree {
  int n;
  vector<int> dat;

  void init(int n_) {
    n = 1;
    while (n < n_)
      n *= 2;
    dat.resize(2 * n - 1, INF);
  }

  void update(int k, int a) {
    k += n - 1;
    dat[k] = a;
    while (k > 0) {
      k = (k - 1) / 2;
      dat[k] = min(dat[2 * k + 1], dat[2 * k + 2]);
    }
  }

  int query(int a, int b, int k = 0, int l = 0, int r = -1) {
    if (r < 0)
      r = n;
    if (r <= a || b <= l)
      return INF;
    if (a <= l && r <= b)
      return dat[k];

    int vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
    int vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
    return min(vl, vr);
  }
};

signed main() {
  int N, M;
  string S;
  cin >> N >> M >> S;

  SegmentTree dp;
  dp.init(N + 1);
  dp.update(0, 0);

  for (int i = 1; i <= N; i++) {
    if (S[i] == '0') {
      int update = dp.query(max(0, i - M), i) + 1;
      dp.update(i, update);
    }
  }

  if (dp.query(N, N + 1) == INF) {
    cout << -1 << endl;
    return 0;
  }

  vector<int> ans;
  int pos = 0;
  while (pos < N) {
    for (int i = 1; i <= M; i++) {
      if (pos + i > N) {
        continue;
      }
      if (S[pos + i] == '1') {
        continue;
      }
      if (dp.query(pos + i, pos + i + 1) == dp.query(pos, pos + 1)) {
        continue;
      }
      if (dp.query(pos + i, pos + i + 1) == dp.query(N, N + 1) &&
          pos + i != N) {
        continue;
      }

      ans.push_back(i);
      pos += i;
      break;
    }
  }

  for (int i = 0; i < ans.size(); i++) {
    if (i != 0) {
      cout << " ";
    }
    cout << ans[i];
  }
