// DPと二分探索？
void solve() {
    int n,m; cin >> n >> m;
    string s; cin >> s;

    vector<int> canMoveHenkan; //
    vector<int> canMove;
    // int allGameoverCnt = count(s.begin(), s.end(), '1');
    {
        int cnt = 0;
        rep(i,min(m+1,n+1)) {
            if (s[i] == '1') cnt ++;
            else {
                canMove.push_back(i-cnt);
                canMoveHenkan.push_back(i);
            }
            // gameoverCnt[i] = cnt;
        }
        for (int i=m+1; i<n+1; i++) {
            if (s[i-m-1] == '1') cnt --;
            if (s[i] == '1') cnt ++;
            else {
                int s = canMove.size();
                canMove.push_back( min(m-cnt, s-1) );
                canMoveHenkan.push_back(i);
            }
            // gameoverCnt[i] = cnt;
        }
    }
    //rep(i,canMove.size()) {
    //    cout << canMove[i] << ' ';
    //}
    if (find(canMove.begin()+1,canMove.end(), 0) != canMove.end()) {
        cout << -1 << endl;
        return;
    }

    // 手数が最小になるかつ一番近いマスを前のマスとする？
    // pair<手数,前のマス>
    pair<int,int> dp[100001];
    rep(i,n+1) {
        dp[i].first = -1;
        dp[i].second = -1;
    }
    dp[0].first = 0;
    dp[0].second = -1;
    for (int i=1; i<canMove.size(); i++) {
        int minimumTekazu = dp[i-canMove[i]].first;
        dp[i].first = minimumTekazu+1;
        int lo = i-canMove[i]-1;
        int hi = i-min(1, canMove[i]);
        while (hi - lo > 1) {
            int mid = (hi+lo)/2;
            if (dp[mid].first == minimumTekazu) hi = mid;
            else lo = mid;
        }
        dp[i].second = hi;
    }
    vector<int> route;
    route.push_back(canMove.size()-1);
    for (int i = canMove.size()-1; i > 0;) {
        route.push_back( dp[i].second );
        i = dp[i].second;
    }
    reverse(route.begin(),route.end());
    rep(i,route.size()-2) {
        cout << canMoveHenkan[route[i+1]] - canMoveHenkan[route[i]] << ' ';
    }
    cout << canMoveHenkan[route[route.size()-1]] - canMoveHenkan[route[route.size()-2]] << endl;


}

int main() {
    solve();
}

