int main() {
    int n, m;
    in(n, m);
    n++;

    string s;
    in(s);

    const int inf = 1 << 28;
    vector<int> left(n);

    int l = 0;

    for (int i = 0; i < n; i++) {
        if (s[i] == '0') {
            l = i;
        }

        left[i] = l;
    }

    vector<int> dp(n, inf);

    dp[n - 1] = 0;

    for (int i = n - 2; i >= 0; i--) {
        if (s[i] == '1') {
            continue;
        }

        if (i + m >= n - 1) {
            dp[i] = 1;
        } else if (left[i + m] != i && dp[left[i + m]] != inf) {
            dp[i] = dp[left[i + m]] + 1; 
        }
    }

    if (dp[0] == inf) {
        out(-1);
        return 0;
    }

    set<int> t;
    vector<int> p;

    for (int i = 0; i < n; i++) {
        if (dp[i] != inf && t.count(dp[i]) == 0) {
            t.insert(dp[i]);
            p.push_back(i);
        }
    }

    vector<int> ans;

    for (int i = 1; i < p.size(); i++) {
        ans.push_back(p[i] - p[i - 1]);
    }

    vout(ans, ans.size());
}

