void solve() {
    int n,m;
    string s;
    cin >> n >> m >> s;
    VI pr(n+1);
    REP(i,1,n+1) {
        if (s[i] == '1') pr[i] = pr[i-1];
        else pr[i] = i;
    }
    int index = 0;
    VI path;
    while (index != n) {
        //dump(index);
        int c = min(n, index + m);
        int next = pr[c];
        if (next == index) {
            cout << -1 << endl;
            return;
        }
        path.push_back(next - index);
        index = next;
    }
    for (auto p: path) cout << p << " ";
    cout << endl;
}

