void build(ll l,ll r,ll in,string &s,vector<ll> &tree)
{
    if(l>r)
    {
        return;
    }
    else if(l==r)
    {
        if(s[l]=='0')
        {
            tree[in]=l;
        }
        return ;
    }
    ll mid = (l+r)>>1;
    build(l,mid,2*in+1,s,tree);
    build(mid+1,r,2*in+2,s,tree);
    tree[in] = max(tree[2*in+1],tree[2*in+2]);
    return;
}
ll query(ll l,ll r,ll ql,ll qr,ll in,vector<ll> &tree)
{
    if(r<l)
    {
        return -1;
    }
    if(r<ql || l>qr)
    {
        return -1;
    }
    else if(l>=ql && r<=qr)
    {
        return tree[in];
    }
    ll mid = (l+r)>>1;
    ll ans1 = query(l,mid,ql,qr,2*in+1,tree);
    ll ans2 = query(mid+1,r,ql,qr,2*in+2,tree);
    return max(ans1,ans2);
}
