struct SegT {
private:
	int sz; vector<P> node;
	const P init_c = { mod,0 };
public:
	SegT(int n) {
		sz = 1;
		while (sz < n)sz *= 2;
		node.resize(2 * sz - 1, init_c);
		rep(i, n) {
			node[i + sz - 1].second = i;
		}
	}
	P f(P a, P b) {
		if (a.first < b.first) {
			return a;
		}
		else if (a.first > b.first) {
			return b;
		}
		else {
			if (a.second < b.second) {
				return a;
			}
			else return b;
		}
	}
	void update(int k, int a) {
		k += sz - 1;
		node[k] = { a,k - (sz - 1) };
		while (k > 0) {
			k = (k - 1) / 2;
			node[k] = f(node[k * 2 + 1], node[k * 2 + 2]);
		}
	}
	P query(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0)r = sz;
		if (r <= a || b <= l)return init_c;
		else if (a <= l && r <= b)return node[k];
		else {
			P vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
			P vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
			return f(vl, vr);
		}
	}
};

void solve() {
	int n, m; cin >> n >> m;
	string s; cin >> s;
	vector<int> pre(n + 1);
	SegT st(n + 1);
	st.update(0,0);
	rep1(i, n) {
		if (s[i] == '1')continue;
		P p = st.query(max(0,i - m), i);
		st.update(i, p.first + 1);
		pre[i] = p.second;
	}
	P z = st.query(n, n + 1);
	if (z.first >= mod / 2) {
		cout << -1 << endl;
	}
	else {
		vector<int> ids;
		int cur = n;
		while (cur>0) {
			ids.push_back(cur);
			cur = pre[cur];
		}
		ids.push_back(0);
		reverse(ids.begin(), ids.end());
		vector<int> ans;
		rep(i, (int)ids.size() - 1) {
			int dif = ids[i + 1] - ids[i];
			ans.push_back(dif);
		}
		rep(i, ans.size()) {
			if (i > 0)cout << " ";
			cout << ans[i];
		}
		cout << endl;
	}
}

