using namespace std;

template<class Monoid> struct SegmentTree {
    using Function = function< Monoid(Monoid, Monoid) >;

    int N; vector<Monoid> segment;
    const Function func;
    const Monoid id;

    SegmentTree(int n, const Function func, const Monoid id) : func(func), id(id) {
        N = 1;
        while (N < n) N <<= 1;
        segment.assign(2 * N, id);
    }

    void set(int num, Monoid x) {
        segment[N + num] = x;
    }
    void build() {
        for (int k = N - 1; k > 0; k--) {
            segment[k] = func(segment[2*k], segment[2*k+1]);
        }
    }
    void update(int k, Monoid x) {
        k = k + N; segment[k] = x;
        while(k >>= 1) {
            segment[k] = func(segment[2*k], segment[2*k+1]);
        }
    }

    // query:[a, b)
    Monoid query(int a, int b) {
        Monoid L = id; Monoid R = id; a += N; b += N;
        for (; a < b; a >>= 1, b >>= 1) {
            if (a & 1) L = func(L, segment[a++]);
            if (b & 1) R = func(segment[--b], R);
        }
        return func(L, R);
    }
    // 0-based numbering;
    Monoid operator[](const int k) const {
        return segment[N+k];
    }
};


int main(){
    int n, m; cin >> n >> m;
    string s; cin >> s;
    SegmentTree<int> stmin(n+1, [](int a, int b){return min(a, b);}, 1e8);
    stmin.update(n, 0);
    for (int i = n-1; i >= 0; i--) {
        if (s[i] == '1') continue;
        stmin.update(i, stmin.query(i+1, min(n+1, i+m+1))+1);
    }
    if (stmin[0] >= 1e8) cout << -1 << endl;
    else {
        vector<int> ans(stmin[0], -1);
        int curr = stmin[0]; int iprev = 0;
        for (int i = 1; i <= n; i++) {
            if (stmin[i] == curr-1) {
                ans[stmin[0]-curr] = i-iprev;
                curr--;
                iprev = i;
            }
        }
        for (int i = 0; i < stmin[0]; i++) {
            if (i) cout << " ";
