template<class T>
struct SWAG {
  using FX = function<T(T, T)>;
  stack<pair<T, T>> frst, bcst;
  FX fx;
  const T ex;
  SWAG(FX fx_, T ex_):fx(fx_), ex(ex_) {}
  void push(T x) {
    bcst.emplace(x, fx(x, (bcst.empty()?ex:bcst.top().second)));
  }
  void pop() {
    if(frst.empty()) {
      while(!bcst.empty()) {
        frst.emplace(bcst.first, fx(bcst.first, (frst.empty()?ex:frst.top().second)));
        bcst.pop();
      }
    }
    else frst.pop();
  }
  T clac() {
    return fx(frst.empty()?ex:frst.top().second, bcst.empty()?ex:bcst.top().second);
  }
};

