    for(int i = 1; i <= M; i++){
        dp[N - i] = 1;
    }
    int last_not_updated = N - M + 1;
    for(int i = N; i >= 0; i--){
        if(S[i] != '1' && dp[i] != INT_MAX && last_not_updated >= 0){
            if(i - M >= 0){
                for(int j = last_not_updated; j >= i - M; j--){
                    dp[j] = dp[i] + 1;
                }
            }  else {
                for(int j = last_not_updated; j >= 0; j--){
                    dp[j] = dp[i] + 1;
                }
            }
