typedef long long ll;

struct SegmentTree {
  int n;
  vector<int> data;
  SegmentTree(int size) {
    n = 1;
    while (n < size) n*=2;
    data.resize(2*n-1, INT_MAX);
  }
  // （0-indexed）k番目 を aに更新
  void update(int k, int a) {
    k += n - 1;
    data[k] = a;
    while(k>0){
      k = (k - 1) / 2;
      data[k] = min(data[k*2+1], data[k*2+2]);
    }
  }
  // [a, b)の最小値を求める
  int query(int a, int b) {
    return _query(a, b, 0, 0, n);
  }
  int _query(int a, int b, int k, int l, int r) {
    // [a, b) と [l, r)が交わらない
    if (r<= a || b <= l) return INT_MAX;
    // [a, b)が[l, r)を含んでいるので節点の値
    if (a <= l && r <= b) return data[k];
    int vl = _query(a, b, k * 2 + 1, l, (l + r) / 2);
    int vr = _query(a, b, k * 2 + 2, (l + r) / 2, r);
    return min(vl, vr);
  }
};

