#include <bits/stdc++.h>
using namespace std;
const int INF = INT_MAX/2;

template<class T> struct QueueAggregation {
    using F = function<T(T, T)>;
private :
    struct node {
        T val, sum;
        node (const T &v, const T &s) : val(v), sum(s) { }
    };
    F op;
    stack<node> front_stack, back_stack;
public :
    QueueAggregation (const F &op) : op(op), front_stack(), back_stack() { }

    bool empty() const { return front_stack.empty() && back_stack.empty(); }

    size_t size() const { return front_stack.size() + back_stack.size(); }

    T fold_all() const {
        assert(!empty());
        if (front_stack.empty()) {
            return back_stack.top().sum;
        } else if (back_stack.empty()) {
            return front_stack.top().sum;
        } else {
            return op(front_stack.top().sum, back_stack.top().sum);
        }
    }

    void push(const T &x) {
        if (back_stack.empty()) {
            back_stack.emplace(x, x);
        } else {
            T s{op(back_stack.top().sum, x)};
            back_stack.emplace(x, s);
        }
    }

    void pop() {
        assert(!empty());
        if (front_stack.empty()) {
            front_stack.emplace(back_stack.top().val, back_stack.top().val);
            back_stack.pop();
            while (!back_stack.empty()) {
                T s{op(back_stack.top().val, front_stack.top().sum)};
                front_stack.emplace(back_stack.top().val, s);
                back_stack.pop();
            }
        }
        front_stack.pop();
    }

};

int main() {
    int n, m;
    string s;
    cin >> n >> m >> s;

    struct node { int step, idx; };
    auto f = [](const node& l, const node& r) { return l.step < r.step ? l : r; };
    QueueAggregation<node> swag(f);
    swag.push({0, n});
    vector<int> next(n+1);
    int ans, p = 0;

    for (int i = n-1; i >= 0; i--) {
        if (swag.size() > m) swag.pop();
        const node t = swag.fold_all();
        next[i] = t.idx;
        if (i == 0) ans = t.step + 1;
        if (s[i] == '0') swag.push({t.step + 1, i});
        else swag.push({INF, i});
    }

    if (ans >= INF) { cout << -1 << "\n"; return 0; }
    while (p != n) {
        cout << next[p] - p << " ";
        p = next[p];
    }
    return 0;
}

