void dfs(vector<vector<pair<int, int>>> &graph, vector<int> &ans, int v, int c = -1, int p = -1)
{
	int k = 1;
	for (int i = 0; i < graph[v].size(); i++)
	{
		int nxt = graph[v][i].first;
		int ei = graph[v][i].second;
		if (nxt == p) continue;
		if (k == c)
			k++;
		ans[ei] = k;
		dfs(graph, ans, nxt, k, v);
		k++;
	}
}

