int main(int argc, char **argv)
{
    io_init();

    // Actual program code starts here.
    int N, M;
    string S;
    cin >> N >> M >> S;
    VEC(int) SafeSquares;
    FOR(i, 0, N + 1)
        if (S[i] == '0')
            SafeSquares.push_back(i);

    const int _Infinity = 1 << 20;
    VEC(int) Turns(N + 1, _Infinity);
    VEC(int) Next(N + 1, -1);
    Turns[N] = 0;

    FORD(i, N - 1, -1) {
        int a = i + 1, b = min(i + M, N);
        int upper = upper_bound(ALL(SafeSquares), b) - BEGIN(SafeSquares);
        int lower = lower_bound(ALL(SafeSquares), a) - BEGIN(SafeSquares);
        if (upper == lower) {
            // No safe squares reachable from here.
            continue;
        }

        // [lower - upper)
        int farthest = SafeSquares[--upper];
        Turns[i] = min(Turns[i], 1 + Turns[farthest]);
        Next[i] = farthest;
    }

    int i = 0, t = Turns[0];
    if (t >= _Infinity) {
        cout << -1 << endl;
        return 0;
    }

    VEC(int) SafeSquareDist;
    for (int square : SafeSquares)
        SafeSquareDist.push_back(Turns[square]);

    while (i < N) {
        int a = i + 1, b = min(i + M, N);
        int upper = upper_bound(ALL(SafeSquares), b) - BEGIN(SafeSquares);
        int lower = lower_bound(ALL(SafeSquares), a) - BEGIN(SafeSquares);

        // Always upper > lower.
        int j = lower;
        for (;j < upper && SafeSquareDist[j] > t - 1;j += 100);
        // j >= upper or SSD[j] <= t - 1
        if (j >= upper)
            j = upper - 1;
        while (j > lower && SafeSquareDist[j] == SafeSquareDist[j - 1])
            j--;
        cout << SafeSquares[j] - i << " ";
        i = SafeSquares[j];
        t--;
    }
    cout << endl;

    return 0;
};

