    vector<int> dp(n + 1);
    vector<int> available;
    // init
    if (s[0] != '0') {
        cout << -1 << endl;
        return 0;
    }
    for (int i = 0; i <= n; i++) {
        // -1: game over, 0: no problem
        dp[i] = (int) (s[i] - '0');
        dp[i] = - dp[i];
        if (dp[i] == 0) {
            available.push_back(i);
        }
    }

    for (int i = 1; i <= n; i++) {
        if (dp[i] == -1) {
            continue;
        }
        // find dp[i] is min, and index is max; from [max(0, i - M), i - 1]
        int index = max(i - m, 0);
        if (dp[index] != -1) {
            dp[i] = dp[index] + 1;
        } else {
            auto it = lower_bound(available.begin(), available.end(), index);
            // not found
            if (*it >= i) {
                dp[i] = -1;
            } else {
                dp[i] = dp[*it] + 1;
            }
        }
    }
    // cout << "dp: ";
    // for (int i = 0; i <= n; i++) {
    //     cout << dp[i] << ", ";
    // }
    // cout << endl;
    if (dp[n] == -1) {
        cout << -1 << endl;
    } else {
        int index = n;
        vector<int> ans;
        ans.push_back(index);
        while ((dp[index] - 1) != dp[0]) {
            int i, index_next;
            for (i = index - 1; i >= 0; i--) {
                if (dp[i] == -1) {
                    continue;
                }
                if ((dp[index] - dp[i]) == 1) {
                    index_next = i;
                    continue;
                }
                if ((dp[index] - dp[i]) >= 2) {
                    break;
                }
            }
            index = index_next;
            ans.push_back(index);
        }
        ans.push_back(0);
        for (int i = 0; i < (ans.size() - 1); i++) {
            cout << ans[ans.size() - 1 - i - 1] - ans[ans.size() - 1 - i] << " ";
        }
        cout << endl;
    }

    return 0;
}

