struct E {
    int v, m;
    E() {}
    E(int v, int m) : v(v), m(m) {}
    bool operator < (const E& o) const {
        return v == o.v ? m < o.m : v < o.v;
    }
};

const int INF = 10000000;
const E INF_E = E(INF, -1);

/* range minimum query with segment tree (verified in AOJ/DSL_2_A) */
template<typename T, int B> // 1 << B >= max length
struct segment_tree_min {
    int N; T arr[2 << B];
    segment_tree_min() {}
    void init(int n) {
        N = 1;
        while (N < n) N *= 2;
        for (int i = 0; i < 2*N-1; ++i) arr[i] = INF_E;
    }
    void update(int i, T v) {
        int j = i + N-1; arr[j] = v;
        while (j > 0) {
            j = (j-1) / 2;
            arr[j] = min(arr[2*j+1], arr[2*j+2]);
    }   }
    T query(int a, int b) { return query(a, b, 0, 0, N); }
    T query(int a, int b, int k, int l, int r) {
        if (b <= l || r <= a) return INF_E;
        if (a <= l && r <= b) return arr[k];
        const int m = (l+r)/2;
        return min(query(a, b, 2*k+1, l, m), query(a, b, 2*k+2, m, r));
}   };

int N, M;
string S;

segment_tree_min<E, 17> st;
int dp[101010], nxt[101010];

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> N >> M >> S;
    fill(dp, dp+N+1, INF);
    st.init(N+1);
    dp[N] = 0;
    st.update(N, E(0, N));
    for (int i = N-1; i >= 0; --i) {
        if (S[i] == '1') continue;
        E e = st.query(i+1, min(i+1+M, N+2));
        dp[i] = 1 + e.v;
        nxt[i] = e.m;
        st.update(i, E(dp[i], i));
    }

    if (dp[0] >= INF) {
        cout << -1 << endl;
        return 0;
    }

    for (int i = 0; i < N; i = nxt[i]) {
        cout << (nxt[i] - i) << " ";
    }
    cout << endl;

    return 0;
}

