vector<int> solve(int N, int M, const string& S)
{
    vector<int> ans;
    int x = 0;
    while (x < N) {
        int y = -1;
        for (int i = 1; i <= M && x + i <= N; ++i) {
            if (S[x + i] == '0') {
                y = x + i;
            }
        }
        if (y == -1) {
            return {};
        }
        ans.push_back(y - x);
        x = y;
    }
    reverse(ans.begin(), ans.end());
    return ans;
}

