template <class Monoid>
struct sliding_window_aggregation {
    typedef typename Monoid::value_type value_type;
    Monoid mon;
    std::stack<value_type> front, back;
    std::stack<value_type> sum_front;
    value_type sum_back;
    sliding_window_aggregation(const Monoid & mon_ = Monoid()) : mon(mon_) {
        sum_front.push(mon.unit());
        sum_back = mon.unit();
    }
    /**
     * @note O(1)
     */
    void push(value_type x) {
        back.push(x);
        sum_back = mon.append(sum_back, x);
    }
    /**
     * @note amortized O(1)
     */
    void pop() {
        if (front.empty()) {
            while (not back.empty()) {
                front.push(back.top());
                sum_front.push(mon.append(front.top(), sum_front.top()));
                back.pop();
            }
            sum_back = mon.unit();
        }
        assert (not front.empty());
        front.pop();
        sum_front.pop();
    }
    /**
     * @brief get sum of elements in the queue
     * @note O(1)
     */
    value_type accumulate() const {
        return mon.append(sum_front.top(), sum_back);
    }
    bool empty() const {
        return front.empty() and back.empty();
    }
    size_t size() const {
        return front.size() + back.size();
    }
};

struct min_monoid {
    typedef int value_type;
    value_type unit() const { return INT_MAX; }
    value_type append(value_type a, value_type b) const { return std::min(a, b); }
};

vector<int> solve(int n, int m, const string & s) {
    vector<int> dist(n + 1, INT_MAX);
    sliding_window_aggregation<min_monoid> swag;
    REP_R (i, n + 1) {
        dist[i] = (
            s[i] == '1' ? INT_MAX :
            i == n ? 0 :
            swag.accumulate() == INT_MAX ? INT_MAX :
            swag.accumulate() + 1
        );
        swag.push(dist[i]);
        if (swag.size() > m) swag.pop();
    }
    if (dist[0] == INT_MAX) return vector<int>(1, -1);
    vector<int> answer;
    for (int i = 0; i < n; ) {
        int delta = 1;
        while (dist[i + delta] != dist[i] - 1) {
            ++ delta;
            assert (i + delta <= n);
        }
        answer.push_back(delta);
        i += delta;
    }
    return answer;
}

int main() {
    int n, m; cin >> n >> m;
    string s; cin >> s;
    cout << solve(n, m, s) << endl;
    return 0;
}

