    {
        st[i].in=st[2*i+2].in;
        st[i].vl=st[2*i+2].vl;
    }
    else
    {
        st[i].vl=st[2*i+1].vl;
        st[i].in=min(st[2*i+2].in,st[2*i+1].in);
    }
}
int query(int i,int l,int r,int qs,int qe)
{
    if(qs>r||qe<l)
        return 0;
    if(qs<=l&qe>=r)
        return st[i].in;
    int m=(l+r)/2;
    int in1=query(2*i+1,l,m,qs,qe);
    int in2=query(2*i+2,m+1,r,qs,qe);
    if(in1== 0)
        return in2;
    else if(in2==0)
        return in1;
    else if(dp[in1]<dp[in2])
        return in1;
    else if(dp[in2]<dp[in1])
        return in2;
    else
        return min(in1,in2);
}
