int shorter(vector<int> & ans,vector<int> & cur)
{
    string strans,strcur;
    for(auto el : ans)
    {
        strans+=to_string(el);
    }
    for(auto el : cur)
    {
        strcur+=to_string(el);
    }
    int i;
    for(i = 0 ; i <strans.size();i++)
    {
        if(strans[i] != strcur[i])return strcur[i]-strans[i];
    }
    return strcur[i]-strans[i];
}

void solve(vector<int>& ans, const string& str, int index, int n, int m, vector<int>& cur)
{
      //  cout << index<<endl;

    if(index  == n)
    {
        if(ans.size()==0)ans=cur;
        else
        {
            if(cur.size()<ans.size())
            {
                ans = cur;
            }
            else if( cur.size() == ans.size() && shorter(ans,cur) <0)
            {
                ans = cur;
            }

        }



    }
    if(index>n)return;
    //if(ans.size()!=0 && cur.size()>ans.size())return;
    for(int i = m; i >= 1; i--)
    {
        if(str[i+index]=='0' )
        {
            cur.push_back(i);
            solve(ans,str,index+i,n,m,cur);
            cur.pop_back();
        }
    }



}

