  seg.update(n, 0);
  for (int i = n - 1; i >= 0; i--) {
    if (s[i] == '1') continue;
    ll mi = seg.query(i + 1, min(n + 1, i + m + 1));
    seg.operation(i, mi + 1);
    ll d = seg.query(i, i + 1);
    if (d <= n) {
      pos[d].push_back(i);
      //cerr << i << " " << d << endl;
