    auto itr = upper_bound(pos[i].begin(), pos[i].end(), cur);
    assert(itr != pos[i].end());
    ret.push_back((*itr) - cur);
    cur = *itr;
  }
  ret.push_back(n - cur);
  printv(ret);
}

