using namespace std;
const int maxn = 100500;
vector < int > pos;
int dp[maxn], best[maxn];
int n, m;
int solve(int i){
    if(i == n) return 0;
    int &ret = dp[i];
    if(~ret) return ret;
    int ind = upper_bound(pos.begin(), pos.end(), i + m) - pos.begin();
    int p = pos[ind - 1];
    int a = n + 1, b = n + 1;
    assert(p <= i + m);
    if(p > i)
        a = 1 + solve(p);
    ind = upper_bound(pos.begin(), pos.end(), i) - pos.begin();
    if(pos[ind] > i && pos[ind] - i <= m)
        b = 1 + solve(pos[ind]);
    ret = min(a, b);
    if(b <= a) best[i] = pos[ind];
    else best[i] = p;
    return ret;
}

void print(int i){
    if(i == n) return;
    cout << best[i] - i << ' ';
    print(best[i]);
}
