#define N  100005
vi a(N);
vector <pii> seg(4*N);
void build(ll cur,ll st,ll end)
{
    if(st==end)
    {
        seg[cur].F=a[st];
        seg[cur].S=st;
        return;
    }
    ll mid=(st+end)>>1;
    build((cur<<1),st,mid);
    build((cur<<1)+1,mid+1,end);
    if(seg[cur<<1].F<seg[cur<<1|1].F)
    	seg[cur]=seg[cur<<1];
    else if(seg[cur<<1].F>seg[cur<<1|1].F)
    	seg[cur]=seg[cur<<1|1];
    else {seg[cur]=seg[(cur<<1)];seg[cur].S=min(seg[cur<<1].S,seg[cur<<1|1].S);}//+seg[(cur<<1)+1];                   /* 1-change */
}
void update(ll cur,ll start,ll end,ll idx,ll val)
{
    if(start == end)
        seg[cur].F = min(val,seg[cur].F);
    else
    {
        ll mid = (start + end) >> 1;
        if(start <= idx and idx <= mid)
            update((cur<<1), start, mid, idx, val);
        else
            update((cur<<1)+1, mid+1, end, idx, val);
    if(seg[cur<<1].F<seg[cur<<1|1].F)
    	seg[cur]=seg[cur<<1];
    else if(seg[cur<<1].F>seg[cur<<1|1].F)
    	seg[cur]=seg[cur<<1|1];
    else {seg[cur]=seg[(cur<<1)];seg[cur].S=min(seg[cur<<1].S,seg[cur<<1|1].S);}
    }
}
pii query(ll cur,ll st,ll end,ll l,ll r)
{
    if(st>end||st>r||end<l) return {hell,-1};
    if(st>=l&&end<=r) return seg[cur];
    ll mid=(st+end)>>1;
    pii ans;
    pii ans1=query((cur<<1),st,mid,l,r);
    pii ans2=query((cur<<1)+1,mid+1,end,l,r);
    if(ans1.F<ans2.F)
    	ans=ans1;
    else if(ans1.F>ans2.F)
		ans=ans2;
    else {ans=ans1;ans.S=min(ans1.S,ans2.S);}
    return ans;
   	            /* 14-change */
}
