int n, m;
char s[N];
pii dp[N];
int pre[N];
multiset<pair<int, int>> S;
vector<int> ans;

void solve()
{
    scanf("%d%d", &n, &m);
    scanf("%s", s);
    for (int i = 0; i <= n; ++i)
        dp[i] = {inf, i};
    dp[0].first = 0;
    dp[0].second = 0;
    S.insert({0, 0});
    int L = 0;
    pre[0] = -1;
    for (int i = 1; i <= n; ++i)
    {
        while (i - L > m)
            S.erase(S.find(dp[L])), L++;
        if (s[i] == '0')
        {
            dp[i] = mp((*S.begin()).first + 1, i);
            pre[i] = (*S.begin()).second;
        }
        S.insert(dp[i]);
    }

    // for (int i = 0; i <= n; ++i)
    //     printf("%d ", dp[i]);
    if (dp[n].first == inf)
        return puts("-1"), void();
    for (int i = n; ~i; i = pre[i])
        if (pre[i] != -1)
            ans.pb(i - pre[i]);
    for (int i = ans.size() - 1; i >= 0; --i)
        printf("%d ", ans[i]);
}

