int solve(){
    vector<int> dp(N+1,1e8);
    dp[N]=0;
    SegmentTree< int > seg(N+1, [](int a, int b) { return min(a, b); }, 1e8);
    seg.set(N,dp[N]);
    for (int i = 0; i < N; i++) seg.set(i,1e8);
    seg.build();

    for (int i = N-1; i >= 0; --i)
    {
        if(S[i]=='1') continue;
        dp[i] = seg.query(i+1,min(M+i+1,N+1))+1;
        seg.update(i,dp[i]);
    }
    DBG(dp)

    vector<int> res;
    int idx=0;
    while(idx<N){
        auto itr = min_element(dp.begin()+idx+1,dp.begin()+min(idx+M+1,N+1));
        DBG(*itr)
        if(*itr==1e8){cout << -1 << endl; return 0;}
        idx = itr-dp.begin();
        res.push_back(idx);        
    }

    vector<int> ans(res.size());
    ans[0] = res[0];
    for(int i=0;i<res.size()-1;i++){
        ans[i+1] = res[i+1]-res[i];
    }

    cout << ans << endl;
    return 0;
}


