  int N, M;
  cin >> N >> M;
  string S;
  cin >> S;

  stack<int> st;
  st.push(N);

  dp[N] = 1;

  while(st.size()){
    int pos = st.top();
    st.pop();
    bool flag = true;
    rrep(i, M + 1, 1){
      int next = pos - i;
      if(next < 0) continue;
      if(S[next] == '0') {
        dp[next] = i;
        flag = false;
        if(next != 0) st.push(next);
        break;
      }
    }
    if(flag){
      cout << -1 << endl;
      return 0;
    }
  }

  int pos = 0;
  while(1){
