    vector<int> res;

    int pos = N;
    while (pos > 0) {
        // cout << "pos: " << pos << endl;
        int next_pos = pos - M;
        if (next_pos <= 0) {
            // ゴールにつける。
            res.push_back(pos);
            pos = next_pos;
        }
        else if (f[next_pos] == next_pos) {
            // M手先は行けるので、そのまま進む。
