template <typename T>
class SegmentTree {
public:
    ll size;
    vector<T> node;
    function<T(T, T)> comp;
    T identity_ele;  //comp(x, identity_ele) == x

    SegmentTree(const vector<T> &v, function<T(T, T)> comp, T identity_ele) 
        : comp(comp),
          identity_ele(identity_ele)
    {
        ll tmp = 1;
        while(tmp < v.size()) tmp = (tmp << 1);
        this->size = tmp;
        this->identity_ele = identity_ele;
        this->comp = comp;
        node = V<T>(2 * size - 1, identity_ele);
        for(ll i = 0; i < v.size(); i++) {
            node[i + size - 1] = v[i];
        }
        for(ll i = size - 2; 0 <= i; i--) {
            node[i] = comp(node[i * 2 + 1], node[i * 2 + 2]);
        }
    }

    void update(ll pos, T value) {
        pos += size - 1;
        node[pos] = value;
        while(pos > 0) {
            pos = (pos - 1) / 2;
            node[pos] = comp(node[2 * pos + 1], node[2 * pos + 2]);
        }
    }

    T query(ll a, ll b) {
        return sub_query(a, b, 0, 0, size);
    }

    T sub_query(ll a, ll b, ll k, ll l, ll r) {
        if(r <= a || b <= l) {
            return identity_ele;
        } else if(a <= l && r <= b) {
            return node[k];
        } else {
            T left = sub_query(a, b, k * 2 + 1, l, (l + r) / 2);
            T right = sub_query(a, b, k * 2 + 2, (l + r) / 2, r);
            return comp(left, right);
        }
    }
};

const ll inf = 5e15;
V<ll> ans;

ll solve() {
    ll N, M;
    cin >> N >> M;
    string S;
    cin >> S;
    V<PLL> init_v(N + 1);
    for(ll i = 0; i < N; i++) init_v[i] = S[i] == '0' ? PLL(inf, i) : PLL(inf, inf);
    init_v.back() = PLL(0, N);
    SegmentTree<PLL> st(init_v, [](PLL a, PLL b) { return min(a, b); }, PLL(inf, inf));
    V<ll> trace(N, inf);
    for(ll i = N - 1; 0 <= i; i--) {
        if(S[i] == '1') continue;
        auto val = st.query(i + 1, min(N + 1, i + M + 1));
        if(val.first != inf) {
            val.first++;
            trace[i] = val.second;
            val.second = i;
        }
        st.update(i, val);
    }

    DEBUG(trace);

    if(trace[0] == inf) return -1;
    ll cur = 0;
    while(cur < N) {
        ans.push_back(trace[cur] - cur);
        cur = trace[cur];
    }
    return ans.size();
}

