	ta[0].push_back(n);
	for(int i=n-1;i>=0;i--){
		if(str[i]=='1') continue;
		int mn=seg.range_min_index(i+1,i+m);
		//cout << mn << " ";
		if(dp[mn]==(1LL<<50)) continue;
		dp[i]=dp[mn]+1;
		seg.update(i,dp[i]);

		ta[dp[i]].push_back(i);
		//cout << i << " " << dp[i] << "\n";
	}
	if(dp[0]>=(1LL<<40)){
		cout << -1 << "\n";
		return 0;
	}
	for(int i=0;i<=n;i++){
		reverse(ta[i].begin(),ta[i].end());
	}

	int cur=0;
