ll M=1;
ll INF = 100000000000000;
std::vector<pair<ll, ll> > seg;
void init(ll N){
  while(M<N) M*=2;
  M=M*2-1;
  for(ll i=0;i<M;i++) {
    seg.push_back(make_pair(INF, INF));
  }
  for(ll i=(M+1)/2-1;i<M;i++) seg[i].second = i - ((M+1)/2-1);
}

void update(ll l, ll r, ll x, ll k){
  k+=(M+1)/2-1;
  seg[k].first = x;
  while(k>0){
    k = (k-1)/2;
    if(seg[k*2+1].first>seg[k*2+2].first){
      seg[k].first =  seg[k*2+2].first;
      seg[k].second = seg[k*2+2].second;
    }else{
      seg[k].first =  seg[k*2+1].first;
      seg[k].second = seg[k*2+1].second;
    }
  }
}
pair<ll, ll> query(ll a, ll b, ll l, ll r, ll k){
  if(r<=a || b<=l) return make_pair(INF, INF);
  if(a<=l && r<=b) return seg[k];
  pair<ll, ll> A = query(a, b, l, (l+r)/2, k*2+1);
  pair<ll, ll> B = query(a, b, (l+r)/2, r, k*2+2);
  if(A.first>B.first) return B;
  else return A;
}
