template<class Monoid>
class SegmentTree{
private:
  using T = typename Monoid::T;
  const size_t n;
  vector<T> d;

  void build(){
    for(size_t b = n - 1; b > 0; b--) d[b] = Monoid::op(d[b << 1], d[b << 1 | 1]);
  }

public:
  SegmentTree(size_t n)
    : n(n), d(2 * n, Monoid::identify()) {}

  template<typename InputItr>
  SegmentTree(InputItr first, InputItr last)
    : n(distance(first, last)), d(2 * n, Monoid::identify()){
    copy(first, last, next(d.begin(), n));
    build();
  }

  /* set one value */
  void modify(size_t k, T v){
    for(d[k += n] = v; k > 1; k >>= 1) d[k >> 1] = Monoid::op(d[k], d[k ^ 1]);
  }

  /* return [l, r) value */
  T query(size_t l, size_t r){
    T res {Monoid::identify()};
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l&1) res = Monoid::op(res, d[l++]);
      if (r&1) res = Monoid::op(res, d[--r]);
    }
    return res;
  }

  void dump(){
    FOR(i, n, 2 * n) cout << i - n << ": " << d[i] << endl;
  }
};

/* Range Min Query */
template<typename U = ll>
struct RMQ{
  using T = U;
  static T op(const T& a, const T& b){ return min<T>(a, b); };
  static constexpr T identify(){ return numeric_limits<T>::max(); };
};

int main() {
    int n, m; cin >> n >> m;
    string s; cin >> s;

    reverse(s.begin(), s.end());

    SegmentTree<RMQ<>> t(n + 1);
    t.modify(0, 0);

    FOR(i, 1, n + 1) {
        if (s[i] == '1') continue;
        ll q = t.query(max(0, i - m), i);
        t.modify(i, q + 1);
    }

    vector<int> ans;
    ll f = t.query(n, n + 1);
    int ind = n;

    if (f == RMQ<>::identify()) {
        cout << -1 << endl;
        return 0;
    }

    for (int i = n - 1; i >= 0; i--) {
        ll v = t.query(i, i + 1);

        if (v == RMQ<>::identify()) continue;

        if (v != f) {
            cout << ind << " " << i << endl;
            ans.push_back(ind - i);
            ind = i;
            f = v;
        }
    }

    for (int a : ans) cout << a << " ";
    cout << endl;

    return 0;
}

