int main()
{
#ifdef USE_COLORED
	if (getenv("DEBUG")) {
		std::cout.rdbuf(new colored_stdio_filebuf(stdout, stdout_pre, stdxxx_post));
		std::cerr.rdbuf(new colored_stdio_filebuf(stderr, stderr_pre, stdxxx_post));
	} else
#endif
	{
		int fd = open("/dev/null", O_WRONLY);
		dup2(fd, 2);
		close(fd);
	}

	int N, M;
	std::string S;
	std::cin >> N >> M;
	std::cin >> S;

	std::vector<int> prev;
	prev.resize(N+1);
	std::fill(prev.begin(), prev.end(), -1);

	int cur = 0;
	int last = cur + 1;
	while (cur < N) {
		if (S[cur] == '1') {
			++cur;
			continue;
		}
		while (last <= N && last - cur <= M) {
			if (S[last] != '1') {
				prev[last] = cur;
			}
			++last;
		}
		++cur;
	}

	if (prev[N] == -1) {
		std::cout << "-1\n";
		return 0;
	}

	std::vector<int> way;
	int pos = N;
	while (pos != 0) {
		way.push_back(pos - prev[pos]);
		pos = prev[pos];
	}

	std::reverse(way.begin(), way.end());
	for (int i = 0; i < way.size(); ++i) {
		if (i != 0)
			std::cout << " ";
		std::cout << way[i];
	}
	std::cout << "\n";
}

