using ll = long long;
struct RangeMinimumQuery {
  using type = ll;
  static type id() { return INT_MAX; }
  static type op(const type &l, const type &r) { return std::min(l, r); }
};

template <typename M>
class SegmentTree {
  using T = typename M::type;
  int n;
  std::vector<T> node;

 public:
  // v を基に初期化
  SegmentTree(const std::vector<T> &v) {
    // n は v.size() 以上の最小の2冪
    n = 1;
    while (n < int(v.size())) n *= 2;
    node.resize(2 * n, M::id());

    // i の子 -> 2*i+1, 2*i+2 , 親 -> (i-1)/2
    for (int i = 0; i < int(v.size()); i++) node[i + n] = v[i];
    for (int i = n - 1; i >= 0; i--)
      node[i] = M::op(node[2 * i], node[2 * i + 1]);
  }
  // Monoid::id 初期化
  SegmentTree(int _n) {
    // n は v.size() 以上の最小の2冪
    n = 1;
    while (n < _n) n *= 2;
    node.resize(2 * n, M::id());
  }
  // x 番目を val に更新
  void update(int x, T val) {
    x += n;
    node[x] = val;
    while (x >>= 1) {
      node[x] = M::op(node[2 * x], node[2 * x + 1]);
    }
  }
  // v[x] を M::op(v[x], val) に更新
  void operation(int x, T val) {
    x += n;
    node[x] = M::op(node[x], val);
    while (x >>= 1) {
      node[x] = M::op(node[2 * x], node[2 * x + 1]);
    }
  }
  // [a, b) の op
  T query(int l, int r) {
    l += n;
    r += n;
    T retl = M::id(), retr = M::id();
    while (l < r) {
      if (l & 1) retl = M::op(retl, node[l++]);
      if (r & 1) retr = M::op(node[--r], retr);
      l >>= 1;
      r >>= 1;
    }
    return M::op(retl, retr);
  }
};

constexpr int inf = 1e9;
int main() {
  int n, m;
  cin >> n >> m;
  string s;
  cin >> s;
  SegmentTree<RangeMinimumQuery> seg(n + 2);
  map<int, vector<int>> pos;
  seg.update(0, 0);
  for (int i = 1; i <= n; i++) {
    if (s[i] == '1') continue;
    ll mi = seg.query(max(0, i - m), i);
    seg.operation(i, mi + 1);
    ll d = seg.query(i, i + 1);
    if (d <= n) {
      pos[d].push_back(i);
      cerr << i << " " << d << endl;
    }
  }
  int dist = seg.query(n, n + 1);
  if (dist > n) {
    cout << -1 << endl;
    return 0;
  }
  vector<int> ret;
  int cur = 0;
  for (int i = 1; i < dist; i++) {
    assert(pos.count(i));
    auto itr = upper_bound(pos[i].begin(), pos[i].end(), cur);
    assert(itr != pos[i].end());
    ret.push_back((*itr) - cur);
    cur = *itr;
  }
  ret.push_back(n - cur);
  printv(ret);
}

