		pos = k;
	}
	for(int z=0; z<5; z++){
		set<ii> pq;
		for(int i=1; i<len(path)-1; ++i)
			pq.insert(ii(path[i+1]-path[i], i));

		while(not pq.empty()){
			auto it = pq.begin();
			int dr = it->ff;
			int i = it->ss; 
			pq.erase(it);
			if(i!=1){
				auto x = ii(path[i]-path[i-1], i-1);
