pair<int,int> update(int pos, int val, int node, int x, int y) {
	if (pos < x || y < pos)return seg[node];
	if (x == y)return seg[node] = { val ,x};
	int mid = (x + y) / 2;
	pair<int, int> leftValue = update(pos, val, node * 2, x, mid);
	pair<int, int> rightValue = update(pos, val, node * 2 + 1, mid + 1, y);
	if (leftValue.first > rightValue.first)
		seg[node] = rightValue;
	else
		seg[node] = leftValue;
	return seg[node];
}
pair<int,int> query(int lo, int hi, int node, int x, int y) {
	if (hi < x || y < lo)return { 1234567890 ,1234567890};
	if (lo <= x && y <= hi)return seg[node];
	int mid = (x + y) / 2;
	pair<int, int> returnValue;
	pair<int, int> leftValue = query(lo, hi, node * 2, x, mid);
	pair<int, int> rightValue = query(lo, hi, node * 2 + 1, mid + 1, y);
	if (leftValue.first > rightValue.first) 
		returnValue = rightValue;
	else
		returnValue = leftValue;
	return returnValue;
}
