    cin >> N >> M >> S;

    SegmentTree st = SegmentTree(N);
    st.update(N, 0);
    vector<int> dp(N + 1);
    dp[N] = 0;
    for (int i = N - 1; i >= 0; --i) {
        if (S[i] == '1') {
            dp[i] = INF;
