void upd(int l, int r, int x, int p){
	if(l > x || r < x)return;
	if(l == r){
		tree[p] = x;
	}else{
		int m = l + r >> 1;
		upd(l, m, x, p << 1);
		upd(m + 1, r, x, p << 1 | 1);
		if(dp[tree[p << 1]] < dp[tree[p << 1 | 1]]){
			tree[p] = tree[p << 1];
		}else{
			tree[p] = tree[p << 1 | 1];
		}
	}
}
int ind(int l, int r, int L, int R, int p){
	if(l > R || L > r)return -1;
	if(L <= l && R >= r)return tree[p];
	int m = l + r >> 1; 
	int lf = ind(l, m, L, R, p << 1);
	int rg = ind(m + 1, r, L, R, p << 1 | 1);
	if(lf == -1 && rg == -1)return -1;
	if(lf == -1)return rg;
	if(rg == -1)return lf;
	if(dp[lf] <= dp[rg])return lf;
	return rg;
}
