template<typename T>
class Segtree {
public:
    Segtree(li n,
            T default_value,
            T invalid_value_,
            std::function<T(T, T)> func_) : invalid_value(invalid_value_),
        func(func_) {
        nn = 1;
        while (nn < n) {
            nn *= 2;
        }
        data.resize(nn * 2 - 1);
        for (auto && item : data) {
            item = default_value;
        }
    }

    inline void update(li i, T x) {
        i += nn - 1;
        data[i] = x;
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = func(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    inline T query_(li a, li b, li k, li l, li r) {
        if (r <= a || b <= l) return invalid_value;
        if (a <= l && r <= b) return data[k];
        li mid = (l + r) / 2;
        T vl = query_(a, b, k * 2 + 1, l, mid);
        T vr = query_(a, b, k * 2 + 2, mid, r);
        return func(vl, vr);
    }

    inline T query(li a, li b) {
        li l = 0;
        li r = nn;
        li k = 0;
        if (r <= a || b <= l) return invalid_value;
        if (a <= l && r <= b) return data[k];
        li mid = (l + r) / 2;
        T vl = query_(a, b, k * 2 + 1, l, mid);
        T vr = query_(a, b, k * 2 + 2, mid, r);
        return func(vl, vr);
    }

    li nn;
    vector<T> data;
    T invalid_value;
    function<T(T, T)> func;
};
