string LcsAlphabeticalMinOrder(string a, string b) {
  if (a.size() < b.size()) {
    swap(a, b);
  }

  int n = a.size(), m = b.size();

  vector<string> dp(m + 1);

  for (int i = 0; i < n; i++) {
    vector<string> to(m + 1);
    for (int j = 0; j < m; j++) {
      if (a[i] == b[j]) {
        to[j + 1] = dp[j] + a[i];
      } else {
        if (to[j].size() > dp[j + 1].size()) {
          to[j + 1] = to[j];
        } else if (to[j].size() < dp[j + 1].size()) {
          to[j + 1] = dp[j + 1];
        } else if (to[j] < dp[j + 1]) {
          to[j + 1] = to[j];
        } else {
          to[j + 1] = dp[j + 1];
        }
      }
    }
    dp.swap(to);
  }
  return dp[m];
}
string Lcs(const string &s, const string &t) {
  int dp[3001][3001];
  int n = s.size();
  int m = t.size();
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      if (s[i - 1] == t[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }
  string ans = "";
  int i = s.size(), j = t.size();
  while (i > 0 && j > 0) {
    if (s[i - 1] == t[j - 1]) {
      ans += s[i - 1];
      i--;
      j--;
    } else if (dp[i - 1][j] >= dp[i][j - 1])
      i--;
    else
      j--;
  }
  reverse(ans.begin(), ans.end());
  return ans;
}
vector<int> LcsInteger(const vector<int> &a, const vector<int> &b) {
#define index_of(as, x) \
  distance(as.begin(), lower_bound(as.begin(), as.end(), x))
  struct node {
    int value;
    node *next;
    node(int value, node *next) : value(value), next(next) {}
  };
  const int n = a.size(), m = b.size();
  map<int, vector<int>> M;
  for (int j = m - 1; j >= 0; --j) M[b[j]].push_back(j);
  vector<int> xs(n + 1, INF);
  xs[0] = -INF;
  vector<node *> link(n + 1);
  for (int i = 0; i < n; ++i) {
    if (M.count(a[i])) {
      vector<int> ys = M[a[i]];
      for (int j = 0; j < (int)ys.size(); ++j) {
        int k = index_of(xs, ys[j]);
        xs[k] = ys[j];
        link[k] = new node(b[ys[j]], link[k - 1]);
      }
    }
  }
  vector<int> c;
  int l = index_of(xs, INF - 1) - 1;
  for (node *p = link[l]; p; p = p->next) c.push_back(p->value);
  reverse(c.begin(), c.end());
  return c;
}
bool IsPrime(ll n) {
  if (n < 2) return false;
  for (ll i = 2; i * i <= n; i++)
    if (!(n % i)) return false;
  return true;
}
vector<bool> Eratosthenes(int n) {
  vector<int> res;
  vector<bool> Prime(n + 1, true);
  Prime[0] = Prime[1] = false;
  for (int i = 2; i * i <= n; i++) {
    if (Prime[i]) {
      for (int j = 2; i * j <= n; j++) {
        Prime[i * j] = false;
      }
    }
  }
  for (int i = 2; i <= n; i++) {
    if (Prime[i]) {
      res.emplace_back(i);
    }
  }
  return Prime;
}
ll MergeCount(vector<int> &a) {
  ll count = 0;
  int n = a.size();
  if (n > 1) {
    vector<int> b(a.begin(), a.begin() + n / 2);
    vector<int> c(a.begin() + n / 2, a.end());
    count += MergeCount(b);
    count += MergeCount(c);
    for (int i = 0, j = 0, k = 0; i < n; ++i)
      if (k == (int)c.size())
        a[i] = b[j++];
      else if (j == (int)b.size())
        a[i] = c[k++];
      else if (b[j] <= c[k])
        a[i] = b[j++];
      else {
        a[i] = c[k++];
        count += n / 2 - j;
      }
  }
  return count;
}
bool WarshallFloyd(vector<vector<ll>> &c) {
  int V = c.size();
  for (int i = 0; i < V; i++) {
    c[i][i] = 0;
  }

  for (int i = 0; i < V; i++) {
    for (int j = 0; j < V; j++) {
      for (int k = 0; k < V; k++) {
        if (c[j][k] > c[j][i] + c[i][k]) {
          c[j][k] = c[j][i] + c[i][k];
        }
      }
    }
  }

  for (int i = 0; i < V; i++) {
    if (c[i][i] < 0) {
      return false;
    }
  }

  return true;
}
vector<ll> Dijkstra(int i, vector<vector<edge>> graph) {
  int n = graph.size();
  vector<ll> d(n, LONGINF);
  d[i] = 0;
  priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>>
      q;
  q.push(make_pair(0, i));  
  while (!q.empty()) {
    pair<ll, int> p = q.top();
    q.pop();
    int v = p.second;
    if (d[v] < p.first) {
      continue;
    }
    for (auto x : graph[v]) {
      if (d[x.to] > d[v] + x.cost) {
        d[x.to] = d[v] + x.cost;
        q.push(make_pair(d[x.to], x.to));
      }
    }
  }
  return d;
}
bool BellmanFord(int start, int V, int E, vector<edge> Edge, vector<ll> &d) {
  resize(d, V);
  fill(d.begin(), d.end(), LONGINF);
  d[start] = 0;
  vector<bool> t(V, false);

  for (int i = 0; i < V - 1; i++) {
    for (int j = 0; j < E; j++) {
      edge e = Edge[j];
      if (d[e.from] == LONGINF) {
        continue;
      }
      if (d[e.to] > d[e.from] + e.cost) {
        d[e.to] = d[e.from] + e.cost;
      }
    }
  }

  for (int i = 0; i < V; i++) {
    for (int j = 0; j < E; j++) {
      edge e = Edge[j];
      if (d[e.from] == LONGINF) {
        continue;
      }
      if (d[e.to] > d[e.from] + e.cost) {
        d[e.to] = d[e.from] + e.cost;
        t[e.to] = true;
        /*
        if (i == V - 1) {
                return false;
        }
        */
      }
      if (t[e.from]) {
        t[e.to] = true;
      }
    }
  }

  if (t[V - 1]) {
    return false;
  }

  return true;
}
bool TopologicalSort(const vector<vector<edge>> &g, vector<int> &ans) {
  int n = g.size(), k = 0;
  vector<int> ord(n), in(n);
  for (auto &es : g) {
    for (auto &e : es) {
      in[e.to]++;
    }
  }
  queue<int> q;
  for (int i = 0; i < n; ++i) {
    if (in[i] == 0) q.push(i);
  }
  while (!q.empty()) {
    int v = q.front();
    q.pop();
    ord[k++] = v;
    for (auto &e : g[v]) {
      if (--in[e.to] == 0) q.push(e.to);
    }
  }
  ans = ord;
  if (*max_element(in.begin(), in.end()) == 0) {
    return true;
  }
  return false;
}
vector<int> ArticulationNode(const vector<vector<edge>> &g) {
  int n = g.size(), idx;
  vector<int> low(n), ord(n), art;
  function<void(int)> DFS = [&](int v) {
    low[v] = ord[v] = ++idx;
    for (auto &e : g[v]) {
      int w = e.to;
      if (ord[w] == 0) {
        DFS(w);
        low[v] = min(low[v], low[w]);
        if ((ord[v] == 1 && ord[w] != 2) || (ord[v] != 1 && low[w] >= ord[v])) {
          art.push_back(v);
        }
      } else {
        low[v] = min(low[v], ord[w]);
      }
    }
  };
  for (int u = 0; u < n; u++) {
    if (ord[u] == 0) {
      idx = 0;
      DFS(u);
    }
  }

  sort(art.begin(), art.end()); 
  art.erase(unique(art.begin(), art.end()),
            art.end()); 

  return art;
}
vector<vector<edge>> ToRootTree(const vector<vector<edge>> &g, int r) {
  int n = g.size();
  vector<vector<edge>> G(n);
  vector<int> ord(n, -1);

  queue<int> q;

  q.push(r);
  int k = 0;

  while (q.size()) {
    int u = q.front();
    q.pop();

    for (auto &e : g[u]) {
      int v = e.to;
      if (ord[v] == -1) {
        ord[v] = k;
        k++;
        q.push(v);
        G[u].emplace_back(e);
      }
    }
  }

  return G;
}
edge TreeDiameter(const vector<vector<edge>> &g) {

  int start = 0;  

  static const auto bfs = [](const vector<vector<edge>> &g, int s,
                             queue<int> &q, vector<ll> &dist) {
    while (!q.empty()) {
      q.pop();
    }
    q.push(s);
    int n = g.size();
    dist.assign(n, LONGINF);
    dist[s] = 0;
    while (q.size()) {
      int u = q.front();
      q.pop();
      for (auto &e : g[u]) {
        int v = e.to;
        if (dist[v] == LONGINF) {
          dist[v] = dist[u] + e.cost;
          q.push(v);
        }
      }
    }
    return dist;
  };
  vector<ll> dist;
  queue<int> q;
  bfs(g, start, q, dist);
  int n = g.size(), u = -1, v = -1;
  for (int i = 0; i < n; i++)
    if (dist[i] != LONGINF && (u == -1 || dist[i] > dist[u])) u = i;
  bfs(g, u, q, dist);
  for (int i = 0; i < n; i++)
    if (dist[i] != LONGINF && (v == -1 || dist[i] > dist[v])) v = i;
  ll d = dist[v];
  if (u > v) swap(u, v); 
  return edge(u, v, d);
}
