  vector<lint> dp(n + 1, LINF);
  dp[0] = 0;
  repc(i, 0, n) {
    repc(j, 1, m) {
      if(i + j >= n + 1) {
        break;
      }
      if(s[i + j] == '0') {
        chmin(dp[i + j], dp[i] + 1);
      }
    }
  }

#ifdef LOCAL
  for(auto &&e : dp) {
    cout << e << " ";
  }
  cout << endl;
