using namespace std;

template<class V,ll NV> class SegTree_Pair {
public:
	vector<pair<V,ll>> val;
	static V const def=1<<30;
	pair<V,ll> comp(pair<V,ll> l,pair<V,ll> r){ return min(l,r);}
	SegTree_Pair(){
		val.resize(NV*2);
		for(ll i = 0; i < NV; ++ i) val[i+NV]=make_pair(def,i);
		for(ll i=NV-1;i>=1;i--) val[i]=comp(val[2*i],val[2*i+1]);
	};
	pair<V,ll> getval(ll x,ll y,ll l=0,ll r=NV,ll k=1) {
		if(r<=x || y<=l) return make_pair(def,NV);
		if(x<=l && r<=y) return val[k];
		return comp(getval(x,y,l,(l+r)/2,k*2),getval(x,y,(l+r)/2,r,k*2+1));
	}
	void update(ll entry, V v) {
		entry += NV;
		val[entry]=make_pair(v,entry-NV);
		while(entry>1) entry>>=1, val[entry]=comp(val[entry*2],val[entry*2+1]);
	}
};


