int main(void)
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	//ifstream cin("test.out");
	int n,k;
	string s;

	cin >> n >> k;
	cin >> s;

	int Min = n;
	fill(dist,dist+100001,INF);
	dist[n] = 0;
	priority_queue <pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> pque;
	pque.push(make_pair(dist[n],n));

	memset(history,-1,sizeof(history));
	memset(memo,-1,sizeof(memo));

	while(!pque.empty())
	{
		int now = pque.top().second;
		int val = pque.top().first;
		pque.pop();
		/*
		if(now > Min)
		{
			continue;
		}
		*/
		if(val > dist[now])
		{
			continue;
		}
		if(now==0 || dist[0]!=INF)
		{
			break;
		}
		for(int i=1;i<=k;i++)
		{
			if(now-i < 0)
			{
				break;
			}
			if(s[now-i]=='1')
			{
				continue;
			}
			if(dist[now - i] > dist[now] + 1)
			{
				dist[now - i] = dist[now] + 1;
				memo[now - i] = i;
				history[now - i] = now;
				Min = min(Min,now-i);
				if(now-i<=Min)
				{
					pque.push(make_pair(dist[now - i],now - i));
				}
			}
		}
	}	

	if(dist[0]>=INF)
	{
		cout << -1 << '\n';
	}
	else
	{
		vector <int> res;
		int now = 0;
