void solve()
{
	ll N, M;
	cin >> N >> M;
	string S;
	cin >> S;
	vll ans;

	ll idx = N;
	while (1){
		ll retJ = -1;
		REPS(j, idx-M, idx-1){
			if (j < 0)continue;
			if (S[j] == '0'){
				retJ = j;
				break;
			}
		}
		if (retJ == -1){
			cout << -1 << '\n'; return;
		}


		ans.push_back(idx-retJ);
		idx = retJ;
		if (idx == 0) break;
	}

	std::reverse(ans.begin(), ans.end());
	coutv(ans);
}


