vector<LL> solve(LL n, LL m, string s){
    vector<LL> ans;
    LL cur = n;
    while(cur > 0){
        LL v = 0;
        for(LL i = 1; i <= m; ++i){
            if(cur - i < 0) break;
            if(s[cur-i] == '0'){
                v = i;
            }
        }
        if(v == 0) return vector<LL>{-1};
        ans.push_back(v);
        cur -= v;
    }
    reverse(ans.begin(), ans.end());
    return ans;
}


