inline ll mul(ll a, ll b, ll m) { return (((a % m * b % m) % m + m) % m); }

int dp[N],parent[N];
vi ans;

void solve () {
    int n,m;cin>>n>>m;
    string s;cin>>s;
    deque<ii> q;
    if (s[0] == '1' || s[n] == '1') {
        cout<<-1<<endl;
        return;
    }
    // Base Case.
    for (int i=1;i<=n;i++) dp[i] = INF;
    dp[0] = 0;
    q.pb({0,0});
    int l = 0;
    for (int i=1;i<=n;i++) {
        // Whether to kick out or not.
        if (i >= m+1) {
            if (q.front().first == dp[l]) q.pop_front();
            l++;
        }
        if (s[i] == '1') continue;
        if (!q.empty()) {
            dp[i] = q.front().first + 1;
            parent[i] = q.front().second;
        }
        while (!q.empty() && dp[i] < q.back().first) q.pop_back();
        q.push_back({dp[i],i});
    }
    if (dp[n] == INF) {
        cout<<-1<<endl;
        return;
    }
    int curr = n;
    while (curr != 0) {
        ans.pb(curr);
        curr = parent[curr];
    }
    reverse(all(ans));
    int si = sz(ans);
    for (int i=0;i<si;i++) {
        if (i == 0) cout<<ans[i]-0<<" ";
        else cout<<ans[i]-ans[i-1]<<" ";
    }
}

