pii t[N * 4];
void upd(int v, int l, int r, int pos, pii val) {
    if (l == r) {
        t[v] = val;
        return;
    }
    pos <= md ? upd(v + v, l, md, pos, val) : upd(v + v + 1, md + 1, r, pos, val);
    t[v] = min(t[v + v], t[v + v + 1]);
}
pii get(int v, int l, int r, int left, int right) {
    if (left > r || right < l) return {INF1, INF1};
    if (left <= l and r <= right) return t[v];
    return min(get(v + v, l, md, left, right), get(v + v + 1, md + 1, r, left, right));
}
