void upd(int pos, int val, int v = 0, int tl = 0, int tr = N){
    if (tl + 1 == tr){
        t[v] = {val, -pos};
        return;
    }
    int tm = tl + tr >> 1;
    if (pos < tm){
        upd(pos, val, v+v+1, tl, tm);
    }
    else{
        upd(pos, val, v+v+2, tm, tr);
    }
    t[v] = min(t[v+v+1], t[v+v+2]);
}

pii get(int l, int r, int v = 0, int tl = 0, int tr = N){
    if (tl >= r || l >= tr) return {inf, inf};
    //cout << l << " " << r-1 << " " << tl << " " << tr-1 << endl;;
    if (l <= tl && tr <= r) return t[v];
    int tm = tl + tr >> 1;
    return min(get(l, r, v+v+1, tl, tm),
               get(l, r, v+v+2, tm, tr));
}

