void build(int a[], int v, int tl, int tr) {
    if (tl == tr) {
        t[v] = {a[tl], tl};
    } else {
        int tm = (tl + tr) / 2;
        build(a, v*2, tl, tm);
        build(a, v*2+1, tm+1, tr);
        if(t[2*v].f>t[2*v+1].f){
        	t[v]=t[2*v+1];
        }
        else{
        	t[v]=t[2*v];
        }
    }
}

pair<int, int> mini(int v, int tl, int tr, int l, int r) {
    if (l > r) 
        return {2, 0};
    if (l == tl && r == tr) {
        return t[v];
    }
    int tm = (tl + tr) / 2;
    auto u1=mini(v*2, tl, tm, l, min(r, tm));
    auto u2=mini(v*2+1, tm+1, tr, max(l, tm+1), r);
    if(u1.f>u2.f){
    	return u2;
    }
    else{
    	return u1;
    }
}


