struct segment_tree {
  struct node;
  using iter = vector<node>::iterator;

  struct node {
    int a, b;
    iter left, right;
    ii best;
    void pushup() {
      best = min(left->best, right->best);
    }
  };

  vector<node> pool;
  iter last, root;

  iter _build(int a, int b) {
    iter cur = last++;
    cur->a = a;
    cur->b = b;
    cur->best = {INF, INF};
    if (a + 1 == b) return cur;
    cur->left = _build(a, (a + b) / 2);
    cur->right = _build((a + b) / 2, b);
    return cur;
  }

  void init(int n) {
    pool.resize(n * 2);
    last = pool.begin();
    root = _build(0, n);
  }

  void insert(iter cur, int pos, int val) {
    if (cur->a + 1 == cur->b) {
      cur->best = {val, cur->a};
      return;
    }
    if ((cur->a + cur->b) / 2 > pos) {
      insert(cur->left, pos, val);
    } else {
      insert(cur->right, pos, val);
    }
    cur->pushup();
  }

  ii query(iter cur, ii range) {
    if (cur->a >= range.first && cur->b <= range.second) {
      return cur->best;
    }
    ii ret = {INF, INF};
    if ((cur->a + cur->b) / 2 > range.first) {
      ret = min(ret, query(cur->left, range));
    }
    if ((cur->a + cur->b) / 2 < range.second) {
      ret = min(ret, query(cur->right, range));
    }
    return ret;
  }
};

int main() {
  int n, m;
  scanf("%d%d", &n, &m);
  scanf("%s", s);
  segment_tree st;
  st.init(n + 1);
  vector<int> dp(n + 1, -1), nxt(n + 1);
  dp[n] = 0;
  st.insert(st.root, n, dp[n]);
  for (int i = n - 1; i >= 0; --i) {
    if (s[i] == '1') continue;
    int L = i + 1, R = min(i + m, n) + 1;
    auto cur = st.query(st.root, {L, R});
    if (cur.first != INF) {
      dp[i] = cur.first + 1;
      nxt[i] = cur.second;
      st.insert(st.root, i, dp[i]);
    }
  }
  if (dp[0] < 0) {
    puts("-1");
  } else {
    bool first = true;
    for (int i = 0; i != n; i = nxt[i]) {
      if (first) {
        first = false;
      } else {
        putchar(' ');
      }
      printf("%d", nxt[i] - i);
    }
    puts("");
  }
  return 0;
}

