    SegmentTree<LL> dp(vector<LL>(n + 1, HINF<LL>()));
    dp.update(n, 0);
    for(int i = n - 1;i >= 0;i--){
        if(s[i] == '1')continue;
        LL n_dp = dp.getmin(i + 1, min(n + 1, i + m + 1)) + 1;
        if(n_dp >= HINF<LL>()){
            cout << -1 << endl;
            return 0;
        }
        dp.update(i, n_dp);
    }

    int cur_val = dp.getmin(0, 1);
    int cur = 0;
    vector<int> ans;
    for(int i = 1;i <= n;i++){
        int d = dp.getmin(i, i + 1);
        if(d == cur_val - 1 || i == n){
            ans.emplace_back(i - cur);
            cur_val = d;
            cur = i;
        }
    }
    REP(i, (int)ans.size()){
        if(i)cout << " ";
        cout << ans[i];
    }
    cout << endl;
}

