using namespace std;
typedef pair<llint, llint> P;

struct SegTree{
	int size;
	vector<P> seg;

	SegTree(){}
	SegTree(int size){
		this->size = size;
		seg.resize(1<<(size+1));
	}

	void init()
	{
		for(int i = 0; i < (1<<(size+1)); i++) seg[i] = make_pair(inf, inf);
	}

	void update(int i, P val)
	{
		i += (1 << size);
		seg[i] = val;
		while(i > 1){
			i /= 2;
			seg[i] = min(seg[i*2], seg[i*2+1]);
		}
	}

	P query(int a, int b, int k, int l, int r)
	{
		if(b < l || r < a) return make_pair(inf, inf);
		if(a <= l && r <= b) return seg[k];
		P lval = query(a, b, k*2, l, (l+r)/2);
		P rval = query(a, b, k*2+1, (l+r)/2+1, r);
		return min(lval, rval);
	}
	P query(int a, int b)
	{
		return query(a, b, 1, 0, (1<<size)-1);
	}
};

llint n, m;
string s;
SegTree seg(18);
llint succ[100005];

int main(void)
{
	ios::sync_with_stdio(0);
	cin.tie(0);

	cin >> n >> m;
	cin >> s;

	seg.init();
	seg.update(n, P(0, n));

	for(int i = n-1; i >= 0; i--){
		if(s[i] == '1'){
			seg.update(i, P(inf, i));
			continue;
		}
		P res = seg.query(i+1, i+m);
		seg.update(i, P(res.first+1, i));
		if(res.second < inf/2) succ[i] = res.second-i;
	}
	if(seg.query(0, 0).second > inf/2){
		cout << -1 << endl;
		return 0;
	}

	llint p = 0;
	while(p < n){
		cout << succ[p] << " ";
		p += succ[p];
	}
	cout << endl;

	return 0;
}

