struct SegmentTree{
private:
	vector<int> node;
	int n;
    int I=INF;

public:
	SegmentTree(){
		int sz=100010;
		n=1;
		while(n<sz) n*=2;
		rep(i,2*n-1) node.push_back(I);
	}

	void update(int k,int a){
		k+=n-1;
		node[k]=a;
		while(k>0){
			k=(k-1)/2;
			node[k]=min(node[2*k+1],node[2*k+2]);
		}
	}

	int find(int a,int b,int k=0,int l=0,int r=-1){
		if(r<0) r=n;
		if(r<=a || b<=l) return I;
		if(a<=l && r<=b) return node[k];
		else{
			int vl=find(a,b,2*k+1,l,(l+r)/2);
			int vr=find(a,b,2*k+2,(l+r)/2,r);
			return min(vl,vr);
		}
	}
};

