void solve(){
    int N,M;cin>>N>>M;
    string S;cin>>S;
    SegmentTree<int> table([](int a,int b){return min(a,b);},
                               [](int a,int b){return b;},(int)1e9);
    table.init(N+1);
    vector<int> dp(N+1);
    table.update(N,0);
    RREP(i,N){
        if(S[i]=='0'){
            dp[i]=table.query(i+1,min(i+M,N))+1;
            table.update(i,dp[i]);
        }else{
            dp[i]=1e9;
        }
    }
    if(dp[0]>N){
        cout<<-1<<endl;
        return;
    }
    vector<int> ans;
    int pre=0;
    int K=dp[0];
    REP(l,N+1){
        if(dp[l]<K){
            ans.push_back(l-pre);
            pre=l;
            K--;
        }
    }
    REP(i,ans.size()) cout<<ans[i]<<" \n"[i+1==ans.size()];
}

