void init() {
  scanf("%d %d", &N, &M);
  scanf("%s", S);
  std::reverse(S, S + N + 1);
}

void solve() {
  F[0] = 0;
  static int que[MaxN];
  int head = 1, tail = 0;
  que[++tail] = 0;
  for (int i = 1; i <= N; ++i) {
    if (S[i] == '1') {
      F[i] = -1;
      continue;
    }
    while (head <= tail && que[head] + M < i) head++;
    if (head > tail) {
      F[i] = -1;
      continue;
    }
    int j = que[head];
    F[i] = F[j] + 1;
    Nxt[i] = j;
    while (head <= tail && F[que[tail]] >= F[i]) tail--;
    que[++tail] = i;
  }
  if (F[N] == -1) {
    printf("%d\n", F[N]);
    return;
  }
  for (int i = N; i; i = Nxt[i])
    printf("%d ", i - Nxt[i]);
  putchar('\n');
}

int main() {
  init();
  solve();
  return 0;
}

