using namespace std;

const int inf = 1000003;

string S;
int dp[100005], tree[400005];

void update(int left, int right, int x, int val, int root)
{
    if(left > x || right < x)
        return;

    if(left == right)
    {
        tree[root] = val;
        return;
    }

    int mid = (left + right) / 2;

    update(left, mid, x, val, root*2);
    update(mid+1, right, x, val, root*2+1);

    tree[root] = min(tree[root*2], tree[root*2+1]);
}

int query(int left, int right, int L, int R, int root)
{
    if(left > R || right < L)
        return inf;

    if(left >= L && right <= R)
        return tree[root];

    int mid = (left + right) / 2;

    return min(query(left, mid, L, R, root*2), query(mid+1, right, L, R, root*2+1));
}

