template<typename T> class LazySegmentTree
{
 private:
    int n;
    vector<T> node,lazy;
 public:
    LazySegmentTree(int sz,T init){
        n=1;
        while(n<sz) n*=2;
        node.assign(2*n-1,init);
        lazy.assign(2*n-1,-1);
    }
    void update(int a,int b,int x,int k,int l,int r){
        if(a<=l and r<=b) node[k]=lazy[k]=x;
        else{
            if(lazy[k]!=-1) push(k),lazy[k]=-1;
            if(check(a,b,l,(l+r)/2)) update(a,b,x,2*k+1,l,(l+r)/2);
            if(check(a,b,(l+r)/2,r)) update(a,b,x,2*k+2,(l+r)/2,r);
            node[k]=min(node[2*k+1],node[2*k+2]);
        }
    }
    T get(int a,int b,int k,int l,int r){
        if(a<=l and r<=b) return node[k];
        else{
            if(lazy[k]!=-1) push(k),lazy[k]=-1;
            T res=INT_MAX;
            if(check(a,b,l,(l+r)/2)) res=min(res,get(a,b,2*k+1,l,(l+r)/2));
            if(check(a,b,(l+r)/2,r)) res=min(res,get(a,b,2*k+2,(l+r)/2,r));
            return res;
        }
    }
    void push(int k){
        node[2*k+1]=node[2*k+2]=lazy[k];
        lazy[2*k+1]=lazy[2*k+2]=lazy[k];
    }
    bool check(int a,int b,int l,int r){
        return max(a,l)<min(b,r);
    }
    void update(int a,int b,int x){ update(a,b,x,0,0,n); }
    T get(int a,int b){ return get(a,b,0,0,n); }
};

