template<class T> class SegmentTree {
    public:
    size_t n;          // 葉の数
    vector<T> data; // データ
    T def;          // 単位元
    function<T(T, T)> update_func;  // 点更新で使う処理
    function<T(T, T)> find_func;    // 区間クエリで使う処理

    SegmentTree(size_t _n, T _def, function<T(T, T)> _update_func, function<T(T, T)> _find_func)
        : def(_def), update_func(_update_func), find_func(_find_func) {
        // 2のべき乗にする
        n = 1;
        while(n < _n) n <<= 1;
        data = vector<T>(2*n-1, _def);
    }

    void update(size_t i, T x){
        i += n-1;
        data[i] = update_func(data[i], x);
        while(i){
            i = (i-1)/2;
            data[i] = find_func(data[2*i+1], data[2*i+2]);
        }
    }

    T _find(size_t s, size_t t, size_t k, size_t kl, size_t kr){
        if(kr <= s || t <= kl) return def;
        if(s <= kl && kr <= t) return data[k];
        size_t kc = (kl+kr)/2;
        T vl = _find(s, t, 2*k+1, kl, kc);
        T vr = _find(s, t, 2*k+2, kc, kr);
        return find_func(vl, vr);
    }

    T find(size_t s, size_t t) {
        return _find(s, t, 0, 0, n);
    }
};


int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    string s;
    cin >> s;
    vector<int> a(n+1, INF);
    for(int i=0;i<=n;++i) if(s[i] == '1') a[i] = -1;
    vector<int> min_m(n+1, INF);

    SegmentTree<int> tree(
        n+2, INF, 
        [](int a, int b) { return b; }, 
        [](int a, int b) { return min(a, b); }
    );
    a[n] = 0;
    tree.update(n, 0);
    map<ll, int> value_to_idx;
    value_to_idx[0] = n;
    for(int i=n-1;i>=0;--i) {
        if(a[i] == -1) continue;

        a[i] = tree.find(i+1, min(n, i+m)+1) + 1;
        int j = value_to_idx[a[i]-1];
        if(j != 0 && j-i <= m) min_m[i] = j-i;
        // cerr << a[i] << ":" << min_m[i] << endl;

        tree.update(i, a[i]);
        value_to_idx[a[i]] = i;
    }

    {
        int i = 0;
        vector<int> ans;
        while(i < n) {
            if(min_m[i] == INF) {
                cout << -1 << endl;
                return 0;
            }
            ans.push_back(min_m[i]);
            i = i + min_m[i];
        }
        for(int x: ans) cout << x << " ";
        cout << endl;
    }
}

