int n, m;
string s;

int main(){
    cin >> n >> m >> s;
    SegmentTree seg(vector<LL>(n + 2, INF<int>()));
    seg.update(0, 0);
    for(int i = 1;i <= n;i++){
        if(s[i] == '1')continue;
        int l = max(0, i - m);
        LL num = seg.getmin(l, i) + 1;
        seg.update(i, num);
    }
    if(seg.getmin(n, n + 1) >= INF<int>()){
        cout << -1 << endl;
        return 0;
    }

    int pre = 0;
    int preidx = 0;
    vector<int> ans;
    for(int i = 1;i <= n;i++){
        if(seg.getmin(i, i + 1) == pre + 1){
            ans.emplace_back(i - preidx);
            pre++;
            preidx = i;
        }
    }
    int sum = 0;
    REP(i, (int)ans.size())sum += ans[i];
    ans[(int)ans.size() - 1] += (n - sum);
    REP(i, (int)ans.size()){
        if(i)cout << " ";
        cout << ans[i];
    }
    cout << endl;
}

