struct SegT {
	vector< pii > container;
	int n;
	void update(int i, pii x) {
		int ii = i + n - 1;
		container[ii] = x;
		while (ii > 0) {
			ii = (ii - 1) / 2;
			//////////////////  update to better one  ////////////////////////
			container[ii] = min(container[2 * ii + 1], container[2 * ii + 2]);
		}
	}
	pii get(int l, int r, int l2 = 0, int r2 = -1, int k = 0) {
		if (r2 == -1)
			r2 = n;
		/////////////////  return worst  //////////////////
		if (r2 <= l || r <= l2)
			return make_pair(LINF, 0);

		if (l <= l2 && r2 <= r)
			return container[k];
		pii vl = get(l, r, l2, (l2 + r2) / 2, 2 * k + 1);
		pii vr = get(l, r, (l2 + r2) / 2, r2, 2 * k + 2);
		/////////////  return better one  //////////////
		return min(vl, vr);
	}
	SegT(vector< pii > &A) {
		n = pow(2, (int)log2(A.size()) + 1);
		container = vector< pii >(2 * n - 1);
		for (int i = 0; i < A.size(); i++)
			update(i, A[i]);
	}
};

