	scanf("%s",c);
	for(int i=n;i;i--)
	{
		if(c[i]=='0')nxt[i]=i;
		else nxt[i]=nxt[i+1];
	}
	for(int i=1;i<=n;i++)
	{
		int j=max(0,i-m);
