int main(){
  int N, M; cin >> N >> M;
  string S; cin >> S;

  int cnt = 0; bool flag = true;
  for (int i = 0; i < S.length(); i++){
    if (S[i] == '0'){
      if (cnt >= M){
        flag = false;
      }
      cnt = 0;
    }else{
      cnt++;
    }
  }
  if (cnt >= M) flag = false;

  if (flag == true){
    vector <int> ans;
    for (int i = S.length() - 1; i >= 0; i--){

      for (int j = M; j >= 1; j--){
        if (i - j >= 0){
          if (S[i - j] == '0'){
            ans.push_back(j);
            i = i - j + 1;
            break;
          }
        }
      }
    }

    for (int i = ans.size() - 1; i >= 0; i--){
      cout << ans[i];
      if (i != 0) cout << " ";
    }
    cout << endl;

  }else{
    cout << -1 << endl;
  }


  return 0;
}

