using namespace std;
const int INF = 1e9;
struct SegTree {
    int N;
    vector<pair<int, int>> A;
    SegTree(int n) {
        N = 1;
        while (N < n) N *= 2;
        A.resize(2 * N);
        for (int i = 0; i < N; i++) {
            A[N + i] = make_pair(INF, i);
        }
        for (int i = N - 1; i > 0; i--) {
            A[i] = min(A[2*i+0], A[2*i+1]);
        }
    }
    void set(int idx, int val) {
        auto p = make_pair(val, idx);
        idx += N;
        A[idx] = p;
        idx /= 2;
        while (idx > 0) {
            A[idx] = min(A[2*idx+0], A[2*idx+1]);
            idx /= 2;
        }
    }
    pair<int, int> minrange(int L, int R) {
        pair<int, int> ans = make_pair(INF, -1);
        L += N, R += N;
        while (L < R) {
            if (R & 1) ans = min(ans, A[--R]);
            if (L & 1) ans = min(ans, A[L++]);
            R /= 2, L /= 2;
        }
        return ans;
    }
};
int main() {
    cin.tie(nullptr); ios::sync_with_stdio(false);
    int N, M; cin >> N >> M;
    string S; cin >> S;
    SegTree st(N + 1);
    vector<int> prev(N + 1);
    st.set(0, 0);
    for (int i = 1; i <= N; i++) {
        if (S[i] == '1') continue;
        auto p = st.minrange(max(0, i - M), i);
        st.set(i, p.first + 1);
        prev[i] = p.second;
    }
    if (st.minrange(N, N + 1).first == INF) {
        cout << "-1\n";
    } else {
        vector<int> A;
        int curr = N;
        while (curr > 0) {
            A.push_back(curr - prev[curr]);
            curr = prev[curr];
        }
        reverse(begin(A), end(A));
        for (int i = 0; i < A.size(); i++) {
            cout << A[i] << " \n"[i == A.size() - 1];
        }
    }
    return 0;
}

