  int N, M;
  string S;
  cin >> N >> M >> S;
  if (S.back() == '1') {
    cout << -1 << endl;
    return 0;
  }
  queue<vector<int>> Q;
  Q.push({0});
  vector<bool> visited(N + 1, false);
  vector<vector<int>> res;
  while (!Q.empty()) {
    int q_size = Q.size();
    for (int i = 0; i < q_size; i++) {
      queue<int> visit_queue;
      auto path = Q.front();
      Q.pop();
      int pos = path.back();
      for (int j = 1; j <= M; j++) {
        if (pos + j <= N) {
          if (!visited[pos + j] && S[pos + j] == '0') {
            visit_queue.push(pos + j);
            path.push_back(pos + j);
            Q.push(path);
            if (pos + j == N) {
              res.push_back(path);
            }
            path.pop_back();
          }
        } else {
          break;
        }
      }
      while (!visit_queue.empty()) {
        visited[visit_queue.front()] = true;
        visit_queue.pop();
      }
    }
  }
  if (res.empty()) {
    cout << -1 << endl;
    return 0;
  }
  sort(res.begin(), res.end());
  for (int k = 1; k < res[0].size(); k++) {
    cout << res[0][k] - res[0][k - 1] << " ";
  }
  cout << endl;
  return 0;
}

