struct Seg{
    vec dat;
    //要素数
    int n;

    Seg(int n_){
        n=1;
        while(n<n_)n*=2;
        dat.resize(2*n);

        for(int i=0;i<2*n-1;i++)
            dat[i]=INF;
    }

    //k番目の値をaに変更
    void update(int k,ll a){
        k+=n-1;
        dat[k]=a;
        while(k>0){
            k=(k-1)/2;
            dat[k]=min(dat[2*k+1],dat[2*k+2]);
        }
    }

    //[a,b)の最小値を求める
    //kは節点の番号、[l,r)はその区間
    ll query(int a,int b,int k,int l,int r){
        if(r<=a || b<=l)return INF;
        if(a<=l && r<=b)return dat[k];
        else{
            ll vl=query(a,b,2*k+1,l,(l+r)/2);
            ll vr=query(a,b,2*k+2,(l+r)/2,r);
            return min(vl,vr);
        }
    }
};

int main(){
    int N,M; cin>>N>>M;
    string S; cin>>S;
    Seg seg(N+M);
    vec dp(N,INF);
    seg.update(N,0);
    for(int i=N-1;i>=0;i--){
        if(S[i]=='1') continue;
        ll res=seg.query(i+1,i+M+1,0,0,seg.n);
        if(res==INF){
            cout<<-1<<endl;
            return 0;
        }
        dp[i]=1+res;
        seg.update(i,dp[i]);
    }
    vec ans={0}; ll k=dp[0];
    rep(i,N){
        if(dp[i]==k-1){
            ans.pb(i);
            k--;
        }
    }
    ll m=dp[0];
    rep(i,m-1) cout<<ans[i+1]-ans[i]<<" ";
    cout<<N-ans[m-1]<<endl;
    return 0;
}

