  vector<ll> node;
  bool is_min;
  public:
  SegmentTree(vector<ll> v, bool flag = true) {
    sz = v.size();
    is_min = flag;
    n = 1; while(n < sz) n *= 2;
    node.resize(2*n-1, (is_min ? 1 : -1) * INF64);
    for(int i = 0; i < sz; ++i) node[i+n-1] = v[i];
    for(int i = n-2; i >= 0; --i) {
      if(is_min) node[i] = min(node[2*i+1], node[2*i+2]);
      else node[i] = max(node[2*i+1], node[2*i+2]);
    }
  }
  void update(int x, ll val) {
    x += (n-1);
    node[x] = val;
    while(x > 0) {
      x = (x-1)/2;
      if(is_min) node[x] = min(node[2*x+1], node[2*x+2]);
      else node[x] = max(node[2*x+1], node[2*x+2]);
  }
  }
  //[a, b) 区間の最大／最小値
  ll get_val(int a, int b, int k = 0, int l = 0, int r=-1) {
    if(r < 0) r = n;
    if(r <= a || b <= l) return (is_min ? 1 : -1) * INF64;
    if(a <= l && r <= b) return node[k];
    ll vl = get_val(a, b, 2*k+1, l, (l+r)/2);
    ll vr = get_val(a, b, 2*k+2, (l+r)/2, r);
    if(is_min) return min(vl, vr);
    else return max(vl, vr);
  }
  vector<ll> get_vec() {
    vector<ll> res;
    rep(i, sz) res.push_back(node[i+n-1]);
    return res;
  }
  ll get_node(int x) {
    return node[x+n-1];
  }
};

int main()
{
  int n, m;
  cin >> n >> m;
  string s; cin >> s;

  SegmentTree dp(vector<ll>(n+1, INF));
  dp.update(0, 0);

  set<P> st;
  st.insert(make_pair(0, 0));
  vector<int> num(n+1);

  for(int now = 1; now <= n; ++now) {
    if(s[now] == '1') continue;

    int A = dp.get_val(max(0, now-m), now);
    if(A == INF) {
      cout << -1 << endl;
      return 0;
    }
    auto it = *st.lower_bound(P(A, max(0, now-m)));
    num[now] = now - it.second;
    dp.update(now, A+1);
    st.insert(make_pair(A+1, now));
  }
  vector<int> ans;
  int now = n;
  while(now != 0) {
    ans.push_back(num[now]);
    now -= num[now];
  }
  reverse(ALL(ans));
  line_out(ans);
}

