	int N, M;
	std::string S;
	std::cin >> N >> M;
	std::cin >> S;

	int pos = N;
	std::vector<int> way;

	while (pos != 0) {
		int from;
		for (from = std::max(pos - M, 0); from < pos; ++from) {
			if (S[from] == '0') {
				break;
			}
		}
		if (from == pos) {
			std::cout << "-1\n";
			return 0;
		}
		way.push_back(pos - from);
		pos = from;
	}

	std::reverse(way.begin(), way.end());
	for (int i = 0; i < way.size(); ++i) {
		if (i != 0)
			std::cout << " ";
		std::cout << way[i];
	}
	std::cout << "\n";
}

