ll solve()
{
    int N, M;

    cin >> N >> M;

    string s;
    cin >> s;

    int counterOnes = 0;

    for (int i = 0; i < s.length(); ++i)
    {
        if (s[i] == '1')
        {
            ++counterOnes;
            if (counterOnes >= M)
            {
                cout << -1 << endl;
                return 0;
            }
        }
        else
        {
            counterOnes = 0;
        }
    }

    stack<int> st;
    int index = s.length() - 1;

    while (index > 0)
    {
        for (int j = std::max(0, index - M); j < index; ++j)
        {
            if (s[j] == '1') continue;

            st.push(index - j);
            index = j;
            break;
        }
    }

    while (st.size() > 1)
    {
        cout << st.top() << " ";
        st.pop();
    }

    cout << st.top() << endl;

    return 0;
}

