template <typename T>
struct SegTree {
	T init_val;
	int n;
	vector<T> dat;

	SegTree(int _n, T init_val) : init_val(init_val) {
		n = 1;
		while (n < _n) n *= 2;
		dat.resize(n * 2 - 1, init_val);
	}

	void update(int i, T x) {
		i += n - 1;
		dat[i] = min(dat[i], x);
		while (i > 0) {
			i = (i - 1) / 2;
			dat[i] = min(dat[i * 2 + 1], dat[i * 2 + 2]);
		}
	}

	void set(int i, T x) {
		dat[i + n - 1] = x;
		update(i, x);
	}

	// 探索範囲[a,b), 現在見ているkノード[l,r)
	T query(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = n;

		if (r <= a || b <= l) return init_val;
		if (a <= l && r <= b) return dat[k];
		return min( query(a, b, k * 2 + 1, l, (l + r) / 2), query(a, b, k * 2 + 2, (l + r) / 2, r) );
	}
};

int main() {
	int N, M;
	string S;
	cin >> N >> M;
	cin >> S;

	SegTree<int> seg(N + 1, INF);
	seg.update(0, 0);

	FOR(i, 1, N + 1) {
		if (S[i] == '1') continue;
		int l = i - M;
		chmax(l, 0);
		seg.update(i, seg.query(l, i) + 1);
	}

	int ansl = seg.query(N, N + 1);
	if (ansl == INF) {
		puts("-1");
		return 0;
	}

	vector<int> mn(ansl + 1, INF);
	REP(i, N + 1) {
		int cur = seg.query(i, i + 1);
		if (cur == INF) continue;
		chmin(mn[cur], i);
	}

	vector<int> ans;
	int pos = 0;
	REP(i, ansl - 1) {
		ans.push_back(mn[i + 1] - mn[i]);
		pos = mn[i + 1];
	}
	ans.push_back(N - pos);
	REP(i, ans.size()) printf("%d%c", ans[i], i == ans.size() - 1 ? '\n' : ' ');
	return 0;
}

