    int val[MAXN<<2],l[MAXN<<2],r[MAXN<<2];
    inline int ls(int rt) { return rt << 1; }
    inline int rs(int rt) { return rt << 1 | 1; }
    void pushup(int rt){ val[rt] = min(val[ls(rt)],val[rs(rt)]); }
    void build(int L, int R, int rt){
        l[rt] = L, r[rt] = R;
        if(L+1==R) return;
        int mid =(L+R) >> 1;
        build(L,mid,ls(rt));
        build(mid,R,rs(rt));
    } 
    void update(int pos, int rt, int x){
        if(l[rt]+1==r[rt]){
            val[rt] = x;
            return;
        }
        int mid = (l[rt]+r[rt]) >> 1;
        if(pos<mid) update(pos,ls(rt),x);
        else update(pos,rs(rt),x);
        pushup(rt);
    }
    int querymin(int L, int R, int rt){
        if(l[rt]>=R || L>=r[rt]) return INF;
        if(L<=l[rt] && r[rt]<=R) return val[rt];
        return min(querymin(L,R,ls(rt)),querymin(L,R,rs(rt)));
    }
