const int MAX = 1e5;

int N, M;
string S;
int last_step[MAX];

bool check(int n, int k) {
    while (k) {
        if (n+M >= N) return true;
        n = last_step[n+M];
        k--;
    }
    return false;
}

void solve() {
    REP (i, N+1) {
        if (S[i] == '0') last_step[i] = i;
        else last_step[i] = last_step[i-1];
    }

    if (!check(0, N)) {
        cout << -1 << endl;
        return;
    }

    int ng = 0, ok = N;
    while (ok - ng > 1) {
        int mid = (ok + ng) / 2;
        if (check(0, mid)) ok = mid;
        else ng = mid;
    }

    int steps = ok;
    vi ans(steps);
    int pos = 0;
    REP (i, steps-1) {
        ng = 0, ok = min(N-pos, M);
        while (ok - ng > 1) {
            int mid = (ok + ng) / 2;
            if (check(last_step[pos+mid], steps-1-i)) ok = mid;
            else ng = mid;
        }
        ans[i] = ok;
        pos = last_step[pos+ok];
    }
    ans[steps-1] = N-pos;
    FORE (a, ans) cout << a << endl;
}

