struct monotonic_queue
{
	deque<pair<int, int>> deq;

	void add(int k, int v)
	{
		while (!deq.empty() && deq.back().second >= v)
			deq.pop_back();
		deq.push_back({k, v});
	}

	void remove(int k)
	{
		while (!deq.empty() && deq.front().first <= k)
			deq.pop_front();
	}

	int min()
	{
		return deq.front().S;
	}
};

