	//各マス目に最短何手目で到達できるか
	//x,yの型は、DequeAggregationに格納する型と合わせること
	auto F = [](const ll x, const ll y) {
		return min(x,y);
	};
	DequeAggregation<ll, decltype(F)> qa(F);
	qa.push_back(0);

	vector<ll> step(N+1,INF);
	step[N]=0;
	rep(i,N){
		ll j=N-1-i;
		if(qa.size()>M)qa.pop_front();
		ll t=INF;
		if(S[j]=='0')t=qa.fold_all();
		step[j]=t+1;
		qa.push_back(t+1);
	}

	debug(step);
	if(step[0]>=INF){
		p(-1);return;
	}

	ll stepval=step[0]+1;
	vector<ll> ans;
	rep(i,N+1){
		if(stepval-1 == step[i]){
			stepval--;
			ans.push_back(i);
		}
	}
	debug(ans);

	rep(i,ans.size()-1){
		cout << ans[i+1]-ans[i] << (" \n"[i==ans.size()-2]);
	}
}

