        int index = max(i - m, 0);
        auto it = lower_bound(available.begin(), available.end(), index);
        // not found in [max(i - m, 0), i)
        if (*it >= i) {
            dp[i] = -1;
        } else {
            dp[i] = dp[*it] + 1;
            dp_from[i] = *it;
        }
    }
    if (dp[n] == -1) {
        cout << -1 << endl;
    } else {
        vector<int> ans;
        int index = n;
        ans.push_back(index);
