    int n, m;
    cin >> n >> m;
    string s;
    cin >> s;
    vector<int> id(n + 1, -1), dp(n + 1, INF);
    Segtree<int> seg(n + 1, INF);
    seg.upd(0, 0);
    for (int i = 1; i <= n; i++) {
        if (s[i] == '1') {
            continue;
        }
        dp[i] = seg.get(max(0, i - m), i) + 1;
        if (dp[i] != INF + 1) {
            int fr = seg.find(max(0, i - m), i, dp[i] - 1);
            id[i] = fr;
            seg.upd(i, dp[i]);
        } else {
            dp[i] = INF;
        }
    }
    if (dp[n] == INF) {
        cout << -1 << endl;
        return 0;
    }
    int k = n;
    vector<int> v;
    while (k != 0) {
        v.push_back(k - id[k]);
