template<typename T>
struct LazySegTree {
	vector<T> node, lazy;
	vector<bool> done;
	int n;
	T init_val;

	LazySegTree(int _n, T init_val) : init_val(init_val) {
		n = 1;
		while (n < _n) n *= 2;
		node.resize(n * 2 - 1, init_val);
		lazy.resize(n * 2 - 1, init_val);
		done.resize(n * 2 - 1, true);
	}

	void eval(int k, int l, int r) {
		if (done[k]) return;
		chmin(node[k], lazy[k]);
		// node[k] = lazy[k];

		if (r - l > 1) {
			chmin(lazy[k * 2 + 1], lazy[k]);
			chmin(lazy[k * 2 + 2], lazy[k]);
			// lazy[k * 2 + 1] = lazy[k];
			// lazy[k * 2 + 2] = lazy[k];
			done[k * 2 + 1] = false;
			done[k * 2 + 2] = false;

		}
		done[k] = true;
	}

	void update(int a, int b, T x, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = n;
		eval(k, l, r);

		if (a >= r || b <= l) return;
		if (a <= l && r <= b) {
			chmin(lazy[k], x);
			// lazy[k] = x;
			done[k] = false;
			eval(k, l, r);
		}
		else {
			update(a, b, x, k * 2 + 1, l, (l + r) / 2);
			update(a, b, x, k * 2 + 2, (l + r) / 2, r);
			node[k] = min(node[k * 2 + 1], node[k * 2 + 2]);
		}
	}

	T query(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = n;
		eval(k, l, r);

		if (a >= r || b <= l) return init_val;
		if (a <= l && r <= b) return node[k];

		T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return min(vl, vr);
	}
};

int main() {
	int N, M;
	string S;
	cin >> N >> M;
	cin >> S;

	LazySegTree<pii> seg(N + 1, pii(INF, 0));
	seg.update(0, 1, pii(0, -1));

	REP(i, S.size()) {
		if (S[i] == '1') continue;
		int r = i + M;
		chmin(r, N);
		seg.update(i + 1, r + 1, pii(seg.query(i, i + 1).fi + 1, i));
	}

	int ansl = seg.query(N, N + 1).fi;
	if (ansl == INF) {
		puts("-1");
		return 0;
	}

	vector<int> ans;
	int pos = N;
	while (pos != 0) {
		int npos = seg.query(pos, pos + 1).se;
		ans.push_back(pos - npos);
		pos = npos;
	}
	reverse(ALL(ans));
	REP(i, ans.size()) printf("%d%c", ans[i], i == ans.size() - 1 ? '\n' : ' ');
	return 0;
}

