typedef long long ll;
typedef pair<ll,ll> P;
struct segtree{
private:
  vector<P> node;
  int siz;
public:
  segtree(int n){
    siz=1;
    while(siz<=n) siz*=2;
    node.resize(siz*2+1,P(0,0));
  }
  void upd(int pos,P x){
    pos+=siz-1;
    node[pos]=x;
    while(pos>0){
      pos=(pos-1)/2;
      node[pos]=max(node[pos*2+1],node[pos*2+2]);
    }
  }
  P get_max(int a,int b,int pos,int l,int r){
    if(a<=l&&r<=b) return node[pos];
    if(r<=a||b<=l) return P(0,0);
    int mid=(l+r)/2;
    P lb=get_max(a,b,pos*2+1,l,mid);
    P rb=get_max(a,b,pos*2+2,mid,r);
    return max(lb,rb);
  }
  P max_q(int a,int b){
    return get_max(a,b,0,0,siz);
  }
};
