#include <boost/multiprecision/cpp_int.hpp>
namespace mp = boost::multiprecision;

ll dp[100005];
mp::cpp_int dp2[100005];

void solve()
{
    IN(n, m);
    string s; cin >> s;
    fill(dp, dp+100005, 1LL << 60);
    fill(dp2, dp2+100005, 1LL << 60);
    dp[0] = 0;
    dp2[0] = 0;
    rep(i, n)
    {
        if (s[i] == '1') continue;
        rep(j, m)
        {
            if (i+j+1>n) break;
            if (s[i+j+1] == '1') continue;
            if (dp[i+j+1] >= dp[i]+1)
            {
                dp[i+j+1] = dp[i]+1;
                chmin(dp2[i+j+1], (mp::cpp_int)(dp2[i] * m + j));
            }
        }
    }
    auto k = dp2[n];
    V<mp::cpp_int> vs;
    while (k > 0)
    {
        vs.push_back(k % m);
        k -= k % m;
        k /= m;
    }
    for (auto itr = vs.rbegin(); itr != vs.rend(); ++itr)
    {
        if (*itr == 0) continue;
        cout << *itr+1 << " ";
    }
}

int main()
{
    cin.tie(0); cout.tie(0);
    ios::sync_with_stdio(false);
    cout << setprecision(numeric_limits<double>::max_digits10);

    solve();

    return 0;
}

