    int nn = n;
    init(n);


    string s; cin >> s;
    update(0, 0);
    srep(i,1,nn+1){
        if(s[i] == '1')continue;
        int l = max(0, i - m);
        int cnt = query(l, i, 0, 0, n);
        update(i, cnt + 1);
    }

    int ans = query(nn, nn+1, 0, 0, n);
    if(ans > 1001001)ans = -1;
    if(ans == -1){
        cout << ans << endl;
        return 0;
    }
    int v[ans+1];
    v[ans] = nn;
    drep(i,nn+1){
        int tmp = query(i, i+1, 0, 0, n);
        if(tmp < ans){
            if(v[tmp + 1] - i <= m){
                v[tmp] = i;
            }
        }
    }
    // rep(i,ans+1)cout << v[i] << ' ';
    // cout << endl;
    rep(i, ans){
        cout << v[i+1] - v[i];
        if(i == ans - 1){
            cout << endl;
        }else{
            cout << ' ';
        }
    }
    return 0;
}

