int main() {
    int64_t N, M;
    cin >> N >> M;
    string S;
    cin >> S;

    struct Cost {
        Cost() : cost(LLONG_MAX) {}
        Cost(int64_t v) : cost(v) {}
        int64_t cost;
        vector<int64_t> order;
        bool operator<(const Cost& rhs) const {
            return (cost != rhs.cost ? cost < rhs.cost : order < rhs.order);
        }
        bool operator>(const Cost& rhs) const {
            return (cost != rhs.cost ? cost > rhs.cost : order > rhs.order);
        }
    };

    vector<Cost> cost(N + 1);
    struct Element {
        int64_t node;
        Cost cost;
        bool operator<(const Element& rhs) const {
            return cost < rhs.cost;
        }
        bool operator>(const Element& rhs) const {
            return cost > rhs.cost;
        }
    };
    priority_queue<Element, vector<Element>, greater<Element>> pq;

    cost[0].cost = 0;
    pq.push({ 0, Cost(0) });
    while (!pq.empty()) {
        Element t = pq.top();
        pq.pop();
        if (t.cost > cost[t.node]) {
            continue;
        }

        if (cost[N].cost != LLONG_MAX) {
            if (t.cost.cost >= cost[N].cost) {
                continue;
            }
        }

        for (int64_t i = M; i >= 1; i--) {
            Cost new_cost;
            new_cost.cost = t.cost.cost + 1;
            new_cost.order = t.cost.order;
            new_cost.order.push_back(i);

            int64_t next_node = t.node + i;

            if (next_node > N) {
                continue;
            }

            if (S[next_node] == '1') {
                continue;
            }

            if (new_cost < cost[next_node]) {
                cost[next_node] = new_cost;
                pq.push({ next_node, new_cost });
            }
        }
    }

    if (cost[N].cost == LLONG_MAX) {
        cout << -1 << endl;
    } else {
        for (int64_t i = 0; i < cost[N].order.size(); i++) {
            cout << cost[N].order[i] << " \n"[i == cost[N].order.size() - 1];
        }
    }
}

