  bool x = 0;
  ll cnt = 0;
  rep(i, S.size()){
    if(x == 0 && S[i] == '0'){
      cnt++;
    }else if(x == 0 && S[i] == '1'){
      mp.pb({0, cnt});
      cnt = 1;
      x = 1;
    }else if(x == 1 && S[i] == '0'){
      mp.pb({1, cnt});
      cnt = 1;
      x = 0;
    }else if(x == 1 && S[i] == '1'){
      cnt++;
    }
  }
  if(cnt != 0){
    mp.pb({(ll)x, cnt});
  }

  ll M = mp.size();
  vector<ll> sum(M, 0);
  sum[0] = mp[0].s - 1;
  rep(i, M){
    if(i == 0) continue;
    sum[i] = mp[i].s + sum[i-1];
  }


  vector<ll> ans;
  ll now = 0;
  while(now < N){
