void solve() {
    i64 N, M;
    cin >> N >> M;
    edamat::directed_graph<int> g(N + 1);
    string S;
    cin >> S;
    for(int i = 1; i < N + 1; i++) {
        g.add_edge(i, i - 1, 0);
    }
    for(int i = 0; i < N + 1; i++) {
        if(S[i] != '1') {
            g.add_edge(i, min(i + M, N), 1);
        }
    }
    auto root = g.dijkstra(0);
    if(root.empty()) {
        cout << -1 << endl;
        return;
    }
    vector<int> tmp;
    int t = N;
    tmp.emplace_back(t);
    while(t != 0) {
        t = root[t];
        tmp.emplace_back(t);
    }
    reverse(tmp.begin(), tmp.end());
    // cout << tmp << endl;
    vector<int> ans;
    for(int i = 0; i < tmp.size() - 1; i++) {
        if(tmp[i] < tmp[i + 1]) {
            ans.emplace_back(tmp[i]);
        }
    }
    // cout << ans << endl;
    ans.emplace_back(N);
    rep(i, ans.size() - 1) { cout << ans[i + 1] - ans[i] << " "; }
    cout << endl;
}

