template<class T>bool chmin(T &a, const T &b) { if (a>b) { a=b; return 1; } return 0; }

using Lint=long long;
const int INF=1e9;

template<typename T> class LazySegmentTree
{
 private:
    int n;
    vector<T> node,lazy;
 public:
    LazySegmentTree(int sz,T init){
        n=1;
        while(n<sz) n*=2;
        node.assign(2*n-1,init);
        lazy.assign(2*n-1,-1);
    }
    void update(int a,int b,int x,int k,int l,int r){
        if(a<=l and r<=b) node[k]=lazy[k]=x;
        else{
            if(lazy[k]!=-1) push(k),lazy[k]=-1;
            if(check(a,b,l,(l+r)/2)) update(a,b,x,2*k+1,l,(l+r)/2);
            if(check(a,b,(l+r)/2,r)) update(a,b,x,2*k+2,(l+r)/2,r);
            node[k]=min(node[2*k+1],node[2*k+2]);
        }
    }
    T get(int a,int b,int k,int l,int r){
        if(a<=l and r<=b) return node[k];
        else{
            if(lazy[k]!=-1) push(k),lazy[k]=-1;
            T res=INT_MAX;
            if(check(a,b,l,(l+r)/2)) res=min(res,get(a,b,2*k+1,l,(l+r)/2));
            if(check(a,b,(l+r)/2,r)) res=min(res,get(a,b,2*k+2,(l+r)/2,r));
            return res;
        }
    }
    void push(int k){
        node[2*k+1]=node[2*k+2]=lazy[k];
        lazy[2*k+1]=lazy[2*k+2]=lazy[k];
    }
    bool check(int a,int b,int l,int r){
        return max(a,l)<min(b,r);
    }
    void update(int a,int b,int x){ update(a,b,x,0,0,n); }
    T get(int a,int b){ return get(a,b,0,0,n); }
};

signed main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N,M; cin>>N>>M;
    string s; cin>>s;

    LazySegmentTree<int> seg(N+1,INF);
    seg.update(N,N+1,0);
    int R=N;
    for(int i=N;i>=1;i--) if(s[i]=='0'){
        if(seg.get(i,i+1)>=INF) continue;
        int L=max(0LL,i-M);
        // cout<<L<<' '<<R<<' '<<seg.get(i,i+1)<<endl;
        if(L<=R) seg.update(L,R,seg.get(i,i+1)+1);
        chmin(R,L);
        // for(int i=0;i<=N;i++) cout<<seg.get(i,i+1)<<' '; cout<<endl;
    }

    int mn=seg.get(0,1);
    if(mn>=INF){
        cout<<-1<<endl;
        return 0;
    }
    vector<int> ans(mn,-1);
    for(int i=0;i<=N;i++) if(s[i]!='1'){
        int x=seg.get(i,i+1);
        if(ans[x]==-1) ans[x]=i;
    }

    for(int i=mn;i>=1;i--){
        cout<<ans[i-1]-ans[i]<<' ';
    }
    cout<<endl;
    return 0;
}

