  cin >> N >> M;
  string S;
  cin >> S;
  vector<int> DP(N + 1, INT_MAX);
  DP[0] = 0;
  rep(i, N) {
    if (S[i] == '1') continue;
    rep(j, M) {
      int next = i + j + 1;
      if (next <= N && S[next] != '1') {
        DP[next] = min(DP[next], DP[i] + 1);
      }
    }
  }
  if (DP[N] == INT_MAX) {
    cout << -1 << endl;
    return 0;
  }

  // replay
  vector<int> hist(DP[N] + 1);
  hist[DP[N]] = N;
  for (int i = N - 1; i >= 0; --i) {
    if (0 <= DP[i] && DP[i] < DP[N]) {
      hist[DP[i]] = i;
    }
  }

  rep(i, DP[N]) {
    if (i != 0) cout << " ";
    cout << hist[i + 1] - hist[i];
  }
  cout << endl;
  return 0;
