template<class Monoid>
class SegmentTree {

public:
    /**
     * @param N size
     * @param e identity element
     * @param operation operation to merge `data`
     * @param updater operation to update `data`
     */
    SegmentTree(size_t N, Monoid e, function<Monoid(Monoid, Monoid)> operation,
                function<Monoid(Monoid, Monoid)> updater)
            : e(e), operation(operation), updater(move(updater)) {
        n = 1;
        while (n < N) {
            n *= 2;
        }
        data = vector<Monoid>(2 * n - 1, e);
        for (int i = n - 2; i >= 0; i--) {
            data[i] = operation(data[2 * i + 1], data[2 * i + 2]);
        }
    }

    /**
     * iの値をxに更新 ( 0-indexed )
     */
    void update(int i, Monoid x) {
        i += n - 1;
        data[i] = updater(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    /**
     * [a, b)の区間でクエリを実行
     */
    Monoid query(int a, int b) {
        return query(a, b, 0, 0, n);
    }

    /**
     * 添字でアクセス( 0-indexed )
     */
    Monoid operator[](int i) {
        return data[i + n - 1];
    }

private:
    int n;
    vector<Monoid> data;
    Monoid e;
    function<Monoid(Monoid, Monoid)> operation;
    function<Monoid(Monoid, Monoid)> updater;

    Monoid query(int a, int b, int k, int l, int r) {
        // 交差しない
        if (r <= a || b <= l) return e;
        // 区間 [a, b) に l, r が含まれる
        if (a <= l && r <= b) return data[k];
        // 左の子
        Monoid c1 = query(a, b, 2 * k + 1, l, (l + r) / 2);
        // 右の子
        Monoid c2 = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return operation(c1, c2);
    }
};

void Main() {
    ll N, M;
    cin >> N >> M;
    string S;
    cin >> S;

    SegmentTree<ll> segmentTree(N + 1, INF, [](ll a, ll b) { return min(a, b); }, [](ll a, ll b) { return b; });

    segmentTree.update(N, 0);
    rrep(i, N - 1, 0) {
        if (S[i] == '0') {
            segmentTree.update(i, segmentTree.query(i + 1, min(N + 1, i + M + 1)) + 1);
        }
    }
    if (segmentTree.query(0, 1) == INF) {
        cout << -1 << '\n';
        return;
    }
    ll target = segmentTree.query(0, 1);
    vector<ll> ans;
    ll start = 0;
    while (start < N) {
        rep2(j, start + 1, min(N, start + M) + 1) {
            if (segmentTree.query(j, j + 1) == target - 1) {
                target--;
                start = j;
                ans.push_back(j);
                break;
            }
        }
    }
    rep(i, ans.size()) {
        if (i == 0) {
            cout << ans[i] << ' ';
        } else {
            cout << ans[i] - ans[i - 1] << ' ';
        }
    }
    cout << '\n';
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);
    Main();
    return 0;
}

