struct SegmentTree {
    //SegmentTree seg( vector<ll>(l + 5, INF) );
private:
    ll n;
    vector<P> node;

public:
    SegmentTree(vector<P> v) {
        ll sz = v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1, P(INF,-1));
        for(int i=0; i<sz; i++) node[i+n-1] = v[i];
        for(int i=n-2; i>=0; i--) node[i] = min(node[2*i+1], node[2*i+2]);
    }

    void update(ll x, ll val) {
    //a[x]をyに更新(小さい方に更新ではないので注意)
        x += (n - 1);
        node[x].first = val;
        while(x > 0) {
            x = (x - 1) / 2;
            node[x] = min(node[2*x+1], node[2*x+2]);
        }
    }

    P getmin(int a, int b, int k=0, int l=0, int r=-1) {
    //[a,b)の最小値を得る
        if(r < 0) r = n;
        if(r <= a || b <= l) return P(INF,-1);
        if(a <= l && r <= b) return node[k];

        P vl = getmin(a, b, 2*k+1, l, (l+r)/2);
        P vr = getmin(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }
};

