/* 
read_graph(n, m, graph, cost, directed, offset)
    cost: if link cost is fixed, put positive integer
          otherwise -1
    directed: if directed true, olse false
    offset: if the given vertex is 1-indexed, -1.
*/

void solve(){
    in3(n, m, s);

    set<ll> ss;

    ss.insert(INF);
    rep(i, n + 1)
        if (s[i] == '0') ss.insert(i);

    vl dp(n + 1, INF), path(n + 1, -1);
    dp[0] = 0;
    For(i, 1, n + 1){
        auto it = ss.lower_bound(i - m);
        if (*it >= i) continue;
        dp[i] = dp[*it] + 1;
        path[i] = *it;
    }

    if (dp[n] == INF) {prl(-1); return;}
    vl ans; ll cur = n, nxt;
    while (true){
        ans.pb(cur);
        nxt = path[cur];
        if (nxt == -1) break;
        swap(cur, nxt);
    }

    reverse(all(ans));
    rep(i, ans.size() - 1)
        prs(ans[i + 1] - ans[i]);
    prl("");
}

void test(ll num = 0, bool verbose = false){
    rep(i, max(1LL, num)){
        ll t = clock();
        if (verbose) prl4("\n#####", i + 1, "#####", "\n## Answer ##");
        solve();
        if (verbose) {prl(""); prl_time(t);}
    }
}

