vector<int> f() {
	int N, M; cin >> N >> M;
	string s; cin >> s;
	vector<priority_queue<int, vector<int>, greater<int>>> q(N+1);
	q[0].push(N);
	vector<int> to(N+1, -1);
	int c = 0;
	rrep(i, N) {
		if (s[i] == '1') continue;
		while (c < q.size()) {
			while (!q[c].empty() && i + M < q[c].top()) {
				q[c].pop();
			}
			if (q[c].empty()) {
				c++;
				continue;
			}
			q[c+1].push(i);
			to[i] = q[c].top();
			break;
		}
		if (c == q.size()) return {};
	}
	if (q[c+1].top() != 0) return {};
	vector<int> res{0};
	int n = 0;
	while (n >= 0) {
		res.push_back(to[n]);
		n = to[n];
	}
	res.pop_back();
	return res;
}


