  vi ans;
  for(int i = n; i > 0;) {
    bool ok = false;
    rrep(j, 1, m + 1)if(i >= j && s[i - j] == '0') {
      ans.push_back(j);
      ok = true;
      i -= j;
      break;
    }
    if(!ok) {
      COUT(-1);
      return;
    }
  }
  rev(ans);
  CVEC(ans);
}


