	REP(i, S.size() + 1)dp[i] = -1;
	dp[0] = 0;

	auto f = [](int a, int b) {return min(a, b); };
	SegmentTree<int>seg(N, INF, f);
	seg.update(0, 0);
	int nxt = 1;
	int pre = 0;
	bool ok = true;
	while (ok) {
		int nxt2 = 0;
		ok = false;
		FOR(i, nxt, nxt + M) {
			if (i > N)continue;
			if (S[i] == '1')continue;

			ok = true;
			nxt2 = i + 1;
			int l = min(max((ll)0, i - M), pre);
			int r = nxt;
			int from = seg.query(l, r);
			dp[i] = i - from;
			seg.update(i, i);
		}
		pre = nxt;
		nxt = nxt2;
	}
	vector<int>ans;
	int now = N;
	if (dp[N] == -1) { print(-1); return; }
	while (now > 0) {
		ans.push_back(dp[now]);
		now -= dp[now];
	}
	VREVERSE(ans);
	REP(i, ans.size()) {
		pe(ans[i]);
	}cout << endl;
}

