const int MAXN = 2e5 + 1;
const ll inf = 1e12;
vector<ll> arr(0);
vector<ll> prefsumm(0);
map<ll, int> ost;
vector<ll> dp(1e5 + 1, inf);
vector<int> where(1e5 + 1, 0);
vector<pair<ll, int>> t(4e5 + 1);

void build(int v, int vl, int vr) {
    if (vl == vr) {
        t[v] = {dp[vl], vl};
        return;
    }
    int tmp = (vl + vr) / 2;
    build(2 * v, vl, tmp);
    build(2 * v + 1, tmp + 1, vr);
    if (t[2 * v].first <= t[2 * v + 1].first) {
        t[v] = make_pair(t[2 * v].first, t[2 * v].second);
    } else {
        t[v] = make_pair(t[2 * v + 1].first, t[2 * v + 1].second);
    }
}

pair<ll, int> query(int v, int vl, int vr, int l, int r) {
    if (l > r) return {inf, MAXN};
    if (vl == l && vr == r) {
        return t[v];
    }
    int tmp = (vl + vr) / 2;
    pair<ll, int> fi = query(2 * v, vl, tmp, l, min(r, tmp));
    pair<ll, int> se = query(2 * v + 1, tmp + 1, vr, max(l, tmp + 1), r);
    if (fi.first <= se.first) {
        return fi;
    } else {
        return se;
    }
}

void update(int v, int vl, int vr, int pos, ll val) {
    if (vl == vr) {
        t[v] = {val, pos};
        return;
    }
    int tmp = (vl + vr) / 2;
    if (pos <= tmp) {
        update(2 * v, vl, tmp, pos, val);
    } else update(2 * v+1,tmp+1,  vr, pos, val);
    if (t[2 * v].first <= t[2 * v + 1].first) {
        t[v] = make_pair(t[2 * v].first, t[2 * v].second);
    } else {
        t[v] = make_pair(t[2 * v + 1].first, t[2 * v + 1].second);
    }
}

