    int n, m;
    cin >> n >> m;
    string s;
    cin >> s;
    if(s[n]=='1'){
        cout<<-1;
        return;
    }
    dp[n] = 0;
    build(1,0,n);
    //cout<<"ok"<<endl;
    update(1,0,n, n, dp[n]);
    //cout<<"ok2"<<endl;
    for (int i = n - 1; i >= 0; i--) {
        if (s[i] == '1') continue;
        //cout<<"ok3"<<endl;
        pair<ll , int> left = query(1, 0, n, i + 1, min(i + m, n));
        //cout<<"ok4"<<endl;
        if (left.first == inf) continue;
        dp[i] = left.first + 1;
        where[i] = left.second;
        update(1, 0, n, i, dp[i]);
        //cout<<i<<endl;
    }
    if(dp[0]==inf) cout<<-1;
    else{
        int i=0;
        while(i!=n){
            cout<<where[i]-i<<" ";
            i=where[i];
        }
    }

}

