// ゴールから逆算する。
// ゴールからすると、一番遠い距離に行くのが手数を少なくするためには最善。
// なので、ゴールからMの距離から順に到着できるところを探す。
// M 以内にスタート地点が来た場合、一手前に戻ってスタート地点から
// 2手で進む場合に1手目が一番小さい数字になる場合を探す？

#include <bits/stdc++.h>
#define REP(i,n) for(int i=0;i<(n);++i)
#define REPI(i,f,n) for(int i=(f);i<(n);++i)
using namespace std;
