namespace _segment_tree_detail {
  template < class Seg, class Value = typename Seg::value_type >
  struct entry {
    Seg * ptr;
    std::size_t i;
    entry& operator=(int);
    operator Value();
  };
}

template<typename Value, typename BinaryOp>
class segment_tree {
  public:
    using this_type = segment_tree< Value, BinaryOp >;
    using value_type = Value;
    using entry_type = _segment_tree_detail::entry< this_type >;

  private:
    friend class _segment_tree_detail::entry< this_type >;

    int sz, n, N;
    BinaryOp op;
    Value id;
    std::vector<Value>  table;

    auto& op_eq(Value& x, Value y) const { return x = op(x, y); }

    void merge(int u)
      { table.at(u) = op(table.at(2 * u), table.at(2 * u + 1)); }

    Value query_impl(int l, int r, int k, int L, int R) const {
      return l <= L && R <= r
        ? table.at(k)
        : R <= l || r <= L
        ? id
        : op(query_impl(l, r, 2 * k, L, (L + R) / 2), query_impl(l, r, 2 * k + 1, (L + R) / 2, R));
    }

  public:
    segment_tree(int sz, BinaryOp op, Value id):
      sz    (sz),
      n     (std::pow(2, int(std::log2(2 * sz - 1)))),
      N     (n * 2),
      op    (op),
      id    (id),
      table (N, id)
      {}

    auto at(std::size_t i) { return entry_type{this, i}; }
    auto at(std::size_t i) const { return entry_type{this, i}; }

    auto collect() const {
      auto ret = std::vector<Value>(sz);
      for (auto i = 0; i < sz; i++)
        { ret.at(i) = at(i); }
      return ret;
    }

    auto query(int l, int r) const
      { return query_impl(l, r, 1, 0, n); }

    void build()
      { for (auto i = 1; i < n; i++) merge(i); }
};

template<typename Value, typename BinaryOp>
auto make_segment_tree(int sz, BinaryOp op, Value id)
  { return segment_tree<Value, BinaryOp>(sz, std::move(op), id); }

namespace _segment_tree_detail {
  template < class Seg, class Value >
  entry< Seg, Value >& entry< Seg, Value >::operator=(int x) {
    ptr->table.at(ptr->n + i) = x;
    for (i += ptr->n, i /= 2; i > 0; i /= 2) ptr->merge(i);
    return *this;
  }
  template < class Seg, class Value >
  entry< Seg, Value >::operator Value() {
    return ptr->table.at(ptr->n + i);
  }
}

