using namespace std;
typedef long long ll;

const int INF = 100000000;

int main() {
  int N, M;
  cin >> N >> M;
  string S;
  cin >> S;

  string answer[N + M + 10];
  int dp[N + M + 10];
  for (int i = 0; i < N + M + 10; ++i) {
    dp[i] = INF;
    answer[i] = "";
  }
  dp[0] = 0;
  bool success = false;

  for (int i = 0; i < S.size() && !success; ++i) {
    if (S[i] == '1') continue;

    for (int m = 1; m <= M; ++m) {
      int j = i + m;

      if (S[j] == '1') continue;
      if (dp[j] != INF) continue;

      string com = answer[i] + to_string(m);

      if (dp[j] > dp[i] + m) {
        if (answer[i] == "") {
          answer[j] = com;
        } else if (answer[j] == "") {
          answer[j] = com;
        }

        if (j == N) success = true;
      }
      dp[j] = min(dp[j], dp[i] + m);
    }
  }

  if (success) {
    string ans = answer[N];

    for (int i = 0; i < ans.size(); ++i) {
      cout << ans[i];
      if (i != ans.size() - 1) cout << " ";
    }
    cout << endl;
  } else {
    cout << -1 << endl;
  }

  return 0;
}

