int dp[100010];
int main() {
  int n, m;
  cin >> n >> m;
  string s;
  cin >> s;
  int r = 0;
  dp[0] = 0;
  while (r < n) {
    // cout << r  << " " << dp[r] << endl;
    int nr = r;
    for (int i = 1; i <= m; ++i) {
      if (r+i > n) break;
      if (s[r+i] == '1') continue;
      dp[r+i] = dp[r]+1;
      nr = r+i;
    }
    if (r == nr) {
      cout << "-1" << endl;
      return 0;
    }
    r = nr;
  }
  int l = n;
  vector<int> ans;
  while (l > 0) {
    int bl = l;
    for (int i = 1; i <= m; ++i) {
      if (l-i < 0) break;
      if (s[l-i] == '1') continue;
      if (dp[l-i] < dp[l]) {
        bl = l-i;
      }
    }
    ans.push_back(l-bl);
    l = bl;
  }
  for (int i = ans.size()-1; i >= 0; --i) {
    cout << ans[i] << " ";
  }
  cout << endl;
}

