  } else {
    //順DP
    vector<int> DP1(N+1,N+1);
    DP1[0] = 0;
    for (int i = 0; i < N + 1; i++){
      if (G[i]) DP1[i] = -1;
    }
    bool flg = false;
    for (int i = 0; i < N + 1; i++){
      if (DP1[i] == N+1 && i > 0){
        flg = true;
        break;
      }
      if (DP1[i] == -1) continue;
      for (int j = 1; j <= M; j++){
        if (i + j <= N){
          if (DP1[i+j] != -1){
            DP1[i+j] = DP1[i]+1;
          }
        } else {
          break;
        }
      }
    }
    if (flg){
      cout << -1;
    } else {
      int MV = DP1[N];
      //逆DP
      vector<int> DP2(N+1,N+1);
