class FSugoroku {
public:
	void solve(std::istream& in, std::ostream& out) {
	    int n, m;
	    string s;
	    in >> n >> m >> s;

	    set<int> st;
	    st.insert(n+1);
	    vl dp(n+1, inf);
	    dp[n] = 0;
//	    vl res(n+1);
	    for(int i=n; i>=0; i--){
	        if(s[i] == '1') continue;
	        auto it = st.upper_bound(m+i);
	        if(it != st.begin()) --it;
	        if(*it <= m+i) {
	            chmin(dp[i], dp[*it]+1);
//	            if(dp[i] >= dp[*it] + 1){
//	                dp[i] = dp[*it]+1;
//	                res[i] = *it-i;
//	            }
	        }
	        st.insert(i);
	    }

	    //debug.print(dp);

	    if(dp[0] == inf){
	        out << -1 << enl;
	        return;
	    }

	    vi res;
	    int now = dp[0], cur = 1, last = 0;
	    while(cur <= n){
	        if(dp[cur] == now-1){
	            res.push_back(cur-last);
	            last = cur;
	            now--;
	        }
	        cur++;
	    }

	    for(auto& e : res) out << e << " ";
	    out << enl;
	}
};


