void solve() {
    int n, m;
    cin >> n >> m;

    string s;
    cin >> s;

    vector<int> prev(n+1, -1);
    vector<int> dp(n+1, -1);
    dp[0] = 0;

    priority_queue<pii, vecii, greater<pii>> pq;
    pq.push({0,0});
    for (int i=1; i<=n; ++i) {
        while (!pq.empty() && i - pq.top().se > m) pq.pop();

        if (pq.empty()) {
            cout << -1 << endl;
            return;
        }
        if (s[i]=='0') {
            pii nearest = pq.top();
            dp[i] = nearest.fi + 1;
            prev[i] = nearest.se;
            pq.push({dp[i], i});
        }
    }

    if (dp[n]<0) {
        cout << -1 << endl;
        return;
    }

    stack<int> ans;
    int cur = n;
    while (prev[cur]>=0) {
        ans.push(cur-prev[cur]);
        cur = prev[cur];
    }
    while (!ans.empty()) {
        cout << ans.top() << " ";
        ans.pop();
    }
    cout << endl;
}

