	Node ():v(inf),p(0),ls(NULL),rs(NULL) {}
	void pushup ()
	{
		v=min(ls->v,rs->v);
		if ( v==rs->v ) p=rs->p;
		if ( v==ls->v ) p=ls->p;
	}
};
