void update(int v, int i, int j, int x, int y)
{
    if(i == j and j == x) { t[v] = y ; return ; }
    if(x < i or x > j) return ;
    int mid = i+j >> 1 ;
    update(v*2, i, mid, x, y); update(v*2 + 1, mid + 1, j, x, y);
    t[v] = min(t[v*2], t[v*2 + 1]);
}

int get(int v, int i, int j, int l, int r)
{
    if(i > r or j < l) return 1e9;
    if(i >= l and j <= r) return t[v] ;
    int mid = i+j  >> 1 ;
    return min(get(v*2, i, mid, l, r), get(v*2 + 1, mid + 1, j, l, r));
}

