// http://beet-aizu.hatenablog.com/entry/2017/09/10/132258
template <typename T, typename E>
struct SegmentTree {
    using F = function<T(T, T)>;
    using G = function<T(T, E)>;
    int n;                       // 葉の数
    F f;                         // 二項演算
    G g;                         // 点更新処理
    T d1;                        // 単位元
    vector<T> dat;               // データ
    SegmentTree(){};
    // 葉の数、二項演算、点更新処理、単位元、初期配列
    // 二項演算はa.(b.c) == (a.b).c && d1.a == a.d1 == aが必要
    SegmentTree(int n_, F f, G g, T d1, vector<T> v = vector<T>())
        : f(f), g(g), d1(d1) {
        init(n_);
        if(n_ == (int)v.size()) build(n_, v);
    }
    void init(int n_) {
        n = 1;
        while(n < n_) n *= 2;
        dat.clear();
        dat.resize(2 * n - 1, d1);
    }
    void build(int n_, vector<T> v) {
        for(int i = 0; i < n_; i++)
            dat[i + n - 1] = v[i];
        for(int i = n - 2; i >= 0; i--)
            dat[i] = f(dat[i * 2 + 1], dat[i * 2 + 2]);
    }
    void update(int k, E a) {
        k += n - 1;
        dat[k] = g(dat[k], a);
        while(k > 0) {
            k = (k - 1) / 2;
            dat[k] = f(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }
    // [a, b)
    inline T query(int a, int b) {
        T vl = d1, vr = d1;
        for(int l = a + n, r = b + n; l < r; l >>= 1, r >>= 1) {
            if(l & 1) vl = f(vl, dat[(l++) - 1]);
            if(r & 1) vr = f(dat[(--r) - 1], vr);
        }
        return f(vl, vr);
    }
};

