void upd(ll pos,ll x,ll v=1,ll tl=0,ll tr=n){
	if(tr<pos||pos<tl){
		return;
	}
	if(tl==tr){
		t[v]=x;
		return;
	}
	ll tm=(tl+tr)/2;
	upd(pos,x,v*2,tl,tm);
	upd(pos,x,v*2+1,tm+1,tr);
	t[v]=min(t[v*2],t[v*2+1]);
}
ll get(ll l,ll r,ll v=1,ll tl=0,ll tr=n){
	if(r<tl||tr<l){
