template <typename A>
string to_string(vector<A> v) {
    bool first = true;
    string result = "[";
    for (A i : v) {
        if (!first) result += ", ";
        first = false;
        result += to_string(i); 
    }
    return result + "]";
}

template <typename A>
string to_string(A x[], signed n) {
    string result = "{";
    for (signed i=0; i<n; ++i) {
        if (i!=0) result += ", ";
        result += to_string(x[i]); 
    }
    return result + "}";
}

signed main() {
    ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);

    int n,m;
    cin >> n >> m;
    char s[n+1];
    cin >> s;
    int nextZero[n+1], z;
    for (int i=0; i<=n; ++i) {
        if (s[i] == '0') z = i;
        nextZero[i] = z;
    }

    vector<int> dp[n+1];
    bool failed = false;
    for (int x=n-1; x>=0; --x) {
        if (s[x] == '1') continue;
        int leap = nextZero[min(x+m, n)];
        if (leap == x) {
            cout << -1;
            failed = true;
            break;
        }

        int keep = dp[leap].size();

        int k=leap;
        for (int b=m; b>=1; b/=2) {
            while (k-b>=0) {
                int check = nextZero[k-b];
                if (check <= x || dp[check].size() != keep) break;
                k = check;
            }
        }
        vector<int> sol = dp[k];
        sol.push_back(k-x);
        dp[x] = sol;
        //cout << x << " has " << to_string(dp[x]) << endl;
    }
    if (!failed) {
        reverse(dp[0].begin(), dp[0].end());
        REP(i, dp[0].size()) cout << dp[0][i] << ' ';
    }
}

