signed main() {
	INIT;

	VAR(int, n, m);
	VAR(std::string, s);

	SegmentTree<Monoid::min<int>> st(n + 1);
	st.update(n, 0);

	RREP(i, n) {
		if (s[i] == '1') continue;
		st.update(i, st.query(i + 1, std::min(n + 1, i + m + 1)) + 1);
	}

	if (st[0] >= INFINT) {
		OUT(-1)BR;
		return 0;
	}
	int rest = st[0];
	int now = 0;
	while (now < n) {
		int p = now + 1;
		while (true) {
			if (st[p] == rest - 1) {
				OUT(p - now);
				--rest;
				if (rest == 0) {
					BR;
					return 0;
				}
				else {
					SP;
				}
				break;
			}
			++p;
		}
		now = p;
	}

	return 0;
}

