    if (s[i] == '0') j = i;
    memo[i] = j;
  }

  vector<int> ans;
  vector<bool> visited(n + 1, 0);
  for (int i = n; i > 0;) {
    visited[i] = 1;
    int next = memo[max(0, i - m)];
    if (visited[next]) {
      cout << -1 << endl;
      return 0;
    }
    ans.eb(i - next);
    i = next;
  }

  reverse(all(ans));

  rep(i, ans.size()) cout << ans[i] << ' ';
  cout << endl;
}

