struct solve
{
	solve(){}
	void operator()(int n, int k, string s) {
		deque<int> ans;
		int p=n;
		for(;p>0;)
		{
			int cp=p;
			for(int i=1;i<=k && i<=p;i++)
			{
				int np=p-i;
				if(s[np]=='0')
				{
					min_u(cp, np);
				}
			}
			if(cp==p)
			{
				cout << "-1\n";
				return;
			}
			ans.push_front(p-cp);
			p=cp;
		}
		cout << ans[0]; ans.pop_front();
		for(int m:ans) cout << " " << m;
		cout << "\n";
		return;
	}
};

