const int MAXN = 1e5 + 5;

int N, M, before[MAXN];
string S;

int main() {
    // setInput("in.txt");
    // setOutput("out.txt");
    // setError("err.txt");
    setLength(MAXN);
    read(N, M, S);
    reverse(S.begin(), S.end());
    int last = 0;
    for (int i = 0; i <= N; i++) {
        if (S[i] == '0') last = i;
        before[i] = last;
    }
    vector<int> ans;
    for (int cur = 0; cur < N; ) {
        int jump = min(N - cur, M);
        int nxt = before[cur + jump];
        if (nxt <= cur) {
            writeln(-1);
            return 0;
        }
        ans.push_back(nxt - cur);
        cur = nxt;
    }
    reverse(ans.begin(), ans.end());
    writeln(ans);
    return 0;
}

