const int N = 100005;

int st[4 * N];

int query(int p, int L, int R, int i, int j) {
	if(i > R or j < L) return 1e9;
	if(L >= i and R <= j) return st[p];
	int mid = (L + R) / 2;
	return min(query(2 * p, L, mid, i, j),
				query(2 * p + 1, mid + 1, R, i, j));
}

void upd(int p, int L, int R, int i, int val) {
	if(i > R or i < L) return;
	if(L == R) return void(st[p] = val);
	int mid = (L + R) / 2;
	upd(2 * p, L, mid, i, val);
	upd(2 * p + 1, mid + 1, R, i, val);
	st[p] = min(st[2 * p], st[2 * p + 1]);
}

int getL(int p, int L, int R, int lo, int mn) {
	if(R < lo or st[p] > mn) return -1;
	if(L == R) return L;
	int mid = (L + R) / 2;
	int ans = getL(2 * p, L, mid, lo, mn);
	if(ans != -1) return ans;
	return getL(2 * p + 1, mid + 1, R, lo, mn);
}

