		while (!q.empty()) {
			auto t = q.top();
			if (t.second + m < i) { dump(t); q.pop(); continue; }
			ans[i] = t.second;
			q.emplace(t.first + 1, i);
			break;
		}
	}
	dump(ans);

	ll f = n;
	list<ll> lst;
	while (true) {
		if (ans[f] == -1) {
			if (f > 0) { lst = list<ll>(); break; }
			break;
		}
		lst.emplace_front(f - ans[f]);
		f = ans[f];
	}

	return lst;
}

