const int MAXN = 1e5+5;
char S[MAXN];
std::set<int> good;
std::vector<int> step;
int M, N;

void display() {
    for (int x: step) {
        printf("%d ", x);
    }
    putchar('\n');
}

void init() {
    for (int i = 0; i <= N; ++i) {
        if (S[i] == '0') {
            good.insert(i);
        }
    }
}

void solve() {
    M = std::min(N, M);
    int cur = N;
    while (cur > 0) {
        int prev = std::max(cur - M, 0);
        auto ptr = good.lower_bound(prev);
        if (*ptr == cur) {
            step.assign({-1});
            return;
        }
        step.push_back(cur - *ptr);
        cur = *ptr;
    }
    std::reverse(ALL(step));
}

int main() {
    scanf(" %d%d%s", &N, &M, S);
    init();
    solve();
    display();
    return 0;
}

