inline int mn(int x, int y)
{
	if (x < 0)
		return y;
	if (y < 0)
		return x;
	return f[x] < f[y] || (f[x] == f[y] && x < y) ? x : y;
}
inline void Ckmin(int& x, int y)
{
	x = mn(x, y);
}
void amend(int x, int rt = 1, int L = 1, int R = n + 2)
{
	if (L == R - 1 && x == L)
	{
		Ckmin(val[rt], x);
		return ;
	}
	if (x < (L + R) / 2)
		amend(x, rt * 2, L, (L + R) / 2);
	else
		amend(x, rt * 2 + 1, (L + R) / 2, R);
	Ckmin(val[rt], mn(val[rt * 2], val[rt * 2 + 1]));
}
int query(int l, int r, int rt = 1, int L = 1, int R = n + 2)
{
	if (l <= L && R <= r)
		return val[rt];
	int res = -1;
	if (l < (L + R) / 2)
		Ckmin(res, query(l, r, rt * 2, L, (L + R) / 2));
	if ((L + R) / 2 < r)
		Ckmin(res, query(l, r, rt * 2 + 1, (L + R) / 2, R));
	return res;
}
inline void modify(int x, int v)
{
	if (v >= f[x])
		return ;
	f[x] = v;
	amend(x);
}
