    vt<int> ans;
    for (int i = n; i > 0;) {
        int t = max(0, i - m);
        auto it = upper_bound(all(ok), t, greater<int>());
        if (it == ok.end()) it--;

        int okIdx = distance(ok.begin(), it);
        if (t >= ng[okIdx]) {
            if (!okIdx || *--it == i) return cout << -1, 0;
        }

        int mv = min(i - t, i - *it);
        ans.push_back(mv);
        i -= mv;
    }

    reverse(all(ans));
    for (int i : ans) cout << i << ' ';
}

