const int MAXN = (int)1e5 + 777;
string S;
int n, m;

pii tree[2 * MAXN];
int pa[MAXN];

void build() {
	for(int i = 0; i < n; ++i) {
		tree[n + i] = make_pair(INT_INF, -i);
	}

	for(int i = n - 1; i > 0; --i) {
		tree[i] = min(tree[2 * i], tree[2 * i + 1]);
	}
}

void change(int pos, pii val) {
	pos += n;
	tree[pos] = val;

	for(; pos > 1; pos /= 2) {
		tree[pos / 2] = min(tree[pos], tree[pos ^ 1]);
	}
}

pii get(int l, int r) {
	l += n;
	r += n + 1;
	pii rez = make_pair(INT_INF, INT_INF);

	while(l < r) {
		if(l & 1) {
			rez = min(rez, tree[l++]);
		}

		if(r & 1) {
			rez = min(rez, tree[--r]);
		}

		l /= 2;
		r /= 2;
	}

	return rez;
}

void solve() {
	cin >> n >> m >> S;
	reverse(S.begin(), S.end());

	++n;
	build();
	change(0, make_pair(0, 0));
	DBG(get(0, 1));

	for(int i = 0; i < n; ++i) {
		pa[i] = -INT_INF;
	}

	for(int i = 1; i < n; ++i) {
		if(S[i] == '0') {
			int j = max(0, i - m);
			auto best = get(j, i);
			int old = tree[i + n].first;

			DBG(j); DBG(i);
			DBG(best);

			if(best.first + 1 < old) {
				change(i, make_pair(best.first + 1, -i));
				pa[i] = -best.second;
			} else if(best.first + 1 == old) {
				pa[i] = max(pa[i], -best.second);
			}
		}
	}

	if(get(n - 1, n - 1).first < INT_INF) {
		vector<int> answ;
		int cur = n - 1;

		while(cur != 0) {
			answ.push_back(cur - pa[cur]);
			DBG(pa[cur]);
			cur = pa[cur];
		}

		cout << answ << '\n';
	} else {
		cout << NIL << '\n';
	}
}

