    vector<ll> a(N + 1, INF);
    a[N] = 0;

    SegmentTree sg = SegmentTree(a);

    for(int i = N - 1; i >= 0; i--){
        if(s[i] != '1'){
            ll mn = sg.query(i + 1, min(N + 2, i + M + 1));
            sg.update(i, mn + 1);
