int dp[100005], pred[100005];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    int n, m;
    string s;
    cin >> n >> m >> s;

    deque<int> dq{0};
    pred[0] = -1;
    for (int i=1; i<=n; i++) {
        if (!dq.empty() && dq.front() == i - m - 1)
            dq.pop_front();
        if (s[i] == '1')
            dp[i] = INF;
        else {
            dp[i] = dp[dq.front()] + 1;
            pred[i] = dq.front();
        }
        while (!dq.empty() && dp[dq.back()] > dp[i])
            dq.pop_back();
        dq.push_back(i);
    }

    if (dp[n] >= INF) {
        cout << "-1\n";
        return 0;
    }
    int u = n;
    vector<int> v;
    while (pred[u] != -1) {
        v.push_back(u - pred[u]);
        u = pred[u];
    }
    for (int i=(int)v.size()-1; i>=0; i--)
        cout << v[i] << " \n"[i==0];

    return 0;
}

