auto solve_correct(ll n, ll m, const string& s) {}

auto solve(ll n, ll m, const string& s) {

	VL ans(n + 1, -1);

	auto c = [](const PAIR& l, const PAIR r) {
		if (l.first == r.first) {
			return l.second > r.second;
		}
		return l.first > r.first;
	};
	priority_queue<PAIR, V<PAIR>, decltype(c)> q;
	q.emplace(PAIR{0,0});
	FOR(i, 1, n + 1) {
		if (s[i] == '1') { continue; }

		while (!q.empty()) {
			auto t = q.top();
			if (t.second + m < i) { dump(t); q.pop(); continue; }
			ans[i] = t.second;
			q.emplace(t.first + 1, i);
			break;
		}
	}
	dump(ans);

	ll f = n;
	list<ll> lst;
	while (true) {
		if (ans[f] == -1) {
			if (f > 0) { lst = list<ll>(); break; }
			break;
		}
		lst.emplace_front(f - ans[f]);
		f = ans[f];
	}

	return lst;
}

