template<typename T>
struct MinQueue {
    deque<T> deq;

    MinQueue() = default;

    bool empty() const { return deq.empty(); }

    T min() const {
        ASSERT(!empty());
        return deq.front();
    }

    void push(const T& x) {
        while(!deq.empty() && deq.back() > x)
            deq.pop_back();
        deq.push_back(x);
    }

    void pop(const T& x) {
        if(!deq.empty() && deq.front() == x)
            deq.pop_front();
    }
};

[[noreturn]] void impossible() {
    PRINTLN(-1);
    exit(0);
}

