    v[N] = {0,0};

    MinQueue<pair<i64,i64>> que;  // (最短手数,インデックス)
    for(i64 i = N-1; i >= max<i64>(0,N-K); --i) {
        if(S[i] == '0') {
            v[i] = {1, N-i};
        }
        que.push(make_pair(v[i].first, i));
