    if(S[i]==1) Mcount++;
    else Mcount=0;
    if(Mcount>=M) {
      cout << -1 << endl;
      return 0;
    }
  }

  int f[100001] = {};
  update(N, 0);
  for (int i = N-1; i>=0; i--) {
    if (S[i] == 0) {
      int fin = min(N, i+M);
      f[i] = query(i+1,fin+1,0,0,n) + 1;
      update(i, f[i]);
    } else {
      f[i] = INT_MAX;
