// Problem
void solve() {
    ll n, m;
    cin >> n >> m;
    string s;
    cin >> s;

    char ng = '1', ok = '0';
    // 後ろから貪欲?
    ll cur = n;
    vll ret;
    while (cur > 0) {
        ll ncur = cur;
        REPR(tcur, cur - 1, max(cur - m, 0LL)) {
            if (s[tcur] == ok) ncur = tcur;
        }
        if (ncur == cur) {
            cout << -1 << endl;
            return;
        }
        ret.push_back(cur - ncur);
        cur = ncur;
    }
    reverse(ALL(ret));
    cout >> ret;
}

