/*

    idea: start from the end and try to reach the beginning taking the longest jumps possible.

*/


#include<bits/stdc++.h>


using namespace std;

using ll   = long long;
using ii   = pair   < int , int >;
using i3   = pair   < int , ii  >;
using li   = pair   < ll  , int >;
using lii  = pair   < ll  , ii  >;
using pll  = pair   < ll  , ll  >;
using vi   = vector < int       >;
using vl   = vector < ll        >;
using vii  = vector < ii        >;
using vpll = vector < pll       >;
using vi3  = vector < i3        >;
using vlii = vector < lii       >;


const int N = 1;
const ll INF = 1e17 + 7;
const double eps = 1e-9 , PI = acos(-1);



int n , m;
vi ans , v;

void solve(int testCase){

    scanf("%d %d" , &n , &m);

    string s;
    cin >> s;

    /// to start from the end
    reverse(s.begin() , s.end());

    /// store all positions of 0's
    for(int i = 0 ; s[i] ; i ++){
            if(s[i] == '0'){
                    v.push_back(i);
            }
    }

    // initial position
    int pos = 0;

    while( pos != n ){

            // farthest place I can go
            int nxt = upper_bound(v.begin() , v.end() , pos + m) - v.begin() - 1;

            // if I'm still in my place => no solution
            if(v[nxt] == pos){
                    printf("-1\n");
                    return;
            }

            // insert the length of the jump into the answer
            ans.push_back(v[nxt] - pos);

            // update position
            pos = v[nxt];
    }

    // print the answer backwards: from begin to end.
    reverse(ans.begin() , ans.end());

    for(int A : ans)printf("%d " , A);
    printf("\n");

}

main(){

    int t = 1;
    //scanf("%d" , &t);

    for(int testCase = 1 ; testCase <= t ; testCase ++){
            solve(testCase);
    }

    return 0;
}

