    position() {}
    position(ll a, ll b) : x(a), y(b) {}
    position next(ll i) { return {x + dx[i], y + dy[i]}; }
    ll mdist() { return abs(x) + abs(y); }
    double dist() { return sqrt(x * x + y * y); }
    double norm(ll d) {
        if (d == inf) return max(x, y);
        if (d == 1) return mdist();
        if (d == 2) return dist();
        return 0;
    }
