#define INF 1987654321
#define IINF 87654321987654321
#define MOD 1000000007

struct SegmentTree {
	int n;
	vector<pii> st;

	void init(int sz) {
		n = 1;
		while(n < sz)
			n <<= 1;
		st.assign(2*n, {INF, INF});
	}

	void update(int p, pii val) {
		p += n-1;
		st[p] = val;
		for(p >>= 1; p; p >>= 1)
			st[p] = min(st[2*p], st[2*p+1]);
	}

	pii rangeMin(int l, int r) {
		pii res = {INF, INF};
		for(l += n-1, r += n-1; l <= r; l >>= 1, r >>= 1) {
			if(l & 1)
				res = min(res, st[l++]);
			if(!(r & 1))
				res = min(res, st[r--]);	
		}
		return res;
	}
};


const int MAXN = 1e5 + 50;
char s[MAXN];
int n, m;
void readInput() {
	scanf("%d%d", &n, &m);
	scanf("%s", s);
}


int dp[MAXN], nxt[MAXN];
void solve() {
	SegmentTree tree;
	tree.init(n);

	dp[n] = 0;
	tree.update(n, {dp[n], n});
	for(int i = n-1; i >= 0; i--) {
		if(s[i] == '1') {
			dp[i] = INF;
			tree.update(i, {dp[i], i});
		} else {
			pii val = tree.rangeMin(i+1, min(i+m, n));
			dp[i] = min(val.first + 1, INF);
			nxt[i] = val.second;
			if(i > 0)
				tree.update(i, {dp[i], i});
		}
	}

	if(dp[0] == INF) {
		printf("-1\n");
	} else {
		int cur = 0;
		while(cur < n) {
			printf("%d ", nxt[cur] - cur);
			cur = nxt[cur];
		}
	}
}

int main() {
	readInput();
	solve();
}

