void build(llong v, llong tl, llong tr){
    if(tl == tr) {
        t[v].F = INF;
        return ;
    }
    llong tm = (tl + tr) / 2;
    build(v * 2, tl, tm);
    build(v * 2 + 1, tm + 1, tr);
    t[v].F = min(t[v * 2].F, t[v * 2 + 1].F);
}

pair<llong, llong> get(llong v, llong tl, llong tr, llong L, llong R){
    if(L <= tl && tr <= R){
        return t[v];
    }
    if(R < tl || tr < L) return {INF, INF};
    llong tm = (tl + tr) / 2;
    pair<llong, llong> a = get(v * 2, tl, tm, L, R);
    pair<llong, llong> b = get(v * 2 + 1, tm + 1, tr, L, R);
    if(a.F > b.F) return b;
    else return a;
}

void upd(llong v, llong tl, llong tr, llong ind, llong x){
    if(tl == tr) {
        t[v].F = x;
        t[v].S = tl;
        return ;
    }
    llong tm = (tl + tr) / 2;
    if(ind <= tm){
        upd(v * 2, tl, tm, ind, x);
    }else{
        upd(v * 2 + 1, tm + 1, tr, ind, x);
    }
    if(t[v + v].F > t[v + v + 1].F) t[v] = t[v + v + 1];
    else t[v] = t[v + v];
}

