int dp[N] , t[N << 2] , to[N];
void upd(int v , int tl , int tr , int pos){
	if(tl == tr)
		return void(t[v] = pos);
	int tm = (tl + tr) >> 1;
	if(pos <= tm)
		upd(v << 1, tl , tm , pos);
	else upd(v << 1|1 , tm + 1,  tr , pos);
	if(dp[t[v << 1]] > dp[t[v << 1|1]])
		t[v] = t[v << 1 | 1];
	else t[v] = t[v << 1];
}
int get(int v , int tl , int tr , int l , int r){
//	cerr << tl << ' ' << tr << '\n';
	if(l > r or l > tr or tl > r)
		return 0;
	if(l <= tl and tr <= r){
		return t[v];
	}
	int tm = (tl + tr) >> 1;
	int a = get(v << 1 , tl  , tm , l , r) , b = get(v << 1|1 , tm + 1, tr , l , r);
	if(dp[a] > dp[b])
		return b;
	return a;	
}
