ll dp[100005];
ll fun(int pos)
{
    if(pos==n)
    {
        return dp[pos]=0;
    }
    if(pos>n)
    {
        return dp[pos]=1e8;
    }
    if(dp[pos]!=-1)
    {
        return dp[pos];
    }
    ll req=1e8;
    for(int i=1;(pos+i)<=n;i++)
    {
        if(i>m)
            break;
        if(ch[pos+i]=='0')
        {
            req=min(req,1+fun(pos+i));
        }
    }
    return dp[pos]=req;
}
vector<int> razib;
ll res;
void path(int pos)
{
    if(pos==n)
    {
        return;
    }
    for(int i=1;(pos+i)<=n;i++)
    {
        if(i>m)
            break;
        if(ch[pos+i]=='0')
        {
            ll req=dp[pos+i];
            //cout<<req<<" req "<<res<<endl;
            if((req+1)==res)
            {
                res--;
                razib.push_back(i);
                path(pos+i);
                break;
            }
        }
    }
}
