{
    if(curr == 0) return true;
    if(s[curr] == '1') return false;
    int index = max(curr-m, 0LL);
    int z =  last_zero[index];
    while(z != curr)
    {
        bool check = f(z, ans, last_zero);
        if(check) 
        {
            ans.pb(curr - z);
            return true;
        }
        z = last_zero[z+1];
    }
    return false;
}


