using namespace std;

template <typename T>
struct LazySegtree {
	private:
		size_t n;
		vector<T> node, lazy;
		T M0, L0;

	public:
		LazySegtree(size_t sz, T m0, T l0) {
			n = 1;
			M0 = m0;
			L0 = l0;
			while (n < sz) { n *= 2; }
			node.assign(2*n - 1, M0);
			lazy.assign(2*n - 1, L0);
		}

		T merge(T a, T b) { return min(a, b); }
		void updateNode(int k, T x) { lazy[k] = min(lazy[k], x); }
		void propagate(int k) { node[k] = min(node[k], lazy[k]); }

		void eval(int k, int l, int r) {
			if (lazy[k] == L0) { return; }
			propagate(k);
			if (r - l > 1) {
				updateNode(2*k + 1, lazy[k]);
				updateNode(2*k + 2, lazy[k]);
			}
			lazy[k] = L0;
		}

		void update(int a, int b, T x, int k=0, int l=0, int r=-1) {
			if (r < 0) { r = n; }
			eval(k, l, r);
			if (r <= a || b <= l) { return; }
			if (a <= l && r <= b) {
				updateNode(k, x);
				eval(k, l, r);
			} else {
				update(a, b, x, 2*k + 1, l, (l + r) / 2);
				update(a, b, x, 2*k + 2, (l + r) / 2, r);
				node[k] = merge(node[2*k + 1], node[2*k + 2]);
			}
		}

		T query(int a, int b, int k=0, int l=0, int r=-1) {
			if (r < 0) { r = n; }
			eval(k, l, r);
			if (r <= a || b <= l) { return M0; }
			if (a <= l && r <= b) { return node[k]; }
			T vl = query(a, b, 2*k + 1, l, (l + r) / 2);
			T vr = query(a, b, 2*k + 2, (l + r) / 2, r);
			return merge(vl, vr);
		}
};

int main() {
	const int INF = 1e9;
	int N, M;
	string s;
	cin >> N >> M >> s;

	LazySegtree<int> seg(N + 10, INF, INF);
	seg.update(N, N + 1, 0);
	for (int i = N; i > 0; --i) {
		if (s[i] == '1') { continue; }

		int val = seg.query(i, i + 1) + 1;
		int l = max(0, i - M), r = i;
		seg.update(l, r, val);
	}

	if (seg.query(0, 1) == INF) {
		cout << -1 << endl;
		return 0;
	}

	int x = seg.query(0, 1);
	vector<int> ans(x + 1, INF);
	ans[x] = 0;
	for (int i = 0; i <= N; ++i) {
		if (s[i] == '1') { continue; }
		int val = seg.query(i, i + 1);
		if (val >= x) { continue; }

		ans[val] = min(ans[val], i);
	}

	for (int i = x - 1; i >= 0; --i) {
		cout << ans[i] - ans[i + 1] << (i == 0 ? "\n" : " ");
	}

	return 0;
}

