                     [](int a, int b) { return b; });
    sgt.change(n, 0);

    for (int i = n - 1; i >= 0; --i) {
        if (s[i] == '1') continue;
        int mi = sgt.query(i + 1, min(i + m + 1, n + 1));
        if (mi != inf) sgt.change(i, mi + 1);
    }
    // rep(i, n + 1) cout << sgt[i] << " "; cout << endl;

    if (sgt[0] == inf) { cout << -1 << endl; return 0; }

    vector<int> ans;
