  cin >> n >> m >> s;
  int dp[n + 1], current = n;
  for (int i = m; i >= 0; --i) {
    if (s.rbegin()[i] == '0') {
      dp[n] = n - i;
      break;
    }
  }
  for (int i = n - 1; i >= 0; --i) {
    if (i - m >= 0 && s[i - m] == '0') {
      dp[i] = i - m;
    } else {
      dp[i] = min(dp[i + 1], i);
    }
  }
  vector<int> result;
  do {
    auto next = dp[current];
    if (next == current) {
      result = {-1};
      break;
    }
    result.emplace_back(current - next);
    current = next;
  } while (current != 0);
  for (auto it = result.rbegin(); it != result.rend(); ++it) {
    cout << *it << ' ';
  }
  return 0;
}

