const int DIM = 1e5 + 7;

bool v[DIM];
bool arb[DIM * 4];

int from[DIM];

void build(int pos, int l, int r)
{
	if(l == r)
	{
		arb[pos] = v[l];
		return ;
	}

	int mid = (l + r) / 2;

	build(pos * 2, l, mid);
	build(pos * 2 + 1, mid + 1, r);

	arb[pos] = (arb[pos * 2] | arb[pos * 2 + 1]);
}

int query(int pos, int l, int r, int x, int y)
{
	if(x <= l && r <= y)
	{
		if(arb[pos] == false)
			return -1;

		if(l == r)
			return l;

		int mid = (l + r) / 2;

		int p = query(pos * 2, l, mid, x, y);

		if(p != -1)
			return p;

		return query(pos * 2 + 1, mid + 1, r, x, y);
	}

	int mid = (l + r ) / 2;

	int p1 = -1;
	int p2 = -1;

	if(x <= mid)
		p1 = query(pos * 2, l, mid, x, y);

	if(y > mid)
		p2 = query(pos * 2 + 1, mid + 1, r, x, y);

	if(p1 != -1)
		return p1;

	return p2;
}

