const int MAX = 1 << 17;
const int INF = 1001001001;
const int MOD = 1e9 + 7;

int dat[2 * MAX - 1];

class SegmentTree {
    public:
        unsigned int N;
        SegmentTree(int n);
        int query(int a, int b, int k, int l, int r);
        void update(int k, int a);
};

SegmentTree::SegmentTree(int n) {
    N = 1;
    while (N < n) N *= 2;
    rep(i, N) dat[i] = INF;
}

int SegmentTree::query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return INF;

    if (a <= l && r <= b) {
        return dat[k];
    } else {
        int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
        int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
}

void SegmentTree::update(int k, int a) {
    k += N - 1;
    dat[k] = a;

    while (0 < k) {
        k = (k - 1) / 2;
        dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
};

int main() {
    int N, M;
    string S;
    cin >> N >> M >> S;

    SegmentTree st = SegmentTree(N);
    st.update(N, 0);
    vector<int> dp(N + 1);
    dp[N] = 0;
    for (int i = N - 1; i >= 0; --i) {
        if (S[i] == '1') {
            dp[i] = INF;
            st.update(i, INF);
            continue;
        }
        int l = i + 1, r = min(N + 1, l + M);
        dp[i] = st.query(l, r, 0, 0, st.N) + 1;
        st.update(i, dp[i]);
    }

    if (dp[0] >= INF) {
        cout << -1 << endl;
        return 0;
    }

    vector<int> ans;
    int x = 0;
    while (x < N) {
        int i = 1;
        while (dp[x] - 1 != dp[x + i]) i++;
        x += i;
        ans.push_back(i);
    }

    for (int i : ans) cout << i << " ";
    cout << endl;
}

