    int cpos = N;
    if(memo[cpos] == inf) return puts("-1") * 0;
    if(d[N] != inf){
        std::reverse(ans.begin(),ans.end());
        for(auto s : ans)
            std::cout << s << std::endl;
    } else {
        puts("-1");
    }
}

