const int MAXN = 1e5+5;
const int MOD = 1e9+7;
const int INF = 1e9+1;

pair<LL,int> val[MAXN*4];
int trace[MAXN];

int N,M;
char S[MAXN];

void build(int node, int left, int right) {
    if (left == right) {
        if(left == N) val[node] = {0, left};
        else val[node] = {1e9,left};
        return;
    }

    int m = (left + right) / 2;
    build(node*2, left, m);
    build(node*2+1, m+1, right);

    val[node] = min(val[node*2], val[node*2+1]);
}

void update(int node, int left, int right, int i, int newval) {
    if(left == right) {
        assert(left == i);
        val[node].fi = newval;
        return;
    }

    int m = (left + right) / 2;
    if(i <= m) update(node*2, left, m, i, newval);
    else update(node*2+1, m+1, right, i, newval);

    val[node] = min(val[node*2],val[node*2+1]);
}

pair<LL,int> query(int node, int left, int right, int l, int r) {
    if (r < l) return {1e9, 1e9};
    if (r < left || right < l) return {1e9,1e9};

    if (l <= left && right <= r) return val[node];

    int m = (left + right) / 2;
    return min(query(node*2, left, m, l, min(m,r)), 
               query(node*2+1, m+1, right, max(m+1,l), r));
}


