int main(){
  int N, M, S[SIZE];

  scanf("%d%d", &N, &M);

  for (int i=0; i<=N; i++) {
    scanf("%1d", S+i);
  }

  priority_queue<pair<int,int>> pq;
  int back[SIZE];

  for (int i=0; i<=N; i++) {
    back[i] = -1;
  }

  pq.push({0, 0});

  for (int i=1; i<=N; i++) {
    if (S[i]) continue;

    while(pq.size() && -pq.top().second < i - M) {
      pq.pop();
    }

    if (pq.empty()) continue;

    auto p = pq.top();

    back[i] = -p.second;

    pq.push({p.first-1, -i});
  }

  if (back[N] == -1) {
    puts("-1");
    return 0;
  }

  vector<int> ans;

  int now = N;

  while(now != 0) {
    ans.push_back(now);
    now = back[now];
  }

  reverse(ans.begin(), ans.end());

  now = 0;
  bool first = true;
  for (int pos : ans) {
    if (!first) printf(" ");
    printf("%d", pos - now);
    first = false;
    now = pos;
  }

  puts("");

