int solve(int i){
    if(i == n) return 0;
    int &ret = dp[i];
    if(~ret) return ret;
    int ind = upper_bound(pos.begin(), pos.end(), i + m) - pos.begin();
    int p = pos[ind - 1];
    int a = n + 1, b = n + 1;
    if(p > i)
        a = 1 + solve(p);
    ind = upper_bound(pos.begin(), pos.end(), i) - pos.begin();
    if(pos[ind] > i && pos[ind] - i <= m)
        b = 1 + solve(pos[ind]);
    ret = min(a, b);
    id[ret] = min(id[ret], i);
    return ret;
}

