void build (int v = 1, int tl = 0, int tr = n) {
   if (tl == tr) {
      if (tl == 0) t[v].F = 0;
      else t[v].F = mod;
      t[v].S = tl;
      return;
   }
   int tm = tl + tr >> 1;
   build (v + v, tl, tm);
   build (v + v + 1, tm + 1, tr);
   t[v] = min (t[v + v], t[v + v + 1]);
}

void upd (int pos, int val, int v = 1, int tl = 0, int tr = n) {
   if (tl == tr) {
      t[v].F = val;
      return;
   }
   int tm = tl + tr >> 1;
   if (pos <= tm) upd (pos, val, v + v, tl, tm);
   else upd (pos, val, v + v + 1, tm + 1, tr);
   t[v] = min (t[v + v], t[v + v + 1]);
}

pii get (int l, int r, int v = 1, int tl = 0, int tr = n) {
   if (tl > r || tr < l) return mp (mod, mod);
   if (l <= tl && tr <= r) return t[v];
   int tm = tl + tr >> 1;
   return min (get (l, r, v + v, tl, tm), get (l, r, v + v + 1, tm + 1, tr));
}

