         dp[i] = mod;
         upd (i, mod);
         continue;
      }
      pii res = get ((i - m < 0 ? 0 : i - m), i);
      if (res.F == mod) {
         dp[i] = mod;
         upd (i, mod);
         continue;
      }
      dp[i] = res.F + 1;
      p[i] = res.S;
      upd (i, dp[i]);
