int main() {
	int n, m; scanf("%d%d", &n, &m); n++;
	std::string s; cin >> s;

	// solve
	using P = std::pair<int, int>;
	// (val, lifetime)

	std::vector<int> dp(n + 1, 1 << 30); dp[0] = 0;
	std::vector<int> from(n + 1, -1);
	std::queue<P> qu({{0, -m}});
	for(int i = 0; i < n; i++) {
		if(s[i] == '1') continue;

		while(!qu.empty() and (i - qu.front().second) > m) qu.pop();
		if(qu.empty()) break;

		dp[i + 1] = qu.front().first + 1;
		from[i + 1] = qu.front().second + 1;
		qu.push({dp[i + 1], i});
	}

	#ifndef NDEBUG
	for(auto v: dp) cerr << v << " "; cerr << endl;
	for(auto v: from) cerr << v << " "; cerr << endl;
	#endif

	if(dp[n] == 1 << 30) {
		printf("-1\n");
		return 0;
	}

	int now = n;
	std::vector<int> ans;
	while(now > 1) {
		ans.push_back(now - from[now]);

		now = from[now];
	}
	reverse(begin(ans), end(ans));

	for(auto v: ans) printf("%d ", v);
	printf("\n");
	return 0;
}

