const int maxn = 300010;
int n, m;
char w[maxn];
int lst[maxn];
struct sgt{
	// v first s second
	int v[maxn<<1], s[maxn<<1];
	sgt(){memset(v, 0x3f3f3f3f, sizeof(v));memset(s, 0, sizeof(s));};
	void add(int p, pair<int,int> nv, int l = 0, int r = n, int i = 1){
		if(p > r || p < l)return;
		if(l == r and p == l)tie(v[i], s[i]) = nv;
		else{
			int mid = l+r>>1;
			add(p, nv, l, mid, i<<1), add(p, nv, mid+1, r, i<<1|1);
			if(v[i<<1] < v[i<<1|1]){
				s[i] = s[i<<1];
				v[i] = v[i<<1];
			}
			else if(v[i<<1] > v[i<<1|1]){
				s[i] = s[i<<1|1];
				v[i] = v[i<<1|1];
			}
			else{
				s[i] = min(s[i<<1], s[i<<1|1]);
				v[i] = v[i<<1];
			}
		}

	}
	pair<int,int> query(int ql, int qr, int l = 0, int r = n, int i = 1){
		if(ql > r || qr < l)return {maxn, maxn};
		if(ql <= l and qr >= r)return {v[i], s[i]};
		else{
			int mid = l+r>>1;
			return min(query(ql, qr, l, mid, i<<1), query(ql, qr, mid+1, r, i<<1|1));
		}
	}
}tree;
