  while(now > 0){
      int tmp = step(S,now,M);
      if(tmp == -1){cout << -1 << endl; return 0;}
      ans[idx] = tmp; idx++;
      now -= tmp;
  }

  for(i=99999;i>=0;i--){
      if(ans[i]>0){
          cout << ans[i];
          if(i!=0){cout << " ";}
    }
  }

  return 0;
}

