    scanf("%d %d\n%s", &n, &m, s);
    dp[0] = 1; d[t++] = 0;
    for(int i = 1; i <= n; i++){
        while(d[h] < i - m) h++;
        if(s[i] == '1') dp[i] = 1e9;
        else dp[i] = dp[d[h]] + 1; opt[i] = d[h];
        while(h < t && dp[d[t - 1]] > dp[i]) t--;
        d[t++] = i;
    }
    if(dp[n] >= 1e9) puts("-1");
    else{
        for(int i = n; i; i = opt[i]) ans[c++] = i - opt[i];
        while(c--) printf("%d ", ans[c]);
    }
    return 0;
}

