const int N = 1e5+5;
const int inf = 1e8+7;
struct Node{
    int p; int v;
    Node(int p = 0,int v = 0):p(p), v(v){}
    bool operator < (const Node& other)const{
        return v>other.v;
    }
};
int a[N];
int f[N];
int next[N];

int min(int a,int b){ return a>b?b:a; }

int main(){
    int n,m;
    scanf("%d%d",&n,&m);
    for(int i = 0; i <= n; i++) scanf("%1d",&a[i]);
    std::priority_queue<Node>Q;
    for(int i = n; i >= 0; i--){
        if(i==n) f[i] = 0;
        else f[i] = inf;
        if(a[i]!=1){
        int last = i + m;
            while(Q.size() && Q.top().p>last) Q.pop();
            if(Q.size()){ 
                next[i] = Q.top().p;
                f[i] = min(f[i],Q.top().v+1);
            }
        }
        if(f[i]<inf) Q.push(Node(i,f[i]));
    }
    if(f[0]>=inf) printf("-1\n");
    else{
        int p = 0;
        while(p!=n){
            printf("%d ",next[p]-p);
            p = next[p];
        }
        printf("\n");
    }
    return 0;
}

