int N, M;
string S;

void solve() {
    vector<int> res;
    vector<int> next(N+1, N);
    for (int i = N; i >= 0; --i) {
        if (S[i] == '1') next[i] = next[i+1];
        else next[i] = i;
    }       
    int s = N;
    while (s) {
        int ns = next[max(0, s-M)];
        if (ns == s) {
            cout << -1 << endl;
            return;
        }
        res.push_back(s-ns);
        s = ns;
    }
    reverse(res.begin(), res.end());
    for (auto v : res) cout << v << " ";
    cout  << endl;
}

int main() {
    while (cin >> N >> M >> S) solve();
}

