using namespace std;

int dist[100001];
const int INF = 1e9;
int history[100001];
int memo[100001];

int main(void)
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	//ifstream cin("test.out");
	int n,k;
	string s;

	cin >> n >> k;
	cin >> s;

	fill(dist,dist+100001,INF);
	dist[0] = 0;
	priority_queue <pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> pque;
	pque.push(make_pair(dist[0],0));

	memset(history,-1,sizeof(history));
	memset(memo,-1,sizeof(memo));

	while(!pque.empty())
	{
		int now = pque.top().second;
		int val = pque.top().second;
		pque.pop();
		if(val > dist[now])
		{
			continue;
		}

		for(int i=1;i<=k;i++)
		{
			if(now+i > n)
			{
				break;
			}
			if(s[now+i]=='1')
			{
				continue;
			}
			if(dist[now + i] > dist[now] + 1)
			{
				dist[now + i] = dist[now] + 1;
				memo[now + i] = i;
				history[now + i] = now;
				pque.push(make_pair(dist[now + i],now + i));
			}
		}
	}	

	if(dist[n]>=INF)
	{
		cout << -1 << '\n';
	}
	else
	{
		vector <int> res;
		int now = n;
		while(now > 0)
		{
			res.push_back(memo[now]);
			now = history[now];
		}

		for(int i=res.size()-1;i>=0;i--)
		{
			cout << res[i] << ' ';
		}
		cout << '\n';
	}
	return 0;
}

