#define ll long long
#define mid (l+r)/2
#define L (x<<1)
#define R (L+1)
pair<int,int> tree[1000000];
string s;
void build(int x,int l,int r)
{
    if (l==r){
        tree[x]={1e9,l};
    } else {
        build(L,l,mid);
        build(R,mid+1,r);
        tree[x]=min(tree[L],tree[R]);
    }
}
void upd(int x,int l,int r,int v,int val){
    if (v>r || v<l)return;
    if (l==r){
        tree[x] = {val, l};
    } else {
        upd(L,l,mid,v,val);
        upd(R,mid+1,r,v,val);
        tree[x]=min(tree[L],tree[R]);
    }
}
pair<int,int> query(int x,int l,int r,int s,int e) {
    if (l>e || r<s)return {1e9,0};
    if (l>=s && r<=e)return tree[x];
    return min(query(L,l,mid,s,e),query(R,mid+1,r,s,e));
}
