		{
			if (str[loc - i] == '0')
			{
				next = loc - i;

				break;
			}
		}

		if (next == loc)
		{
			printf("-1\n");

			return 0;
		}

		move.push_back(loc - next);

		loc = next;
	}

	for (int i = move.size() - 1; i >= 0; i--)
	{
		printf("%d ", move[i]);
	}

	printf("\n");

	return 0;
}

