void build(int k,int l,int r){
	if(l==r){
		tr[k]=s[l]-'0';
		return ;
	}
	int mid=(l+r)>>1;
	build(k<<1,l,mid);
	build(k<<1|1,mid+1,r);
	tr[k]=min(tr[k<<1],tr[k<<1|1]);
}
int query(int k,int l,int r,int a,int b){
	if(l==r){
		if(tr[k]==1){
			return -1;
		}
		else{
			return l;
		}
	}
	if(tr[k]==1)return -1;
	int mid=(l+r)>>1;
	if(b<=mid){
		return query(k<<1,l,mid,a,b);
	}
	else if(a>mid){
		return query(k<<1|1,mid+1,r,a,b);
	}
	else{
		int c=query(k<<1|1,mid+1,r,mid+1,b);
		if(c==-1)c=query(k<<1,l,mid,a,mid);
		return c;
	}
}
