inline int lt(int x){return 2*x;}
inline int rt(int x){return 2*x+1;}

void build(int nd, int s, int e)
{
    if(s==e)
    {
        segt[nd]={1e9, 1e9};
        return;
    }
    int m=(s+e)/2;
    build(lt(nd), s, m);
    build(rt(nd), m+1, e);
    segt[nd]={1e9, 1e9};
}

void upd(int nd, int s, int e, int idx, int val)
{
    if(s>idx || e<idx)
        return;
    if(s==e)
    {
        segt[nd]={val, s};
        return;
    }
    int m=(s+e)/2;
    upd(lt(nd), s, m, idx, val);
    upd(rt(nd), m+1, e, idx, val);
    segt[nd]=min(segt[lt(nd)], segt[rt(nd)]);
}

pair<int, int> quer(int nd, int s, int e, int l, int r)
{
    if(s>r || e<l)
        return {1e9, 1e9};
    if(s>=l && e<=r)
        return segt[nd];
    int m=(s+e)/2;
    return min(quer(lt(nd), s, m, l, r), quer(rt(nd), m+1, e, l, r));
}

