constexpr u32 INFTY = std::numeric_limits<u32>::max();

struct Vtx
{
	std::vector<std::pair<u32,u32>> adj;
	u32 hops = INFTY;
	//std::string lex;
	u32 cost = 0;
	u32 prev = 0;
};

struct cmp
{
	cmp(std::vector<Vtx>& gi)
	  : g(gi)
	{}

	bool operator()(const auto& a, const auto& b)
	{
		if(g[a].hops == g[b].hops)
		{
			//return std::lexicographical_compare(g[b].lex.begin(), g[b].lex.end(), g[a].lex.begin(), g[a].lex.end());
			return a>b;
		}
		return g[a].hops < g[b].hops;
	}

	std::vector<Vtx>& g;
};

void dijkstra(std::vector<Vtx>& g, u32 src, u32 n)
{
	std::set<u64, cmp> q(g);
	g[src].hops = 0;
	q.insert(src);

	while(not q.empty())
	{
		u32 vi = *(q.begin());

		Vtx& u = g[vi];
		q.erase(vi);

		if(u.hops > g[n].hops)
		{
			continue;
		}

		for(u32 i=0; i<u.adj.size(); ++i)
		{
			u32 va = u.adj[i].first;
			Vtx& v = g[va];
			if(vi == va) continue;

			u32 cost = u.adj[i].second;

			if(u.hops + 1 < v.hops || (u.hops + 1 == v.hops && va > vi/*std::lexicographical_compare(g[vi].lex.begin(), g[vi].lex.end(), g[va].lex.begin(), g[va].lex.end())*/))
			{
				q.erase(va);

				//std::clog << "vi = " << vi << " va = " << va << " u.hops = " << u.hops << " v.hops = " << v.hops << " cost = " << cost << " new_hops = " << v.hops + cost << "\n";

				v.hops = u.hops + 1;
				//v.lex = u.lex + (u.lex.size() > 0 ? " " : "") + std::to_string(cost);
				v.cost = cost;
				v.prev = vi;

				/*auto ret = */q.insert(va);
				//std::clog << std::boolalpha << ret.second << std::endl;
			}
		}
	}
}

