		return;
	}

	int mid = (l + r) / 2;
	upd(id * 2, l, mid, idx, val);
	upd(id * 2 + 1, mid + 1, r, idx, val);
	segTree[id] = min(segTree[id * 2], segTree[id * 2 + 1]);
}

int getMn(int id, int l, int r, int L, int R){
	if(L <= l && r <= R){
		return segTree[id];
	}

	if(r < L || l > R){
		return BIG;
	}

	int mid = (l + r) / 2;
	int ans = getMn(id * 2, l, mid, L, R);
	ans = min(ans, getMn(id * 2 + 1, mid + 1, r, L, R));

	return ans;
}

void upd(int idx, int val){
	for(; idx < maxN; idx += idx & -idx){
		fwt[idx] += val;
	}
}

int pre(int idx){
	int ans = 0;
	for(; idx > 0; idx -= idx & -idx){
		ans += fwt[idx];
	}

	return ans;
}

int sum(int l, int r){
	return pre(r) - pre(l - 1);
}

