    SegmentTree seg(z);
    dp[n] = 0;
    seg.update(0, n);
    int now = 0;
    for (int i = n - 1; i >= 0; i--){
        if (s[i] == '1') continue;
        int a = seg.getmin(now, now + 1);
        if (a - i <= m){
            dp[i] = now + 1;
            seg.update(now + 1, i);
        }
        else {
            now++;
            a = seg.getmin(now, now + 1);
