P dat[ST_SIZE]; //{最小値、それを保持する添え字}　の順で保持

int a;

void init(const int& n){ 

  a = 1;

  while( a < n){ a *= 2;}

  for(int i = 0; i < 2*a-1 ; i++){ dat[i].first = INF;}

}

P query(int s,int t, int k, int l, int r){
 // [a,b)の範囲での最小値と、それを与える添え字を返す
  if( r <= s || t <= l){ return {INF,INF};}
  if( s <= l && r <= t){ return dat[k];}
  else{

    P v1 = query(s,t,2*k+1,l,(l+r)/2);
    P v2 = query(s,t,2*k+2,(l+r)/2,r);


    return min(v1,v2); //添え字込みで、最小のものを返す
  }
}

void update(int k, int x){ //k-リーフの値をxに変えた時の更新

  k += a-1;


  dat[k] = {x,k-(a-1)}; //添え字は、リーフのこと

  while( k > 0){ 

    k = (k-1)/2;

    P res1 = dat[2*k+1];
    P res2 = dat[2*k+2];

    dat[k] = min(res1,res2); //添え字込みで、小さい方を返す

  }

}

