  //初期化

  //まずは最短手数を求める
  for(int i = N-1; i >= 0; i--){
    if( S[i] == 1 ){ continue;}

     int right = min(N,i+M);
    //[i+1,right]で最小値を求める

     int res = query(i+1,right+1,0,0,a+1).first; 
    //queryはfirstで最小値、secondでそれを与える添え字を返す


    update(i,res+1);


