  //次に、辞書順最小を求める

  int pos = 0; bool reach = true; //ゴールまでたどり着けるか判定

  vector<int> ans;


  while(pos < N ){ 


    int region = min(N,pos+M);

    int next = query(pos,region+1,0,0,a+1).second;

    if( pos == next){ reach = false;break;} 

    pos = next; 

    ans.push_back(pos);


