#define pb push_back
#define pii pair<int,int>
#define ff first
#define ss second

priority_queue< pii > Q;
int ans[100010];

int main() {

    int n, m;
    string s;
    cin >> n >> m;
    cin >> s;

    // cout << n << ' ' << m << ' ' << s << endl;

    fill(ans, ans + n + 1, -1);

    for(int i = n - 1, j = 1; i >= n - m; i--, j++){
        if(i < 0)break;
        if(s[i] == '1') continue;
        Q.push({-1,-i});
        ans[i] = j;
    }

    for(int i = n - m - 1; i >= 0; i--){
        if(s[i] == '1') continue;

        while(!Q.empty()){
            pii u = Q.top();

            // cout << i << ' ' << u.ff << ' ' << u.ss << endl;

            if(i + m < -u.ss){
                Q.pop();
                continue;
            }
            else {
                Q.push({u.ff-1, -i});
                ans[i] = -u.ss - i;
                break;
            }
        }
    }

    if(ans[0] == -1){
        cout << -1 << endl;
        return 0;
    }
    for(int i = 0;i < n;i += ans[i]){
        cout << ans[i] <<' ';
    }

    return 0;
}

