void leave(string message) {
    cout << message << endl;
    exit(0);
}

int main() {
    lint n, m;
    cin >> n >> m;

    string s;
    cin >> s;

    SegmentTree<lint> ok(n+1, 0, [](lint a, lint b){ return max(a, b); });
    ok.update(0, 1);
    for(lint now=1; now<=n; now++) {
        if(s[now] == '1')  continue;
        ok.update(now, ok.query(now-m, now));
    }

    vector<lint> g(n+1);
    for(lint i=0; i<n+1; i++)  g[i] = ok[i];

    vector<lint> ans;
    lint x = n;
    while(x != 0) {
        for(lint jump=m; jump>0; jump--) {
            if(g[x-jump]) {
                x -= jump;
                ans.push_back(jump);
                break;
            }
            if(jump == 1) {
                leave("-1");
            }
        }
    }

    reverse(begin(ans), end(ans));
    for(auto& e : ans)  cout << e << " \n"[&e == &ans.back()];
}

