    const ll INF = (1ll<<60);

    seg.update(0, 0);

    for(int i=1;i<=N;i++){
    	if(S[i]=='1') continue;
    	ll lb = max(0ll, i-M);
    	ll rb = i-1;
    	auto mi = seg.minimum(lb, rb+1);
    	seg.update(i, mi.first+1);
    }

    if(seg.get_val(N)==INF){
    	cout << -1 << endl;
    }else{

		ll now = N;
		vector<ll> res;
		while(now!=0){
			ll lb = max(0ll, now-M);
			ll rb = now-1;
			auto pp = seg.minimum(lb, rb+1);
			ll pos = pp.second;
			res.push_back(now-pos);
			now = pos;
		}
		ll L = res.size();
		REP(i, res.size()){
			cout << res[L-1-i] << " ";
		}
		cout << endl;

    }

