void solve() {
    if (s[0] == '1' || s[n] == '1') {
        cout << "-1\n";
        return ;
    }

    dp[n] = 0;
    set< pair<int, int> > st;
    st.insert({0, n});

    for (int i = n - 1; i >= 0; --i) {
        if (i + m + 1 <= n)
            st.erase({dp[i + m + 1], i + m + 1});

        if (s[i] == '0') {
            dp[i] = st.begin()->first + 1;
            p[i] = st.begin()->second;
