            dp[i] = MOD;
        }

        st.insert({dp[i], i});
    }

    if (dp[0] >= MOD) {
        cout << "-1\n";
        return ;
    }

    for (int i = 0; i < n; i = p[i])
        cout << p[i] - i << ' ';

    cout << endl;
}

