	if(s[0] == '1' || s[n] == '1')
	  return 1 ;
	int max1 = 0 ;
	for(int i = 1 ; i <= n ; i ++)
	{
		if(s[i] == '0')  
		{
			a[++ cnt] = i ;
			continue ;
		}	
		int j = i ;
		while(j + 1 <= n && s[j + 1] == '1')
		  j ++ ;
		max1 = max(max1 , j - i + 1) ;
        i = j ;
	}
	if(max1 >= m)
	  return 1 ;
	return 0 ;
}
