template <typename Monoid>
struct SegmentTree{
private:
    using F = function<Monoid(Monoid, Monoid)>;
    int N;
    vector<Monoid> node;
    F f;
    Monoid e;  // identity element

public:
    SegmentTree(){}
    SegmentTree(F f, Monoid e):f(f), e(e){}
    void init(int sz){
        N = 1;
        while(N < sz) N <<= 1;
        node.assign(2*N-1, e);
    }
    void build(vector<Monoid>& v){
        int sz = int(v.size());
        init(sz);
        for(int i=0; i<sz; i++){
            node[i+N-1] = v[i];
        }
        for(int i=N-2; i>=0; i--){
            node[i] = f(node[i*2+1], node[i*2+2]);
        }
    }
    void update(int k, Monoid x){
        k += N-1;
        node[k] = x;
        while(k > 0){
            k = (k-1)/2;
            node[k] = f(node[2*k+1], node[2*k+2]);
        }
    }
    // [a,b)
    Monoid query(int a, int b){return query(a, b, 0, 0, N);}
    Monoid query(int a, int b, int k, int l, int r){
        if(b <= l || r <= a) return e;
        if(a <= l && r <= b) return node[k];
        Monoid vl, vr;
        vl = query(a, b, 2*k+1, l, (l+r)/2);
        vr = query(a, b, 2*k+2, (l+r)/2, r);
        return f(vl, vr);
    }
};

int main(){
    int n, m;
    string s;
    cin >> n >> m >> s;
    SegmentTree<P> dp([](P a, P b){return min(a,b);}, P(IINF,IINF));
    vector<P> tmp(n+1);
    for(int i=0;i<=n;i++){
        tmp[i] = P(IINF, i);
    }
    dp.build(tmp);
    dp.update(n, P(0,n));
    for(int i=n-1;i>=0;i--){
        if(s[i] == '1') continue;
        dp.update(i, P(dp.query(i+1, min(i+m+1,n+1)).first+1,i));
    }
    if(dp.query(0,1).first == IINF){
        cout << -1 << endl;
    }
    else{
        vector<int> ans;
        int now = 0;
        while(now < n){
            int nxt = dp.query(now+1, now+m+1).second;
            ans.emplace_back(nxt - now);
            now = nxt;
        }
        for(int i=0;i<int(ans.size());i++){
            cout << ans[i] << " \n"[i==int(ans.size())-1];
        }
    }
    return 0;
}

