#include "bits/stdc++.h"

using namespace std;

const int maxn = 1e5 + 5;
const int INF = 1e9 + 9;

struct SegmentTree {
      int minval, minpos;
      SegmentTree(int minval = INF, int minpos = INF)
            : minval(minval), minpos(minpos) {}

      void assignLeaf(int num, int pos) {
            minval = num;
            minpos = pos;
      }
      void marge(const SegmentTree lchild, const SegmentTree rchild) {
            if (lchild.minval <= rchild.minval) {
                  minval = lchild.minval;
                  minpos = lchild.minpos;
            }
            else {
                  minval = rchild.minval;
                  minpos = rchild.minpos;
            }
      }
} Tree[maxn * 4];

void update(int node, int a, int b, int pos, int num, int minpos) {
      if (a > pos or b < pos) {
            return;
      }
      if (a >= pos and b <= pos) {
            Tree[node].assignLeaf(num, minpos);
            return;
      }
      int lchild = node * 2;
      int rchild = lchild + 1;
      int mid = (a + b) / 2;
      update(lchild, a, mid, pos, num, minpos);
      update(rchild, mid + 1, b, pos, num, minpos);
      Tree[node].marge(Tree[lchild], Tree[rchild]);
}

SegmentTree query(int node, int a, int b, int i, int j) {
      if (a > j or b < i) {
            return SegmentTree();
      }
      if (a >= i and b <= j) {
            return Tree[node];
      }
      int lchild = node * 2;
      int rchild = lchild + 1;
      int mid = (a + b) / 2;
      SegmentTree p = query(lchild, a, mid, i, j);
      SegmentTree q = query(rchild, mid + 1, b, i, j);
      SegmentTree res;
      res.marge(p, q);
      return res;
}

void Task() {
      int n, m;
      cin >> n >> m;
      string s;
      cin >> s;
      vector <int> dp(n + 1, -1);
      vector <int> par(n + 1, 0);
      update(1, 0, n, 0, 0, 0);
      dp[0] = 0;
      par[0] = 0;
      for (int i = 1; i <= n; i++) {
            if (s[i] == '1') {
                  continue;
            }
            int l = max(0, i - m);
            int r = i;
            SegmentTree seg = query(1, 0, n, l, r);
            if (seg.minpos == INF) {
                  break;
            }
            dp[i] = seg.minval + 1;
            par[i] = seg.minpos;
            update(1, 0, n, i, dp[i], i);
      }
      if (dp[n] == -1) {
