void solve() {
    int n, m;
    cin >> n >> m;
    string s;
    cin >> s;

    SegTree<int> dp(n + 1, inf, [](int a, int b) { return min(a, b); /* query */ }, [](int a, int b) { return b; /* change */ });
    dp.change(n, 0);
    for (int i = n - 2; i >= 0; --i) {
        if (s[i] == '1') continue;
        dp.change(i, dp.query(i + 1, i + m + 1) + 1);
    }
    // dp.out();
    if (dp.query(0, 1) == inf) {
        cout << -1 << endl;
        return;
    }
    vector<int> ans;
    int now = n;
    while (now != 0) {
        for (int i = now - m; i <= now - 1; ++i) {
            if (dp.query(i, i + 1) == dp.query(now, now + 1) + 1) {
                ans.eb(now - i);
                now = i;
                break;
            }
        }
    }
    reverse(all(ans));
    cout << ans << endl;
}

