/* constant */

const int MAX_N = 100000;
const int MAX_E2 = 1 << 18; // = 262144
const int INF = 1 << 30;

/* typedef */

template <typename T, const int MAX_E2>
struct SegTreeMin {
  int n, e2;
  T nodes[MAX_E2];
  SegTreeMin() {}

  void init(int _n) {
    n = _n;
    for (e2 = 1; e2 < n; e2 <<= 1);
    fill(nodes, nodes + MAX_E2, INF);
  }

  T &get(int i) { return nodes[e2 - 1 + i]; }

  void set(int i, T v) {
    int j = e2 - 1 + i;
    nodes[j] = v;
    while (j > 0) {
      j = (j - 1) / 2;
      nodes[j] = min<T>(nodes[j * 2 + 1], nodes[j * 2 + 2]);
    }
  }

  T min_range(int r0, int r1, int k, int i0, int i1) {
    if (r1 <= i0 || i1 <= r0) return INF;
    if (r0 <= i0 && i1 <= r1) return nodes[k];

    int im = (i0 + i1) / 2;
    T v0 = min_range(r0, r1, k * 2 + 1, i0, im);
    T v1 = min_range(r0, r1, k * 2 + 2, im, i1);
    return min<T>(v0, v1);
  }
  T min_range(int r0, int r1) { return min_range(r0, r1, 0, 0, e2); }
};

/* global variables */

char s[MAX_N + 4];
SegTreeMin<int,MAX_E2> st;
int rs[MAX_N];

/* subroutines */

/* main */

int main() {
  int n, m;
  scanf("%d%d%s", &n, &m, s);

  st.init(n + 1);
  st.set(n, 0);

  for (int i = n - 1; i >= 0; i--)
    if (s[i] == '0') {
      int a = st.min_range(i + 1, min(i + m + 1, n + 1));
      if (a >= INF) {
	puts("-1");
	return 0;
      }
      st.set(i, a + 1);
    }

  int rn = 0;
  for (int i = 0; i < n;) {
    int ai = st.get(i);
    int j = i + 1;
    while (j < n && st.get(j) >= ai) j++;
    rs[rn++] = j - i;
    i = j;
  }

  for (int i = 0; i < rn; i++) {
    if (i) putchar(' ');
    printf("%d", rs[i]);
  }
  putchar('\n');
  return 0;
}

