vector<int> solve(int N, int M, const string& s)
{
    int R = N, L = R - 1;
    vector<int> ans;

    while (R > 0)
    {
        int free = -1;

        while (L >= 0 and (R - L <= M))
        {
#ifdef DEBUG
//cout << "Aqui 1: L = " << L << ", s[L] = " << s[L] << "\n";
#endif
            if (s[L] == '0')
            {
                free = L;
            }
            --L;
        }
#ifdef DEBUG
    cout << "R = " << R << ", L = " << L << ", s[L] = " << s[L] << ", free = " << free << ": "
        << (free == -1 ? 'x' : s[free]) << endl;
#endif
        if (free == -1)
            return { };

        ans.push_back(R - free);
        R = free;
    }

    reverse(ans.begin(), ans.end());

    return ans;
}

