const int INF = 100000000;
const ll LINF = 1e18+5;

const int MAX_N = 200000;
ll rmq_N;
ll rmq_dat[2*MAX_N-1];

// 要素数n_で初期化
void rmq_init(int n_) {
    // rmq_Nを2のべき乗にする
    rmq_N = 1;
    while(rmq_N < n_) rmq_N *= 2;
    rep(i,2*rmq_N-1) rmq_dat[i] = INF;
}

// k番目の値をaに変更
void rmq_update(int k, int a) {
    k += rmq_N - 1;
    rmq_dat[k] = a;
    while (k > 0) {
        k = (k - 1) / 2;
        rmq_dat[k] = min(rmq_dat[k * 2 + 1], rmq_dat[k * 2 + 2]);
    }
}

// [a, b)の最小値を求める
// 接点の番号k，subとして[l,r)の最小値を求めてる
int rmq_query(int a, int b, int k, int l, int r) {
    if (r<=a || b<=l) return INF;
    if (a<=l && r<=b) return rmq_dat[k];
    else {
        int vl = rmq_query(a,b,k*2+1,l,(l+r)/2);
        int vr = rmq_query(a,b,k*2+2,(l+r)/2,r);
        return min(vl,vr);
    }
}

int main() {
    ll N, M;
    cin >> N >> M;
    rmq_init(N+1);
    string S;
    cin >> S;
    ll Sn[100001] = {};
    rep(i,N+1) {
        Sn[i] = S[i] - '0';
    }
    ll Msub = 0;
    rep(i,N+1) {
        if(Sn[i] == 1) Msub++;
        else Msub = 0;
        if(Msub ==M) {
            cout << -1 << endl;
            return 0;
        }
    }
    ll f[100001] = {};
    f[N] = 0;
    rmq_update(N, 0);
    for(ll i=N-1;i>=0;i--) {
        if(Sn[i] == 1) {
            f[i] = INF;
            rmq_update(i, INF);
            continue;
        }
        ll end = min(N, i+M);
        ll minnum = rmq_query(i+1, end+1, 0, 0, rmq_N);
        f[i] = minnum + 1;
        rmq_update(i, f[i]);
    }
    vector<ll> route;
    ll pos = 0;
    while(pos!=N) {
        ll dis = 1;
        while(f[pos+dis] != f[pos] - 1) dis++;
        route.push_back(dis);
        pos += dis;
    }
    for(auto r : route) cout << r << " ";
    cout << endl;
    return 0;
}

