int N, M, DP[int(1e5 + 5)];
char S[int(1e5 + 5)];

int main(){
  scanf("%d%d", &N, &M);
  scanf("%s", S);

  fill(DP, DP + N + 1, 1e9);
  DP[0] = 0;
  priority_queue <int> que; que.push(0);

  while (!que.empty() && DP[N] == 1e9){
    int Q = que.top(); que.pop();
    for (int i = 1; i <= M; i++){
      int next = Q + i;
      if (next > N) continue;
      if (S[next] == '1') continue;
      if (DP[next] != 1e9) continue;
      que.push(next);
      DP[next] = DP[Q] + 1;
    }
  }

  if (DP[N] == 1e9){
    printf("-1\n"); return 0;
  }

  vector <int> ans;
  int now = N;
  while (now > 0){
    for (int i = M; i >= 1; i--){
      if (now - i < 0) continue;
      if (DP[now] == DP[now - i] + 1){
        now -= i;
        ans.push_back(i);
        break;
      }
    }
  }

  printf("%d", ans[ans.size() - 1]);
  for (int i = ans.size() - 2; i >= 0; i--){
    printf(" %d", ans[i]);
  }
  printf("\n");

  return 0;
}

