		int st = j-a;
		if(st>M){
			int found = 0;
			for(int q = j-M;q<j;q++){
				if(s[q]=='0'){
					a = q;
					found = 1;
					break;
				}
			}
			if(!found){
				return nn;
			}
		}
	    prev[j] = a;
	}
	vector<int> numbers;
	int sta = N;
	while(sta!=0){
		numbers.push_back(sta-prev[sta]);
		sta = prev[sta];
	}

	return numbers;

}
