		if(s[next] == '1') {
			next = prev[next];
			if(next == cur) {
				ok = false;
				break;
			}
			jump = cur - next;
		}

		ans.push_back(jump);
		cur = next;
	}

	reverse(ans.begin(), ans.end());
	int sz = ans.size();
	if(ok) {
		for(int i = 0; i < sz; i++) {
			cout << ans[i] << " \n"[i==sz-1];
		}
	} else {
		cout << -1 << endl;
	}
