int rec(int no,int s,int e,int st,int en)
{
    if(s>=st&&e<=en)
        return tr[no];
    int mid=(s+e)/2;
    if(mid>=en)
        return rec(no*2,s,mid,st,en);
    else if(mid<st)
        return rec(no*2+1,mid+1,e,st,en);
    else
    {
        int in1 = rec(no*2,s,mid,st,mid);
        int in2 = rec(no*2+1,mid+1,e, mid+1,en);
        if(val[in1] <= val[in2])
            return in1;
        else
            return in2;
    }
}
