int main()
{
  cin.tie(0);
  ios_base::sync_with_stdio(false);
  int N, M;
  string S;
  cin >> N >> M >> S;
  // 後ろからの最短手数
  // 最短手数を満たす動かし方の中で辞書順最小を求める。
  // なるべく後ろから動きたいのでqueueを使う。
  vector<int> dist(N + 1, INF);
  queue<int> q;
  dist[N] = 0;
  q.push(N);
  for (int i = N - 1; i >= 0; --i)
  {
    if (S[i] == '1')
      continue;
    while (q.front() - i > M || dist[q.front()] == INF)
    {
      if (q.empty())
      {
        cout << -1;
        return 0;
      }
      q.pop();
    }
    dist[i] = dist[q.front()] + 1;
    q.push(i);
  }

  vector<int> ans;
  int pos = 0;
  int rest = dist[0];
  while (pos != N)
  {
    --rest;
    int move = 1;
    while (dist[pos + move] != rest)
      ++move;
    pos += move;
    ans.push_back(move);
  }

  for (int i = 0; i < ans.size(); ++i)
    cout << ans[i] << " \n"[i == ans.size() - 1];
  return 0;
}

