int n,m;

void add(vector<pair<int, int>> &segtree, pair<int,int> val, int x, int ind=1, int l=0, int r=n){
    if(l==r){
        segtree[ind] = val;
        return;
    }
    int mid = (l + r) / 2;
    if(x <= mid)
        add(segtree, val, x, ind*2, l, mid);
    else
        add(segtree, val, x, ind*2+1, mid+1, r);
    segtree[ind] = min(segtree[ind*2], segtree[ind*2+1]);
}

pair<int, int> find(vector<pair<int,int>> &segtree, int x, int y, int ind=1, int l=0, int r=n){
    if(x<=l && r<=y){
        return segtree[ind];
    }
    int mid = (l+r)/2;
    if(mid >= y) return find(segtree, x, y, ind*2, l, mid);
    else if(mid < x) return find(segtree, x, y, ind*2+1, mid+1, r);
    else return min(find(segtree, x, mid, ind*2, l, mid), find(segtree, mid+1, y, ind*2+1, mid+1, r));
}

