#define ll long long

class RMQ {
	int n;
	vector<int>dat;
public:
	RMQ(int n_) {
		n = 1;
		while (n < n_)n *= 2;
		dat.resize(2 * n - 1);
		for (int i = 0; i < 2 * n - 1; i++)dat[i] = INT_MAX;
	}
	void update(int k, int a) {
		k += n - 1;
		dat[k] = a;
		while (k > 0) {
			k = (k - 1) / 2;
			dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
		}
	}
	int query(int a, int b, int k = 0, int l = 0, int r = 0) {
		if (r <= l)r = n;
		if (r <= a || b <= l)return INT_MAX;
		if (a <= l && r <= b)return dat[k];
		int vl = query(a, b, k * 2 + 1, l, (r + l) / 2);
		int vr = query(a, b, k * 2 + 2, (r + l) / 2, r);
		return min(vl, vr);
	}
};

