int n, m;
string s;

int f[MAXN];
deque<int> Q;

void pushFront(int i){
	while(!Q.empty() && f[i] < f[Q.front()]){
		Q.pop_front();
	}
	Q.push_front(i);
}

void printAns(int i){
	if(i==n) return;
	for(int cur = 1; cur <= m; ++cur){
		if(f[i+cur] == f[i]-1){
			cout << cur << " ";
			printAns(i+cur);
			return;
		}
	}
}

signed main(){
	cin >> n >> m >> s;
	f[n] = 0;
	pushFront(n);
	for(int i= n-1; i>=0; --i){
		while(!Q.empty() && Q.back() > i+m) Q.pop_back();
		if(s[i] == '1') f[i] = INF;
		else f[i] = 1 + f[Q.back()];
		pushFront(i);
	}
	if(f[0] >= INF){
		cout << -1;
		return 0;
	}
	printAns(0);
}

