    if (S.front() != '0')
    {
        cout << -1 << endl;
    }
    if (S.back() != '0')
    {
        cout << -1 << endl;
    }

    reverse(S.begin(), S.end());
    vector<bool> over(S.size());
    for (int i = 0; i < over.size(); i++)
    {
        over[i] = S[i] == '0';
    }

    bool now = true;
    long long count = 0;
    vector<pair<bool, long long>> comp;
    for (int i = 0; i < over.size(); i++)
    {
        if (now != over[i])
        {
            comp.push_back(make_pair(now, count));
            now = over[i];
            count = 1;
        }
        else
        {
            count++;
        }
    }
    if (count > 0)
    {
        comp.push_back(make_pair(now, count));
    }

    vector<long long> ans;
    long long current = 0;
    long long idx = 0;
    long long remain = comp[0].second - 1;
    while (N > 0)
    {
        long long m = M;
        long long sum = 0;
        while (m > 0)
        {
            if (remain == 0)
            {
                if ((idx + 1) < comp.size() && comp[idx + 1].second < m)
                {
                    m -= comp[idx + 1].second + 1;
                    sum += comp[idx + 1].second + 1;
                    idx += 2;
                    remain = comp[idx].second - 1;
                }
                else
                {
                    m = 0;
                }
            }
            else
            {
                long long d = min(remain, m);
                sum += d;
                m -= d;
                remain -= d;
            }
        }
        if (sum == 0)
        {
            cout << -1 << endl;
            return 0;
        }
        ans.push_back(min(N, sum));
        N -= sum;
    }
    reverse(ans.begin(), ans.end());
    for (long long a : ans)
    {
        cout << a << " ";
    }
    cout << endl;
}

