// セグメント木
template <class M> class ST {
    void init(int _n) {
        for (n = 1, lev = 0; n < _n; n <<= 1, ++lev);
        d.assign(n << 1, u1);
    }

public:
    int n, lev;
    vector<M> d;
    virtual void assign(int, M) = 0;    // 更新処理
    virtual M f(M, M) = 0;              // モノイドの演算
    const M u1;                         // モノイドの単位元

    ST(M u1) : u1(u1) {}

    // 構築
    void build(const vector<M>& v) {
        int _n = v.size();
        init(_n);
        for (int i = 0; i < _n; ++i) d[n + i] = v[i];
        for (int i = n - 1; i > 0; --i) d[i] = f(d[(i << 1) | 0], d[(i << 1) | 1]);
    }
    void build(int _n) { init(_n); }

    // k番目の要素をxに更新 (k: 0-indexed)
    void update(int k, M x) {
        assign(k, x);
        k += n;
        while (k >>= 1) d[k] = f(d[(k << 1) | 0], d[(k << 1) | 1]);
    }

    // 半開区間 [a, b) に対するクエリ (a, b: 0-indexed)
    M query(int a, int b) {
        M L = u1, R = u1;
		for (int l = a + n, r = b + n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) L = f(L, d[l++]);
            if (r & 1) R = f(d[--r], R);
		}
        return f(L, R);
    }
    M query(int a) { return query(a, a + 1); }
};

// Range Minimum Query (RmQ)
template <class M>
struct RmQ : public ST<M> {
    using ST<M>::ST;
    RmQ(const M u1) : ST<M>(u1) {}
    M f(M a, M b) override { return min(a, b); }
    void assign(int k, M x) override { this->d[k + this->n] = x; }
};

