ll sum[MM*4];
void update(int l, int r, int k, int L, ll val)
{
    if(l==r)
    {
        sum[k] = val;
        return;
    }
    int mid = (l+r)/2;
    if(L<=mid)update(l,mid,k*2,L,val);
    else update(mid+1,r,k*2+1,L,val);
    sum[k] = min(sum[k*2],sum[k*2+1]);
}
ll query(int l, int r, int k, int L, int R)
{
    if(l>R || r<L)return MAX;
    if(l>=L && r<=R)return sum[k];
    int mid = (l+r)/2;
    return min(query(l,mid,k*2,L,R),query(mid+1,r,k*2+1,L,R));
}

ll dp[MM];
