void solve() {
  int n, m; cin >> n >> m;
  string s; cin >> s;

  vi ans;
  int idx = n;
  while (idx > 0) {
    bool possible = false;
    for (int i=max(0, idx-m); i<idx; ++i) {
      if (s[i] == '1') continue;
      ans.push_back(idx-i);
      idx = i;
      possible = true;
      break;
    }
    if (!possible) {
      cout << -1 << endl;
      return;
    }
  }

  reverse(ALL(ans));
  cout << ans << endl;
}


