void solver::run(){
    is >> N >> M;
    if(!is) return;
    string S;
    is >> S;
    SegmentTree<ll> seg(N+1, [](ll a, ll b){return min(a, b);}, INF);
    seg.update(0, 0);
    for (int i = 1; i <= N; ++i) {
        if(S[i] == '1') continue;
        ll q = seg.query(max(0ll, i-M), i+1);
        seg.update(i, q+1);
    } // end i
    if(seg[N] >= INF){
        os << -1 << endl;
        return;
    }
    int count = seg[N];
    vector<ll> ans(count+1, INF);
    ans[count] = N;
    ans[0] = 0;
    count--;
    for (int j = N - 1; j >= 1; --j) {
        ll c = seg[j];
        if(c >= INF) continue;
        if(c == count -1) count--;
        if(c == count and j + M >= ans[count+1]){
            ans[count] = j;
        }
    } // end j
    for (int i = 0; i < ans.size() - 1; ++i) {
        os << ans[i+1] - ans[i] << ' ';
    } // end i
    os << endl;

}

