    int n, m; cin >> n >> m;
    string s; cin >> s;
    SegTree<int> seg(vector<int>(n + 1, INF), "min", INF);
    seg.update(0, 0);
    vector<int> bef(n + 1);
    FOR (i, 1, n + 1) {
        if (s[i] != '1') {
            int sita = max(0ll, i - m);
            seg.update(i, seg.getval(sita, i) + 1);
            if (seg.getval(sita, i) != INF) {
                bef[i] = seg.bs(sita, seg.getval(sita, i));
            }
        }
    }
    if (seg.getval(n, n + 1) == INF) {
        cout << -1 << endl;
    } else {
        vector<int> res;
        int now = n;
        res.pb(now);
        while (now != 0) {
            res.pb(bef[now]);
            now = bef[now];
        }
        reverse(all(res));
        FOR (i, 1, res.size()) {
            cout << res[i] - res[i - 1] << " ";
        }
        cout << endl;
    }
    return;
}

