const int MAXN = 1e5 + 10, INF = 1e18; 

int n, m;
string s;
pii t[MAXN * 4];

void upd(int v, int tl, int tr, int id, int x) {
    if (tr < id || tl > id) {
        return; 
    }
    if (tl == tr) {
        t[v] = {x, id};
        return;
    }
    int tm = (tl + tr) / 2;
    upd(v * 2, tl, tm, id, x);
    upd(v * 2 + 1, tm + 1, tr, id, x);
    if (t[v * 2].x <= t[v * 2 + 1].x) {
        t[v] = t[v * 2];
    }
    else {
        t[v] = t[v * 2 + 1];
    }
}

pii gt(int v, int tl, int tr, int l, int r) {
    if (tr < l || tl > r) {
        return {INF, -1};
    }
    if (l <= tl && tr <= r) {
        return t[v];
    }
    int tm = (tl + tr) / 2;
    pii ans1 = gt(v * 2, tl, tm, l, r);
    pii ans2 = gt(v * 2 + 1, tm + 1, tr, l, r);
    if (ans1.x <= ans2.x) {
        return ans1;
    }
    else {
        return ans2;
    }
}

void solve() {
    cin >> n >> m;
    cin >> s;
    for (int i = 0; i < MAXN * 4; ++i) {
        t[i] = {INF, -1};
    }
    upd(1, 0, n, 0, 0); 

    vec<int> pr(n + 1, -1);
    for (int i = 1; i <= n; ++i) {
        pii cur = gt(1, 0, n, max(0ll, i - m), i);
        if (cur.x != INF && s[i] != '1') {
            pr[i] = cur.y;
            upd(1, 0, n, i, cur.x + 1);
        }
    }

    pii cur = gt(1, 0, n, n, n);
    if (cur.x == INF) {
        print(-1);
    }
    else {
        // print(cur.x);
        vec<int> ans;
        int i = n;
        while (i != -1) {
            ans.pb(i + 1);
            i = pr[i];
        }
        reverse(all(ans));
        vec<int> ans2;
        for (int i = 1; i < $(ans); ++i) {
            ans2.pb(ans[i] - ans[i - 1]);
        }
        cout << ans2 << endl;
    }
}

