void run(const string& s, int x, vi& steps) {
  assert(S[x] == '0');
  assert(x<=N);

  if (x==N) return;

  int j = min({x+M, N});
  for (; j>=x; j--) {
    if (S[j]=='0') break;
  }
  if (x==j) {
    steps.clear();
    return;
  }
  steps.emplace_back(j-x);
  run(s, j, steps);
}

