        while(!pq.empty() && -1*pq.top().second > i+m)
        {
            pq.pop();
        }
        if(!pq.empty())
        {
            pair<int,int> cur = pq.top();
            dist[i] = -1*cur.first + 1;
            nxt[i] = -1*cur.second - i;
        }
        pq.push({-1*dist[i], -1*i});
    }
    if(dist[0] >= MX)
    {
        cout << -1 << '\n';
        return 0;
    }
    int x = 0;
    while(x < n)
    {
        cout << nxt[x] << " ";
        x += nxt[x];
    }

    return 0;
}

