using namespace std ;

const int MAX = 1e5 + 10 ;
const int inf = 1e9 ;
int dp[MAX] , tree[4 * MAX] ;
map<int , int>to , last ;
int n , m;
string s ;

void update(int node , int l , int r , int idx , int val)
{
	if(idx > r || idx < l)
		return ;
	if(l == r)
	{
		tree[node] = val ;
		return ;
	}
	int mid = (l + r) >> 1 ;
	update(node << 1 , l , mid , idx , val) ;
	update(node << 1 | 1 , mid + 1 , r , idx , val) ;
	tree[node] = min(tree[node << 1] , tree[node << 1 | 1]) ;
}

int query(int node , int l , int r , int from , int to)
{
	if(to < l || from > r)
		return inf;
	if(l >= from && r <= to)
		return tree[node] ;
	int mid = (l + r) >> 1 ;
	int a = query(node << 1 , l , mid , from , to) ;
	int b = query(node << 1 | 1 , mid + 1 , r , from , to) ;
	return min(a , b) ;
}

int main()
{
	ios_base::sync_with_stdio(0) ;
	cin.tie(0) ;
	cin>>n>>m ;
	cin>>s ;
	dp[n] = 1 ;
	last[dp[n]] = n ;
	update(1 , 0 , n , n , dp[n]) ;
	for(int i = n-1 ; i >= 0 ; --i)
	{
		if(s[i] == '1')
		{
			dp[i] = inf ;
			update(1 , 0 , n , i , dp[i]) ;
			last[dp[i]] = i ;
			continue ;
		}
		dp[i] = query(1 , 0 , n , i+1 , min(n , i+m)) + 1 ;
		update(1 , 0 , n , i , dp[i]) ;
		to[i] = last[dp[i] - 1] - i;
		last[dp[i]] = i ;
	}
	if(dp[0] >= inf)
		return cout<<-1<<"\n" , 0 ;
	int cur = 0 ;
	while(cur != n)
	{
		cout<<to[cur]<<" " ;
		cur += to[cur] ;
	}
	return 0 ;
}

