typedef pair<int, int> P;
P smt[maxn * 4];
vector<int> ans;

void update(int idx, int l, int r, int k, int x)
{
    if (l > k || r < k)
        return;
    if (l == r)
    {
        smt[idx] = P(x, l);
        return;
    }
    int mid = (l + r) / 2;
    update(idx << 1, l, mid, k, x);
    update(idx << 1 | 1, mid + 1, r, k, x);
    smt[idx] = min(smt[idx << 1], smt[idx << 1 | 1]);
}

P query(int idx, int l, int r, int a, int b)
{
    if (r < a || l > b)
        return P(INT_MAX, 0);
    if (l >= a && r <= b)
        return smt[idx];
    int mid = (l + r) / 2;
    return min(query(idx << 1, l, mid, a, b), query(idx << 1 | 1, mid + 1, r, a, b));
}

