            dp[i] = INT_MAX;
            continue;
        }
        int l = max(0, i - m);
        int r = i - 1;
        P p = query(1, 0, n, l, r);
        if (p.first == INT_MAX)
        {
            update(1, 0, n, i, INT_MAX);
            dp[i] = INT_MAX;
            continue;
        }
        dp[i] = p.first + 1;
        f[i] = p.second;
        update(1, 0, n, i, dp[i]);
