    if(val[tr[no*2]] <= val[tr[no*2+1]])
        tr[no] = tr[no*2];
    else
        tr[no] = tr[no*2+1];
}

int rec(int no,int s,int e,int st,int en)
{
    if(s>=st&&e<=en)
        return tr[no];
    int mid=(s+e)/2;
    if(mid>=en)
