}

//(x,y)とv[0]x+v[1]y+v[2]=0との距離
double dis(vll v,ll x,ll y){
    double s=sqrt(v[0]*v[0]+v[1]*v[1]);
    return (double) abs(v[0]*x+v[1]*y+v[2])/s;
}

