template<class T, T Op(T, T), T E()>
struct SegmentTree {
  const int n;
  vector<T> t;
  SegmentTree(int _n) : n(_n), t(2 * n, E()) {}
  T& operator[](int i) { return t[n + i]; }
  void build() { for (int i = n - 1; i >= 1; --i) t[i] = Op(t[2 * i], t[2 * i + 1]); }
  T acc(int l, int r) const {
    l = max(l, 0);
    r = min(r, n);
    T a = E(), b = E();
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l & 1) a = Op(a, t[l++]);
      if (r & 1) b = Op(t[--r], b);
    }
    return Op(a, b);
  }
  void set(int i, const T& a) {
    t[i += n] = a;
    while (i >>= 1) t[i] = Op(t[2 * i], t[2 * i + 1]);
  }
};
template<class T> T _min(T a, T b) { return b < a ? b : a; }
pair<int, int> inf() { return {0x3f3f3f3f, -1}; }

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  int n, m;
  cin >> n >> m;
  string s;
  cin >> s;
  SegmentTree< pair<int, int>, _min, inf > dp(n + 1);
  dp.set(n, {0, n});
  for (int i = n - 1; i >= 0; --i) {
    if (s[i] == '0') {
      dp.set(i, {1 + dp.acc(i + 1, i + 1 + m).first, i});
    }
  }
  if (dp[0].first > n) {
    cout << "-1\n";
    return 0;
  }
  vector<int> res;
  int i = 0;
  while (i < n) {
    int ni = dp.acc(i + 1, i + 1 + m).second;
    res.push_back(ni - i);
    i = ni;
  }
  m = res.size();
  for (int j = 0; j < m; ++j) {
    cout << res[j] << " \n"[j == m - 1];
  }
}

