template<typename T>
struct SegmentTree{//セグ木によるRMQ
  private:
      int n;
      vector<T>node;
      T MAXV=numeric_limits<T>::max();

  public:
      SegmentTree(vector<T>v){
        //構築O(N)

        int sz=v.size();
        n=1;
        while(n<sz)n*=2;//nは配列のサイズ以上となる最小の2の冪
        node.resize(2*n-1,MAXV);

        //最下段から順番に値を代入していく
        for(int i=0;i<sz;i++)node[i+n-1]=v[i];
        //最下段までにn-1個のノードがある

        for(int i=n-2;i>=0;i--)node[i]=min(node[2*i+1],node[2*i+2]);
        //自分の子を参照
      }

      void update(int k,T val){//値の更新
        //最下段のノードにアクセス
        k+=(n-1);

        node[k]=val;
        //あとはのぼりながら更新
        while(k>0){
          k=(k-1)/2;//親
          node[k]=min(node[2*k+1],node[2*k+2]);
        }
      }

      T getv(int k){
        k+=n-1;
        return node[k];
      }

      T query(int a,int b,int k=0,int l=0,int r=-1){
        if(r<0)r=n;
        //クエリ[a,b),今見ている節点番号k,それに対応する区間[l,r)

        //[a,b)と[l,r)が交差しないとき
        if(r<=a||l>=b)return MAXV;

        //[a,b)が[l,r)を完全に被覆するとき
        if(a<=l&&b>=r)return node[k];//対象区間のノードの値を返す

        //一部を被覆するとき,子について探索を行う
        T vl=query(a,b,2*k+1,l,(l+r)/2);
        T vr=query(a,b,2*k+2,(l+r)/2,r);
        return min(vl,vr);
      }
};


void solve(){
  int n,m;
  cin>>n>>m;
  string s;
  cin>>s;
  const int inf=numeric_limits<int>::max();
  vector<int>v(n+1,inf);
  SegmentTree<int>seg(v);
  vector<int>dp(n+1,inf);
  dp[n]=0;
  seg.update(n,0);
  for(int i=n-1;i>=0;--i){
    if(s[i]=='1')continue;
    int x;
    x=seg.query(i+1,min(n,i+m)+1);
    if(x==inf){
      cout<<-1<<endl;
      return;
    }
    dp[i]=x+1;
    seg.update(i,dp[i]);
  }
  int cur=0;
  vector<int>ans;
  rep(i,n+1){
    if(dp[cur]==dp[i]+1){
      ans.pb(i-cur);
      cur=i;
    }
  }
  rep(i,ans.size()){
    if(i)cout<<" ";
    cout<<ans[i];
  }
  cout<<endl;
}

int main(){
	ios::sync_with_stdio(false);
  cin.tie(0);
	cout<<fixed<<setprecision(15);
	solve();
	return 0;
}

