int main(){
	ios::sync_with_stdio(0);
	int n, m;
	cin >> n >> m;
	string st;
	cin >> st;
	vector<int> pred(n+1, 0);
	vector<int> post(n+1, 0);

	for(int i=0; i<=n; ++i){
		if(st[i]=='0') pred[i] = i;
		else pred[i] = pred[i-1];
	}
	for(int i=n; i>=0; --i){
		if(st[i]=='0') post[i] = i;
		else post[i] = post[i+1];
	}
	vector<int> path;
	int pos = 0;
	while(pos<n){
		path.push_back(pos);
		if(n-pos<=m){
			path.push_back(n);
			break;
		}
		int k = pred[pos+m];
		if(k==pos){
			cout << -1 << endl;
			return 0;
		}
		pos = k;
	}
	set<ii> pq;
	for(int i=1; i<len(path)-1; ++i)
		pq.insert(ii(path[i+1]-path[i], i));

	while(not pq.empty()){
		auto it = pq.begin();
		int dr = it->ff;
		int i = it->ss; 
		pq.erase(it);
		if(i!=1){
			auto x = ii(path[i]-path[i-1], i-1);
			pq.erase(x);
		}
		int d = m-dr;
		int new_pos = post[max(path[i-1]+1, path[i]-d)];

		if(path[i]==new_pos) continue;

		path[i] = new_pos;
		pq.insert(ii(path[i+1]-path[i], i));
		if(i!=1) pq.insert(ii(path[i]-path[i-1], i-1));
	}
	for(int i=1; i<len(path); ++i)
		cout << path[i]-path[i-1] << " ";
	cout << endl;
}

