struct RMQ {
  using t = long long;
  constexpr static t id() { return std::numeric_limits<t>::min()/2; }
  static t op(const t &a, const t &b) { return std::max(a, b); }
};

struct RmQ {
  using t = long long;
  constexpr static t id() { return 1e9; }
  static t op(const t &a, const t &b) { return std::min(a, b); }
};

template <typename M>
struct SegmentTree {
  int n;
  using T = typename M::t;
  std::vector<T> nodes;

  SegmentTree(std::vector<T> v) {
    int sz = (int)v.size();
    n = 1;
    while (n < sz) n *= 2;
    nodes.resize(2 * n - 1, M::id());
    for (int i = 0; i < sz; i++) nodes[i + n - 1] = v[i];
    for (int i = n - 2; i >= 0; i--)
      nodes[i] = M::op(nodes[i * 2 + 1], nodes[i * 2 + 2]);
  }
  SegmentTree(int _n) {
    n = 1;
    while (n < _n) n *= 2;
    nodes.resize(2 * n - 1, M::id());
  }
  void update(int k, T a) {
    k += n - 1;
    nodes[k] = a;
    while (k > 0) {
      k = (k - 1) / 2;
      nodes[k] = M::op(nodes[2 * k + 1], nodes[2 * k + 2]);
    }
  }
  T get(int k) { return nodes[k + n - 1]; }
  T query(int a, int b) { return query(a, b, 0, 0, n); }

 private:
  T query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return M::id();
    if (a <= l && r <= b)
      return nodes[k];
    else {
      T vl = query(a, b, 2 * k + 1, l, (r + l) / 2),
        vr = query(a, b, 2 * k + 2, (r + l) / 2, r);
      return M::op(vl, vr);
    }
  }
};
int main() {
  int n, m;
  cin >> n >> m;
  string s;
  cin >> s;
  vector<int> dist(n + 1,1e9), rdist(n + 1,1e9);
  auto calc = [&](vector<int> &d) {
    SegmentTree<RmQ> st(n + 1);
    st.update(0, 0);
    d[0] = 0;
    REP(i, n) {
      if (s[i + 1] == '1') continue;
      d[i + 1] = st.query(max(0, i + 1 - m), i + 1)+1;
      st.update(i + 1, d[i + 1]);
    }
  };
  calc(dist);
  reverse(ALL(s));
  calc(rdist);
  reverse(ALL(s));
  reverse(ALL(rdist));
  int d = dist[n];
  if(1e9<=d){
      cout<<-1<<endl;
      return 0;
  }
  vector<vector<int>> pos(n+1);
  REP(i, n + 1) { if(rdist[i]<1e9)pos[rdist[i]].push_back(i); }
  int now=0;
  int rem=d;
  vector<int> ans;
  while(now<n){
      auto c=*lower_bound(ALL(pos[rem-1]),now);
      ans.push_back(c-now);
      rem--;
      now=c;
  }
  for(auto a:ans)cout<<a<<" ";
  cout<<endl;

}

