vector<pair<char,ll>> runLengthEncoding(string s){
	vector<pair<char,ll>> ans;
	char ch=s[0];
	ll count=0;
	for(ll i=0,size=s.size(); i<size; i++){
		if(ch==s[i]){
			count++;
		}else{
			ans.push_back({ch,count});
			ch=s[i];
			count=1;
		}
	}
	ans.push_back({ch,count});
	return ans;
}
