using namespace std;

template <typename X>
struct RMQ{
  vector<X> dat;
  int n;
  X init;

  RMQ(int _n,X _init)
  {
    n = 1;
    init = _init;
    while(n < _n) n *= 2;
    dat.resize(2*n-1);
    rep(i,2*n-1){
      dat[i] = init;
    }
  }

  void update(int k,X a)
  {
    k += n - 1;
    dat[k] = a;
    while(k > 0){
      k = (k - 1)/2;
      dat[k] = min(dat[2*k+1],dat[2*k+2]);
    }
  }

  X query(int a,int b,int k,int l,int r)
  {
    if(r<=a||b<=l) return init;

    if(a<=l&&r<=b) return dat[k];
    else{
      X vl = query(a,b,2*k+1,l,(l+r)/2);
      X vr = query(a,b,2*k+2,(l+r)/2,r);
      return min(vl,vr);
    }
  }
};

int main()
{
  int n,m;
  cin >> n >> m;
  string s;
  cin >> s;
  const int inf=1e+9;

  RMQ<int> rmq(n+1,inf);

  rmq.update(0,0);

  rep1(i,n){
    if(s[i]=='1'){
      continue;
    }
    int l=max(0,i-m);
    int d=rmq.query(l,i,0,0,rmq.n)+1;
    rmq.update(i,d);
  }

  vector<int> dp(n+1);
  rep(i,n+1){
    dp[i]=rmq.dat[i+rmq.n-1];
  }

  if(dp[n]>=inf){
    cout << -1 << "\n";
    return 0;
  }

  vector<int> res(0);
  int l = dp[n];
  int i=n;
  while(i>0){
    int x;
    rep1(j,m){
      if(i-j<0) break;
      if(dp[i-j]==l-1){
