#define S second

struct RLQ{
  int n=(1<<17);
  P data[(1<<18)];
  RLQ(){
  	r(i,(1<<18)){
  		data[i]=P(INT_MAX,INT_MAX);
  	}
  }
  void update(int k,int x){
  	int y=k;
    k+=n-1;
    data[k]=P(x,y);
    while(k>0){
      k=(k-1)/2;
      data[k]=min(data[k*2+1],data[k*2+2]);
    }
  }
  P find(int a,int b,int k=0,int l=0,int r=(1<<17)){
    if(r<=a || b<=l)return P(INT_MAX,INT_MAX);
    if(a<=l && r<=b)return data[k];
    P v1=find(a,b,k*2+1,l,(l+r)/2);
    P v2=find(a,b,k*2+2,(l+r)/2,r);
    return min(v1,v2);
  }
};

