const int N = 100005;

int dp[N], nx[N], it[4 * N];

void build(int k, int l, int r) {
    //cout << k << ' ' << l << ' ' << r << endl;
    if (l == r) {it[k] = l; return;}
    int mid = (l + r) / 2;
    build(2 * k, l, mid);
    build(2 * k + 1, mid + 1, r);
    if (dp[it[2 * k]] <= dp[it[2 * k + 1]]) {
        it[k] = it[2 * k];
    } else it[k] = it[2 * k + 1];
}

void update(int k, int l, int r, int id, int val) {
    if (l > id || r < id) return;
    if (l == id && r == id) {
        it[k] = id;
        return;
    } 
    int mid = (l + r) / 2;
    update(2 * k, l, mid, id, val);
    update(2 * k + 1, mid + 1, r, id, val);
    if (dp[it[2 * k]] <= dp[it[2 * k + 1]]) {
        it[k] = it[2 * k];
    } else it[k] = it[2 * k + 1];
}

int get(int k, int l, int r, int u, int v) {
    if (l > v || r < u) return 0;
    if (l >= u && r <= v) return it[k];
    int mid = (l + r) / 2;
    int g1 = get(2 * k, l, mid, u, v);
    int g2 = get(2 * k + 1, mid + 1, r, u, v);
    if (dp[g1] <= dp[g2]) {
        return g1;
    } else {
        return g2;
    }
}

