    dp[n] = 0;
    update(1, 1, n, n, 0);
    for (int i = n - 1; i >= 1; i--) {
        if (s[i] == '1') continue;
        int k = get(1, 1, n, i + 1, min(n, i + m));
        //cout << i + 1 << ' ' << min(n, i + m) << endl;
        //cout << k << endl;
        if (dp[k] == 1e9) continue;
