	void add(int p, pair<int,int> nv, int l = 0, int r = n, int i = 1){
		if(p > r || p < l)return;
		if(l == r and p == l)tie(v[i], s[i]) = nv;
		else{
			int mid = l+r>>1;
			add(p, nv, l, mid, i<<1), add(p, nv, mid+1, r, i<<1|1);
			if(v[i<<1] < v[i<<1|1]){
				s[i] = s[i<<1];
				v[i] = v[i<<1];
			}
			else if(v[i<<1] > v[i<<1|1]){
				s[i] = s[i<<1|1];
				v[i] = v[i<<1|1];
			}
			else{
				v[i] = v[i<<1];
				s[i] = (s[i<<1] - lst[s[i<<1]] < s[i<<1|1] - lst[s[i<<1|1]] ? s[i<<1] : s[i<<1|1]);
