void upd(int v, int tl, int tr, int pos, int val) {
	if(tl == tr) {
		t[v].first=val;
		t[v].second=pos;

	} else {
		int tm = (tl + tr) / 2;
		if(pos <= tm)
			upd(v + v, tl, tm, pos, val);
		else upd(v + v + 1, tm + 1, tr, pos, val);
		if(t[v + v].second) {
			t[v] = t[v + v];
			if(t[v + v + 1].second){
				t[v] = min(t[v + v], t[v + v + 1]);
			}
		}
		else t[v] = t[v + v + 1];

	}
}

pair <int, int>get(int v, int tl, int tr, int l, int r) {
	if(l > r) return {(int)1e9,0};

	if(tl == l && tr == r) {
