void solve()
{
	READ(int, N, M);
	string S = read<string>();

	vector<int> nextZero(S.size());

	REP(i, N + 1)
	{
		if (S[i] == '1')
		{
			int j = 0;
			while (S[i + j] == '1')
			{
				j++;
			}

			REP(k, j)
			{
				nextZero[i + k] = j - k;
			}
			i += j;
			i--;
		}
	}

	DEBUG(nextZero);
	if (*max_element(allof(nextZero)) >= M)
	{
		WRITE(-1);
		return;
	}

	std::reverse(allof(nextZero));
	std::reverse(allof(S));
	int x = 0;
	vector<int> ans;
	while (x < N)
	{
		if (x + M >= N)
		{
			ans.push_back(N - x);
			break;
		}

		int m = M - nextZero[x + M];
		ans.push_back(m);
		x += m;
	}

	reverse(allof(ans));
	WRITE(ans);

}

#include <iostream>
#include <vector>
#include <string>

using namespace std;

vector<int> solve(int N, int M, const string& S)
{
    vector<int> ans;
    int x = 0;
    while (x < N) {
        int y = -1;
        for (int i = 1; i <= M && x + i <= N; ++i) {
            if (S[x + i] == '0') {
                y = x + i;
            }
        }
        if (y == -1) {
            return {};
        }
        ans.push_back(y - x);
        x = y;
    }
    reverse(ans.begin(), ans.end());
    return ans;
}

