typedef pair<int,int> P;

const int MAX_N = 101000;
const int ST_SIZE = (1<<18);
const int INF = 1e8;


P dat[ST_SIZE]; //{最小値、それを保持する添え字}　の順で保持

int a;

void init(const int& n){ 

  a = 1;

  while( a < n){ a *= 2;}

  for(int i = 0; i < 2*a-1 ; i++){ dat[i].first = INF;}

}

P query(int s,int t, int k, int l, int r){
 // [a,b)の範囲での最小値と、それを与える添え字を返す
  if( r <= s || t <= l){ return {INF,INF};}
  if( s <= l && r <= t){ return dat[k];}
  else{

    P v1 = query(s,t,2*k+1,l,(l+r)/2);
    P v2 = query(s,t,2*k+2,(l+r)/2,r);


    return min(v1,v2); //添え字込みで、最小のものを返す
  }
}

void update(int k, int x){ //k-リーフの値をxに変えた時の更新

  k += a-1;


  dat[k] = {x,k-(a-1)}; //添え字は、リーフのこと

  while( k > 0){ 

    k = (k-1)/2;

    P res1 = dat[2*k+1];
    P res2 = dat[2*k+2];

    dat[k] = min(res1,res2); //添え字込みで、小さい方を返す

  }

}

int main(){

  int N,M; cin >> N >> M;

  if( N < 4){ return 0;}

  vector<int> S(N+1);
  for(int i = 0; i <= N; i++){
    char c; cin >> c; S[i] = c-'0';}


  init(N+1);  //リーフの個数はN+1

  update(N,0); //N(0-indexed)を0に書き換える
  //初期化

  //まずは最短手数を求める
  for(int i = N-1; i >= 0; i--){
    if( S[i] == 1 ){ continue;}

     int right = min(N,i+M);
    //[i+1,right]で最小値を求める

     int res = query(i+1,right+1,0,0,a+1).first; 
    //queryはfirstで最小値、secondでそれを与える添え字を返す


    update(i,res+1);


  } //for-とじ



  //次に、辞書順最小を求める

  int pos = 0; bool reach = true; //ゴールまでたどり着けるか判定

  vector<int> ans;


  while(pos < N ){ 


    int region = min(N,pos+M);

    int next = query(pos,region+1,0,0,a+1).second;

    if( pos == next){ reach = false;break;} 

    pos = next; 

    ans.push_back(pos);


