ll INF=pow(10,9);

struct LazySegment{
    vector<P> dat;
    //要素数
    int n;

    LazySegment(int n_){
        n=1;
        while(n<n_)n*=2;
        dat.resize(2*n);

        for(int i=0;i<2*n-1;i++)
            dat[i]={INF,i-n+1};
    }

    //k番目の値をaに変更
    void update(int k,ll a){
        k+=n-1;
        dat[k].first=a;
        while(k>0){
            k=(k-1)/2;
            if(dat[2*k+1].first<=dat[2*k+2].first) dat[k]=dat[2*k+1];
            else                                   dat[k]=dat[2*k+2];
        }
    }

    //[a,b)の最小値を求める
    //kは節点の番号、[l,r)はその区間
    P query(int a,int b,int k,int l,int r){
        if(r<=a || b<=l)return {INF,INF};
        if(a<=l && r<=b)return dat[k];
        else{
            P vl=query(a,b,2*k+1,l,(l+r)/2);
            P vr=query(a,b,2*k+2,(l+r)/2,r);
            if(vl.first<=vr.first) return vl;
            else                   return vr;
        }
    }
};

int main(){
    int N,M;cin>>N>>M;
    string S;cin>>S;
    vec dp(N);
    LazySegment LS(N+1);LS.update(N,0);
    for(int i=N-1;i>=0;i--){
        if(S[i]=='1') continue;
        P p=LS.query(i+1,min(i+M,N)+1,0,0,LS.n);
        if(p.first==INF){
            cout<<-1<<endl;
            return 0;
        }
        dp[i]=p.second-i;
        LS.update(i,1+p.first);
    }
    int i=0;
    while(i<N){
        cout<<dp[i]<<" ";
        i+=dp[i];
    }
    return 0;
}

