llong n, m;
pair<llong, llong> t[MXN * 4];
string s;

void build(llong v, llong tl, llong tr){
    if(tl == tr) {
        t[v].F = INF;
        return ;
    }
    llong tm = (tl + tr) / 2;
    build(v * 2, tl, tm);
    build(v * 2 + 1, tm + 1, tr);
    t[v].F = min(t[v * 2].F, t[v * 2 + 1].F);
}

pair<llong, llong> get(llong v, llong tl, llong tr, llong L, llong R){
    if(L <= tl && tr <= R){
        return t[v];
    }
    if(R < tl || tr < L) return {INF, INF};
    llong tm = (tl + tr) / 2;
    pair<llong, llong> a = get(v * 2, tl, tm, L, R);
    pair<llong, llong> b = get(v * 2 + 1, tm + 1, tr, L, R);
    if(a.F >= b.F) return b;
    else return a;
}

void upd(llong v, llong tl, llong tr, llong ind, llong x){
    if(tl == tr) {
        t[v].F = x;
        t[v].S = tl;
        return ;
    }
    llong tm = (tl + tr) / 2;
    if(ind <= tm){
        upd(v * 2, tl, tm, ind, x);
    }else{
        upd(v * 2 + 1, tm + 1, tr, ind, x);
    }
    if(t[v + v].F >= t[v + v + 1].F) t[v] = t[v + v + 1];
    else t[v] = t[v + v];
}

int main(){
    ios;
    cin >> n >> m;
    cin >> s;
    build(1, 1, n);
    upd(1, 1, n, n, 0);
    for(llong i = n - 1; i >= 1; i--){
        if(s[i] == '0'){
            pair<llong, llong> ans = get(1, 1, n, i + 1, min(n, i + m));
            upd(1, 1, n, i, ans.F + 1);
        }
    }
    if(get(1, 1, n, 1, min(n, m)).F == INF){
        cout << -1;
        return 0;
    }
    vector<llong> v;
    int cur = 0, last = 0;
    while(cur != n){
        last = cur;
        pair<llong, llong> lol = get(1, 1, n, cur + 1, min(cur + m, n));
        cur = lol.S;
        v.pb(cur - last);
    }
    for(int i = 0; i < v.size(); i++){
        cout << v[i] << ' ';
    }
}

