struct RangeMinQuery{
  P dat[(1<<19)-1];
  int size;

  void init(int n_){
    size=1;
    while(size<n_) size*=2;
    for(int i=0;i<2*size-1;i++)dat[i]=P(INF,INF);
  }

  void update(int k,ll a){
    ll i=k;
    k+=size-1;
    dat[k]=P(a,i);
    while(k>0){
      k=(k-1)/2;
      dat[k]=min(dat[k*2+1],dat[k*2+2]);
    }
  }

  P subquery(int a,int b,int k,int l,int r){
    if(r<=a||b<=l)return P(INF,INF);
    if(a<=l&&r<=b)return dat[k];
    else{
      return min(subquery(a,b,k*2+1,l,(l+r)/2),subquery(a,b,k*2+2,(l+r)/2,r));
    }
  }

  P query(int a,int b){
    return subquery(a,b,0,0,size);
  }
};

RangeMinQuery sgt;

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  ll N,M;
  string S;
  cin>>N>>M>>S;
  sgt.init(N+1);
  sgt.update(N,0);
  for(ll i=N-1;i>=0;i--){
    if(S[i]=='1')continue;
    P v=sgt.query(i+1,min(N+1,i+M+1));
    sgt.update(i,v.fi+1);
  }
  {
