    if(ans.fi==INF){
      cout<<-1<<endl;
      return 0;
    }
  }
  vector<ll> res;
  ll crt=0;
  while(crt!=N){
    P p=sgt.query(crt+1,min(N+1,crt+M+1));
    res.push_back(p.se-crt);
    crt=p.se;
  }
  rep(i,res.size())cout<<res[i]<<" ";
  cout<<endl;

  return 0;
}

