#include <bits/stdc++.h>

using namespace std;

const int INF = 1e9;

struct SegTree {
#define left 2 * i
#define right 2 * i + 1
#define m (l + r) / 2

    int n, len;
    vector<int> seg;

    SegTree(const int n) : n(n), len(4 * n), seg(len, INF) {}

    int read(int x, int y, int i, int l, int r) {
        if (y < l or r < x) {
            return INF;
        }
        if (x <= l and r <= y) {
            return seg[i];
        }
        return min(read(x, y, left, l, m), read(x, y, right, m + 1, r));
    }

    int read(int x, int y) { return read(x, y, 1, 1, n); }

    void update(int x, int val, int i, int l, int r) {
        if (l == r) {
            seg[i] = val;
            return;
        }
        if (x <= m)
            update(x, val, left, l, m);
        else
            update(x, val, right, m + 1, r);
        seg[i] = min(seg[left], seg[right]);
    }

    void update(int x, int val) { update(x, val, 1, 1, n); }

    int find(int x, int y) {
        int lo = x - 1, hi = y;
        const int val = read(x, y);
        while (lo + 1 < hi) {
            const int mid = (lo + hi) / 2;
            if (read(x, mid) == val)
                hi = mid;
            else
                lo = mid;
        }
        return hi;
    }

#undef left
#undef right
#undef m
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    cin >> n >> m;
    string s;
    cin >> s;
    SegTree seg(n);
    seg.update(n, 0);
    for (int i = n - 1; i > 0; i--) {
        const int val = s[i] == '1' ? INF : seg.read(i + 1, i + m);
        if (val == INF) continue;
        seg.update(i, val + 1);
    }

    if (seg.read(1, m) == INF) {
        cout << "-1\n";
        return 0;
    }

    for (int i = 0; i < n;) {
        const int j = seg.find(i + 1, i + m);
        cout << (j - i) << ' ';
        i = j;
    }
    cout << '\n';
}

