template <typename T, T F(T, T), T ZERO>
struct SegmentTree {
    T n;
    vector<T> v;

    SegmentTree(T n_){
        n = 1;
        while(n < n_){ n *= 2; }
        v.resize(2 * n - 1);
        fill(v.begin(), v.end(), ZERO);
    }

    // zero-indexed
    void update(ll k, T a){
        k += n - 1;
        v[k] = a;
        while(k > 0){
            k = (k - 1) / 2;
            v[k] = F(v[k * 2 + 1], v[k * 2 + 2]);
        }
    }

    // [a, b), zero-indexed
    T query(ll a, ll b) const {
        return query_internal(a, b, 0, 0, n);
    }

    T get(ll a) const {
        return query(a, a + 1);
    }

    T query_internal(ll a, ll b, ll k, ll l, ll r) const {
        if(r <= a || b <= l){ return ZERO; }
        if(a <= l && r <= b){
            return v[k];
        }else{
            T v1 = query_internal(a, b, k * 2 + 1, l, (l + r) / 2);
            T v2 = query_internal(a, b, k * 2 + 2, (l + r) / 2, r);
            return F(v1, v2);
        }
    }
};

ll op(ll x, ll y){ return min(x, y); }

void solve(long long N, long long M, const string& S){
    SegmentTree<ll, op, numeric_limits<ll>::max()> st(N + 1);
    st.update(N, 0);
    for(ll i = N - 1; i >= 0; --i){
        if(S.at(i) == '1'){ continue; }
        ll d = st.query(i + 1, min(i + M, N) + 1);
        if(d != numeric_limits<ll>::max()){
            st.update(i, d + 1);
        }
    }

    if(st.get(0) == numeric_limits<ll>::max()){
        cout << -1 << endl;
        return;
    }

    vector<ll> d, p;
    REP(i, N + 1){
        if(S.at(i) == '1'){ continue; }
        d.push_back(- st.get(i));
        p.push_back(i);
    }

    vector<ll> ans;
    ll pos = 0;
    while(pos != d.size() - 1){
        ll i = lower_bound(d.begin(), d.end(), d.at(pos) + 1) - d.begin();
        ans.push_back(p.at(i) - p.at(pos));
        pos = i;
    }

    REP(i, ans.size()){
        cout << ans.at(i);
        if(i + 1 < ans.size()){
            cout << ' ';
        }
    }
    cout << endl;
}

