#define m (s + e) / 2
using namespace std;
typedef pair<int, int> ii;
const int INF = 1000000000;
struct segnode {
	int s, e;
	ii v;
	segnode *l, *r;
	segnode(int _s, int _e) {
		s = _s;
		e = _e;
		v = ii(INF, s);
		if (s != e) {
			l = new segnode(s, m);
			r = new segnode(m + 1, e);
		}
	}
	void update(int i, int nv) {
		if (s == e) {
			v = ii(nv, i);
			return;
		} else if (i > m) r -> update(i, nv);
		else l -> update(i, nv);
		v = min(l -> v, r -> v);
	}
	ii query(int a, int b) {
		if (s == a && e == b) return v;
		if (a > m) return r -> query(a, b);
		if (b <= m) return l -> query(a, b);
		return min(l -> query(a, m), r -> query(m + 1, b));
	}
} *root;
int main() {
	int N, M;
	scanf("%d %d", &N, &M);
	char squares[N + 1];
	for (int i = 0; i <= N; ++i) scanf(" %c", &squares[i]);
	ii dptable[N + 1];
	dptable[N] = ii(0, -1);
	root = new segnode(0, N);
	root -> update(N, 0);
	for (int i = N - 1; i >= 0; --i) {
		if (squares[i] == '1') {
			dptable[i] = ii(INF, -1);
			continue;
		}
		ii ans = root -> query(i + 1, min(N, i + M));
		dptable[i] = ii(ans.first + 1, ans.second);
		root -> update(i, ans.first + 1);
	}
	if (dptable[0].first >= INF) {
		printf("-1");
		return 0;
	}
	for (int i = 0; dptable[i].second != -1; i = dptable[i].second) printf("%d ", dptable[i].second - i);
	return 0;
}

