	vector<int> re;
	REP(i, 1, sqrt(n) + 1) {
		if (n % i == 0) {
			re.push_back(i);
			if (i != n / i) re.push_back(n / i);
		}
	}
	return re;
}
int modPow(int a, int n, int mod) {
	int ret = 1;
	while (n) {
		if (n & 1) ret = ret * a % mod;
		a = a * a % mod;
		n >>= 1;
	}
	return ret;
}
int comb(int n, int r) {
	if (n - r < r) r = n - r;
	if (r == 0) return 1;
	if (r == 1) return n;

	vector<int> num(r);
	vector<int> den(r);

	for (int k = 0; k < r; k++) {
		num[k] = n - r + k + 1;
		den[k] = k + 1;
	}

	for (int p = 2; p <= r; p++) {
		int pivot = den[p - 1];
		if (pivot > 1) {
			int offset = (n - r) % p;
			for (int k = p - 1; k < r; k += p) {
				num[k - offset] /= pivot;
				den[k] /= pivot;
			}
		}
	}

	int ret = 1;
	for (int k = 0; k < r; k++) {
		if (num[k] > 1) ret = ret * num[k] % 1000000007;
	}

	return ret;
}
