// Tは f : T \to T$ についてモノイドである必要がある。
template <typename T = int64_t>
struct SegTree {
    using F = function<T(T, T)>;
    int N;
    vector<T> array;
    const F f;
    const T init;
    SegTree() {}
    // len : データ長, f : 二項演算, init: 初期値
    SegTree(int len, const F f, const T &init) : f(f), init(init) {
        for(N = 1; N < len; N <<= 1);
        int n = 2 * N - 1;
        for(int i = 0; i < n; i++) array.push_back(init);
    }
    // 値の更新 O(\log N)$
    // k : 添字, val : 値
    void update(int k, T val) {
        k += N;
        array[k] = val;
        while(k >>= 1) array[k] = f(array[2 * k], array[2 * k + 1]);
    }
    // 値の取り出し O(1)$
    // k : 添字
    T operator[] (int k) { return array[k + N]; }
    // 範囲検索 O(\log N)$
    // [L : R) の範囲について、f( [L : R) ) を求める
    T query(int l, int r) {
        T L = init, R = init;
        for(l += N, r += N; l < r; l >>= 1, r >>= 1) {
            if(l & 1) L = f(L, array[l++]);
            if(r & 1) R = f(array[--r], R);
        }
        return f(L, R);
    }
};

