    seg.set(N,0);
    seg.build();
    for(int i=N-1;i>=0;i--){
        if(S[i]=='1') continue;
        dp[i] = seg.query(i+1,min(N+1,i+M+1))+1;
        seg.update(i,dp[i]);
    }
