void solve(){
    in3(n, m, s);
    set<ll> ss;
    ss.insert(INF);
    rep(i, n + 1)
        if (s[i] == '0') ss.insert(i);

    vl dp(n + 1, INF), path(n + 1, -1);
    dp[0] = 0;
    For(i, 1, n + 1){
        auto it = ss.lower_bound(i - m);
        if (s[i] == '0' || *it >= i) continue;
        dp[i] = min(INF, dp[*it] + 1);
        path[i] = *it;
