    if (dp[n] == INF) {prl(-1); return;}
    vl ans; ll cur = n, nxt;
    while (true){
        ans.pb(cur);
        nxt = path[cur];
        if (nxt == -1) break;
        swap(cur, nxt);
    }

    reverse(all(ans));
    rep(i, ans.size() - 1)
        prs(ans[i + 1] - ans[i]);
    prl("");
}

