template<class T> struct  SegTree{
    typedef  function<T(T, T)> F;
    int n = 1;
    vector<T> node;
    T et;
    F f, g;

    SegTree(int n_, T et_, F f_, F g_):
    et(et_), f(f_), g(g_){
        while(n < n_) n *= 2;
        node.resize(n*2-1, et);
    }

    void update(int i, T x){
        i += n-1;
        node[i] = g(node[i], x);
        while(i){
            i = (i-1) / 2;
            node[i] = f(node[i*2+1], node[i*2+2]);
        }
    }

    T query(int a, int b){
        T vl = et, vr = et;
        for(a+=n-1, b+=n-1; a<b; a=(a-1)/2, b=(b-1)/2){
            if(!(a&1)) vl = f(vl, node[a++]);
            if(!(b&1)) vr = f(node[--b], vr);
        }
        return f(vl, vr);
    }
};

int main(){
    int n, m;
    scanf("%d%d", &n, &m);
    string s;
    cin >> s;

    auto f=[&](pii p, pii q){
        if(p.fi==INF) return q;
        else if(q.fi==INF) return p;
        else if(p.fi==q.fi) return p;
        else return min(p, q);
    };
    SegTree<pii> st(n+1, make_pair(INF, MAX), f, f);
    rep(i, n+1) st.update(i, make_pair(INF, i));
    st.update(0, make_pair(0, 0));

    int prev[n+1];
    For(i, 1, n+1)if(s[i]=='0'){
        pii tmp=st.query(max(0, i-m), i);
        if(tmp.fi==INF){
            printf("-1\n");
            return 0;
        }
        st.update(i, make_pair(tmp.fi+1, i));
        prev[i]=tmp.se;
    }

    vector<int> ans;
    int cur=n;
    while(cur){
        ans.push_back(cur-prev[cur]);
        cur=prev[cur];
    }
    reverse(ans.begin(), ans.end());
    for(int x: ans) printf("%d ", x);
}

