int main(){
    using namespace std;
    unsigned long N, M;
    cin >> N >> M;
    string s;
    cin >> s;
    vector<unsigned long> uku(N + 1);
    for(unsigned long i = 0; i <= N; ++i){
        if(s[i] == '1')uku[i] = numeric_limits<unsigned long>::max();
        else uku[i] = i;
    }
    reverse(uku.begin(), uku.end());
    vector<unsigned long> tap(N);
    stack<unsigned long> front, back;
    unsigned long loc{numeric_limits<unsigned long>::max()};
    front.push(loc);
    const auto& push = [&back, &loc](unsigned long x) -> void {
        back.push(x);
        loc = min(loc, x);
    };
    const auto& pop = [&front, &back, &loc]() -> void {
        if(front.size() == 1){
            while(!back.empty()){
                auto t = back.top();
                back.pop();
                front.push(min(front.top(), t));
            }
            loc = numeric_limits<unsigned long>::max();
        }
        front.pop();
    };
    const auto& get = [&front, &loc]() -> unsigned long { return min(front.top(), loc); };
    for(unsigned long i = 0; i < M; ++i)push(uku[i]);
    for(unsigned long i = 0; i < N; ++i){
        if(i + M <= N)push(uku[i + M]);
        pop();
        tap[i] = get();
    }
    tap.push_back(0);
    reverse(tap.begin(), tap.end());
    vector<unsigned long> ans{N};
    unsigned long idx{N};
    while(idx > 0){
        idx = tap[idx];
        if(idx > N)return 0 & puts("-1");
        ans.push_back(idx);
    }
    reverse(ans.begin(), ans.end());
    auto n{ans.size()};
    for(unsigned long i = 1; i < n; ++i)cout << ans[i] - ans[i - 1] << " ";
    cout << endl;
    return 0;
}

