struct SegmentTree {
private:
    int n;
    vi node;
    vi moto;

public:
    SegmentTree(vi v) {
        int sz = v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1, INT_MAX);
        moto.resize(2*n-1, INT_MAX);
        REP(i,sz) {
            node[i+n-1] = v[i];
            moto[i+n-1] = i;
        }
        REPN(i,n-2) {
            node[i] = min(node[2*i+1], node[2*i+2]);
            moto[i] = node[2*i+1] <= node[2*i+2] ? moto[2*i+1] : moto[2*i+2];
        }
    }
    void update(int k, int x){
        k += n-1;
        node[k] = x;
        while(k){
            k = (k-1)/2;
            node[k] = min(node[2*k+1],node[2*k+2]);
            moto[k] = node[2*k+1] <= node[2*k+2] ? moto[2*k+1] : moto[2*k+2];
        }
    }
    pi getmin(int a, int b, int k=0, int l=0, int r=-1){
        if(r<0) r=n;
        if(r<=a || b<=l) return {INT_MAX, INT_MAX};
        if(a<=l && r<=b) return {node[k], moto[k]};
        return min( getmin(a,b,2*k+1,l,(l+r)/2),getmin(a,b,2*k+2,(l+r)/2,r) );
    }
};

