template <typename T>
class segTree
{
    typedef function<T(T a, T b)> func;

public:
    int sz = 1;
    T lmt;
    vector<T> dat;
    func monoid;

    segTree(){};

    segTree(T a, func f, T e)
    {
        monoid = f;

        while (sz < a)
            sz <<= 1;
        dat.resize(2 * sz - 1, 0);

        for (int i = 0; i < 2 * sz - 1; i++)
            dat[i] = e;

        lmt = e;
    }

    void update(int k, T x)
    {
        k += sz - 1;
        dat[k] = x;

        while (k)
        {
            k = (k - 1) / 2;
            dat[k] = monoid(dat[2 * k + 1], dat[2 * k + 2]);
        }
    }

    void show()
    {
        printf("number_of_nodes:%d\n", sz);
        for (int i = 0; i < 2 * sz - 1; i++)
        {
            if (i == sz - 1)
                printf("--array_begin--\n");
            printf("No%d:%d\n", i, dat[i]);
        }
        printf("\n--input_array--\n");
        for (int i = 0; dat[i + 1] != lmt; i++)
        {
            printf("No%d:%d\n", i, get(i));
        }
    }

    //区間[l,r)のクエリ
    T query(int l, int r)
    {
        int L = l + sz, R = r + sz;
        int ret = lmt;

        while (L < R)
        {
            if (R & 1)
            {
                R -= 1;
                ret = monoid(ret, dat[R - 1]);
            }

            if (L & 1)
            {
                ret = monoid(ret, dat[L - 1]);
                L += 1;
            }
            L >>= 1;
            R >>= 1;
        }
        //for(int i=0;i<n-1;i++)for(int j=i+1;j<n;j++)printf("[%d,%d):%d\n",i,j+1,seg.rmq(i,j+1));

        return ret;
    }

private:
    T get(int a) { return dat[a + sz - 1]; }
};

