template <class Monoid> class SegmentTree{
  private:
    using T = typename Monoid::type;
    int sz, N;
    vector<T> dat;
  public:
    SegmentTree(const vector<T> &vec){
      sz = vec.size(); N = 1; while(N<sz) N<<=1;
      dat.resize(2*N);
      fill(dat.begin(),dat.end(),Monoid::id());
      copy(vec.begin(),vec.end(),dat.begin()+N-1);
      for(int i=N-2;i>=0;i--) dat[i]=Monoid::op(dat[2*i+1],dat[2*i+2]);
    }
    SegmentTree(const int n){
      sz = n; N = 1; while(N<n) N<<=1;
      dat.resize(2*N);
      fill(dat.begin(),dat.end(),Monoid::id());
      for(int i=N-2;i>=0;i--) dat[i]=Monoid::op(dat[2*i+1],dat[2*i+2]);
    }
    void update(int i,T val){
      assert(0<=i && i<sz);
      dat[i+=N-1] = val;
      while(i>0){
        i=(i-1)/2;
        dat[i]=Monoid::op(dat[2*i+1],dat[2*i+2]);
      }
      return;
    }
    T query(int a,int b){ // op[a,b)
      return query(a,b,0,0,N);}
    T query(int a,int b,int k,int l,int r){
      assert(0<=l && l<=r && r<2*N);
      if(r<=a || b<=l) return Monoid::id();
      else if(a<=l && r<=b) return dat[k];
      else{
        T lval=query(a,b,2*k+1,l,(l+r)/2);
        T rval=query(a,b,2*k+2,(l+r)/2,r);
        return Monoid::op(lval,rval);
      }
    }
};

struct RMQ{
  using type = Pl;
  static type id(){return Pl(LINF,LINF);}
  static type op(const type &a ,const type &b){return min(a,b);}
};

void solve(long long N, long long M, string S){
  SegmentTree<RMQ> dp(N+4);
  dp.update(0,{0LL,0LL});
  vl pre(N+1);
  pre[0] = -1LL;
  REP(i,1,N+1){
    if(S[i]=='1') continue;
    auto pl = dp.query(max(i-M,0LL),i);
    ll mi, ag;
    tie(mi, ag) = pl;
    pre[i] = ag;
    dp.update(i,{min(mi+1,LINF), i});
  }
  vector<ll> val(N+1);
  REP(i,1,N+1) val[i] = dp.query(i,i+1).fi;
  if(val[N]==LINF){
    cout << "-1" << endl; return;
  }
  ll now = N;
  vl ans;
  ans.pb(now);
  while(true){
    if(now==0) break;
    now = pre[now];
    ans.pb(now);
  }
  reverse(ALL(ans));
  dump(ans);
  ll sz = ans.size();
  rep(i,sz-1) cout << ans[i+1]-ans[i] << (i==sz-2 ? "\n":" ");
}

