int path[max_n];
int main(){
    scanf("%d%d %s",&n,&m,s);
    dp[n]=0;
    head=1,tail=1;
    Q[head]=n;
    for(int i=n-1;i>=0;i--){
        if(s[i]=='1')dp[i]=inf;
        else{
            int j=Q[head];

            //cout<<i<<' '<<j<<endl;
            if(dp[j]==inf)dp[i]=inf;
            else{
                dp[i]=dp[j]+1;
                path[i]=j;
            }
        }
        while(tail>=head&&dp[Q[tail]]>=dp[i])tail--;
        Q[++tail]=i;
        while(tail>=head&&Q[head]-i+1>m)head++;
    }
    if(dp[0]==inf)printf("-1\n");
    else{
        int x=0;
        vector<int> way;
        while(x!=n){
            int nx=path[x];
            way.push_back(nx-x);
            x=nx;
        }
        //printf("%d\n",way.size());
        for(int i=0;i<way.size();i++)printf("%d%c",way[i],i+1==way.size()?'\n':' ');
    }
    return 0;
}

