ll solve() {
    ll N, M;
    cin >> N >> M;
    string S;
    cin >> S;
    stack<int> st;
    for ( int i = 0; i < N; i++ ) {
        if ( S[i] == '0' ) st.push(i); 
    }
    int cur = N;
    vector<int> ansr;
    while ( !st.empty() ) {
        int v = -1;
        while ( !st.empty() && cur - st.top() <= M ) {
            v = st.top();
            st.pop();
        }
        if ( v == -1 ) return -1;
        ansr.push_back(cur - v);
        cur = v;
    }
    for ( int i = ansr.size()-1; i >= 0; i-- ) {
        cout << (i != ansr.size()-1 ? " " : "") << ansr[i];
    }
    cout << "\n";
    return 0;
}

