int main(){
  int N,M;
  cin>>N>>M;
  string S;
  cin>>S;

  SegmentTree<int> seg(N+1,[](int a,int b){return min(a,b);},INF);
  vector<int> dp(N+1,INF);
  seg.update(N,0);
  dp[N]=0;
  for(int i=N-1;i>=0;i--){
      if(S[i]=='1') continue;
      int qry=seg.query(i,min(N+1,i+M+1));
      if(qry==INF) continue;

      seg.update(i,qry+1);
      dp[i]=qry+1;
  }

  if(dp[0]==INF) cout<<-1<<endl;
  else{
      vector<int> ans;
      int now=0;
      SegmentTree<pair<int,int>> sg(N+1,[](pair<int,int> a,pair<int,int> b){
          if(a.first<b.first) return a;
          else if(a.first>b.first) return b;
          else if(a.second<b.second) return a;
          else return b;
      },mkp(INF,INF));

      vector<pair<int,int>> v(N+1);
      for(int i=0;i<=N;i++) v[i]=mkp(dp[i],i);
      sg.initialize(v);

      while(now<N){
          auto q=sg.query(now+1,min(N+1,now+M+1));
          //cout<<now<<" "<<q.first<<" "<<q.second<<endl;
          ans.push_back(q.second-now);
          now=q.second;
      }
      for(auto n:ans) cout<<n<<" ";
      cout<<endl;
  }

  return 0;
}

