    int n, m;
    std::cin >> n >> m;
    std::string s;
    std::cin >> s;

    struct node {
        int step;
        int idx;
    };
    const auto f = [](const node &l, const node &r) {
        if(l.step == r.step)
            return l.idx < r.idx ? l : r;
        else
            return l.step < r.step ? l : r;
    };

    edamat::aggregatable_queue<node, decltype(f)> qa(f);
    std::vector<int> next(n + 1);
    qa.push_back({0, n});
    constexpr int Inf = std::numeric_limits<int>::max() / 2;
    int ans;
    for(int i = n - 1; i >= 0; i--) {
        if(qa.size() > m) {
            qa.pop_front();
        }
        const node t = qa.fold_all();
        // std::cout << t.step << " " << t.idx << std::endl;
        next[i] = t.idx;
        if(i == 0) {
            ans = t.step + 1;
        }
        if(s[i] == '0') {
            qa.push_back({t.step + 1, i});
        } else {
            qa.push_back({Inf, i});
        }
    }
    if(ans >= Inf) {
        std::cout << "-1" << std::endl;
        return;
    }
    int p = 0;
    while(p != n) {
        // std::cout << next[p] << " ";
        std::cout << next[p] - p << ' ';
        p = next[p];
    }
    std::cout << std::endl;
}

