int main()
{
  int64_t N, M;
  cin >> N >> M;
  string S;
  cin >> S;
  vector<int64_t> steps(N + 1, -1);
  steps.at(N) = 0;
  vector<bool> checked(N + 1, false);
  checked.at(N) = true;
  for (int64_t i = N; i > 0; i--)
  {
    if (S[i] == '1')
    {
      continue;
    }
    for (int64_t j = max((int64_t)0, i - M); j <= i; j++)
    {
      if (checked.at(j))
      {
        break;
      }
      checked.at(j) = true;
      if (S[j] == '1')
      {
        continue;
      }
      steps.at(j) = steps.at(i) + 1;
    }
  }
  if (steps.at(0) == -1)
  {
    cout << -1 << endl;
    return 0;
  }
  vector<int64_t> ans;
  for (int64_t i = 0; i <= N; i++)
  {
    for (int64_t j = 1; j <= M && i + j <= N; j++)
    {
      if (steps.at(i + j) == steps.at(i) - 1)
      {
        ans.push_back(j);
        i += j - 1;
        break;
      }
    }
  }
  for (int64_t i = 0; i < (int64_t)ans.size(); i++)
  {
    if (i)
      cout << ' ';
    cout << ans.at(i);
  }
  cout << endl;
}

