const int MAXN=200000+5;

namespace Seg
{
    pair<int,int>Min[MAXN<<2];
    #define ls (x<<1)
    #define rs (x<<1|1)
    void init(int x,int l,int r)
    {
        Min[x]=make_pair(1<<30,0);
        if(l==r) return;
        int mid=l+r>>1;
        init(ls,l,mid);
        init(rs,mid+1,r);
    }
    void ins(int x,int l,int r,int v,int pos)
    {
        Min[x]=min(Min[x],make_pair(v,pos));
        if(l==r) return;
        int mid=l+r>>1;
        if(pos<=mid) ins(ls,l,mid,v,pos);
        else ins(rs,mid+1,r,v,pos);
    }
    pair<int,int>query(int x,int l,int r,int ql,int qr)
    {
        if(ql<=l&&r<=qr) return Min[x];
        int mid=l+r>>1;
        if(ql>mid) return query(rs,mid+1,r,ql,qr);
        if(qr<=mid) return query(ls,l,mid,ql,qr);
        return min(query(ls,l,mid,ql,qr),query(rs,mid+1,r,ql,qr));
    }
}
int n,m;
int nxt[MAXN];
char s[MAXN];
int main()
{
    scanf("%d%d",&n,&m);
    scanf("%s",s);
    Seg::init(1,1,n);
    Seg::ins(1,1,n,0,n);
    for(int i=n-1;i>0;i--)
    if(s[i]=='0')
    {
        pair<int,int>val=Seg::query(1,1,n,i+1,min(n,i+m));
        nxt[i]=val.second;
        if(val.first!=(1<<30))
        {
            val.first++;
           // printf("%d %d %d\n",i,nxt[i],val.first);
            Seg::ins(1,1,n,val.first,i);
        }
        //printf("%d %d %d %d\n",i,nxt[i],i+1,min(n,i+m));
    }
    pair<int,int>val=Seg::query(1,1,n,1,min(m,n));
    if(val.first==(1<<30))
    {
        puts("-1");
        return 0;
    }
    for(int i=val.second,last=0;;)
    {
        printf("%d ",i-last);
        if(i==n) break;
        last=i;
        i=nxt[i];
    }

    return 0;
}

