const int M=1e5+5;
const int INF=0x3f3f3f3f;

struct TN
{
	int mi,p;
	TN(int mi=0,int p=0)
		:mi(mi),p(p){}
	bool operator<(const TN &B) const
	{
		return mi==B.mi?p<B.p:mi<B.mi;
	}
};
struct SegT
{
	TN tn[M*2];
	void init(int n)
	{
		for(int i=0;i<n*2;i++)
			tn[i]=TN(INF,INF);
	}
	int X,V,P;
	TN unite(const TN &u,const TN &v)
	{
		TN ans=u<v?u:v;
		return ans;
	}
	void pull(int o,int ls,int rs)
	{
		tn[o]=unite(tn[ls],tn[rs]);
	}
	void update(int o,int l,int r)
	{
		if(l==r)
		{
			tn[o]=TN(V,P);
			return;
		}
		int m=(l+r)>>1;
		int ls=o+1,rs=o+((m-l+1)<<1);
		if(X<=m) update(ls,l,m);
		else update(rs,m+1,r);
		pull(o,ls,rs);
	}
	int L,R;
	TN query(int o,int l,int r)
	{
		if(L<=l&&r<=R)
			return tn[o];
		int m=(l+r)>>1;
		int ls=o+1,rs=o+((m-l+1)<<1);
		TN ans(INF,-1);
		if(L<=m) ans=unite(ans,query(ls,l,m));
		if(m<R) ans=unite(ans,query(rs,m+1,r));
		return ans;
	}
}segt;

char s[M];
TN ans[M];
int st[M];

int main()
{
	int n,m; scanf("%d%d",&n,&m);
	scanf("%s",s);
	segt.init(n);
	segt.X=segt.V=segt.P=0;
	segt.update(0,0,n);
	for(int i=1;i<=n;i++)
	{
		if(s[i]=='1') continue;
		segt.L=max(0,i-m); segt.R=i-1;

		ans[i]=segt.query(0,0,n);
		ans[i].mi++;

		segt.X=i;
		segt.V=ans[i].mi;
		segt.P=i;
		segt.update(0,0,n);
		//cout<<i<<" "<<ans[i].mi<<" "<<ans[i].p<<endl;
	}
	//cout<<ans[n].mi<<endl;
	if(ans[n].mi>=INF)
	{
		printf("-1\n");
		return 0;
	}
	int x=n;
	for(int i=ans[n].mi;i>0;i--)
	{
		st[i]=x-ans[x].p;
		x=ans[x].p;
	}
	for(int i=1;i<=ans[n].mi;i++)
		printf("%d%c",st[i],i==ans[n].mi?'\n':' ');
	return 0;
}

