vector<int> dfs(int s){
    if(dp[s].size() != 0) return dp[s];
    vector<int> res;
    for(int i = 1; i <= M; i++){
        if(i + s > N) break;
        if(S[i + s] == '1') continue;
        vector<int> t = dfs(i + s);
        if(res.size() == 0) {
            res = t;
            res.emplace_back(i);
        }
        else if(res.size() > t.size() + 1) {
            res = t;
            res.emplace_back(i);
        }
    }
    return dp[s] = res;
}
