void solve()
{
    ll N, M;
    in(N, M);
    string S;
    in(S);
    ll c = 0;
    ll l = 0;
    ll r = 0;
    vll left(N + 1);
    vll right(N + 1);
    for1 (i, N + 1) {
        if (S[i] == '1') {
            c++;
        }
        else {
            c = 0;
            l = i;
        }
        left[i] = l;
        if (c == M) {
            print(-1);
            return;
        }
    }
    r = N;
    rfor2 (i, N, -1) {
        if (S[i] == '0') {
            r = i;
        }
        right[i] = r;
    }

    vll ans;
    ll cur = N;
    while (cur > 0) {
        // dump(cur);
        if (cur - M >= 0) {
            if (S[cur - M] == '0') {
                ans.push_back(M);
                cur -= M;
            }
            else {
                ll r = right[cur - M];
                ans.push_back(cur - r);
                cur -= cur - r;
            }
        }
        else {
            ans.push_back(cur);
            cur -= cur;
        }
    }
    reverse(all(ans));
    print(ans);
}
