using namespace std;

const int maxN = 1 << 18, INF = 1 << 30, maxTS = maxN * 2;

struct Tree
{
	int offset, qbegin, qend;
	int T[maxTS], res;

	void qpriv(int v, int left, int right)
	{
		if (left >= qend or right <= qbegin)	
			return;
		if (left >= qbegin and right <= qend)
		{
			res = min(res, T[v]);
			return;
		}
		qpriv(v * 2, left, (left + right) / 2);
		qpriv(v*2+1, (left + right) / 2, right);
	}

	void init(int n)
	{
		for (offset = 1; offset < n; offset *= 2);
		FOR(i, 1, offset*2)
			T[i] = INF;
	}

	void updt(int v, int val)
	{
		v += offset;
		T[v] = val;
		for (v /= 2; v != 0; v /= 2)
			T[v] = min(T[v * 2], T[v*2+1]);
	}

	int query(int a, int b)
	{
		qbegin = a + offset;
		qend = b + offset + 1;
		res = INF;
		qpriv(1, offset, offset * 2);
		return res;
	}
}tree;

char T[maxN];
int dp[maxN];

void solve()
{
	int n, m;
	scanf ("%d%d", &n, &m);
	scanf ("%s", T);
	tree.init(n + m + 10);
	tree.updt(n, 0);
	dp[n] = 0;

	for (int i=n-1; i>=0; i--)
	{
		dp[i] = T[i] == '1' ? INF : tree.query(i+1, i+m) + 1;
		tree.updt(i, dp[i]);
	}

	if (T[0] == '1' or T[n] == '1' or dp[0] >= INF)
	{
		printf("-1\n");
		return;
	}

	int v = 0;
	while (v != n)
	{
		int u = v;
		while (dp[u] != dp[v]-1)	
			u++;
		printf("%d ", u-v);
		v = u;
	}

	printf("\n");
}

int main()
{
	int t;
	t=1;//scanf ("%d", &t);
	while (t--)
		solve();
	return 0;
}

