    // 残りのサイコロ振れる回数
    int rest = dp[0];
    while(now < n) {
        --rest;
        int move = 1;
        // 最初に最短経路数が変わる場所が辞書順最短手順
        while(dp[now+move] != rest) move++;
        ans.push_back(move);
        now += move;
    }
    rep(i, ans.size()) {
        cout << ans[i] << endl;
    }

    return 0;
}

