void solve(long long n, long long m, std::string s) {
	LL goal = n, prev = -1;
	vector<LL> ans;
	for (LL i = n - 1; i >= 0; --i) {
		if (i + m < goal) {
			if (prev < 0) {
				cout << -1 << endl;
				return;
			}
			ans.push_back(goal);
			goal = prev;
			prev = -1;
		}
		if (s[i] == '0') {
			prev = i;
		}
	}
	ans.push_back(goal);
	if (prev >= 0) {
		ans.push_back(0);
	}
	reverse(ans.begin(), ans.end());
	for (LL i = 1; i < (LL)ans.size(); ++i) {
		if (i > 1) {
			cout << " ";
		}
		cout << (ans[i] - ans[i - 1]);
	}
	cout << endl;
}

