    cout << n;
    return true;
  }
  for (int i = m; i > 0; --i) {
    if (s[n - i] == '1')
      continue;
    if (search(s, n - i, m)) {
      cout << " " << i;
      return true;
    } else {
      return false;
    }
  }
  return false;
}

