typedef long long ll;
#define lef(x) (x<<1)
#define rig(x) (lef(x)+1)
pair<int,int> tree[4*N];
int best[N];

void update(int p,int tl,int tr,int k,int c)
{
	if(tl==tr)
	{
		tree[p]={c,tl-1};
	}else
	{
		int mid=(tl+tr)/2;
		if(k<=mid)
			update(lef(p),tl,mid,k,c);
		else
			update(rig(p),mid+1,tr,k,c);
		tree[p]=min(tree[lef(p)],tree[rig(p)]);
	}
}

pair<int,int> query(int p,int tl,int tr,int l,int r)
{
	if(l>r)
		return {1e9,1e9};
	if(tl==l && tr==r)
	{
		return tree[p];
	}else
	{
		int mid=(tl+tr)/2;
		return min(query(lef(p),tl,mid,l,min(r,mid)),
					query(rig(p),mid+1,tr,max(l,mid+1),r));
	}
}



