		ind[v] = ind[lc];
	}
	else
	{
		t[v] = t[rc];
		ind[v] = ind[rc];
	}

	if (t[lc] == t[rc])
	{
		if (ind[lc] < ind[rc])
		{
			t[v] = t[lc];
			ind[v] = ind[lc];
		}
		else
		{
			t[v] = t[rc];
			ind[v] = ind[rc];
		}
	}
}

void update(int v, int tl, int tr, int pos, int val)
{
	if (tl == tr)
	{
		t[v] = val;
		return;
	}

	int tm = (tl + tr) >> 1, lc = (v << 1), rc = (v << 1) + 1;
	if (pos <= tm)
	{
		update(lc, tl, tm, pos, val);
	}
	else
	{
		update(rc, tm + 1, tr, pos, val);
	}

	if (t[lc] < t[rc])
	{
		t[v] = t[lc];
		ind[v] = ind[lc];
	}
	else
	{
		t[v] = t[rc];
		ind[v] = ind[rc];
	}

	if (t[lc] == t[rc])
	{
		if (ind[lc] < ind[rc])
		{
			t[v] = t[lc];
			ind[v] = ind[lc];
		}
		else
		{
			t[v] = t[rc];
			ind[v] = ind[rc];
		}
	}
}

pair<int, int> get(int v, int tl, int tr, int l, int r)
{
	if (l > r)
	{
		return make_pair(inf, -1);
	}

	if (tl == l && tr == r)
	{
		return make_pair(t[v], ind[v]);
	}

	int tm = (tl + tr) >> 1, lc = (v << 1), rc = (v << 1) + 1;

	pair<int, int> p1, p2;
	p1 = get(lc, tl, tm, l, min(r, tm));
	p2 = get(rc, tm + 1, tr, max(tm + 1, l), r);
	//return make_pair(inf, -1);
	pair<int, int> p;
	if (p1.first < p2.first)
	{
		p.first = p1.first;
		p.second = p1.second;
	}
	else
	{
		p.first = p2.first;
		p.second = p2.second;
	}

	if (p1.first == p2.first)
	{
		if (p1.second < p2.second)
		{
			p.first = p1.first;
			p.second = p1.second;
		}
		else
		{
			p.first = p2.first;
			p.second = p2.second;
		}
	}

	return p;
}

