typedef pair<int, int> P;

const int INF = 1e+9;
const int DEPTH = 18;

struct SegTree {
	P val[1 << (DEPTH + 1)];	//(min, pos)

	SegTree() {
		int i;
		rep(i, (1 << (DEPTH + 1))) val[i] = P(INF, -1);
	}

	void update(int pos, int x) {
		pos += (1 << DEPTH) - 1;
		val[pos] = P(x, pos - ((1 << DEPTH) - 1));
		while (pos > 0) {
			pos = (pos - 1) / 2;
			val[pos] = min(val[pos * 2 + 1], val[pos * 2 + 2]);
		}
	}

	//[l, r)
	P getMin(int l, int r, int a = 0, int b = (1 << DEPTH), int id = 0) {
		if (a >= r || b <= l) return P(INF, -1);
		if (l <= a && b <= r) return val[id];

		P res1 = getMin(l, r, a, (a + b) / 2, id * 2 + 1);
		P res2 = getMin(l, r, (a + b) / 2, b, id * 2 + 2);
		return min(res1, res2);
	}
};

