void solve() {
    int n, m;
    string s;
    cin >> n >> m >> s;

    vector<int> ans;
    int p = n;
    while (p > 0) {
        if (p <= m) {
            ans.push_back(p);
            break;
        }
        bool ok = false;
        for (int i = m; i > 0; i--) {
            if (s[p - i] == '0') {
                ans.push_back(i);
                p -= i;
                ok = true;
                break;
            }
        }
        if (!ok) {
            cout << -1 << EOL;
            return;
        }
    }
    reverse(ALL(ans));
    REP(i, sz(ans)) cout << ans[i] << (i == sz(ans) - 1 ? EOL : ' ');
}

