using namespace std;

int bb(const vector <int>& v, int busca) {

	int L = 0;
	int R = v.size()-1;
	int resp = -1;

	while(L <= R) {
		int mid = (L+R) / 2;

		if(v[mid] > busca) {
			L = mid + 1;
		} else {
			resp = v[mid];
			R = mid - 1;
		}
	}

	return resp;
}

