using namespace std;

int main(){
    int32_t N, M;
    std::cin >> N >> M;
    string S;
    cin >> S;
    struct step {
        int prev;
        int pos;
        int num_step;
        step (int prev, int pos, int ns) : prev(prev), pos(pos), num_step(ns) {}
    };
    queue<step> q;
    q.push(step(0, N, 0));
    vector<bool> visited(N+1, false);
    vector<pair<int,int>> from(N+1);
    for (auto& elem : from) {
      elem = make_pair(INT_MAX, INT_MAX);
    }
    int min_step = INT_MAX;
    while (!q.empty()) {
        step cur_s = q.front();
        q.pop();
        if (cur_s.pos == 0) {
            if (cur_s.num_step < min_step) {
                from[0].first = cur_s.prev;
                from[0].second = cur_s.num_step;
                min_step = cur_s.num_step;
            } else if (cur_s.num_step == min_step) {
                if (cur_s.prev < from[0].first) {
                  from[0].first = cur_s.prev;
                }
            }
            continue;
        }

         if (from[cur_s.pos].second > cur_s.num_step) {
           from[cur_s.pos].second = cur_s.num_step;
           from[cur_s.pos].first = cur_s.prev;
         } else if (from[cur_s.pos].second == cur_s.num_step) {
             if(cur_s.prev < from[cur_s.pos].first) {
               from[cur_s.pos].first = cur_s.prev;
             }
        }

        if (visited[cur_s.pos] == true) {
           continue;
        } else {
            visited[cur_s.pos] = true;
            for (int i = 1; i <= M; i++) {
                if (cur_s.pos < i || visited[cur_s.pos - i] == true || S[cur_s.pos - i] == '1') {
                    continue;
                } else {
                    q.push(step(cur_s.pos, cur_s.pos - i, cur_s.num_step + 1));
                }
            }
        }
    }

    if (min_step == INT_MAX) {
        cout << "-1" << endl;
        return 0;
    }
    int cur = 0;
    while (cur < N) {
      cout << from[cur].first - cur << " ";
      cur = from[cur].first;
    }
    cout << endl;

    return 0;
}

