	vector<int> tmp(N + 1, 1145141919);
	SegTree<int> dp(tmp, [](int a, int b) {return min(a, b); }, 1145141919);
	dp.update(N, 0);

	for (int i = N - 1; i >= 0; i--) {
		if (S[i] == '1')continue;
		dp.update(i, dp.getval(i + 1, min(N + 1, i + 1 + M)) + 1);
	}

	if (dp.getval(0, 1) == 1145141919) {
		cout << -1 << endl;
		return 0;
