template <typename T>
struct SegmentTree {
  using F = function<T(T, T)>;
  vector<T> v;
  F f;
  T e;
  int n;
  SegmentTree(int size, F f, T e) : f(f), e(e) {
    n = 1;
    while (n < size) n <<= 1;
    v.resize(n * 2, e);
  }
  void set(int k, T x) {
    v[k + n] = x;
  }
  void build() {
    for (int i = n - 1; i > 0; i--) {
      v[i] = f(v[i * 2 + 0], v[i * 2 + 1]);
    }
  }
  void update(int k, T x) {
    v[k += n] = x;
    while (k >>= 1) v[k] = f(v[k * 2 + 0], v[k * 2 + 1]);
  }
  T query(int a, int b) {
    T l = e, r = e;
    for (a += n, b += n; a < b; a >>= 1, b >>= 1) {
      if (a & 1) l = f(l, v[a++]);
      if (b & 1) r = f(v[--b], r);
    }
    return f(l, r);
  }
};

void solve() {
  int n, m;
  cin >> n >> m;
  string s;
  cin >> s;
  reverse(all(s));
  SegmentTree<int> st(n + 1, [](int x, int y) { return min(x, y); }, 1e9);
  st.update(0, 0);
  reps(i, n) {
    if (s[i] == '1') continue;
    int mi = st.query(max(i - m, 0), i);
    if (mi == 1e9) continue;
    st.update(i, mi + 1);
  }
  if (st.query(n, n + 1) == 1e9) {
    cout << -1 << endl;
    return;
  }
  vi32 ans;
  int pos = n;
  int now = st.query(n, n + 1);
  rrep(i, n) {
    int s = st.query(i, i + 1);
    if (s != now && s != 1e9) {
      ans.push_back(pos - i);
      now--;
      pos = i;
    }
  }
  cout << ans << endl;
}

