  string t = s;
  reverse(ALL(t));

  using T = lint;  // type T
  using E = lint;  // type E
  auto f = [](T a, T b){ // return type T value
    return min(a, b);
  };
  auto g = [](T a, E b){ // return type T value
    return b;  // return b;
  };
  T ti = INF;  // identify element
  SegmentTree<T, E, decltype(f), decltype(g)> sg(f, g, ti);  // don't change
  sg.build(vector<lint> (t.size(), INF));   // 初期配列を代入
  sg.update(0, 0);

  for(int i = 1; i < t.size(); i++) {
    if(t[i] == '1') continue;
    lint l = i - x;
    lint r = i;
    l = max(0LL, l);
    lint val = sg.query(l, r);
    sg.update(i, val + 1);
  }

  lint dist = sg.query(t.size() - 1, t.size());
  lint cnt = 0;
  if(dist == INF) {
    cout << -1 << endl;
    return 0;
  }

  for(int i = t.size() - 1; i >= 0; i--) {
    lint tmp = sg.query(i, i + 1);
    // cerr << tmp << " " << dist << " " << endl;
    if(tmp == dist - 1) {
      cout << cnt << " ";
      dist = tmp;
      cnt = 1;
    } else {
      cnt++;
    }
  }
  cout << endl;
  return 0;
}

