#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)
#define DUMP(a, n) REP(i, n) printf("%d%c", a[i], i + 1 == n ? '\n' : ' ')
#define DUMP2D(a, n, m) REP(i, n) REP(j, m) printf("%d%c", a[i][j], j + 1 == m ? '\n' : ' '); puts("")

//------------------------------------------------------------------------------
#define LF(i)   (n - 1 + i)
#define PA(k)   ((k - 1) / 2)
#define LC(k)   (k * 2 + 1)
#define RC(k)   (k * 2 + 2)
#define M(l,r)  ((l + r) / 2)

template<typename T> class SegTree {
public:
  int n;
  int sz;
  T def;
  vector<T> dat;

  void init(int _n, T _def) {
    n = 1; while (n < _n) n <<= 1;
    sz = n * 2 - 1;
    def = _def;
    dat.resize(sz, def);
  }

  void update(int i, T x) {
    int k = LF(i);
    dat[k] = x;
    while (k > 0) {
      k = PA(k);
      dat[k] = min(dat[LC(k)], dat[RC(k)]);
    }
  }

  T query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return def;
    if (a <= l && r <= b) return dat[k];
    T vl = query(a, b, LC(k), l, M(l, r));
    T vr = query(a, b, RC(k), M(l, r), r);
    return min(vl, vr);
  }

  T query(int a, int b) {
    return query(a, b, 0, 0, n);
  }

  void dump() {
    REP(i, sz) printf("{%d,%d}%c", dat[i].first, dat[i].second, i + 1 == sz ? '\n' : ' ');
  }
};

