const int N_MAX = 1e5;
const int M_MAX = 1e5;

int N, M;
char S[N_MAX + 2];

//------------------------------------------------------------------------------
const int INF = 1e9+7;

typedef pair<int, int> pii;

SegTree<pii> dp;
int prv[N_MAX + 1];
vector<int> ans;

void solve() {
  dp.init(N + 1, { INF, -1 });
  dp.update(0, { 0, 0 });
  prv[0] = -1;
  FOR(i, 1, N) {
    if (S[i] == '1') continue;
    pii k = dp.query(i - M, i);
    dp.update(i, { k.first + 1, i });
    prv[i] = k.second;
  }
  if (prv[N] < 0) {
    puts("-1");
    return;
  }
  int v = N;
  int u = prv[v];
  while (u >= 0) {
    ans.push_back(v - u);
    v = u;
    u = prv[v];
  }
  for (int i = ans.size() - 1; i >= 0; i--) {
    printf("%d%c", ans[i], i == 0 ? '\n' : ' ');
  }
}

void input() {
  scanf("%d%d", &N, &M);
  scanf("%s", &S);
}

int main() {
  input();
  solve();
  return 0;
}

