template <typename T> class SegmentTreeRangeMinimumQuery{
private:
  int size;
  vector<T> vec;
  T e;

  inline T aux(int x, int y, int i, int l, int r){
    if(r<=x || y<=l) return e;
    else if(x<=l && r<=y) return vec[i];
    else return min(aux(x,y,i*2+1,l,(l+r)/2), aux(x,y,i*2+2,(l+r)/2,r));
  };

public:
  SegmentTreeRangeMinimumQuery(int n, const T &e): e(e){
    size = 1;
    while(size < n) size *= 2;
    size = size*2-1;
    vec = vector<T>(size, e);
  }

  inline void update(int i, const T &x){
    int j = i+(size+1)/2-1;
    vec[j] = x;
    --j;
    while(j>=0){
      vec[j/2] = min(vec[(j/2)*2+1], vec[(j/2)*2+2]);
      (j /= 2) -= 1;
    }
  }

  inline T at(int i){
  	return vec[(size+1)/2 + i - 1];
  }

  inline T get(int x, int y){ // [x,y)
    return aux(x,y,0,0,(size+1)/2);
  }
};




const int INF = INT_MAX / 2;

int main(){
  int n,m;
  string s;
  while(cin >> n >> m >> s){

    SegmentTreeRangeMinimumQuery<int> seg(n+1, INF);

    seg.update(n, 0);

    REV(i,n-1,0){
      if(s[i] == '0'){
        auto t = seg.get(i+1, min<int>(n+1, i+m+1)) + 1;
        chmin(t, seg.at(i));
        seg.update(i, t);
      }
    }


    int L = seg.at(0);

    if(L == INF){
      cout << -1 << endl;
    }else{
      vector<int> ans;

      SegmentTreeRangeMinimumQuery<pair<int,int>> seg2(n+1, make_pair(INF, -1));
      REPE(i,n){
        seg2.update(i, make_pair(seg.at(i), i));
      }

      int cur = 0;

      while(cur < n){
        auto res = seg2.get(cur+1, min<int>(n+1, cur+m+1));
        int next = res.snd;
        ans.push_back(next-cur);

        cur = next;
      }

      join(cout, ALL(ans));
    }

  }

  return 0;
}

