template <typename T, class F> struct SegmentTree { // (T, f) : monoid
  using size_type = std::size_t;
  F f; T e; size_t n; std::vector<T> dat;
  SegmentTree() {}
  SegmentTree(F f, T e, size_type n_=0) : f(f), e(e), n(0), dat() { init(n_); }
  void init(size_type n_) {
    n=1; while(n<n_) n<<=1;
    dat.assign(2*n, e);
  }
  void build(std::vector<T> const& v) {
    size_type n_ = v.size(); init(n_);
    for(size_type i=0;i<n_;++i) dat[n+i] = v[i];
    for(size_type i=n;i-->0;) dat[i] = f(dat[i<<1], dat[i<<1|1]);
  }
  T operator[](size_type i) const { return dat[n+i]; }
  void update(size_type k, T x) {
    dat[k+=n] = x; while(k>>=1) dat[k] = f(dat[k<<1], dat[k<<1|1]);
  }
  T query(size_type a, size_type b) {
    T l = e, r = e;
    for(a+=n, b+=n; a<b;a>>=1, b>>=1) {
      if(a & 1) l = f(l, dat[a++]);
      if(b & 1) r = f(dat[--b], r);
    }
    return f(l, r);
  }
};
template <typename T, class F> auto make_seg(F f, T e, std::size_t n=0) {
  return SegmentTree<T, F>(f, e, n);
}

