int main(){

    int N, M;
    cin >> N >> M;
    vector<bool> can(N + 1);
    rep(i, N + 1){
        char c;
        cin >> c;
        can[i] = (c == '0');
    }

    vector<int> mins(N + 1, N + 2);
    auto f1 = [](int x, int y){ return min(x, y); };
    auto f2 = [](int x, int y, int l){ return min(x, y); };
    LazySegmentTree<int, int> seg(mins, N + 2, N + 2, f1, f1, f2);
    seg.effect(0, 1, 0);
    rep(i, N + 1){
        if(seg[i] == N + 2){
            cout << "-1\n";
            return 0;
        }
        if(can[i]){
            int l = i + 1, r = i + M + 1;
            chmin(l, N);
            chmin(r, N + 1);
            if(l >= r)continue;
            seg.effect(l, r, i);
        }
    }

    vector<int> ans;
    int pos = N;
    while(pos > 0){
        int t = seg[pos];
        ans.push_back(pos - t);
        pos = t;
    }

    reverse(all(ans));
    for(int x : ans)cout << x << ' ';
    cout << '\n';
    return 0;

}

