struct SegmentTree {/*{{{*/
  private:
    int n;
    vector<pair<int, string>> node;

  public:
    SegmentTree(vector<pair<int, string>> a) {
      int sz = a.size();
      n = 1; while(n < sz) n *= 2;
      node.resize(2*n-1, mp(INF, ""));
      for(int i=0; i<sz; i++) node[i+n-1] = a[i];
      for(int i=n-2; i>=0; i--) node[i] = min(node[2*i+1], node[2*i+2]);
    }
    SegmentTree(int V) : SegmentTree(vector<pair<int, string>>(V, mp(INF, ""))) {}

    void update(int x, pair<int, string> val) {
      x += (n - 1);
      node[x] = val;
      while(x > 0) {
        x = (x - 1) / 2;
        node[x] = min(node[2*x+1], node[2*x+2]);
      }
    }

    // get min of [l, r)
    pair<int,string> getmin(int a, int b, int k=0, int l=0, int r=-1) {
      if(r < 0) r = n;
      if(r <= a || b <= l) return mp(INF, "");
      if(a <= l && r <= b) return node[k];

      pair<int, string> vl = getmin(a, b, 2*k+1, l, (l+r)/2);
      pair<int, string> vr = getmin(a, b, 2*k+2, (l+r)/2, r);
      return min(vl, vr);
    }
};/*}}}*/

