vl func(string &S, ll N, ll M, ll b, ll now, ll limit) {
  vl ans;
  if ((limit <= 0 && now < N) || now > N || now + (limit * M) < N)
    return ans;
  else if (now == N) {
    ans.push_back(b);
    return ans;
  }
  FOR(i, 1, M + 1) {
    if (S[now + i] == '0') {
      auto po = func(S, N, M, i, now + i, limit - 1);
      if (po.size() > 0) {
        ans.push_back(b);
        AUTO(p, po) ans.push_back(p);
        return ans;
      }
    }
  }
  return ans;
}

