const int N = 2e5 + 10, inf = 1e9;
int dp[N], par[N];

int main() {
    ios_base::sync_with_stdio(false), cin.tie(0), cout.tie(0);
    int n, m;
    string s;
    cin >> n >> m >> s;
    par[n] = -1;
    deque<int> dq;
    for (int i = n - 1; ~i; i--) {
        if (s[i] == '0') {
            if (dq.size() && dq.front() == i + m + 1)
                dq.pop_front();
            while (dq.size() && dp[dq.back()] >= dp[i + 1])
                dq.pop_back();
            dq.push_back(i + 1);
            dp[i] = dp[dq.front()] + 1;
            par[i] = dq.front();
        }
        else {
            if (dq.size() && dp[dq.back()] == i + m + 1)
                dq.pop_front();
            while (dq.size() && dp[dq.back()] >= dp[i + 1])
                dq.pop_back();
            dq.push_back(i + 1);
            dp[i] = inf;
            par[i] = -1;
        }
    }
    int root = 0;
    vector<int> ans;
    while (root ^ -1) {
        ans.push_back(root);
        root = par[root];
    }
    if (ans.back() != n) {
        cout << "-1\n";
        return 0;
    }
    for (int i = 1; i < ans.size(); i++)
        cout << ans[i] - ans[i - 1] << " ";
    cout << "\n";
    return 0;
}

