/*
https://scrapbox.io/data-structures/Sliding_Window_Aggregation
半群の列 (a0, a1, ... , aN-1) を扱う
空間計算量 O(N)
new()
	空の状態でデータ構造を作成する
	時間計算量 O(1)
fold_all()
	op(a0, a1, ... , aN-1) を計算する
	時間計算量 O(1)
push_front/back()
	x を先頭 / 末尾に追加する
	時間計算量 O(1) amortized
pop_front/back()
	先頭要素 a0/末尾要素 aN-1 を削除する
	時間計算量 O(1) amortized
front/back()
	先頭要素 a0/末尾要素 aN-1 を返す
	時間計算量 O(1) amortized	
*/
template <class Data, class Aggregation, class Op> class DequeAggregation {
private:
	class node {
	public:
		Data val;
        Aggregation sum;
		node(const Data &val, const Aggregation &sum) : val(val), sum(sum) {}
	};

	Op op;
	std::stack<node> front_stack, back_stack;

public:
	DequeAggregation(const Op &op = Op())
			: op(op), front_stack(), back_stack() {}

	bool empty() const { return front_stack.empty() && back_stack.empty(); }

	std::size_t size() const { return front_stack.size() + back_stack.size(); }

	Aggregation fold_all() const {
		assert(!empty());
		if (front_stack.empty()) {
			return back_stack.top().sum;
		} else if (back_stack.empty()) {
			return front_stack.top().sum;
		} else {
			return op(front_stack.top().sum, back_stack.top().sum);
		}
	}

	void _push_core(const Data &x, std::stack<node> &first_stack){
		if (first_stack.empty()) {
			first_stack.emplace(x, x);
		} else {
			Aggregation s{op(first_stack.top().sum, x)};
			first_stack.emplace(x, s);
		}
	}

	void push_front(const Data &x) {
		_push_core(x, front_stack);
	}

	void push_back(const Data &x) {
		_push_core(x, back_stack);
	}

	void flatten(std::stack<node> &first_stack, std::stack<node> &second_stack) {
		assert(!empty());
		if (first_stack.empty()) {
			std::size_t firstsize = second_stack.size() / 2 + 1;
			std::size_t secondsize = second_stack.size() - firstsize;
			std::queue<Data> tmp_first_queue;
			std::stack<Data> tmp_second_stack;
			for(std::size_t i = 0; i < secondsize; i++) {
				tmp_second_stack.emplace(second_stack.top().val);
				second_stack.pop();
			}
			for(std::size_t i = 0; i < firstsize; i++) {
				tmp_first_queue.emplace(second_stack.top().val);
				second_stack.pop();
			}

			if(firstsize > 0) {
				first_stack.emplace(tmp_first_queue.front(), tmp_first_queue.front());
				tmp_first_queue.pop();
				while (!tmp_first_queue.empty()) {
					Aggregation s{op(tmp_first_queue.front(), first_stack.top().sum)};
					first_stack.emplace(tmp_first_queue.front(), s);
					tmp_first_queue.pop();
				}
			}
			if(secondsize > 0) {
				second_stack.emplace(tmp_second_stack.top(), tmp_second_stack.top());
				tmp_second_stack.pop();
				while (!tmp_second_stack.empty()) {
					Aggregation s{op(tmp_second_stack.top(), second_stack.top().sum)};
					second_stack.emplace(tmp_second_stack.top(), s);
					tmp_second_stack.pop();
				}
			}
		}
	}

	Data _pop_core(std::stack<node> &first_stack, std::stack<node> &second_stack) {
		flatten(first_stack, second_stack);
		Data val = first_stack.top().val;
		first_stack.pop();
		return val;
	}

	Data pop_front() {
		return _pop_core(front_stack, back_stack);
	}

	Data pop_back() {
		return _pop_core(back_stack, front_stack);
	}


	Data _peek_core(std::stack<node> &first_stack, std::stack<node> &second_stack) {
		flatten(first_stack, second_stack);
		return first_stack.top().x;
	}

	Data front() {
		return _peek_core(front_stack, back_stack);
	}

	Data back() {
		return _peek_core(back_stack, front_stack);
	}
};

