    vector<vector<int>> seq(n+1);

    for(int i = 1; i < n + 1; ++i) {
        if(s[i] == '0') {
            int j = max(0, i - m);

            while(j < i) {
                if(s[j] == '0') {
                    dp[i] = dp[j] + 1;
                    seq[i] += seq[j];
                    seq[i].push_back(i - j);
                    break;
                }
                j++;
            }
        }
    }

    if(dp[n] == 0) {
        print(-1);
        return 0;
    }

    for(auto jump : seq[n]) {
        print(jump, false);
        print(" ", false);
    }
    print();

    return 0;
