        x[i] = t.sc;
        t = mp(t.fs+1,i);
        seg.update(i,t);
    }
    vector<int> ans;
    int t=n,now=n;
    while(now != 0){
        t = x[now];
        ans.pb(now-t);
        now = t;
    }
    reverse(ALL(ans));
    for (int i = 0; i < ans.size(); i++) {
        cout << ans[i] << (i+1==ans.size()?"\n":" ");
    }
    return 0;
}

