class Solution {
public:
    vector<int> solve(string& s, int m) {
        int n = s.length();
        if (s[n - 1] == '1') {
            return {};
        }

        const int INF = 1 << 24;
        vector<int> dp(n + 1, INF);
        vector<int> next(n + 1, n);
        dp[n - 1] = 0;
        deque<int> que;
        que.emplace_back(n - 1);
        for (int i = n - 2; i >= 0; --i) {
            if (s[i] == '1') {
                continue;
            }

            while (!que.empty()) {
                int u = que.front();
                if (u > i + m) {
                    que.pop_front();
                } else {
                    break;
                }
            }
            if (que.empty()) {
                break;
            }
            dp[i] = dp[que.front()] + 1;
            next[i] = que.front();
            while (!que.empty()) {
                if (dp[que.back()] == dp[i]) {
                    que.pop_back();
                } else {
                    break;
                }
            }
            que.push_back(i);
        }   

        if (dp[0] >= INF) {
            return {};
        }
        int x = 0;
        vector<int> res;
        while (x < n - 1) {
            int nx = next[x];
            res.push_back(nx - x);
            x = nx;
        }
        return res;
    }
};

int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;
    string s;
    cin >> s;

    Solution sol;
    auto res = sol.solve(s, m);
    if (res.empty()) {
        cout << "-1\n";
    } else {
        int m = res.size();
        for (int i = 0; i < m; ++i) {
            cout << res[i] << (i == m - 1 ? '\n' : ' ');
        }
    }

    return 0;
}

