const int N=2e5+10 ;
const int inf=1e9 ;

int f[N] ;

struct Node
{
	int v , p ;
	Node* ls ;
	Node* rs ;
	Node ():v(inf),p(0),ls(NULL),rs(NULL) {}
	void pushup ()
	{
		v=min(ls->v,rs->v);
		if ( v==ls->v ) p=ls->p;
		if ( v==rs->v ) p=rs->p;
	}
};
Node pool[N<<1] ;
Node* rt ;
inline Node* newNode ()
{
	static int cnt=0 ;
	return &pool[++cnt];
}

inline Node* build ( int l , int r )
{
	Node* x=newNode();
	if ( l==r ) return x->p=l,x ;
	int mid=(l+r)>>1 ;
	x->ls=build(l,mid),
	x->rs=build(mid+1,r),
	x->pushup();
	return x ;
}

inline void update ( Node* x , int l , int r , int p , int d )
{
	if ( l==r )
	{
		x->v=d;
		return ;
	}
	int mid=(l+r)>>1 ;
	if ( p<=mid ) update(x->ls,l,mid,p,d);
	else update(x->rs,mid+1,r,p,d);
	x->pushup();
	return ;
}
inline int query ( Node* x , int l , int r , int a , int b )
{
	if ( a<=l && r<=b ) return x->p ;
	int mid=(l+r)>>1 , v=inf , res=inf , t ;
	if ( a<=mid )
		t=query(x->ls,l,mid,a,b),
		v=min(v,f[t]),
		res=(v==f[t]?t:res);
	else
		t=query(x->rs,mid+1,r,a,b),
		v=min(v,f[t]),
		res=(v==f[t]?t:res);
	return res ;
}

