#define HIGHESTSETBIT(mask) ( sizeof(int)*8-1-__builtin_clz((mask)) )

class RMQ_SegmentTree {
   VI M;

   void _preprocess(int node, int L, int R) {
      if (L == R) {
         M[node] = L;
         return;
      }

      const int mid = (L+R)/2;
      _preprocess(2 * node, L, mid);
      _preprocess(2 * node + 1, mid+1, R);

      const int pL = M[2 * node];
      const int pR = M[2 * node + 1];

      M[node] = A[pL] <= A[pR] ? pL : pR;
   } 

   int _query(int i, int j, int node, int L, int R) {
      if (i > R || j < L)
         return -1;

      if (i <= L && R <= j)
         return M[node];

      int pL = _query(i, j, 2 * node, L, (L + R) / 2);
      int pR = _query(i, j, 2 * node + 1, (L + R) / 2 + 1, R);

      if (pL < 0) return pR;
      if (pR < 0) return pL;
      return A[pL] <= A[pR] ? pL : pR;
   }

   void _update(int i, int val, int node, int L, int R) {
      if (L == R) {
         M[node] = L;
         A[i] = val;
         return;
      }
      int mid = (L + R)/2 + 1;
      if (i < mid)
         _update(i, val, 2*node, L, mid-1);
      else
         _update(i, val, 2*node+1, mid, R);

      int pL = M[2 * node];
      int pR = M[2 * node + 1];
      M[node] = A[pL] <= A[pR] ? pL : pR;
   }
   VI A;

public:
   RMQ_SegmentTree(const VI& _A) : A(_A) {
      const int N = A.size();
      const int MAXIND = N > 1 ? 2 * ( 1 << (HIGHESTSETBIT(N-1)+1) ) : 2;
      M = VI(MAXIND, -1);
      _preprocess(1, 0, N-1);
   }

   int query(int i, int j) {
      return _query(i, min(j, int(A.size())-1), 1, 0, int(A.size())-1);
   }

   void update(int i, int val) {
      _update(i, val, 1, 0, int(A.size())-1);
   }
};

