// 0-indexed
template <class T>
struct SegmentTree {
  // a,b,c: T, e:T(unit)
  // abc = (ab)c = a(bc)
  // ae = ea = a
  typedef function<T(T, T)> F;
  int n;
  F f;
  T unit;
  vector<T> dat;
  SegmentTree(){};
  SegmentTree(int newn, F f, T t) : f(f), unit(t) {
    init(newn);
  }
  void init(int newn) {
    n = 1;
    while(n < newn) n <<= 1;
    dat.assign(n << 1, unit);
  }

  // "go up" process
  void update(int k, T newdata) {
    dat[k += n] = newdata;
    while(k >>= 1) {
      dat[k] = f(dat[(k << 1) | 0], dat[(k << 1) | 1]);
    }
  }
  // [a,b)
  T query(int a, int b) {
    T vl = unit, vr = unit;
    for(int l = a + n, r = b + n; l < r; l >>= 1, r >>= 1) {
      if(l & 1) vl = f(vl, dat[l++]);
      if(r & 1) vr = f(dat[--r], vr);
    }
    return f(vl, vr);
  }
};
struct data {
  long long dis, num, bf;
};

long long n, m;
string s;
vector<long long> ans;

long long solve();

int main() {
  cin >> n >> m >> s;
  if(solve() == -1)
    cout << -1 << endl;
  else {
    for(int i = 0; i < ans.size(); ++i) {
      if(i != 0) cout << " ";
      cout << ans[i];
    }
    cout << endl;
  }
  return 0;
}

long long solve() {
  auto f = [](data l, data r) {
    if(l.dis < r.dis)
      return l;
    else if(l.dis == r.dis && l.num <= r.num)
      return l;
    return r;
  };
  data dummy = {inf, -1, -1};
  SegmentTree<data> seg(n + 1, f, dummy);
  seg.update(0, {0, 0, -1});
  for(int i = 0; i < n; ++i)
    if(s[i + 1] == '0') {
      data now = seg.query(max(0LL, i - m + 1), i + 1);
      if(now.dis == inf) continue;
      now.bf = now.num;
      now.num = i + 1;
      ++now.dis;
      seg.update(i + 1, now);
    }
  if(seg.query(n, n + 1).dis == inf) return -1;
  data now = seg.query(n, n + 1);
  while(now.num != 0) {
    ans.push_back(now.num - now.bf);
    now = seg.query(now.bf, now.bf + 1);
  }
  reverse(ans.begin(), ans.end());
  return 0;
}

