void update(int i,int l,int r,int in1,int v)
{
    // if(l>r)
    //   return;
    if(in1<l||in1>r)
        return;
    else if(l==r)
    {
        st[i].vl=v;
        st[i].iin=in1;
        return;
    }
    int m=(l+r)/2;
    update(2*i+1,l,m,in1,v);
    update(2*i+2,m+1,r,in1,v);
    if(st[2*i+1].vl<st[2*i+2].vl)
    {
        st[i].iin=st[2*i+1].iin;
        st[i].vl=st[2*i+1].vl;
    }
    else if(st[2*i+1].vl>st[2*i+2].vl)
    {
        st[i].iin=st[2*i+2].iin;
        st[i].vl=st[2*i+2].vl;
    }
    else
    {
        st[i].vl=st[2*i+1].vl;
        st[i].iin=min(st[2*i+2].iin,st[2*i+1].iin);
    }
}
int query(int i,int l,int r,int qs,int qe)
{
    if(qs>r||qe<l)
        return 0;
    if(qs<=l&qe>=r)
        return st[i].iin;
    int m=(l+r)/2;
    int in1=query(2*i+1,l,m,qs,qe);
    int in2=query(2*i+2,m+1,r,qs,qe);
    if(in1== 0)
        return in2;
    else if(in2==0)
        return in1;
    else if(dp[in1]<dp[in2])
        return in1;
    else if(dp[in2]<dp[in1])
        return in2;
    else
        return min(in1,in2);
}
