template <typename Value, typename Time, typename Compare = less<Value>>
class slidemin {
private:
    deque<pair<Value, Time>> deq;
    const Compare compare;

public:
    slidemin(Compare cmp = Compare()): compare(cmp) {}

    void push(Value val, Time t) {
        while(!deq.empty() && !compare(deq.back().first, val)) deq.pop_back();
        deq.emplace_back(val, t);
    }

    void pop(Time t) {
        while(!deq.empty() && deq.front().second < t) deq.pop_front();
    }

    pair<Value, Time> getmin() {
        return deq.front();
    }
};

