// 蟻本p300 スライド最小値
// https://betrue12.hateblo.jp/entry/2019/11/25/225556
void solve() {
    int n, m;
    cin >> n >> m;
    string s;
    cin >> s;

    vector<int> dp(n + 1, inf);
    dp[n] = 0;
    deque<int> q;
    q.push_back(n);
    for (int i = n - 1; i >= 0; --i) {
        if (s[i] == '1') continue;
        while (sz(q) && i + m < q[0]) {
            q.pop_front();
        }
        // cerr << "i " << i << endl; rep(j, sz(q)) cerr << q[j] << " "; cerr << endl;
        dp[i] = dp[q[0]] + 1;
        while (sz(q) && dp[q.back()] >= dp[i]) { // 末尾を取り除く
            q.pop_back();
        }
        q.push_back(i);
    }
    // cerr << dp << endl;
    if (dp[0] >= inf) {
        cout << -1 << endl;
        return;
    }

    // debuged, 辞書順で最小のもの!!
    vector<int> ans;
    int now = 0;
    while (now != n) {
        for (int i = now + 1; i <= now + m; ++i) {
            if (dp[now] - 1 == dp[i]) {
                ans.eb(i - now);
                now = i;
                break;
            }
        }
    }
    cout << ans << endl;
}

