struct Continuity {
  int length;
  bool gameover;
};

std::vector<int> solve(const int N, const int M, const std::string S_reverse) {
  const auto &S = S_reverse;
  auto steps = std::vector<int>{};
  steps.reserve(N);

  {
    auto cont = std::vector<Continuity>{};
    cont.reserve(N + 1);

    for (auto i = 0; i < N + 1;) {
      auto i0 = i;
      auto first = S[i];
      for (; i < N + 1 && S[i] == first; ++i)
        ;
      auto c = Continuity{i0 - i, first == '1'};
      cont.emplace_back(c);
    }

    auto cpos = 0;
    auto pos = 0;
    for (;;) {
      auto move = N - pos;
      if (move <= M) {
        steps.emplace_back(move);
        pos += move;
        break;
      }

      move = M;
      for (; move >= 1; --move) {
        if (S[pos + move] == '0') {
          steps.emplace_back(move);
          pos += move;
          break;
        }
      }
      if (move) {
        continue;
      }

      if (steps.empty())
        return {-1};

      move = steps.back();
      steps.pop_back();
      pos -= move;

      for (--move; move >= 1; --move) {
        if (S[pos + move] == '0') {
          steps.emplace_back(move);
          pos += move;
          break;
        }
      }
      if (move)
        continue;

      return {-1};
    }
  }

  std::reverse(std::begin(steps), std::end(steps));
  return steps;
}

