struct node {
  int i, d, prev;

  node(): i(-1), d(1000000000), prev(-1) {}
  node(int i, int d, int prev): i(i), d(d), prev(prev) {}

  bool operator<(const node& oth) const {
    if(d == oth.d) {
      return prev > oth.prev;
    }
    return d > oth.d;
  }
};

