    int present = 1;  // ゴールからどれくらい離れているか+1 次に調べるべきところ
    int index;
    int next_present = present;
    bool finish = true;
    for(int i=0;i<N+1;i++){
        if(S.at(i)=='1'){
            A.at(i) = -1;
        }
    }
    while(finish){
        for(int i=0;i<M;i++){
            index = N - present - i;
            if(S.at(index) == '0'){
                A.at(index) = count;
                next_present = present + i + 1;
            }
            if(index==0){
                finish = false;
                break;
            }
        }
        if(!finish){
            break;
        }
        if(present==next_present){
            cout << -1 << endl;
            return 0;
        }
        present = next_present;
        count++;
    }
    // output 
    // for(int i=0;i<N+1;i++){
    //     cout << A.at(i) << ",";
    // }
    // cout << endl;
    int initial_n = A.at(0);
    int present_index = 0;
    for(int i=0;i<initial_n;i++){
        for(int j=1;j<=M;j++){
            if(A.at(present_index+j)==-1){
                continue;
            }
            if(A.at(present_index)!=A.at(present_index+j)){
                cout << j << " ";
                // present_indexをきめる
                present_index = present_index + j;
                break;
            }
        }
    }

    return 0;
}

