// セグ木
template<typename T,typename F>
struct ST{

  int size;
  vector<T> seg;
  const F func;
  const T UNIT;

  ST(int N,F func , T UNIT): func(func) , UNIT(UNIT) {
    size = 1;
    while(size < N) size <<= 1;
    seg.assign(2 * size, UNIT);
  }

  ST(const vector<T> &v,F func , T UNIT) : func(func) , UNIT(UNIT){
    // initialize
    int N = (int)v.size();
    size = 1;
    while(size < N) size <<= 1;
    seg.assign(2 * size , UNIT);
    // set
    for(int i = 0; i < N; i++){
      seg[i + size] = v[i];
    }
    build();
  }

  void set(int k, T x){
    seg[k + size] = x;
  }

  void build(){
    for(int k = size-1; k > 0; k--){
      seg[k] = func(seg[2 * k] , seg[2 * k + 1] );
    }
  }

  void update(int k, T x){
    k += size; seg[k] = x;
    while(k >>= 1){
      seg[k] = func( seg[2 * k] , seg[2 * k + 1] );
    }
  }

  void add(int k , T x){
    k += size; seg[k] += x;
    while(k >>= 1){
      seg[k] = func(seg[2 * k] , seg[2 * k + 1] );
    }
  }

  // 半開区間[a,b)へのクエリ
  T query(int a, int b){
    T L = UNIT, R = UNIT;
    for(a+=size,b+=size; a<b; a>>=1,b>>=1){
      if(a & 1) L = func(L,seg[a++]);
      if(b & 1) R = func(seg[--b],R);
    }
    return func(L, R);
  }

  T operator[](const int &k) const{
    return seg[k + size];
  }

};

void solve(){
  ini(N,M);
  ins(S);
  auto f = [&](int a,int b){return min(a,b);};
  ST<int,decltype(f)> seg(N + 10,f,inf);

  vi ans(N + 1 , inf); ans[0] = N;
  seg.update(N , 0);
  repr(i , N){
    if(S[i] == '1') continue;
    int nya = seg.query( min(i + 1 , N) , min(i + M , N) + 1) + 1;
    if(nya < inf){
      seg.update(i , nya );
      amin(ans[nya] , i);
    }
  }
  rep(i,N+1) trc(seg.query(i,i+1));
  trc(ans);
  if(seg.query(0 , 1) == inf) die(-1);
  vi aaa;
  repr(i , seg.query(0,1)) aaa.pb(ans[i] - ans[i + 1]);
  out(aaa);




}

