#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;

struct SegTree {
	int n;
	vector<pair<int, int>> t;

	SegTree(int n) : n(n), t(4 * n, make_pair(INF, -1)) {}

	void update(int p, int x) {
		update_(0, 0, n, p, x);
	}

	pair<int, int> query(int l, int r) {
		return query_(0, 0, n, l, r);
	}

private:
	void update_(int v, int l, int r, int p, int x) {
		if (l + 1 == r) {
			t[v] = make_pair(x, p);
			return;
		}
		int m = (l + r) / 2;
		if (p < m)
			update_(v * 2 + 1, l, m, p, x);
		else
			update_(v * 2 + 2, m, r, p, x);
		t[v] = min(t[v * 2 + 1], t[v * 2 + 2]);
	}

	pair<int, int> query_(int v, int l, int r, int ql, int qr) {
		if (ql >= qr) {
			return make_pair(INF, -1);
		}
		if (l == ql && r == qr) {
			return t[v];
		}
		int m = (l + r) / 2;
		auto xl = query_(v * 2 + 1, l, m, ql, min(qr, m));
		auto xr = query_(v * 2 + 2, m, r, max(ql, m), qr);
		return min(xl, xr);
	}
};

int main() {
	int n, m;
	cin >> n >> m;
	string s;
	cin >> s;
	SegTree t(n + 1);
	t.update(n, 0);
	vector<int> ans(n + 1, -1);
	for (int i = n - 1; i >= 0; i--) {
		if (s[i] == '1') {
			continue;
		}
		pair<int, int> b = t.query(i + 1, min(i + m + 1, n + 1));
		if (b.first != INF) {
			t.update(i, b.first + 1);
			ans[i] = b.second;
		}
	}
	if (ans[0] == -1) {
		cout << -1 << endl;
		return 0;
	}
	for (int i = 0; i < n; i = ans[i]) {
		cout << ans[i] - i << ' ';
	}
	cout << endl;
	return 0;
}

