template<class Type>
Type solve(Type res = Type()){
    int N,M; cin >> N >> M;
    string S; cin >> S;
    for(auto& c:S) c -= '0';

    reverse(S.begin(),S.end());

    vector<int> idx;
    for(int i = 0; i <= N;i++){
        if(S[i] == 0) idx.push_back(i);
    }
    idx.push_back(INF);

    int now = 0;
    while(idx[now] != N){
        if(idx[now+1]-idx[now] > M) return vector<ll>{-1};
        int next = now+1;
        while(idx[next+1]-idx[now] <= M){
            next++;
        }

        res.push_back(idx[next]-idx[now]);
        now = next;

    }
    reverse(res.begin(),res.end());
    return res;
}
