    // input
    cout << fixed << setprecision(10);
    int N, M; cin >> N >> M;
    string str; cin >> str;
    vector<int> dp(N+1, 0);
    int len = 0;
    rep(i, str.size()){
        if(str[i] == '1'){
            len++;
            dp[i] = INTINF;
            if(len >= M) {
                cout << -1 << endl;
                return 0;
            }
        }
        else{
            len = 0;
        }
    }

    ll ans = 0;
    dp[N] = 0;
    SegmentTree seg;
    seg.init(N+1);
    seg.update(N, 0);
    for(int i=N-1; i>=0; i--){
        if(str[i] == '1') continue;
        int l = i;
        int r = min(N, l + M);
        int mi = seg.query(l, r+1);
        seg.update(i, mi + 1);
        dp[i] = mi + 1;
    }

    vector<int> path;
    int bef = dp[0];
    int p = 0;
    rep(i, N+1){
        if(bef > dp[i]){
            path.push_back(p);
            p = 0;
            bef = dp[i];
        }
