#define VARS int mid = (l + r) / 2, lchild = 2*node + 1, rchild = 2*node + 2

using namespace std;
typedef long long ll;
typedef pair<int, int> pii;
typedef vector<int> vi;

const int MAXN = 100005, INF = (1 << 30);

int N, M;
pii ST[4 * MAXN];
string S;

pii combine ( pii a, pii b )
{
	if ( a.first == b.first )
		return a;
	return (a.first < b.first ? a : b);
}

void build ( int node = 0, int l = 0, int r = N )
{
	if ( l == r )
	{
		ST[node] = {0, l};
		return;
	}

	VARS;
	build ( lchild, l, mid );
	build ( rchild, mid + 1, r );
	ST[node] = combine ( ST[lchild], ST[rchild] );
}

void upd ( int pos, int x, int node = 0, int l = 0, int r = N )
{
	if ( pos < l || r < pos )
		return;
	if ( l == r )
	{
		ST[node] = {x, l};
		return;
	}

	VARS;
	upd ( pos, x, lchild, l, mid );
	upd ( pos, x, rchild, mid + 1, r );
	ST[node] = combine ( ST[lchild], ST[rchild] );
}

pii qry ( int L, int R, int node = 0, int l = 0, int r = N )
{
	if ( r < L || R < l )
		return {INF, 0};
	if ( L <= l && r <= R )
		return ST[node];

	VARS;
	return combine ( qry ( L, R, lchild, l, mid ), qry ( L, R, rchild, mid + 1, r ) );
}

int main ()
{
	cin >> N >> M;
	cin >> S;
	build ( );

	pii DP[N + 1];
	DP[N] = {0, N};
	upd ( N, DP[N].first );
	for ( int i = N - 1; i >= 0; i-- )
	{
		if ( S[i] == '1' )
			DP[i] = {INF, -1};
		else
			DP[i] = qry ( i + 1, min ( N, i + M ) );

		if ( DP[i].first != INF )
			DP[i].first++;
		upd ( i, DP[i].first );
	}

	if ( DP[0].first == INF )
		cout << "-1\n";
	else
	{
		int node = 0;
		while ( DP[node].second != node )
			cout << DP[node].second - node << " ", node = DP[node].second;
		cout << "\n";
	}

	return 0;
}

