            cont++;
        } else {
            cont = 0;
        }
        if (cont >= M) works = false;
    }
    if (!works) {
        cout << "-1\n" << endl;
        return 0;
    }
    memset(dp, INF, sizeof(dp));
    memset(nxt, INF, sizeof(nxt));
    fill(tree, tree+3*N, make_pair(INF,INF));
    dp[N] = 0;
    update(1, 0, N, N, dp[N]);
    for (int i=N-1; i>=0; i--){
        if (S[i] == '0') {
            pii result = query(1, 0, N, i+1, min(i+M, N));
            dp[i] = 1+result.first;
            nxt[i] = result.second;
            update(1, 0, N, i, dp[i]);
        }
    }
    int idx = 0;
    while (idx != N){
        printf("%d ", nxt[idx]-idx);
        idx = nxt[idx];
    } cout << endl;
    return 0;
}

