template<class T>
class min_queue {
private:
    queue<T> Q;
    deque<T> minQ;
public:
    void push(T val) {
        Q.push(val);
        while(!minQ.empty() && minQ.back() > val) minQ.pop_back();
        minQ.push_back(val);
    }

    T front() {
        return Q.front();
    }

    void pop() {
        T remove_element = Q.front();
        Q.pop();
        if(!minQ.empty() && minQ.front() == remove_element) minQ.pop_front();
    }

    T getMin() {
        return minQ.front();
    }

    size_t size() {
        return Q.size();
    }

    bool empty() {
        return Q.empty();
    }
};

