class seg_min_index{
public:
	int n,size;
	vector<long long> arr;
	vector<int> hai;
	long long inf;
	seg_min_index(int size) : n(size/2),inf(1LL << 60){
		arr.resize(n);
		hai.resize(n*2);
		fill(arr.begin(),arr.end(),inf);
		this->size=size;
		for(int i=n;i<size;i++) hai[i]=i-n;
	}

	void update(int i,long long v){
		arr[i]=v;
		i+=n;
		while(i>1){
			i/=2;
			hai[i]=arr[hai[2*i]] < arr[hai[2*i+1]] ? hai[2*i] : hai[2*i+1];
		}
	}
	int range_min_index(int left,int right){
		if(left>right) return -1;
		int res=left;
		left+=n,right+=n;
		for(;left<=right;left=(left+1)>>1,right=(right-1)>>1){
			if(left&1){
				if(arr[res] > arr[hai[left]]) res=hai[left];
			}
			if((right&1)==0){
				if(arr[res] > arr[hai[right]]) res=hai[right];
			}
		}
		return res;
	}
};
