    int MAX = n + 1;
    SegmentTree<int64_t> dp(n + 1, MAX, [](const int64_t& l, const int64_t& r) {
        return min(l, r);
    });
    dp.update(n, 0);
    rrep(i, n)
    {
        if (s[i] == '1') {
            dp.update(i, MAX);
