const ll MOD = 1e9+7;
const ll INF = 1e11;

ll R[101000];
typedef pair<ll, ll> P;

class SegmentTree{
    ll n;
    vector<P> node;

public:
    SegmentTree(vector<P> v){
        ll size = v.size();
        n = 1;
        while(n < size) n *= 2;
        node.resize(2*n-1, make_pair(INF, INF));

        for(ll i = 0; i < size; i++){
            node[n-1+i] = v[i];
        }
        for(ll i = n-2; i >= 0; i--){
            node[i] = min(node[2*i+1], node[2*i+2]);
        }
    }

    ll update(ll idx, ll val){
        idx += n-1;
        node[idx] = make_pair(val, idx-(n-1));
        while(idx > 0){
            idx = (idx-1)/2;
            node[idx] = min(node[2*idx+1], node[2*idx+2]);
        }
    }

    //return min value within [a,b)
    //call get_min(a, b);
    P get_min(ll a, ll b, ll k=0, ll l=0, ll r=-1){
        if(r < 0) r = n;

        if(b <= l || r <= a) return make_pair(INF, INF);

        if(a <= l && r <= b) return node[k];

        P vl = get_min(a, b, 2*k+1, l, (l+r)/2);
        P vr = get_min(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }
};


