template<typename F, typename T>
struct swag {
        F func;
        vector<T> front, back, front_acc, back_acc;
        swag(F _func) : func(_func) {}
        T fold_all() {
                assert(not front.empty() || not back.empty());
                if (front.empty()) {
                        return back_acc.back();
                } else if (back.empty()) {
                        return front_acc.back();
                } else {
                        return func(front_acc.back(), back_acc.back());
                }
        }
        void push(T x) {
                if (not back_acc.empty()) {
                        back_acc.push_back(func(back_acc.back(), x));
                } else {
                        back_acc.push_back(x);
                }
                back.push_back(x);
        }
        void pop() {
                if (front_acc.empty()) {
                        assert(not back.empty());
                        while (not back.empty()) {
                                T v = back.back();
                                back.pop_back();
                                back_acc.pop_back();
                                if (not front_acc.empty()) {
                                        front_acc.push_back(func(front_acc.back(), v));
                                } else {
                                        front_acc.push_back(v);
                                }
                                front.push_back(v);
                        }
                }
                front_acc.pop_back();
                front.pop_back();
        }
};

int main() {
        int n, m;
        cin >> n >> m;
        string s;
        cin >> s;
        vector<int> dist(n + 1, 1e9);
        dist[n] = 0;
        auto f = [&](int a, int b) { return min(a, b); };
        swag<decltype(f), int> sw(f);
        for (int i = n - 1; i >= max(0, n - m); i --) {
                if (s[i] != '1') {
                        dist[i] = 1;
                }
                sw.push(dist[i]);
        }
        for (int i = n - m - 1; i >= 0; i --) {
                if (s[i] == '0') {
                        dist[i] = sw.fold_all() + 1;
                }
                sw.pop();
                sw.push(dist[i]);
        }

        int prev = 0;
        set<int> used;
        used.insert(dist[0]);
        vector<int> ans;
        rep(i, n + 1) if (i) {
                if (dist[i] < 1e9 && used.count(dist[i]) == 0) {
                        ans.push_back(i - prev);
                        prev = i;
                        used.insert(dist[i]);
