class Result {
public:
	string proc;
	int procNum;
	Result(string procin, int n) {
		proc = procin;
		procNum = n;
	}
	Result() {
		proc = "";
		procNum = 0;
	}

	bool operator<(const Result &another) const
	{
		if (procNum != another.procNum) {
			return procNum < another.procNum;
		}

		return proc < another.proc;
	};

	bool operator>(const Result &another) const
	{
		if (procNum != another.procNum) {
			return procNum > another.procNum;
		}

		return proc > another.proc;
	};
};

