const ll inf = 5e15;
V<ll> ans;

bool solve() {
    ll N, M;
    cin >> N >> M;
    string S;
    cin >> S;

    V<ll> dists(N + 1, inf);
    ll idx = inf;
    dists.back() = 0;
    for(ll i = 1; i <= M; i++) {
        if(N - i < 0) break;
        if(S[N - i] == '1') continue;
        dists[N - i] = 1;
        idx = N - i;
    }

    if(idx == inf) return false;

    for(ll i = N - M - 1; 0 <= i; i--) {
        if(S[i] == '1') continue;
        while(M < idx - i) idx--;
        while(i < idx && dists[idx] == inf) idx--;
        if(i == idx) return false;
        dists[i] = dists[idx] + 1;
    }

    if(dists[0] == inf) return false;
    DEBUG(dists);

    ll cur_d = dists[0];
    ll cur = 0;
    while(cur < N) {
        ll tmp = cur;
        while(dists[cur] != cur_d - 1) cur++;
        ans.push_back(cur - tmp);
        cur_d--;
    }

    return true;
}

int main() {
    if(solve()) {
        for(ll e : ans) cout << e << ' ';
        cout << endl;
    } else {
