void solve(long long N, long long M,string S){
  reverse(S.begin(),S.end());
  vector<ll> dp(N+1,-1);
  dp[0]=0;
  ll l=0;
  for(ll i=1;i<=N;++i){
    if(S[i]=='1'){
      continue;
    }
    if(l==0||i-dp[l-1]>M){
      if(i-dp[l]>M){
        cout<<-1<<endl;
        return;
      }
      dp[l+1]=i;
      ++l;
    }else{
      dp[l]=i;
    }
  }
  vector<ll> ans;
  REP(l){
    ans.push_back(dp[i+1]-dp[i]);
  }
  reverse(ans.begin(),ans.end());
  REP(ans.size()){
    cout<<ans[i];
    if(i==ans.size()-1){
      cout<<endl;
    }else{
      cout<<" ";
    }
  }
}

