    ans.push_back(b);
    return ans;
  }
  FOR(i, 1, M + 1) {
    if (S[now + i] == '0') {
      auto po = func(S, N, M, i, now + i, limit - 1);
      if (po.size() > 0) {
        ans.push_back(b);
        AUTO(p, po) ans.push_back(p);
        return ans;
      }
    }
  }
  return ans;
}

