void upd(int v, int tl, int tr, int idx, int val){
    //cout << idx << " " << v << "\n";
    if(idx < tl || idx > tr)
        return;
    if(tl == idx && tr == idx){
        seg[v] = val;
        return;
    }
    else{
        int tm = (tl+tr)/2;
        upd(2*v, tl ,tm, idx, val);
        upd(2*v+1, tm+1 ,tr, idx, val);
        seg[v] = min(seg[2*v], seg[2*v+1]);
    }
}
int get(int v, int tl, int tr, int l, int r){
    //cout << l << " " << r << " " << v << "\n";
    if(r < tl || l > tr)
        return 1e9;
    if(l <= tl && tr <= r)
        return seg[v];
    else{
        int tm = (tl+tr)/2;
        return min(
            get(2*v, tl, tm, l, r),
            get(2*v+1, tm+1, tr, l, r)
        );
    }
}
