int N,dp[225816],segtree[816225],pr[225816];
vector<int> ans;

void init(int l=0, int r=N, int i=0){
	int vl,vr;
	if(r-l>1){
		init(l,(l+r)>>1,i*2+1);
		init((l+r)>>1,r,i*2+2);
		vl = segtree[i*2+1];
		vr = segtree[i*2+2];
		if(dp[vl] < dp[vr]){
			segtree[i] = vl;
		}else if(dp[vl] > dp[vr]){
			segtree[i] = vr;
		}else{
			segtree[i] = vl;
		}
	}else{
		segtree[i] = l;
	}
}

void update(int p, int l=0, int r=N, int i=0){
	int vl,vr;
	if(p<l || r<=p){
		return;
	}else if(r-l>1){
		update(p,l,(l+r)>>1,i*2+1);
		update(p,(l+r)>>1,r,i*2+2);
		vl = segtree[i*2+1];
		vr = segtree[i*2+2];
		if(dp[vl] < dp[vr]){
			segtree[i] = vl;
		}else if(dp[vl] > dp[vr]){
			segtree[i] = vr;
		}else{
			segtree[i] = min(vl,vr);
		}
	}else{
		segtree[i] = p;
	}
}

int query(int p, int q, int l=0, int r=N, int i=0){
	int vl,vr;
	if(q<=l || r<=p){
		return N;
	}else if(p<=l && r<=q){
		return segtree[i];
	}else{
		vl = query(p,q,l,(l+r)>>1,i*2+1);
		vr = query(p,q,(l+r)>>1,r,i*2+2);
		if(dp[vl] > dp[vr]){
			return vr;
		}else if(dp[vl] < dp[vr]){
			return vl;
		}else{
			return min(vl,vr);
		}
	}
}

int main(void){
	int n,m,i,v;
	string s;
	fill(dp,dp+225816,INF);
	cin >> n >> m;
	N = n+m;
	cin >> s;
	dp[0] = 0;
	for(i=1; i<=m; ++i){
		if(i>n || s[i]=='1'){
			continue;
		}
		pr[i] = 0;
		dp[i] = 1;
	}
	init();
	for(i=m+1; i<=n; ++i){
		if(s[i]=='1'){
			continue;
		}
		pr[i] = query(i-m,i);
		dp[i] = dp[pr[i]]+1;
		update(i);
	}
	v = n;
	while(v){
		if(!(dp[v]<INF)){
			cout << "-1" << endl;
			return 0;
		}
		ans.push_back(v-pr[v]);
		v = pr[v];
	}
	for(i=(ans.l_ength()-1); i>=0; --i){
		cout << ans[i] << ((i)?" ":"");
	}
	cout << endl;
	return 0;
}

