    cout << n << endl;
    return 0;
  }
  vector<int> A(n+5, INF);
  A[0] = 0;
  for (int i = 1; i <= n && i <= m; ++i) {
    if (s[i] == '0') A[i] = 1;
  }
  auto f = [](int a, int b){ return min(a,b);};
  SegmentTree<int> seg(n+5, f, INF);
  seg.build(n+5, A);
  for (int i = m+1; i <= n; ++i) {
    if (s[i] == '0') {
      int v = seg.query(i-m,i) + 1;
      seg.set_val(i,v);
    }
  }
  if (seg[n] == INF) {
    cout << -1 << endl;
    return 0;
  }
  // rep(i, n+1) debug(seg[i]);
  vector<int> ans;
  int now = seg[n]-1, idx = n-1, pre = n;
  for (int i = n-1; i >= 0; --i) {
    if (seg[i] == INF) continue;
    if (seg[i] == now) idx = i;
    else if (seg[i] == now - 1) {
      ans.emplace_back(pre - idx);
      pre = idx;
      idx = i;
      now--;
    }
  }
  ans.emplace_back(pre - 0);
  reverse(all(ans));
