void upd(int v, int val)
{
	d[v] = val;
	mi[v] = v;
	v >>= 1;
	while (v)
	{
		d[v] = min(d[v * 2], d[v * 2 + 1]);
		if (d[v] == d[v * 2])
		{
			vosst[v] = vosst[v * 2];
			mi[v] = mi[v * 2];
		}
		else
		{
			vosst[v] = vosst[v * 2 + 1];
			mi[v] = mi[v * 2 + 1];
		}
		v >>= 1;
	}
}

pair <int, int> get_min(int v, int cl, int cr, int nl, int nr)
{
	if (cl > nr || cr < nl)
		return mp(1e9, -1);
	if (nl <= cl && cr <= nr)
		return mp(d[v], mi[v]);
	int mid = (cl + cr) / 2;
	pair <int, int> p = get_min(v * 2, cl, mid, nl, nr);
	pair <int, int> q = get_min(v * 2 + 1, mid + 1, cr, nl, nr);
	if (p.first > q.first)
		return q;
	return p;
}

