// ランレングス
// 例 s = "aabccc" => [2, 1, 3]
VI run_length(string s){
  char prev = s[0];
  VI V;
  ll cnt = 1;
  FOR(i, 1, s.size()){
    char c = s[i];
    if(c!=prev){
      V.push_back(cnt);
      // reset
      cnt = 1;
      prev = c;
    }else{
      cnt++;
    }
  }
  V.push_back(cnt);
  return V;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    ll N, M;
    cin >> N >> M;

    string s; cin >> s;

    auto A = run_length(s);
    rep(i, A.size()){
      if(i%2==1){
        // 飛び越せない間隔
        if(A[i]>=M) no();
      }
    }

    // 以降、到達可能

    ll L = s.size();
    VI F(L); // iに行きたい時、実際はどこに着地するか
    ll can = 0;
    for(int i=L-1; i>=0; i--){
      if(s[i]=='0'){
        F[i] = i;
        can = i;
      }else{
        F[i] = can;
      }
    }

    ll pos = L-1;
    VI Ans;
    // 後ろから貪欲
    // いまいる場所からMでどこまでいけるか
    while(pos!=0){
      ll to = max(pos-M, 0LL);
      if(s[to]=='0'){
        pos = to;
      }else{
        pos = F[to];
      }
      Ans.push_back(pos);
    }
    reverse(ALL(Ans));
    Ans.push_back(L-1);
    FOR(i, 0, Ans.size()-1){
      // 出目
      ll diff = Ans[i+1] - Ans[i];
      cout << diff << ' ';
    }
    cout << endl;

    return 0;
}

