template<typename T>
class SegTree {
public:
  using fn = function<T(T&, T&)>;
  SegTree (fn f, T ini_, size_t n_) : merge(f), ini(ini_) {
    n = 1;
    while (n < n_) n *= 2;
    v.resize(n * 2 - 1, ini = ini_);
    merge = f;
  }
  void update(size_t k, T x) {
    k += n - 1;
    v[k] = x;
    while (0 < k) {
      k = (k - 1) / 2;
      v[k] = merge(v[k * 2 + 1], v[k * 2 + 2]);
    }
    return ;
  }
  // [begin, end)
  T query(size_t begin, size_t end) {
    return query(begin, end, 0, 0, n);
  }
  T operator [] (size_t idx) const {
    return v[idx + n - 1];
  }
  void show(void) {
    for (int i = 0; i * 2 + 2 < v.size() && v[i] != ini; ++i) {
      clog << make_pair(i, v[i]) << ": " << make_pair(i * 2 + 1, v[i * 2 + 1]) << ", " << make_pair(i * 2 + 2, v[i * 2 + 2]) << endl;
    }
    return ;
  }
private:
  vector<T> v;
  int n;
  fn merge;
  T ini;

  T query(int begin, int end, int k, int l, int r) {
    if (r <= begin || end <= l) {
      return ini;
    }
    if (begin <= l && r <= end) {
      return v[k];
    } else {
      auto x = query(begin, end, k * 2 + 1, l, (l + r) / 2);
      auto y = query(begin, end, k * 2 + 2, (l + r) / 2, r);
      return merge(x, y);
    }
  }
};

int main(int argc, char *argv[])
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  int n, m;
  string s;
  while (cin >> n >> m >> s) {
    if (s == "0") {
      cout << endl;
      continue;
    }

    SegTree<pair<int, int>>::fn merge = [] (pair<int, int> a, pair<int, int> b) {
      if (a.first != b.first) return a < b ? a : b;
      return a.second < b.second ? b : a;
    };
    const int inf = 1 << 29;
    SegTree<pair<int, int>> segtree(merge, make_pair(inf, -1), n);
    segtree.update(0, make_pair(0, 0));

    reverse(s.begin(), s.end());
    const int N = 1e5 + 5;
    int prev[N];
    fill(prev, prev + N, -1);
    for (int i = 1; i < s.size(); ++i) {
      if (s[i] == '1') continue;
      pair<int, int> mn = segtree.query(max(0, i - m), i);
      pair<int, int> p = make_pair(mn.first + 1, i);
      segtree.update(i, p);
      prev[i] = mn.second;
    }

    if (segtree.query(n, n+1).first == inf) {
      cout << -1 << endl;
      continue;
    }
    vector<int> path;
    for (int curr = n; curr != -1; curr = prev[curr]) {
      path.push_back(curr);
    }
    path.pop_back();
    vector<int> v;
    for (int i = 0; i < path.size(); ++i) {
      v.push_back(path[i] - path[i + 1]);
    }
    each (i, v)cout << i << ' '; cout << endl;
  }

  return 0;
}

