namespace edamat {
template <class Info>
struct edge {
    int from, to;
    Info info;
    edge(int to, Info info) : to(to), info(info) {}
    edge(int from, int to, Info info) : from(from), to(to), info(info) {}
};

struct normal_edge {
    normal_edge() {}
};

//! graphは基底クラス！使うときはundirected_graphかdirected_graphを使う。
template <class Info>
class graph {
   protected:
    using edge_type = edge<Info>;
    ::std::size_t N;
    ::std::vector<::std::vector<edge_type>> edges;

   public:
    graph(::std::size_t N_) : N(N_), edges(N_) {}
    virtual void add_edge(int x, int y, Info info = static_cast<Info>(1)) = 0;
    const ::std::vector<edge_type> &delta(int v) const {
        assert(v < N);
        return edges[v];
    }
    const ::std::vector<edge_type> &operator[](int v) const {
        return this->delta(v);
    }
    ::std::size_t size() const noexcept { return N; }
    ::std::vector<Info> bfs(int);
    ::std::vector<Info> dijkstra(int);
    ::std::vector<Info> bellman_ford(int);
};

template <class Info>
class undirected_graph : public graph<Info> {
   public:
    undirected_graph(::std::size_t N) : graph<Info>(N) {}
    void add_edge(int x, int y, Info info = static_cast<Info>(1)) {
        this->edges[x].push_back(edge<Info>(x, y, info));
        this->edges[y].push_back(edge<Info>(y, x, info));
    }
};

template <class Info>
class directed_graph : public graph<Info> {
   public:
    directed_graph(::std::size_t N) : graph<Info>(N) {}
    void add_edge(int x, int y, Info info = static_cast<Info>(1)) {
        this->edges[x].push_back(edge<Info>(x, y, info));
    }
    ::std::vector<int> topological_sort(void);
};

template <typename Info>
::std::vector<Info> graph<Info>::bfs(int s) {
    const auto INF = ::std::numeric_limits<Info>::max();
    ::std::vector<Info> dist(edges.size(), INF);
    ::std::vector<int> b(edges.size(), -1);  // 経路復元

    ::std::queue<Info> q;
    q.push(s);
    dist[s] = 0;
    while(!q.empty()) {
        Info v = q.front();
        q.pop();
        for(auto e : edges[v]) {
            if(dist[e.to] != INF) continue;
            dist[e.to] = dist[e.from] + e.info;
            b[e.to] = e.from;  // 経路復元
            q.push(e.to);
        }
    };
    return dist;
}

template <typename Info>
::std::vector<Info> graph<Info>::dijkstra(int s) {
    const auto INF = ::std::numeric_limits<Info>::max();
    ::std::vector<Info> dist(edges.size(), INF);
    ::std::vector<int> b(edges.size(), -1);  // 経路復元
    using Pi = ::std::pair<Info, int>;

    ::std::priority_queue<Pi, std::vector<Pi>, std::greater<Pi>> que;
    dist[s] = 0;
    que.emplace(dist[s], s);
    while(!que.empty()) {
        Info cost;
        int idx;
        ::std::tie(cost, idx) = que.top();
        que.pop();
        if(dist[idx] < cost) continue;
        for(auto &e : edges[idx]) {
            auto next_cost = cost + e.info;
            if(dist[e.to] <= next_cost) continue;
            dist[e.to] = next_cost;
            b[e.to] = idx;  // 経路復元
            que.emplace(dist[e.to], e.to);
        }
    }
    if(dist[edges.size() - 1] == INF) {
        return vector<Info>();
    }
    return b;
};

template <typename Info>
::std::vector<Info> graph<Info>::bellman_ford(int s) {
    const auto INF = ::std::numeric_limits<Info>::max();
    ::std::vector<Info> dist(edges.size(), INF);
    ::std::vector<int> b(edges.size(), -1);  // 経路復元

    dist[s] = 0;
    for(int i = 0; i < edges.size() - 1; i++) {
        for(int idx = 0; idx < edges.size(); idx++) {
            for(auto &e : edges[idx]) {
                if(dist[e.from] == INF) continue;
                auto next_cost = dist[e.from] + e.info;
                if(dist[e.to] <= next_cost) continue;
                dist[e.to] = next_cost;
                b[e.to] = e.from;  // 経路復元
            }
        }
    }
    for(int idx = 0; idx < edges.size(); idx++) {
        for(auto &e : edges[idx]) {
            if(dist[e.from] == INF) continue;
            if(dist[e.from] + e.info < dist[e.to]) return ::std::vector<Info>();
        }
    }
    return dist;
}

template <typename Info>
::std::vector<int> directed_graph<Info>::topological_sort() {
    ::std::vector<int> h(this->size(), 0);
    for(int idx = 0; idx < this->size(); idx++) {
        for(auto &e : this->edges[idx]) {
            h[e.to]++;
        }
    }

    //入次数が0の頂点の集合
    ::std::stack<int> st;

    //入次数が0の頂点であればstに追加
    rep(i, this->size()) if(h[i] == 0) st.push(i);

    //ソートされた後のグラフ
    ::std::vector<int> ret;
    // stがなくなるまでループ
    while(st.size()) {
        // stの集合のから一つ取り出す
        int i = st.top();
        st.pop();
        ret.emplace_back(i);
        for(auto &e : this->edges[i]) {
            //隣接する頂点の入次数をマイナス1
            h[e.to]--;
            //これによって入次数が0になればstに追加
            if(h[e.to] == 0) st.push(e.to);
        }
    }
    return ret;
}

}  // namespace edamat
void solve() {
    i64 N, M;
    cin >> N >> M;
    edamat::directed_graph<int> g(N + 1);
    string S;
    cin >> S;
    for(int i = 1; i < N + 1; i++) {
        g.add_edge(i, i - 1, 0);
    }
    for(int i = 0; i < N + 1; i++) {
        if(S[i] != '1') {
            g.add_edge(i, min(i + M, N), 1);
        }
    }
    auto root = g.dijkstra(0);
    if(root.empty()) {
        cout << -1 << endl;
        return;
    }
    vector<int> ans;
    int t = N;
    while(t != 0) {
        if(root[t] > t) {
            t = root[t];
        } else {
            t = root[t];
            ans.emplace_back(t);
        }
    }
    reverse(ans.begin(), ans.end());
    ans.emplace_back(N);
    rep(i, ans.size() - 1) { cout << ans[i + 1] - ans[i] << " "; }
    cout << endl;
}

