    std::reverse(s.begin(), s.end());
    std::list<int> l;
    int p = 0;
    while (true) {
        if (p + m >= n) {
            l.push_front(n - p);
            break;
        }
        bool f = false;
        for (auto d : boost::irange(m, 0, -1)) {
            if (s[p + d] == '0') {
                f = true;
                l.push_front(d);
                p += d;
                break;
            }
        }
        if (!f) {
            out(-1);
            return;
        }
    }
    out.print(l);
}

