class Segment_Tree{
	private:
	int n;
	vi date;
	public:
	Segment_Tree(int n_){
		n=1;
		while(n<n_) n*=2;
		date=vi(2*n-1,inf);
	}
	void Update(int k,int x){
		k+=n-1;
		date[k]=min(date[k],x);
		while(k>0){
			k=(k-1)/2;
			date[k]=min(date[k*2+1],date[k*2+2]);
		}
	}
	int Query(int a,int b){
		a+=n-1;b+=n-1;
		int m=inf;
		while(a<b){
			if(a%2==0) m=min(m,date[a++]);
			if(b%2==0) m=min(m,date[--b]);
			a/=2;b/=2;
		}
		return m;
	}
	int Open(int k){return date[k+n-1];}
};

