// segtree {{{
class segtree {
  private:
    int size;
    vector<Z> range, real;
    void update_impl(int left, int right, int node, int a, int b, Z x) {
      if (right <= a || b <= left) return;
      if (left <= a && b <= right) {
        ix(range, node) = min(ix(range, node), x);
        ix(real, node) = min(ix(real, node), x);
        return;
      }
      update_impl(left, right, 2 * node + 1, a, (a + b) / 2, x),
      update_impl(left, right, 2 * node + 2, (a + b) / 2, b, x);
      ix(real, node) = min(ix(real, 2 * node + 1), ix(real, 2 * node + 2));
    }
    Z query_impl(int left, int right, int node, int a, int b) const {
      if (right <= a || b <= left) return INF;
      if (left <= a && b <= right) return real[node];
      auto lv = query_impl(left, right, 2 * node + 1, a, (a + b) / 2),
           rv = query_impl(left, right, 2 * node + 2, (a + b) / 2, b);
      return min({lv, rv, ix(range, node)});
    }
  public:
    segtree(int n) {
      size = 1;
      while (size < n) size *= 2;
      range.resize(size * 2 - 1, INF);
      real.resize(size * 2 - 1, INF);
    }

    Z query(int left, int right) const {
      return query_impl(left, right, 0, 0, size);
    }

    void update(int left, int right, Z x) {
      update_impl(left, right, 0, 0, size, x);
    }
};
