struct SegmentTree
{
    using T = int;

    int N;
    vector<T> dat;

    T id = INF;
    T F(T &a, T &b) { return min(a, b); }

    SegmentTree(int n){
        N = 1;
        while(n > N) N = N << 1;
        dat = vector<T>(2 * N - 1, id);
    }

    SegmentTree(int n, vector<T> &v){
        N = 1;
        while(n > N) N = N << 1;
        dat = vector<T>(2 * N - 1, id);
        for(int i = 0; i < n; i++) dat[i + N - 1] = v[i];
        for(int i = N - 2; i >= 0; i--) dat[i] = F(dat[i * 2 + 1], dat[i * 2 + 2]); 
    }

    SegmentTree(){}


    void update(int k, T a){
        k += N - 1;
        dat[k] = a;
        while(k > 0){
            k = (k - 1) / 2;
            dat[k] = F(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }

    void reset() { fill(dat.begin(), dat.end(), id); }

    T get(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return id;
        if(a <= l && r <= b) return dat[k];
        else{
            T vl = get(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = get(a, b, k * 2 + 2, (l + r) / 2, r);
            return F(vl, vr);
        }
    }
    T get(int a, int b) { return get(a, b, 0, 0, N); }

    T val(int k){ return dat[k + N - 1]; }
};

signed main(){

    int N, M; cin >> N >> M;
    string S; cin >> S;
    SegmentTree ST(N + 1);
    vec dp(N + 1, INF);
    dp[0] = 0;
    ST.update(0, 0);

    FOR(i, 1, N + 1) if(S[i] == '0'){
        int m = ST.get(max(0LL, i - M), i);
        if(m < INF){
            dp[i] = m + 1;
            ST.update(i, m + 1);
        }
    }
    //debug(dp[N]);

    if(dp[N] >= INF) Return(-1);

    int now = N;
    vec ans;
    while(now){
        IFOR(i, 1, M + 1) if(now - i >= 0){
            if(dp[now] == dp[now - i] + 1){
                ans.pb(i);
                now -= i;
                break;
            }
        }
    }
    Reverse(ans);
    for(int x: ans) cout << x << " ";
    cout << endl;

    return 0;
}

