const int oo = 1e9;

struct segment_tree{


	vector<int> st;

	segment_tree(int n) : st(4 * n){

	}

	void update(int node, int b, int e, int pos, int v){
		if(b == e)
			st[node] = v;
		else{
			int m = (b + e) >> 1;
			int l = node << 1;
			int r = l | 1;

			if(pos <= m)
				update(l, b, m, pos, v);
			else
				update(r, m + 1, e, pos, v);

			st[node] = min(st[l], st[r]);
		}
	}

	int query(int node, int b, int e, int i, int j){
		if(b >= i && e <= j)
			return st[node];

		if(b > j || e < i)
			return oo;

		int m = (b + e) >> 1;
		int l = node << 1;
		int r = l | 1;

		int L = query(l, b, m, i, j);
		int R = query(r, m + 1, e, i, j);

		return min(L, R);
	}

};

int main(){
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	//freopen("input.txt", "r", stdin);
	//freopen("output.txt", "w", stdout);

