	n++;

	string s;
	cin >> s;

	segment_tree st(n);

	for(int i = 0; i < n; i++){
		if(s[i] == '0')
			st.update(1, 0, n - 1, i, i);
		else
			st.update(1, 0, n - 1, i, oo);
	}

	vector<int> ans;

	int pos = n - 1;
	while(pos > 0){
		int hi = pos - 1;
		int lo = max(0, pos - k);
		int p = st.query(1, 0, n - 1, lo, hi);

		if(p == oo){
			cout << -1 << endl;
			return 0;
		}

		ans.push_back(pos - p);
		pos = p;
	}

	reverse(ans.begin(), ans.end());
	for(int i = 0; i < ans.size(); i++)
		cout << ans[i] << " \n"[i + 1 == ans.size()];

	return 0;
}

