  std::vector<long long int> field;
  for(long long int i = 0; i <= N; i++){
    if(S[i] == '0'){
      field.push_back(i);
    }
  }
  /*
  std::cerr << "S:" << std::endl;
  std::cerr << S << std::endl;
  std::cerr << "field" << std::endl;
  for(long long int i = 0; i < field.size(); i++){
