  // solve problem
  //long long int current_pos = N;
  long long int current_index = field.size()-1;
  int possible_flag = 1;

  long long int l, r, mid;
  std::vector<long long int> dices_reverse;
  while(current_index > 0){
    // go back to initial position
    if(field[current_index] <= M){
      dices_reverse.push_back(field[current_index]);
      //current_pos = 0;
      current_index = 0;
      break;
    }
    // it is impossible to reach goal
    else if(field[current_index] - field[current_index-1] > M){
      possible_flag = 0;
      break;
    }
    // bisection
    l = 0;
    r = current_index-1;
    while(r-l > 1){
      mid = (l+r)/2;
      if(field[current_index]-field[mid]>M)l = mid;
      else r = mid;
    }
    dices_reverse.push_back(field[current_index] - field[r]);
    current_index = r;
  }

  std::cerr << "Answer:" << std::endl;
  if(possible_flag == 0){
    std::cout << -1 << std::endl;
  }
