class ST {
  const int n;
  vector<PP> v;
public:
  ST(int k)
    : n(1 << k), v(2 << k, PP(inf, inf)) {
  }

  PP query(int l, int r) {
    l += n;
    r += n;
    PP mn(inf, inf); 
    while (l < r) {
      if (l & 1) mn = min(mn, v[l++]);
      if (r & 1) mn = min(mn, v[--r]);
      l /= 2;
      r /= 2;
    }
    return mn;
  }

  void update(int i, PP p) {
    i += n;
    while (i > 0) {
      v[i] = min(v[i], p);
      i /= 2;
    }
  }
};

