vl func(vl &DP, string &S, ll N, ll M, ll b, ll now, ll limit) {
  vl ans;
  if ((limit <= 0 && now < N) || now > N || now + (limit * M) < N)
    return ans;
  else if (now == N) {
    ans.push_back(b);
    return ans;
  }
  if (DP[now] == limit)
    return ans;
  DP[now] = limit;
  FOR(i, 1, M + 1) {
    if (S[now + i] == '0') {
      auto po = func(S, N, M, i, now + i, limit - 1);
      if (po.size() > 0) {
        ans.push_back(b);
        AUTO(p, po) ans.push_back(p);
        return ans;
      }
    }
  }
  return ans;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  ll N, M;
  cin >> N >> M;
  string S;
  cin >> S;
  //最短
  ll now = 0;
  ll count = 0;
  ll oldnow = 0;
  vl DP(N + 1, 0);
  while (true) {
    oldnow = now;
    count++;
    for (ll i = M; i >= 1; i--) {
      if (i + now > N || S[i + now] == '1')
        continue;
      else {
        now += i;
        break;
      }
    }
    if (now == N)
      break;
    if (oldnow == now) {
      cout << -1 << endl;
      return 0;
    }
  }
  auto A = func(DP, S, N, M, 0, 0, count);
  REP(i, A.size() - 1) cout << A[i + 1] << " ";
  cout << endl;

  return 0;
}

