    debug(A);

    rep(i, A.size()){
      if(i%2==1){
        //いけないばしょ
        if(A[i]>=M) no();
      }
    }

    debug("can go");

    ll L = s.size();
    VI F(L);
    ll can = 0;
    for(int i=L-1; i>=0; i--){
      if(s[i]=='0'){
        F[i] = i;
        can = i;
      }else{
        F[i] = can;
      }
    }
    debug(F);
    debug(s);

    ll pos = L-1;

    VI Ans;
    // いまいるばしょからMでどこまでいけるか
    while(pos!=0){
      ll to = max(pos-M, 0LL);
      if(s[to]=='0'){
        pos = to;
      }else{
        pos = F[to];
      }
      Ans.push_back(pos);
      //p(pos);
    }
    reverse(ALL(Ans));
