template<typename Monoid>
struct SegmentTree{
    using F = function<Monoid(Monoid, Monoid)>;

    int sz;
    vector<Monoid> seg;

    const F f;      // モノイドに対して二項演算を行う関数オブジェクト
    const Monoid M1;

    SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1){
        sz = 1;
        while(sz < n)   sz <<= 1;
        seg.assign(2 * sz, M1);
    }

    void set(int k, const Monoid &x){
        seg[k + sz] = x;
    }

    void build(){
        for(int k = sz - 1; k > 0; --k){
            seg[k] = f(seg[k << 1], seg[k << 1 | 1]);
        }
    }

    void update(int k, const Monoid &x){
        k += sz;
        seg[k] = x;
        while(k >>= 1){
            seg[k] = f(seg[k << 1], seg[k << 1 | 1]);
        }
    }

    Monoid query(int a, int b){
        Monoid L = M1, R = M1;
        for(a += sz, b += sz; a < b; a >>= 1, b >>= 1){
            if(a & 1)   L = f(L, seg[a++]);
            if(b & 1)   R = f(seg[--b], R);
        }
        return f(L, R);
    }

    Monoid operator[](const int &k) const{
        return seg[k + sz];
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    string s;
    cin >> n >> m >> s;
    SegmentTree<P> dp(n + 1, [](P a, P b){return min(a, b);}, P(INF, -1));
    dp.update(0, P(0, 0));
    for(int i = 1; i <= n; ++i){
        if(s[i] == '1') continue;
        int left = max(0, i - m), right = i + 1;
        P p = dp.query(left, right);
        dp.update(i, P(p.first + 1, i));
    }
    if(dp[n].first >= INF){
        cout << -1 << "\n";
        return 0;
    }
    vector<int> res;
    int pos = n;
    int cnt = dp[n].first;
    while(cnt > 0){
        int left = max(0, pos - m), right = pos;
        P p = dp.query(left, right);
        res.push_back(pos - p.second);
        cnt = p.first, pos = p.second;
    }
    reverse(res.begin(), res.end());
    int sz = res.size();
    for(int i = 0; i < sz; ++i) cout << res[i] << ((i == sz - 1) ? "\n" : " ");
}

