const ll MAX_N = 100000;
const ll MAX_M = 100000;
const ll MAX_S = MAX_N + 1;

ll N, M;
char S[MAX_S + 10];
vector<ll> dp[MAX_S + 10];

bool solve(int prev, int cur) {
    while (cur >= 0) {
        while (S[cur] == '1') {
            cur--;
        }
        if (prev - cur > M) return false;

        if (dp[prev].front() + prev - cur <= M) {
            dp[cur] = dp[prev];
            dp[cur][0] += prev - cur;
        } else {
            dp[cur] = {prev - cur};
            dp[cur].insert(dp[cur].end(), dp[prev].begin(), dp[prev].end());
        }
        prev = cur;
        cur--;
    }

    return true;
}

