            prev = i;
            dp[i] = { N - i};
        }
    }

    if (solve(prev, N - min(N, M) - 1)) {
        for (auto &x : dp[0]) {
            cout << x << endl;
        }
    } else {
        cout << -1 << endl;
    }

    return 0;
}

