//-------------------------------------------------------------------
struct segtree{
  ll M=1, INF = 1000000000000000000, INIT;
  vector<vll> dat;
  segtree(ll N, ll num){
    INIT = num;
    while(M<N) M*=2;
    dat.resize(M*2-1, vll{num, -1});
  }
  void update(ll x, ll k, ll l=0, ll r=-1){
    if(r==-1) r = M;
    k+=M-1;
    dat[k] = vll{x, k-(M-1)};
    while(k>0) {
      k = (k-1)/2;
      dat[k] = min(dat[k*2+1], dat[k*2+2]);
    }
  }
  vll query(ll a, ll b=-1, ll k=0, ll l=0, ll r=-1){
    if(r==-1) r = M;
    if(b==-1) b = M;
    if(r<=a || b<=l) return vll{INIT, -INIT};
    if(a<=l && r<=b) return dat[k];
    vll A = query(a, b, k*2+1, l, (l+r)/2);
    vll B = query(a, b, k*2+2, (l+r)/2, r);
    return min(A, B);
  }
};
//-------------------------------------------------------------------

vll pre(100002, -1);
int main(int argc, char const *argv[]) {
  ll n, m, INF=10000000000;std::cin >> n >> m;
  string s;std::cin >> s;
  segtree seg(n+1, INF);
  seg.update(0, n);
  for(int i=n-1;i>=0;i--){
    vll q = seg.query(i+1, min(n+1, i+m+1));
    if(q[0]==INF||s[i]=='1') continue;
    seg.update(q[0]+1, i);
    pre[i] = q[1];
  }
  ll ans = seg.query(0, 1)[0];
  if(ans==INF){
    std::cout << -1 << '\n';
    return 0;
  }
  ll now = 0, p = -1;
  vll a;
  while(now!=-1){
    p = now;
    now = pre[now];
    if(now!=-1) a.push_back(now - p);
  }
  re(i, a.size()) std::cout << a[i] << (i==a.size()-1?"\n":" ");
  return 0;
}

