typedef long long ll;
typedef pair<int, int> P;


P dat[270010];

int seginit(int n_) {
    int n = 1;
    while (n < n_) n *= 2;
    for (int i = 0; i < n * 2 - 1; i++) dat[i] = P(1e9, 0);
    return n;
}

void update(int n, int k, P p) {
    k += n - 1;
    dat[k] = p;
    while (k > 0) {
        k = (k - 1) / 2;
        if (dat[k] <= p) break;
        dat[k] = p;
    }
    return;
}

P query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return P(1e9, 0);
    if (a <= l && r <= b) return dat[k];
    else {
        P vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
        P vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
}

int main(void) {
