    for(int i = 1; i<=N; i++){
        char c;
        cin >> c;
        if(c == '0'){
            int k = query(max(0, i-M), i-1, 1);
            dp[i] = dp[k] + 1;
            par[i] = k;
        }
        else{
            dp[i] = INT_MAX/2;
        }
        upd(i, 1);
    }
    if(dp[N] >= INT_MAX/2){
        cout << -1 << "\n";
        return 0;
    }
    stack<int> stk;
    int c = N;
    while(c){
        stk.push(c-par[c]);
