//lazy evaluation
void eval(long long k){
  if(lazy[k]!=-llinf){
    stree[k]=llmax(stree[k],lazy[k]);
    if(k<(ssize-1)){
      lazy[2*k+1]=llmax(lazy[2*k+1],lazy[k]);
      lazy[2*k+2]=llmax(lazy[2*k+2],lazy[k]);
    }
    lazy[k]=-llinf;
  }
  return;
}

