  for(i=0;i<n;i++){
    a[i]=i;
  }
  for(i=n-1;i>=1;i--){
    p=rand()%(i+1);
    swap(&a[p],&a[i]);
  }
}

typedef struct{
int val;
int node;
}sd;

int sdsortfnc(const void *a,const void *b){
if(((sd*)a)->val < ((sd*)b)->val){return -1;}
if(((sd*)a)->val > ((sd*)b)->val){return 1;}
return 0;
}

void coordinate_comp(int a[],int n){
  int i,c=0;
  sd dat[524288];
  for(i=0;i<n;i++){
    dat[i].val=a[i];
    dat[i].node=i;
  }
  qsort(dat,n,sizeof(dat[0]),sdsortfnc);
  a[dat[0].node]=c;
  for(i=1;i<n;i++){
    if(dat[i-1].val!=dat[i].val){c++;}
    a[dat[i].node]=c;
  }
}

long long ssize=524288;
long long stree[1048576],lazy[1048576];

void sinit(){
    long long i,j;
    for(i=0;i<2*ssize;i++){
        stree[i]=llinf;
        lazy[i]=llinf;
    }
    return;
}

//lazy evaluation
void eval(long long k){
  if(lazy[k]!=llinf){
    stree[k]=llmin(stree[k],lazy[k]);
    if(k<(ssize-1)){
      lazy[2*k+1]=llmin(lazy[2*k+1],lazy[k]);
      lazy[2*k+2]=llmin(lazy[2*k+2],lazy[k]);
    }
    lazy[k]=llinf;
  }
  return;
}

//spread t [a,b)
//call:k=0,l=0,r=ssize
void sprquery(long long a,long long b,long long t,long long k,long long l,long long r){
    if(r<=a){return;}
    if(b<=l){return;}
    long long ld,rd,md;
    eval(k);
    if(a<=l && r<=b){
        lazy[k]=llmin(lazy[k],t);
        eval(k);
        return;
    }
    //eval(k*2+1);
    //eval(k*2+2);
    sprquery(a,b,t,k*2+1,l,(l+r)/2);
    sprquery(a,b,t,k*2+2,(l+r)/2,r);
    stree[k]=llmin(stree[k*2+1],stree[k*2+2]);
    lazy[k]=llinf;
}

//calc min[a,b)
//call:k=0,l=0,r=ssize
long long minquery(long long a,long long b,long long k,long long l,long long r){
    if(r<=a){return llinf;}
    if(b<=l){return llinf;}
    long long ld,rd,md;
    eval(k);
    if(a<=l && r<=b){
        return stree[k];
    }
    else{
        return llmin(
          minquery(a,b,k*2+1,l,(l+r)/2),
          minquery(a,b,k*2+2,(l+r)/2,r)
        );
    }
}

