    var i = 0
    while (i < N) {
        var j = i+1
        var ln = 0
        while (S[j+ln] == '1') {
            ln++
        }
        i = j+ln
        len = max(len, ln)
    }
    if (len >= M) {
        println(-1)
        return
    }

    var goal = false
    var ans = listOf<Int>()

    fun dfs(n: Int, res: List<Int>) {
        if (n <= M) {
            ans = if (n>0) listOf(n) + res else res
            goal = true
            return
        }
        for (i in M downTo 1) {
            if (goal) break
            if (S[n-i] == '1') continue
            dfs(n-i, listOf(i) + res)
        }
    }

    dfs(N, listOf())

    if (goal) println(ans.joinToString(" "))
    else println(-1)

    return
}


