fun solve() {
    val (N,M) = rd.readIntArray()
    val S = rd.readString()

    fun canGoal(ls: IntArray): Boolean {
        var x = 0
        for (dx in ls) {
            if (S[x+dx] == '1') return false
            x += dx
        }
        return true
    }

    var len = INF
    val lsts = ArrayList<List<Int>>()

    fun dfs(n: Int, res: List<Int>) {
        if (res.size > len-1) return

        if (n>=N-M) {
            val ls = res + listOf(N-n)
            len = min(len, res.size+1)

            if (canGoal(ls.toIntArray())) {
                lsts.add(ls)
            }
            return
        }
        for (i in M downTo 1) {
            if (S[n+i] == '1') continue
            dfs(n+i, res + listOf(i))
        }
    }

    dfs(0, listOf())

    if (lsts.size == 0) {
        println(-1)
        return
    }

    val lss = lsts.filter{ it.size == len }

    var ans = lss[0]
    for (i in 1 until lss.size) {
        if (ans.joinToString("") > lsts[i].joinToString()) {
            ans = lsts[i]
        }
    }

    println(ans.joinToString(" "))
}


