fun solve() {
    val (n, m) = nextIntList()
    val s = next()
    var ng = StringBuilder("")
    repeat(m){
        ng.append("1")
    }
    if(s.contains(ng)){
        println(-1)
        return
    }

    var now = n
    val ans:Deque<Int> = ArrayDeque()
    while(now > 0){

        if(now <= m){
            ans.push(now)
            break
        }
        for(step in m downTo 1){
            if(now - step < 0) continue
            if(s[now - step] == '0'){
                ans.push(step)
                now -= step
                break
            }
        }
    }

    while (ans.isNotEmpty()){
        print("${ans.pop()} ")
    }
    println()
}


