fun solve() {
    val (N,M) = rd.readIntArray()
    val S = rd.readString()

    var len = 0
    var i = 0
    while (i < N) {
        var j = i+1
        var ln = 0
        while (S[j+ln] == '1') {
            ln++
        }
        i = j+ln
        len = max(len, ln)
    }
    if (len >= M) {
        println(-1)
        return
    }

    var goal = false
    val ans = ArrayList<Int>()
    var n = N
    while (true) {
        if (n <= M) {
            if (n>0) ans.add(n)
            goal = true
        }

        if (goal) break

        for (i in M downTo 1) {
            if (S[n-i] == '1') continue
            n -= i
            ans.add(i)
            break
        }
    }

    if (goal) println(ans.reversed().joinToString(" "))
    else println(-1)

    return
}


