fun solve(N: Int, M: Int, S: String){
    val dp = IntArray(N + 1){ -1 }    // startからゴールまで辿り着く最短ステップ数
    dp[N] = 0
    for(i in N - 1 downTo 0){
        if(S[i] == '1') continue
        val mstep = (1..M).asSequence()
            .filter{ i + it <= N }
            .map{ dp[i + it] }
            .filter{ it >= 0 }
            .min()
            ?.let{ dp[i] = it + 1 }
    }
    if(dp[0] == -1) println(-1)
    else{
        val ans = mutableListOf<Int>()
        val indices =  mutableListOf<Int>()
        indices.add(0)
        var ret = dp[0]
        for (i in 1..N){
            if(dp[i] == ret - 1){
                ans.add(i - indices.last())
                indices.add(i)
                ret--
            }
        }
        println(ans.joinToString(separator=" "))
    }
    // println(dp.toList())
    return
}

fun <T, R> Iterable<T>.scanLeft(initial: R, operation: (acc: R, T) -> R): Sequence<R> {
    var last = initial
    return this.asSequence().map { last = operation(last, it); last }
}

