    // dp[i] = min(dp[i+1..i+M]) + 1
    val sqrt = Math.sqrt(N.toDouble()).toInt() + 1
    val dp = Array(sqrt * sqrt) { MinMonoid.empty() }
    dp[N] = 0
    val minQuery = SqrtDecomposition(dp, MinMonoid)
    for (i in N - 1 downTo 0) {
        if (S[i] == '1') continue
        val mstep = minQuery.query(i + 1, Math.min(i + M + 1, N + 1))
        if (mstep == MinMonoid.empty()) { println(-1); return }
        minQuery.update(i, mstep + 1)
    }

    val ans = mutableListOf<Int>()
    var lastIndex = 0
    var step = minQuery.get(0)
    for (i in 1..N) {
        if (minQuery.get(i) == step - 1) {
            ans.add(i - lastIndex)
            lastIndex = i
            step--
        }
    }
    println(ans.joinToString(separator = " "))
    // println(minQuery.array.toList())
    return
}

