fun permutation(A: IntArray): List<IntArray> {
    val ary = A.sorted()
    val N = ary.size
    val used = BooleanArray(N){false}
    val hm = HashMap<IntBuffer, IntArray>()
    val ptn = ArrayList<Int>(0)
    fun dfs(n: Int) {
        if (n >= N) {
            val value = ptn.toIntArray()
            val key = IntBuffer.wrap(value)
            hm[key] = value
        }
