import java.util.Arrays;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    final long INF = 1_000_000_000;
    int N = scanner.nextInt();
    int M = scanner.nextInt();
    char[] s = scanner.next().toCharArray();

    long[] dp = new long[N + 1];
    Arrays.fill(dp, INF);
    dp[N] = 0;
    for (int i = N - 1; i >= 0; i--)
      if (s[i] == '0')
        for (int j = i + 1; j <= i + M && j <= N; j++) dp[i] = Math.min(dp[i], dp[j] + 1);
    if (dp[0] == INF) {
      System.out.println(-1);
    } else {
      StringBuilder sb = new StringBuilder();
      int next = 0;
      while (next < N) {
        for (int i = next + 1; i <= next + M && i <= N; i++) {
          if (dp[i] == dp[next] - 1) {
            sb.append(i - next).append(' ');
            next = i;
            break;
          }
        }
      }
      sb.setLength(sb.length() - 1);
      System.out.println(sb.toString());
    }
  }
}

import java.util.*;


class Node{
	int id, cost, to, bad;

	public Node(int id, int cost, int to, int bad) {
		super();
		this.id = id;
		this.cost = cost;
		this.to = to;
		this.bad = bad;
	}

}

public class Main {
	public static void main(String[] args)  {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt(), m = sc.nextInt();
		String s = sc.next();
		sc.close();

		Node dp[] = new Node[n+1];
		int INF = Integer.MAX_VALUE/2;
		for(int i=0;i<n+1;i++) {
			int bad = s.charAt(i) - '0'; 
			dp[i] = new Node(i, INF,-1, bad);
		}
		dp[n].cost = 0;

		Queue<Node> q = new PriorityQueue<>((p1,p2)->{
			if(p1.cost!=p2.cost) return p1.cost - p2.cost;
			return p1.id - p2.id;
		});


		q.offer(dp[n]);

		for(int i=n-1;i>=0;i--) {
			while(!q.isEmpty()&&(q.peek().bad == 1 || q.peek().id - i > m)) {
				q.poll();
			};
			if(q.isEmpty()) {
				System.out.println(-1);
				return;
			}
			if(dp[i].bad==1)continue;
			dp[i].cost = q.peek().cost+1;
			dp[i].to = q.peek().id;
			q.offer(dp[i]);
		}

		StringBuilder sb = new StringBuilder();
		int now = 0;
		while(dp[now].to != -1) {
			int to = dp[now].to;
			int dist = to - now;
			sb.append(dist + " ");
			now = to;
		}
		System.out.println(sb.toString());
	}
}

