class Task {

    private static int mod = 1000000007;


    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        String s = in.next();
        List<Integer> ans = new ArrayList<>();
        int i, j;
        for (i = n; i > 0; i--) {
            for (j = Math.max(0, i - m); j < i; j++) {
                if (s.charAt(j) == '0') {
                    ans.add(i - j);
                    i = j + 1;
                    break;
                }
            }
            if (i == j) {
                break;
            }
        }
        if (i != 0) {
            out.println(-1);
        } else {
            for (i = ans.size() - 1; i >= 0; i--) {
                out.print(ans.get(i) + " ");
            }
            out.println();
        }

    }

}

