		/**
		 * データを更新します。
		 * @param index 更新する場所
		 * @param dat 更新するデータ
		 * @return 更新前の値
		 */
		@Override
		public T set(int index, T dat) {
			T ret = get(index);
			index |= super.size() >> 1;
			super.set(index, dat);
			for (int i = index >> 1; i > 0; i >>= 1) super.set(i, group.apply(super.get(i << 1), super.get(i << 1 | 1)));
			return ret;
		}

		/**
		 * データを更新します。<br>
		 * この操作により、indexの値は元の値にdatを演算した値となります。
		 * @param index 更新する場所
		 * @param dat 更新するデータ
		 */
		public void apply(int index, T dat) {
			set(index, group.apply(get(index), dat));
		}

		@Override
		public Object[] get() {
			Object[] ret = new Object[size];
			System.arraycopy(super.get(), super.size() >> 1, ret, 0, size);
			return ret;
		}

		public Object[] getLocal() {
			return super.get();
		}

		@Override
		public T[] get(T[] array) {
			if (array.length < size) {
				@SuppressWarnings("unchecked")
				T[] ret  = (T[])Arrays.copyOfRange(super.get(), super.size() >> 1, (super.size() >> 1) + size, array.getClass());
				array = ret;
			} else System.arraycopy(super.get(), super.size() >> 1, array, 0, size);
			return array;
		}

		/**
		 * 指定した範囲の合計を取得します。
		 * @param left 範囲の左区間
		 * @param right 範囲の右区間
		 * @return 半開区間[left, right)の合計
		 */
		public T get(int l, int r) {
			T L = group.identity(), R = group.identity();
			l += super.size() >> 1;
			r += super.size() >> 1;
			while (l < r) {
				if ((l & 1) != 0) L = group.apply(L, super.get(l++));
				if ((r & 1) != 0) R = group.apply(super.get(r ^ 1), R);
				l >>= 1;
				r >>= 1;
			}
			return group.apply(L, R);
		}

		/**
		 * 指定した範囲の合計を取得します。
		 * @param range 範囲
		 * @return 区間range内の合計
		 */
		public T get(IntRange range) {
			return get(range.getClosedLower(), range.getOpenUpper());
		}

		@Override
		public T get(int index) {
			return super.get(index | super.size() >> 1);
		}

		@Override
		public int size() {
			return size;
		}

		@Override
		public int length() {
			return size;
		}

		@Override
		public int binarySearch(int left, int right, Predicate<T> f) {
			if (left > right) return revBinarySearch(left - 1, right - 1, f);
			left += super.size() >> 1;
			right += super.size() >> 1;
			T last = group.identity(), next;
			int i = 0;
			while (left < right >>> i) {
				if ((left & 1) == 0) { // 上がある
					left >>>= 1;
					++ i;
				} else {
					if (f.test(next = group.apply(last, super.get(left)))) { // このleft全部を含むか
						last = next;
						++ left;
					} else right = (left + 1 << i) - 1; // 左辺を移動
				}
			}
			while (i > 0) { // 今度は降下しながら見ていく
				left <<= 1;
				-- i;
				if ((right >>> i & 1) != 0) {
					if (f.test(next = group.apply(last, super.get(left)))) {
						last = next;
						++ left;
					} else right = (left + 1 << i) - 1;
				}
			};
			return left - (super.size() >> 1) - 1;
		}

		private int revBinarySearch(int right, int left, Predicate<T> f) {
			left += super.size() >> 1;
			right += super.size() >> 1;
			T last = group.identity(), next;
			int i = 0;
			while (left >>> i < right) {
				if ((right & 1) == 0) { // 上がある
					if (f.test(next = group.apply(super.get(right), last))) { // このright全部を含むか
						last = next;
						-- right;
					} else left = right << i; // 左辺を移動
				} else {
					right >>>= 1;
					++ i;
				}
			}
			while (i > 0) { // 今度は降下しながら見ていく
				right = right << 1 | 1;
				-- i;
				if ((left >>> i & 1) == 0) {
					if (f.test(next = group.apply(super.get(right), last))) {
						last = next;
						-- right;
					} else left = right << i;
				}
			};
			return right - (super.size() >> 1) + 1;
		}

		/**
		 * 指定した値を除く場所の値を取得します。
		 * @param index 取得しない場所
		 * @return 全体からindexを取り除いた値
		 */
		public T getAvoid(int index) {
			return getAvoid(index, index + 1);
		}

		/**
		 * 指定した範囲を除く区間の合計を取得します。
		 * @param left 範囲の左区間
		 * @param right 範囲の右区間
		 * @return 半開区間[0, left)+[right, size)の合計
		 */
		public T getAvoid(int left, int right) {
			return group.apply(get(0, left), get(right, size));
		}

		/**
		 * 指定した範囲を除く区間の合計を取得します。
		 * @param range 区間
		 * @return 区間rangeを除く範囲の合計
		 */
		public T getAvoid(IntRange range) {
			return getAvoid(range.getClosedLower(), range.getOpenUpper());
		}

		private class Iter implements Iterator<T> {
			private int index;

			private Iter() {
				index = 0;
			}

			@Override
			public boolean hasNext() {
				return index < size;
			}

			@Override
			public T next() {
				return get(index++);
			}

			@Override
			public void remove() {
				set(index-1, group.identity());
			}
		}

		@Override
		public Iterator<T> iterator() {
			return new Iter();
		}
	}

	/**
	 * 高速な入出力を提供します。
	 * @author 31536000
	 *
	 */
	public static class FastIO {
		private InputStream in;
		private final byte[] buffer = new byte[1024];
		private int read = 0;
		private int length = 0;
		private PrintWriter out;
		private PrintWriter err;
		private boolean autoFlush = false;

		public FastIO() {
			this(System.in, System.out, System.err);
		}

		public FastIO(InputStream in, PrintStream out, PrintStream err) {
			this.in = in;
			this.out = new PrintWriter(out, false);
			this.err = new PrintWriter(err, false);
		}

		public final void setInputStream(InputStream in) {
			this.in = in;
		}

		public final void setInputStream(File in) {
			try {
				this.in = new FileInputStream(in);
			} catch (FileNotFoundException e) {
				e.printStackTrace();
			}
		}

		public final void setOutputStream(PrintStream out) {
			this.out = new PrintWriter(out, false);
		}

		public final void setOutputStream(File out) {
			try {
				this.out = new PrintWriter(new FileOutputStream(out), false);
			} catch (FileNotFoundException e) {
				e.printStackTrace();
			}
		}

		public final void setErrorStream(PrintStream err) {
			this.err = new PrintWriter(err, false);
		}

		public final void setErrorStream(File err) {
			try {
				this.err = new PrintWriter(new FileOutputStream(err), false);
			} catch (FileNotFoundException e) {
				e.printStackTrace();
			}
		}

		public final void setAutoFlush(boolean flush) {
			autoFlush = flush;
		}

		private boolean hasNextByte() {
			if (read < length) return true;
			read = 0;
			try {
				length = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			return length > 0;
		}

		private int readByte() {
			return hasNextByte() ? buffer[read++] : -1;
		}

		private static boolean isPrintableChar(int c) {
			return 33 <= c && c <= 126;
		}

		private static boolean isNumber(int c) {
			return '0' <= c && c <= '9';
		}

		public final boolean hasNext() {
			while (hasNextByte() && !isPrintableChar(buffer[read])) read++;
			return hasNextByte();
		}

		public final char nextChar() {
			if (!hasNextByte())  throw new NoSuchElementException();
			return (char)readByte();
		}

		public final char[][] nextChar(int height) {
			char[][] ret = new char[height][];
			for (int i = 0;i < ret.length;++ i) ret[i] = next().toCharArray();
			return ret;
		}

		public final String next() {
			if (!hasNext()) throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b;
			while (isPrintableChar(b = readByte())) sb.appendCodePoint(b);
			return sb.toString();
		}

		public final String nextLine() {
			StringBuilder sb = new StringBuilder();
			int b;
			while(!isPrintableChar(b = readByte()));
			do sb.appendCodePoint(b); while(isPrintableChar(b = readByte()) || b == ' ');
			return sb.toString();
		}

		public final long nextLong() {
			if (!hasNext()) throw new NoSuchElementException();
			long n = 0;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			if (!isNumber(b)) throw new NumberFormatException();
			while (true) {
				if (isNumber(b)) {
					n *= 10;
					n += b - '0';
				} else if (b == -1 || !isPrintableChar(b)) return minus ? -n : n;
				else throw new NumberFormatException();
				b = readByte();
			}
		}

		public final int nextInt() {
			long nl = nextLong();
			if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
			return (int) nl;
		}

		public final double nextDouble() {
			return Double.parseDouble(next());
		}

		public final int[] nextInt(int width) {
			int[] ret = new int[width];
			for (int i = 0;i < width;++ i) ret[i] = nextInt();
			return ret;
		}

		public final int[] nextInts() {
			return nextInts(" ");
		}

		public final int[] nextInts(String parse) {
			String[] get = nextLine().split(parse);
			int[] ret = new int[get.length];
			for (int i = 0;i < ret.length;++ i) ret[i] = Integer.valueOf(get[i]);
			return ret;
		}

		public final long[] nextLong(int width) {
			long[] ret = new long[width];
			for (int i = 0;i < width;++ i) ret[i] = nextLong();
			return ret;
		}

		public final long[] nextLongs() {
			return nextLongs(" ");
		}

		public final long[] nextLongs(String parse) {
			String[] get = nextLine().split(parse);
			long[] ret = new long[get.length];
			for (int i = 0;i < ret.length;++ i) ret[i] = Long.valueOf(get[i]);
			return ret;
		}

		public final int[][] nextInt(int width, int height) {
			int[][] ret = new int[height][width];
			for (int i = 0, j;i < height;++ i) for (j = 0;j < width;++ j) ret[i][j] = nextInt();
			return ret;
		}

		public final long[][] nextLong(int width, int height) {
			long[][] ret = new long[height][width];
			for (int i = 0, j;i < height;++ i) for (j = 0;j < width;++ j) ret[j][i] = nextLong();
			return ret;
		}

		public final boolean[] nextBoolean(char T) {
			char[] s = next().toCharArray();
			boolean[] ret = new boolean[s.length];
			for (int i = 0;i < ret.length;++ i) ret[i] = s[i] == T;
			return ret;
		}

		public final boolean[][] nextBoolean(char T, int height) {
			boolean[][] ret = new boolean[height][];
			for (int i = 0;i < ret.length;++ i) {
				char[] s = next().toCharArray();
				ret[i] = new boolean[s.length];
				for (int j = 0;j < ret[i].length;++ j) ret[i][j] = s[j] == T;
			}
			return ret;
		}

		public final Point nextPoint() {
			return new Point(nextInt(), nextInt());
		}

		public final Point[] nextPoint(int width) {
			Point[] ret = new Point[width];
			for (int i = 0;i < width;++ i) ret[i] = nextPoint();
			return ret;
		}

		@Override
		protected void finalize() throws Throwable {
			try {
				super.finalize();
			} finally {
				in.close();
				out.close();
				err.close();
			}
		}

