public class Main implements Runnable{

	private class Min implements Comparable<Min>{
		int dist, last, now;

		public Min(int d, int l, int n) {
			dist = d;
			last = l;
			now = n;
		}
		@Override
		public int compareTo(Min o) {
			if (dist != o.dist) return Integer.compare(dist, o.dist);
			return Integer.compare(now, o.now);
		}
		@Override
		public String toString() {
			return last + "-(" + dist + ")->" + now;
		}
	}

	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * ABC146 F問題
		 * 考察メモ
		 * dp[i]は第i番目まで来る時、何手か(+何処から来たか)
		 * ……ただの復元DPでは><
		 * 区間minが欲しいのでスライド最小値を貼る
		 *
		 */
		int N = io.nextInt(), M = io.nextInt();
		char[] S = io.next().toCharArray();
		Min[] dp = new Min[N + 1];
		for (int i = 0;i < dp.length;++ i) dp[i] = new Min(0, 0, 0);
		SlidingWindowAggregation<Min> swag = new SlidingWindowAggregation<Min>(new Minimum<Min>());
		swag.addLast(dp[0]);
		final int INF = Integer.MAX_VALUE >> 1;
		for (int i = 1;i <= N;++ i) {
			Min get = swag.foldAll();
			if (S[i] == '1') get = new Min(INF, INF, i);
			else get = new Min(get.dist + 1, get.now, i);
			swag.addLast(dp[i] = get);
			if (swag.size() > M) swag.pollFirst();
		}
		if (dp[N].dist >= INF) {
			io.println(-1);
			return;
		}
		int[] ans = new int[dp[N].dist];
		for (int i = 0, l = N;i < ans.length;++ i) {
			Min get = dp[l];
			ans[ans.length - i - 1] = get.now - get.last;
			l = get.last;
		}
		io.println(ans);
	}

