			for (int r = 0; r < s; r++ ) {
				if (cur == n - 1) return true;
				cur = (cur * cur) % n;
			}
			return false;
		}

		/**
		 * 与えられた値が素数か否かを判定します。<br>
		 * この実装はhttp://ceur-ws.org/Vol-1326/020-Forisek.pdfに基づきます。
		 * @param x 判定したい値
		 * @return xが素数ならtrue
		 */
		public static boolean isPrime(int x) {
			if (x == 2 || x == 3 || x == 5 || x == 7) return true;
			if ((x & 1) == 0 || x % 3 == 0 || x % 5 == 0 || x % 7 == 0) return false;
			if (x < 121) return x > 1;
			long h = x;
			h = ((h >> 16) ^ h) * 0x45d9f3b;
			h = ((h >> 16) ^ h) * 0x45d9f3b;
			h = ((h >> 16) ^ h) & 0xFF;
			return isSPRP(x, bases[(int)h]);
		}

		@Override
		public int intValue() {
			return prime;
		}

		@Override
		public long longValue() {
			return prime;
		}

		@Override
		public float floatValue() {
			return prime;
		}

		@Override
		public double doubleValue() {
			return prime;
		}

		@Override
		public String toString() {
			return String.valueOf(prime);
		}
	}

	public static class AbstractArray<T> extends AbstractList<T> implements RandomAccess{

		private final Object[] array;

		public AbstractArray(int size) {
			array = new Object[size];
		}

		public AbstractArray(T[] array) {
			this(array.length);
			System.arraycopy(array, 0, this.array, 0, array.length);
		}

		@Override
		public T set(int index, T element) {
			T ret = get(index);
			array[index] = element;
			return ret;
		}

		@Override
		public T get(int index) {
			@SuppressWarnings("unchecked")
			T ret = (T)array[index];
			return ret;
		}

		public Object[] get() {
			return array;
		}

		public T[] get(T[] array) {
			if (array.length < this.array.length) {
				@SuppressWarnings("unchecked")
				T[] ret  = (T[])Arrays.copyOfRange(this.array, 0, this.array.length, array.getClass());
				return ret;
			}
			System.arraycopy(this.array, 0, array, 0, this.array.length);
			return array;
		}

		@Override
		public int size() {
			return array.length;
		}

		public int length() {
			return size();
		}

		@Override
		public int hashCode() {
			return Arrays.hashCode(array);
		}

		private class Iter implements Iterator<T> {
			private int index;

			private Iter() {
				index = 0;
			}

			@Override
			public boolean hasNext() {
				return index < array.length;
			}

			@Override
			public T next() {
				return get(index++);
			}

			@Override
			public void remove() {
				throw new UnsupportedOperationException();
			}
		}

		@Override
		public Iterator<T> iterator() {
			return new Iter();
		}
	}

	public static class Array<T> extends AbstractArray<T> implements Serializable{

		private static final long serialVersionUID = 2749604433067098063L;

		public Array(int size) {
			super(size);
		}

		public Array(T[] array) {
			super(array);
		}

		public T front() {
			return get(0);
		}

		public T back() {
			return get(size() - 1);
		}
	}
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(in.readLine());
        int n = Integer.parseInt(st.nextToken()) + 1;
        int m = Integer.parseInt(st.nextToken());
        boolean[] bad = new boolean[n];
        int half = n/2 + 5;
        String string = in.readLine();
        for (int i = 0; i < n; i++) {
            if (string.charAt(i) == '1') {
                bad[i] = true;
            }
        }
        Queue<Integer> leftQ = new LinkedList<>();
        Queue<Integer> rightQ = new LinkedList<>();
        int[] leftDist = new int[n];
        int[] rightDist = new int[n];
        Arrays.fill(leftDist, (int)1e9);
        Arrays.fill(rightDist, (int)1e9);
        leftDist[0] = 0;
        rightDist[n-1] = 0;
        leftQ.offer(0);
        rightQ.offer(n-1);
        int[] parLeft = new int[n];
        int[] parRight = new int[n];
        parRight[n-1] = n-1;
        while (!leftQ.isEmpty() || !rightQ.isEmpty()) {
            if (!leftQ.isEmpty()) {
                int node = leftQ.poll();
                for (int i = node+1; i <= node+m; i++) {
                    if (i >= n) {
                        break;
                    }
                    if (bad[i]) {
                        continue;
                    }
                    if (leftDist[i] == (int)1e9) {
                        leftDist[i] = leftDist[node] + 1;
                        if (leftDist[i] <= half) {
                            leftQ.offer(i);
                            parLeft[i] = node;
                        }
                    } else {
                        if (leftDist[i] == leftDist[node] + 1) {
                            parLeft[i] = Math.min(parLeft[i], node);
                        }
                    }
                }
            }
            if (!rightQ.isEmpty()) {
                int node = rightQ.poll();
                for (int i = node-1; i >= node-m; i--) {
                    if (i < 0) {
                        break;
                    }
                    if (bad[i]) {
                        continue;
                    }
                    if (rightDist[i] == (int)1e9) {
                        rightDist[i] = rightDist[node] + 1;
                        if (rightDist[i] <= half) {
                            rightQ.offer(i);
                            parRight[i] = node;
                        }
                    } else {
                        if (rightDist[i] == rightDist[node] + 1) {
                            parRight[i] = Math.min(parRight[i], node);
                        }
                    }
                }
            }
        }

        int res = (int)1e9;

        for (int i = 0; i < n; i++) {
            int sum = leftDist[i] + rightDist[i];
            if (sum < res) {
                res = sum;
            }
        }

        if (res == (int)1e9) {
            System.out.println("-1");
            return;
        }

        int[] output = new int[res];
        Arrays.fill(output, (int)1e9);

        outer: for (int mid = 0; mid < n; mid++) {
            if (leftDist[mid] + rightDist[mid] == res) {
                int[] a = new int[res];
                Stack<Integer> stack = new Stack<>();
                for (int i = mid; i != 0; i = parLeft[i]) {
                    stack.push(i - parLeft[i]);
                }
                Queue<Integer> queue = new LinkedList<>();
                for (int i = mid; i != n - 1; i = parRight[i]) {
                    queue.offer(parRight[i] - i);
                }
                int count = 0;
                for (int i : stack) {
                    a[count] = i;
                    count++;
                }
                for (int i : queue) {
                    a[count] = i;
                    count++;
                }

                for (int i = 0; i < res; i++) {
                    if (output[i] < a[i]) {
                        continue outer;
                    }
                    if (a[i] < output[i]) {
                        output = a;
                        break;
                    }
                }
            }
        }
        for (int i = 0; i < res; i++) {
            if (i > 0) {
                System.out.print(' ');
            }
            System.out.print(output[i]);
        }
        System.out.print('\n');
    }


}
