		while(q.size() > 0) {
			boolean first = true;
			int x = q.poll();
			for(int i = M; i >= 1; i--) {
				if(x-i <= 0) {
					d[0] = d[x] + 1;
					break;
				}
				if(d[x-i] == -1 && s[x-i] == '0') {
					d[x-i] = d[x] + 1;
					if(first) {
						q.add(x-i);
						first= false;
					}
				}
			}
		}
		if(d[0] == -1) {
			System.out.println(-1);
			return;
		}
		int now = 0, prev = d[0];
		while(true) {
			for(int i = 1; i <= M; i++) {
				if(now+i == N) {
					System.out.println(ans.append(i));
					return;
				}
				if(d[now+i] != -1 && d[now+i] != prev) {
					ans.append(i + " ");
					prev = d[now+i];
					now += i;
					break;
				}
			}
		}
	}

}

import java.io.*;
import java.util.*;

public class Main {

    static int N, M;
    static String S;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        S = sc.next();

        ArrayDeque<Integer> ans = solve();
        if( ans != null ) {
            StringJoiner j = new StringJoiner(" ");
            for (Integer i : ans) {
                j.add(i.toString());
            }
            System.out.println( j.toString() );
        } else {
            System.out.println(-1);
        }
    }

    static ArrayDeque<Integer> solve() {
        // ゴールから考える
        // 1. 出目が連続しているので弱い選択肢を取る意味がなくできるだけ遠くまで進む(戻る？)
        // 2. (3, 4) (4, 3)みたいなケースを考えると(3, 4)のほうが辞書順的に強く、これは1の貪欲を妨げないのでいけそうな気がしてくる
        // あとは現在地からMマス以内の安地で最左がわかるとうれしい
        // とりあえず木に入れておけばできるのでそうする
        TreeSet<Integer> safe = new TreeSet<>();
        for (int i = 0; i < N+1; i++) {
            if( S.charAt(i) == '0' ) {
                safe.add(i);
            }
        }
        ArrayDeque<Integer> ans = new ArrayDeque<>();
        int curr = N;
        while(curr > 0) {
            Integer next = safe.ceiling(Math.max(0, curr-M));
            if( next == null || next == curr ) return null;

            int move = curr - next;
            ans.addFirst(move);
            curr = next;
        }
        return ans;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = nextLong();
            return a;
        }
    }

