	private static List<Integer> dfs(int x, List<Integer> a) {
		if (visited[x]) return null;
		visited[x] = true;
		if (x == 0) return a;

		if (g[x].isEmpty()) return null;

		for (Integer i : g[x]) {
			a.add(x - i);
			List<Integer> b = dfs(i, a);
			if (b != null) return b;
			a.remove(a.size() - 1);
		}

		return null;
	}
