		int N = io.nextInt(), M = io.nextInt();
		char[] S = io.next().toCharArray();
		Min[] dp = new Min[N + 1];
		for (int i = 0;i < dp.length;++ i) dp[i] = new Min(0, 0, 0);
		SegmentTree<Min> segment = SegmentTree.create(dp, new Minimum<Min>());
		final int INF = Integer.MAX_VALUE >> 1;
		for (int i = 1;i <= N;++ i) {
			Min get = segment.get(Math.max(0, i - M), i);
			if (S[i] == '1') get = new Min(INF, INF, i);
			else get = new Min(get.dist + 1, get.now, i);
			segment.set(i, get);
		}
		if (segment.get(N).dist >= INF) {
			io.println(-1);
			return;
		}
		int[] ans = new int[segment.get(N).dist];
		for (int i = 0, l = N;i < ans.length;++ i) {
			Min get = segment.get(l);
			ans[ans.length - i - 1] = get.now - get.last;
			l = get.last;
		}
		io.println(ans);
	}

