public class Main {
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int m = sc.nextInt();
		char[] arr = sc.next().toCharArray();
		ArrayDeque<Integer> deq = new ArrayDeque<>();
		int idx = n;
		while (idx > 0) {
		    int next = Math.max(idx - m, 0);
		    while (arr[next] == '1' && next < idx) {
		        next++;
		    }
		    if (next == idx) {
		        System.out.println(-1);
		        return;
		    }
		    deq.push(idx - next);
		    idx = next;
		}
		boolean flag = false;
		StringBuilder sb = new StringBuilder();
		while (deq.size() > 0) {
		    if (flag) {
		        sb.append(" ");
		    }
		    sb.append(deq.pop());
		    flag = true;
		}
		System.out.println(sb);
	}
}

import java.util.*;
public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int M = sc.nextInt();
		char[] s = sc.next().toCharArray();
		List<Integer> ans_rev = new ArrayList<>();
		boolean ok = false;
		boolean[] used = new boolean[N+1];
		Queue<Integer> q = new ArrayDeque<>();
		q.add(N);
		while(q.size() > 0) {
			boolean first = true;
			int x = q.poll();
			for(int i = M; i >= 1; i--) {
				if(x-i <= 0) {
					ans_rev.add(M+x-i);
					ok = true;
					break;
				}
				if(!used[x-i] && s[x-i] == '0') {
					if(first) {
						ans_rev.add(i);
						q.add(x-i);
						first= false;
					}
				}
			}
		}
		if(!ok) {
			System.out.println(-1);
			return;
		}
		for(int i = ans_rev.size()-1; i >= 0; i--)
			System.out.print(ans_rev.get(i) + " ");
	}

}

import java.util.*;
public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int M = sc.nextInt();
		char[] s = sc.next().toCharArray();
		int[] d = new int[N+1];
		Arrays.fill(d, -1);
		d[N] = 0;
		Queue<Integer> q = new ArrayDeque<>();
		q.add(N);
		while(q.size() > 0) {
			int x = q.poll();
			for(int i = 1; i <= M && x-i >= 0; i++) {
				if(d[x-i] == -1 && s[x-i] == '0') {
					q.add(x-i);
					d[x-i] = d[x] + 1;
				}
			}
		}
		if(d[0] == -1) {
			System.out.println(-1);
			return;
		}
		int now = 0, prev = d[0];
		while(true) {
			for(int i = 1; i <= M; i++) {
				if(now+i == N) {
					System.out.println(i);
					return;
				}
				if(d[now+i] != -1 && d[now+i] != prev) {
					System.out.print(i + " ");
					prev = d[now+i];
					now += i;
					break;
				}
			}
		}
	}

}

