import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {
    public static void main(final String[] args) {
        final Scanner scanner = new Scanner(System.in);
        final int n = scanner.nextInt();
        final int m = scanner.nextInt();
        if (m >= n) {
            System.out.println(n);
            return;
        }

        final String s = scanner.next();
        final List<Boolean> list = IntStream.range(1, n)
                .mapToObj(i -> s.charAt(i) == '0')
                .collect(Collectors.toList());

        int falseConstraint = 0;
        for (final boolean bool : list) {
            if (bool) {
                falseConstraint = 0;
                continue;
            }


            falseConstraint++;
            if (falseConstraint >= m) {
                System.out.println(-1);
                return;
            }
        }

        Collections.reverse(list);
        int constraint = 0;
        int last = 0;
        final List<Integer> answer = new ArrayList<>();
        for (int i = 0; i < list.size(); i++) {
            final boolean bool = list.get(i);
            constraint++;
            if (constraint == m) {
                if (bool) {
                    answer.add(constraint);
                    last = i;
                    constraint = 0;
                } else {
                    answer.add(constraint - (i - last));
                    constraint = i - last;
                }
                continue;
            }
            if (bool) {
                last = i;
            }
        }
        answer.add(list.size() - last);
        Collections.reverse(answer);

        final String sAnswer = answer.stream()
                .map(i -> Integer.toString(i))
                .collect(Collectors.joining(" "));
        System.out.println(sAnswer);
    }
}

