import java.util.*;
import java.io.*;

public class Main {


    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int n = sc.nextInt()+1;
        int m = sc.nextInt();
        int N = 1;
        while (N < n) N <<= 1; //padding
        int[]in = new int[N+1];
        char[] s = sc.nextLine().toCharArray();
        SegmentTree sg = new SegmentTree(in);
        for (int i=0;i<n;i++){
            if (s[i]=='1')
                sg.update_point(i+1,2*N);
        }
        sg.update_point(1,0);
        int[]parent=new int[n+1];
        parent[0]=0;
        for (int i =1;i<n;i++){
            if (s[i]=='1')continue;
            Pair x = sg.query(Math.max((i+1)-m,0),i+1);
            parent[i]=x.idx-1;
            sg.update_point(i+1,x.val+1);
        }
        int ans =sg.query(n,n).val;
        if (ans>n+1){
            out.println(-1);
        }
        else {
            ArrayList<Integer>sol = new ArrayList<>();
            int lst =n-1;
            while (parent[lst]!=lst){
                sol.add(lst-parent[lst]);
                lst=parent[lst];
            }
            Collections.reverse(sol);
            for (int x:sol)out.print(x+" ");
        }

        out.flush();
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(FileReader r) {
            br = new BufferedReader(r);
        }

        public Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public double nextDouble() throws IOException {
            String x = next();
            StringBuilder sb = new StringBuilder("0");
            double res = 0, f = 1;
            boolean dec = false, neg = false;
            int start = 0;
            if (x.charAt(0) == '-') {
                neg = true;
                start++;
            }
            for (int i = start; i < x.length(); i++)
                if (x.charAt(i) == '.') {
                    res = Long.parseLong(sb.toString());
                    sb = new StringBuilder("0");
                    dec = true;
                } else {
                    sb.append(x.charAt(i));
                    if (dec)
                        f *= 10;
                }
            res += Long.parseLong(sb.toString()) / f;
            return res * (neg ? -1 : 1);
        }

        public boolean ready() throws IOException {
            return br.ready();
        }
    }

    static class Pair {
        int idx, val;

        Pair(int a, int b) {
            val = a;
            idx = b;
        }
    }

    static class SegmentTree {        // 1-based DS, OOP

        int N;            //the number of elements in the array as a power of 2 (i.e. after padding)
        int[] lazy;
        Pair[] sTree;

        SegmentTree(int[] in) {
            N = in.length - 1;
            sTree = new Pair[N << 1];//no. of nodes = 2*N - 1, we add one to cross out index zero
            lazy = new int[N << 1];
            for (int i =0;i<sTree.length;i++){
                sTree[i]=new Pair(1000000000,i);
            }
            build(1, 1, N);
        }

        void build(int node, int b, int e)    // O(n)
        {
            if (b == e)
                sTree[node] = new Pair(2*N, e);
            else {
                int mid = b + e >> 1;
                build(node << 1, b, mid);
                build(node << 1 | 1, mid + 1, e);
                if (sTree[node << 1].val <= sTree[node << 1 | 1].val)
                    sTree[node] = new Pair(sTree[node << 1].val, sTree[node << 1].idx);
                else {
                    sTree[node] = new Pair(sTree[node << 1 | 1].val, sTree[node << 1 | 1].idx);
                }
            }
        }


        void update_point(int index, int val)            // O(log n)
        {
            index += N - 1;
            sTree[index].val = val;
            while (index > 1) {
                index >>= 1;
                if (sTree[index << 1].val <= sTree[index << 1 | 1].val)
                    sTree[index] = new Pair(sTree[index << 1].val, sTree[index << 1].idx);
                else {
                    sTree[index] = new Pair(sTree[index << 1 | 1].val, sTree[index << 1 | 1].idx);
                }
            }
        }



        Pair query(int i, int j) {
            return query(1, 1, N, i, j);
        }

        Pair query(int node, int b, int e, int i, int j)    // O(log n)
        {
            if (i > e || j < b)
                return null;
            if (b >= i && e <= j)
                return sTree[node];
            int mid = b + e >> 1;
            Pair q1 = query(node << 1, b, mid, i, j);
            Pair q2 = query(node << 1 | 1, mid + 1, e, i, j);
            if (q1==null)return q2;
            if (q2==null)return q1;
            if (q1.val<=q2.val)
            return q1;
            return q2;
        }
    }

}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;
import java.util.function.BinaryOperator;

public class Main {

	static PrintWriter out;
	static InputReader ir;

	static void solve() {
		int n = ir.nextInt();
		int m = ir.nextInt();
		char[] s = ir.next().toCharArray();
		BinaryOperator<Long> f = (A, B) -> Math.min(A, B);
		SegmentTree dp = new SegmentTree(n + 1, f, 1L << 60);
		for (int i = 0; i < n + 1; i++) {
			if (s[i] == '1')
				dp.update(i, 1L << 60);
		}
		dp.update(n, 0);
		for (int i = n - 1; i >= 0; i--) {
			if (s[i] == '1')
				continue;
			long x = dp.query(i + 1, Math.min(i + m, n) + 1) + 1;
			dp.update(i, x);
		}
		long[] d = dp.data();
		// tr(d);
		if (d[0] >= 1L << 60) {
			out.println(-1);
			return;
		}
		int cur = 0;
		while (true) {
			for (int i = cur + 1; i <= Math.min(n, cur + m); i++) {
				if (d[cur] == d[i] + 1) {
					out.print(i - cur + " ");
					cur = i;
					break;
				}
			}
			if (cur == n)
				break;
		}
	}

	static class SegmentTree {

		BinaryOperator<Long> f;
		int n;
		long[] seg;
		long e;

		public SegmentTree(int nn, BinaryOperator<Long> f, long e) {
			this.f = f;
			this.e = e;
			n = 1;
			while (n < nn)
				n <<= 1;
			seg = new long[n * 2 - 1];
			Arrays.fill(seg, e);
		}

		public SegmentTree(long[] a, BinaryOperator<Long> f, long e) {
			this.f = f;
			this.e = e;
			n = 1;
			while (n < a.length)
				n <<= 1;
			seg = new long[n * 2 - 1];
			Arrays.fill(seg, e);
			for (int i = 0; i < a.length; i++)
				seg[i + n - 1] = a[i];
			for (int i = n - 2; i >= 0; i--)
				seg[i] = f.apply(seg[i * 2 + 1], seg[i * 2 + 2]);
		}

		public long query(int l, int r) {
			return query(l, r, 0, 0, n);
		}

		private long query(int a, int b, int k, int l, int r) {
			if (a <= l && r <= b)
				return seg[k];
			if (r <= a || b <= l)
				return e;
			long vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
			long vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
			return f.apply(vl, vr);
		}

		void update(int i, long x) {
			i += n - 1;
			seg[i] = x;
			while (i > 0) {
				i = (i - 1) / 2;
				seg[i] = f.apply(seg[i * 2 + 1], seg[i * 2 + 2]);
			}
		}

		long[] data() {
			long[] res = new long[n];
			for (int i = 0; i < n; i++) {
				res[i] = seg[n - 1 + i];
			}
			return res;
		}
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
	}

	static class InputReader {

		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}

	static void tr(Object... o) {
		out.println(Arrays.deepToString(o));
		out.flush();
	}
}

