import java.util.Scanner;

public class Main {
  private static final int INF = 1_000_000_000;
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    int M = scanner.nextInt();
    char[] s = scanner.next().toCharArray();

    SegmentTree tree = new SegmentTree(N + 1);
    int[] next = new int[N + 1];
    tree.update(N, 0);
    for (int i = N - 1; i >= 0; i--) {
      if (s[i] == '0') {
        Cell min = tree.query(i + 1, i + 1 + M);
        tree.update(i, min.value + 1);
        next[i] = min.pos;
      }
    }
    if (tree.query(0, 1).value == INF) {
      System.out.println(-1);
    } else {
      StringBuilder sb = new StringBuilder();
      int p = 0;
      while (p < N) {
        int q = next[p];
        sb.append(q - p).append(' ');
        p = q;
      }
      sb.setLength(sb.length() - 1);
      System.out.println(sb.toString());
    }
  }

  private static class SegmentTree {
    private int n;
    private final Cell[] dat;

    private SegmentTree(int tmpn) {
      n = 1;
      while (n < tmpn) {
        n <<= 1;
      }
      dat = new Cell[n * 2 - 1];
      for (int i = 0; i < n * 2 - 1; i++) dat[i] = new Cell(-1, INF);
    }

    public Cell query(int left, int right) {
      return query(left, right, 0, 0, n);
    }

    private Cell query(int a, int b, int k, int l, int r) {
      if (r <= a || b <= l) return new Cell(-1, INF);
      if (a <= l && r <= b) return dat[k];
      Cell vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
      Cell vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
      if (vr.value < vl.value) return vr;
      return vl;
    }

    public void update(int k, int value) {
      int l = k + n - 1; // the number of non-leaf nodes is 2 * n - 1 - n = n - 1
      dat[l].pos = k;
      dat[l].value = value;
      while (l > 0) {
        l = (l - 1) / 2;
        Cell min = dat[l * 2 + 2].value < dat[l * 2 + 1].value ? dat[l * 2 + 2] : dat[l * 2 + 1];
        dat[l].pos = min.pos;
        dat[l].value = min.value;
      }
    }
  }

  private static class Cell {
    private int pos;
    private int value;

    private Cell(int pos, int value) {
      this.pos = pos;
      this.value = value;
    }
  }
}

import java.util.*;
import java.math.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        final int INF = 2_000_000 + 228;

        int n = in.nextInt();
        int m = in.nextInt();
        String s = in.next();

        int[] dp = new int[n + 1];
        int[] step = new int[n + 1];

        dp[0] = (s.charAt(0) == '1' ? INF : 0);
        for (int i = 1; i <= n; ++i) {
            dp[i] = INF;
            for (int j = Math.min(m, i); j >= 1 ; --j) {
                if (dp[i - j] < dp[i]) {
                    dp[i] = dp[i - j];
                    step[i] = j;
                }
            }
            dp[i]++;
            if (s.charAt(i) == '1') {
                dp[i] = INF;
            }
            //out.println(dp[i] + " " + step[i]);
        }
        if (dp[n] >= INF) {
            out.println(-1);
        } else {
            List<Integer> ans = new ArrayList<Integer>();
            for (int i = n; i > 0; i -= step[i]) {
                ans.add(step[i]);
            }
            Collections.reverse(ans);
            for (int i = 0; i < ans.size(); ++i) {
                out.print(ans.get(i) + " ");
            }
        }

        in.close();
        out.close();
    }
    static class Pair {
	  		public long first;
	  		public long second;

	  		public Pair() {
	  			this(0, 0);
	  		}

	  		public Pair(final long first, final long second) {
	  			this.first = first;
	  			this.second = second;
	  		}
	  	}
}

import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
	int N, M;
	char[] S;
	Deque<Integer> result;
	boolean enable = true;

	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);
		Main ins = new Main(in);
		ins.calc();
		ins.showResult();
	}

	Main(BufferedReader in) throws IOException {
		String[] tokens = in.readLine().split(" ");
		N = Integer.parseInt(tokens[0]);
		M = Integer.parseInt(tokens[1]);
		S = in.readLine().toCharArray();
		result = new ArrayDeque<>();
	}

	void calc() {
		search(N);
	}

	void search(int current) {
		// System.out.println(current);
		if (current == 0) {
			// 先頭についた
			return;
		}
		// Mが大きい順にsearchする
		for (int i = M; i >= 1; --i) {
			int index = current - i;
			if (index < 0) {
				continue;
			}
			if (S[index] == '0') {
				// 行ける
				result.addFirst(i);
				search(index);
				return;
			}
		}
		// 行けなかった
		enable = false;
	}

	void showResult() {
		if (!enable) {
			System.out.println("-1");
		} else {
			StringBuilder strBuilder = new StringBuilder();
			strBuilder.append(Integer.toString(result.pollFirst()));
			while (!result.isEmpty()) {
				strBuilder.append(" " + Integer.toString(result.pollFirst()));
			}
			System.out.println(strBuilder.toString());
		}
	}
}

