                continue;
            }
            f2(cur+i);
            if(dp[cur]==dp2[cur+i]+1){
                mi[cur] = Math.min(mi[cur],cur+i);
            }
            dp2[cur] = Math.min(dp2[cur], dp2[cur+i]+1);
        }
    }

    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

    public static void main(String[] args) throws Exception { new Main().run(); }

    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {
    public static void main(final String[] args) {
        final Scanner scanner = new Scanner(System.in);
        final int n = scanner.nextInt();
        final int m = scanner.nextInt();
        if (m >= n) {
            System.out.println(n);
            return;
        }

        final String s = scanner.next();
        final List<Boolean> list = IntStream.range(1, n)
                .mapToObj(i -> s.charAt(i) == '0')
                .collect(Collectors.toList());

        int falseConstraint = 0;
        for (final boolean bool : list) {
            if (bool) {
                falseConstraint = 0;
                continue;
            }

            falseConstraint++;
            if (falseConstraint == m) {
                System.out.println(-1);
                return;
            }
        }

        Collections.reverse(list);
        int constraint = 0;
        int last = 0;
        final List<Integer> candidates = new ArrayList<>();
        for (int i = 0; i < list.size(); i++) {
            final boolean bool = list.get(i);
            constraint++;
            if (bool) {
                last = i;
            }
            if (constraint == m) {
                if (bool) {
                    candidates.add(m);
                    constraint = 0;
                } else {
                    candidates.add(m - (i - last));
                    constraint = i - last;
                }
            }
        }
        candidates.add(constraint + 1);
        Collections.reverse(candidates);

        final String answer = candidates.stream()
                .map(i -> Integer.toString(i))
                .collect(Collectors.joining(" "));
        System.out.println(answer);
    }
}

import java.util.*;
import java.math.*;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int M = sc.nextInt();
    String S = sc.next();

    int step = 0, cur = S.length()-1;
    List<Integer> outList = new LinkedList<Integer>();
    while (step <= N) {
      if (cur <= M) {
        outList.add(cur);
        break;
      }
      for (int i = M; i >= 0; i--) {
        if (i == 0) {
          System.out.println("-1");
          return;
        }
        if (S.charAt(cur-i) != '1') {
          outList.add(i);
          cur -= i;
          break;
        }
      }
      step++;
    }
    if (step > N) System.out.println("-1");
    else {
      String out = new String(""+outList.get(outList.size()-1));
      for (int i = outList.size() - 2; i >= 0; i--) {
        out += new String(" " + outList.get(i));
      }
      System.out.println(out);
    }
  }
}

