class Program
{
	static void Main()
	{
		string[] input = Console.ReadLine().Split(' ');
		int n = int.Parse(input[0]);
		int m = int.Parse(input[1]);
		string s = Console.ReadLine();
		List<int> answers = new List<int>();
    int minNumBefore = n;
    int minNum = n;
    int leftNum = n;
    bool answer = true;

    while(true)
    {
      for(int i = leftNum-1; (i >= n-m && i >= 0); i--)
      {
        if(s[i] == '0') minNum = i;
      }
      leftNum = n-m;

      if(minNum == minNumBefore)
      {
        answer = false;
        break;
      }else
      {
        answers.Add(minNumBefore -minNum);
        minNumBefore = minNum;
        if(minNum == 0) break;
      }
    }

