    else
    {
      List<int> answersSub = new List<int>();
      int answerCount = answers.Count();
      for(int i = 0; i < answerCount; i++)
      {
        answersSub[i] = answers[answerCount-1-i];
      }
      Console.WriteLine(string.Join(" ", answersSub));
    }
	}
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using static System.Console;
using static System.Math;

class Program
{
    static void Main()
    {
        SetOut(new System.IO.StreamWriter(OpenStandardOutput()) { AutoFlush = false });
        var NM = ReadLine().Split().Select(int.Parse).ToArray();
        var N = NM[0];
        var M = NM[1];
        var map = new bool[N + 1];
        var s = ReadLine();
        var m = 0;
        var count = 0;
        for (int i = 0; i < N + 1; i++)
        {
            if (s[i] == '1')
            {
                count++;
            }
            else
            {
                m = Max(m, count);
                count = 0;
            }
            map[i] = s[i] == '0';
        }

        if (m >= M)
        {
            WriteLine(-1);
            Out.Flush();
            return;
        }

        Array.Reverse(map);

        var lis = new List<int>();
        var sp = new SparseTable<bool>(map, (x, y) => x & y);
        var k = 0;
        while (k != map.Length - 1)
        {
            var p = k;

            var ok = k;
            var ng = Min(k + M, N);
            var aaa = ng;
            if (map[ng])
            {
                lis.Add(ng - p);
                k = k + ng - p;
            }
            else
            {
                while (ng - ok > 1)
                {
                    var mid = (ok + ng) / 2;
                    if (sp.Query(k, mid))
                    {
                        ok = mid;
                    }
                    else
                    {
                        ng = mid;
                    }
                }
                lis.Add(ok - p);
                k = ok;
            }
        }
        var aaaa = lis.ToArray();
        Array.Reverse(aaaa);

        WriteLine(string.Join(" ", aaaa));
        Out.Flush();
    }
}

public class SparseTable<T>
{
    T[][] buffer;
    Func<T, T, T> F;
    int[] log2;

    public SparseTable(T[] init, Func<T, T, T> f)
    {
        F = f;

        var n = init.Length;

        log2 = new int[n + 1];
        log2[0] = -1;
        for (int i = 2; i < log2.Length; i++)
        {
            log2[i] = log2[i >> 1] + 1;
        }

        buffer = new T[log2[n] + 1][];
        for (int i = 0; i < buffer.Length; i++)
        {
            buffer[i] = new T[n - (1 << i) + 1];
        }

        Array.Copy(init, 0, buffer[0], 0, init.Length);
        for (int i = 1, p = 1; i < buffer.Length; i++, p <<= 1)
        {
            for (int j = 0; j < buffer[i].Length; j++)
            {
                buffer[i][j] = F(buffer[i - 1][j], buffer[i - 1][j + p]);
            }
        }
    }

    public T Query(int l, int r)
    {
        var h = log2[r - l];
        return F(buffer[h][l], buffer[h][r - (1 << h)]);
    }
}

