			tree[abl[i].Item2-1].Add(new VT<ll, ll>(abl[i].Item1-1,i));
		}

		for (int i = 0; i < n; i++)
		{
			if(cmax<tree[i].Count){
				cmax = tree[i].Count;
				root = i;
			}
		}

		Func<ll,ll,ll,bool> dfs = null;
