class Program
{
    static void Main(string[] args)
    {
        var N = sc.ReadInt();
        var M = sc.ReadInt();
        var S = sc.ReadStr();
        var dp = new int[N + 1];
        for (int i = 0; i <= N; i++)
        {
            dp[i] = -1;
        }
        dp[0] = 0;

        var t = 0;
        var index = Array.LastIndexOf(dp, 0);
        while (index >= 0)
        {
            t++;
            for (int i = 1; i <= M; i++)
            {
                if (i + index > N) break;
                if (S[i + index] == '1') continue;
                dp[i + index] = t;
            }
            index = Array.LastIndexOf(dp, t);
        }
        if (dp[N] == -1)
        {
            Console.WriteLine(-1);
            return;
        }
        if (dp[N] == 1)
        {
            Console.WriteLine(N);
            return;
        }

        var now = 0;
        var prev = 0;
        for (int i = 1; i <= dp[N]; i++)
        {
            while (now <= N)
            {
                now++;
                if (dp[now] == i)
                {
                    if (i > 1) Console.Write(" ");
                    Console.Write(now - prev);
                    prev = now;
                    break;
                }
            }
        }
        Console.WriteLine();
    }
