static class CodeJam
{
    static int[] Solve(int N, int M, string S)
    {
        var ans = new List<int>();
        int p = N;
        while (p > 0)
        {
            for (int i = M; i >= 1; --i)
            {
                if (p - i >= 0 && S[p - i] == '0')
                {
                    ans.Add(i);
                    p -= i;
                    break;
                }
                if (i == 1) { return null; }
            }
        }
        ans.Reverse();
        return ans.ToArray();
    }

    static void Main(string[] args)
    {
        int[] V = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        string S = Console.ReadLine();
        var ans = Solve(V[0], V[1], S);
        Console.WriteLine(string.Join(" ", ans ?? new[] { -1 }));
    }
}

