    class Program
    {
        static readonly int MAXIMUM = int.MaxValue / 2;

        private static void Solve2(int n, int m, string s)
        {
            var sarr = s.ToCharArray();
            int current = n;
            int prev = n;
            var path = new List<int>();
            path.Add(current);
            while (current > 0)
            {
                current -= m;
                while (current < 0 || sarr[current] == '1') ++current;
                if (current == prev)
                {
                    Console.WriteLine(-1);
                    return;
                }
                path.Add(current);
                prev = current;
            }

            var arr = path.ToArray();
            var ans = new List<int>();
            for (int i = path.Count - 1; i > 0 ; --i)
            {
                ans.Add(arr[i - 1] - arr[i]);
            }
            var builder = new StringBuilder();
            foreach (var a in ans)
            {
                builder.Append(a);
                builder.Append(" ");
            }
            Console.WriteLine(builder);
        }

        private static void Solve(int n, int m, string s)
        {
            var sarr = s.ToCharArray();
            var nStep = Enumerable.Repeat<int>(MAXIMUM, n + 1).ToArray();
            var from = Enumerable.Repeat<int>(-1, n + 1).ToArray();
            //var nStep = new int[n + 1];
            //var from = new int[n + 1];
            //Array.Fill(nStep, MAXIMUM);
            //Array.Fill(from, -1);
            nStep[0] = 0;
            for (int i = 1; i <= n; ++i)
            {
                if (sarr[i] == '1') continue;
                for (int j = Math.Max(0, i - m); j < i; ++j)
                {
                    if (nStep[j] + 1 <  nStep[i])
                    {
                        nStep[i] = nStep[j] + 1;
                        from[i] = j;
                        //break;
                    }
                }
            }

            if (nStep[n] == MAXIMUM)
            {
                Console.WriteLine(-1);
                return;
            }

            int c = n;
            var ans = new List<string>();
            while (c > 0)
            {
                var step = c - from[c];
                c = from[c];
                ans.Add(step.ToString());
            }

            ans.Reverse();
            var builder = new StringBuilder();
            foreach (var a in ans)
            {
                builder.Append(a);
                builder.Append(" ");
            }
            Console.WriteLine(builder);
        }

        static void Main(string[] args)
        {
            var line = Console.ReadLine().Split(' ');
            var n = Convert.ToInt32(line[0]);
            var m = Convert.ToInt32(line[1]);
            string s = Console.ReadLine();
            Solve2(n, m, s);
        }
    }
}

