class Program
{
    static void Main(string[] args)
    {
        var N = sc.ReadInt();
        var M = sc.ReadInt();
        var S = sc.ReadStr();
        var list = new List<int>();
        while (N > 0)
        {
            var ok = false;
            for (int i = Math.Min(M, N); i >= 1; i--)
            {
                if (S[N - i] == '0')
                {
                    N -= i;
                    list.Add(i);
                    ok = true;
                    break;
                }
            }
            if (ok == false)
            {
                Console.WriteLine(-1);
                return;
            }
        }
        list.Reverse();
        Console.WriteLine(string.Join(" ", list));
    }

    static Scanner sc = new Scanner();
}

