class Program
{
    static void Main(string[] args)
    {
        N = sc.ReadInt();
        M = sc.ReadInt();
        S = sc.ReadStr();
        var list = new List<int>();
        Rec(N, list);
        if (list.Count == 0)
        {
            Console.WriteLine(-1);
            return;
        }
        Console.WriteLine(string.Join(" ", list));
    }

    static int N;
    static int M;
    static string S;
    static long[] Prev = new long[110000];
    static bool Rec(int n, List<int> list)
    {
        if (S[n] == '1') return false;
        if (n == 0) return true;
        for (int i = Math.Min(n, M); i > 0; i--)
        {
            if (Rec(n - i, list))
            {
                list.Add(i);
                return true;
            }
        }
        return false;
    }

    static Scanner sc = new Scanner();
}

