using System;
using System.Collections.Generic;
using System.Linq;

public class Program
{
    private int N, M;
    private char[] S;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        M = sc.NextInt();
        S = sc.Next().ToCharArray();

        var cost = new int[N + 1];
        for (int i = 0; i <= N; i++)
        {
            cost[i] = int.MaxValue;
        }

        cost[N] = 0;
        int pos = N;
        while (pos > 0)
        {
            int np = -1;
            bool f = false;
            for (int i = 1; i <= M; i++)
            {
                int pp = pos - i;
                if (pp < 0) break;
                if (S[pp] == '1') continue;
                cost[pp] = cost[pos] + 1;
                np = pp;
                f = true;
            }

            if (!f)
            {
                Console.WriteLine("-1");
                return;
            }

            pos = np;
        }

        List<int> ans = new List<int>();
        pos = 0;
        while (pos < N)
        {
            for (int i = 1; i <= M; i++)
            {
                if (pos + i > N) continue;
                if (S[pos + i] == '1') continue;
                if (cost[pos] == cost[pos + i] + 1)
                {
                    pos += i;
                    ans.Add(i);
                    break;
                }
            }
        }

        Console.WriteLine(string.Join(" ",ans));
    }


    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

