class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n, m;
        sc.Multi(out n, out m);
        var s = sc.Str;
        var sg = new Segtree<P>(n + 1, (x, y) => x.v1 < y.v1 ? x : x.v1 > y.v1 ? y : x.v2 < y.v2 ? x : y, new P(M, M));
        sg.update(n, new P(0, n));
        var nex = new int[n + 1];
        for (int i = 0; i < n + 1; i++)
        {
            nex[i] = -1;
        }
        for (int i = n - 1; i >= 0 ; i--)
        {
            if (s[i] == '1') continue;
            var p = sg.run(i, i + m + 1);
            if (p.v1 < M) {
                nex[i] = p.v2;
                sg.update(i, new P(p.v1 + 1, i));
            }
        }
        if (nex[0] == -1) {
            Prt(-1);
        }
        else {
            var ans = new List<int>();
            int now = 0;
            while (now < n) {
                ans.Add(nex[now] - now);
                now = nex[now];
            }
            Prt(ans);
        }


    }
}

