        static void Main(string[] args)
        {
            var N = RInt;
            var M = RInt;
            var S = Console.ReadLine();

            // おそらくTLE?
            int[] dp = new int[N + 1].Select(x => int.MaxValue).ToArray(); //最小手数
            dp[0] = 0;
            int[] prev = new int[N + 1].Select(x => -1).ToArray();
            prev[0] = -2;
            int max = 0;
            for (int i = 0; i < N; i++)
            {
                if (S[i] == '1') continue;
                for (int j = max - i; j <= M; j++)
                {
                    int to = i + j;
                    if (to > N) continue;
                    if (S[to] == '1') continue;
                    if (dp[to] > dp[i] + 1)
                    {
                        dp[to] = dp[i] + 1;
                        max = Math.Max(i + j, max);
                        prev[to] = i;
                    }
                }
            }

            List<int> hands = new List<int>();
            int k = N;
            while (prev[k] != -2)
            {
                if (prev[k] == -1) break;
                hands.Add(k - prev[k]);
                k = prev[k];
            }
            hands.Reverse();

            if (hands.Count > 0) Console.WriteLine(string.Join(" ", hands));
            else Console.WriteLine(-1);
        }


    }


