    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		string[] input = Console.ReadLine().Split(' ');
		int n = int.Parse(input[0]);
		int m = int.Parse(input[1]);
		string s = Console.ReadLine();
		List<int> answers = new List<int>();
    int minNumBefore = n;
    int minNum = n;
    int leftNum = n;
    bool answer = true;

    while(true)
    {
      for(int i = leftNum-1; (i >= minNumBefore-m && i >= 0); i--)
      {
        if(s[i] == '0') minNum = i;
      }
      leftNum = n-m;
      //Console.WriteLine(minNum);

      if(minNum == minNumBefore)
      {
        answer = false;
        break;
      }else
      {
        answers.Add(minNumBefore -minNum);
        minNumBefore = minNum;
        if(minNum == 0) break;
      }
    }

		if(!answer) Console.WriteLine(-1);
    else
    {
      int answerCount = answers.Count();
      int[] answersSub = new int[answerCount];
      for(int i = 0; i < answerCount; i++)
      {
        answersSub[i] = answers[answerCount-1-i];
      }
      Console.WriteLine(string.Join(" ", answersSub));
    }
	}
}

using System;
using System.Collections.Generic;
class Program
{
	static void Main(string[] args)
	{
		string[] str = Console.ReadLine().Split();
		int N = int.Parse(str[0]);
		int M = int.Parse(str[1]);
		string s = Console.ReadLine();
		var list = new List<int>();
		for(var i=0;i<N+1;i++){
			if(s.Substring(i,1)=="0"){
				list.Add(i);
			}
		}
		int an = N;
		var ans = new List<int>();
		bool flag = true;
		while(an>0){
			int an2 = an-M;
			int min = 0;
			int max = list.Count-1;
			while(min<max){
				int m = (min+max)/2;
				if(list[m]<an2){
					min = m+1;
				} else {
					max = m;
				}
			}
			int an3 = list[min];
			if(an-an3<=0){
				flag = false;
				break;
			}
			ans.Add(an-an3);
          	an = an3;
		}
		if(flag){
			Console.Write(ans[ans.Count-1]);
			for(var i=ans.Count-2;i>=0;i--){
				Console.Write(" "+ans[i]);
			}
		} else {
			Console.WriteLine("-1");
		}
	}
}

