class Program
{
    static void Main(string[] args)
    {
        var N = sc.ReadInt();
        var M = sc.ReadInt();
        var S = sc.ReadStr();
        var dp = new int[110000];
        var prev = new int[110000];
        for (int i = 0; i < dp.Length; i++)
        {
            dp[i] = int.MaxValue / 2;
            prev[i] = int.MaxValue / 2;
        }
        dp[0] = 0;
        prev[0] = 0;
        for (int i = 0; i < N; i++)
        {
            if (S[i] == '1') continue;
            for (int j = 1; j <= M; j++)
            {
                if (dp[i + j] >= dp[i] + 1)
                {
                    dp[i + j] = dp[i] + 1;
                    prev[i + j] = Math.Min(prev[i + j], i);
                }
            }
        }
        if (dp[N] > N+1)
        {
            Console.WriteLine(-1);
            return;
        }

        var list = new List<int>();
        var index = prev[N];
        list.Add(N - index);
        while (index > 0)
        {
            var prevprev = prev[index];
            list.Add(index - prevprev);
            index = prevprev;
        }
        list.Reverse();
        Console.WriteLine(string.Join(" ", list));
    }
