    class Modulo
    {
        private const long M = 1000000007;
        //private const int M = 998244353;
        private readonly long[] m_facs;
        public long Mul(long a, long b)
        {
            return ((a * b) % M);
        }
        public Modulo(long n)
        {
            m_facs = new long[n + 1];
            m_facs[0] = 1;
            for (long i = 1; i <= n; ++i)
            {
                m_facs[i] = Mul(m_facs[i - 1], i);
            }
        }
        public long Fac(long n)
        {
            return m_facs[n];
        }
        public long Pow(long a, long m)
        {
            switch (m)
            {
                case 0:
                    return 1L;
                case 1:
                    return a;
                default:
                    long p1 = Pow(a, m / 2);
                    long p2 = Mul(p1, p1);
                    return ((m % 2) == 0) ? p2 : Mul(p2, a);
            }
        }
        public long Div(long a, long b)
        {
            return Mul(a, Pow(b, M - 2));
        }
        public long Ncr(long n, long r)
        {
            if (n < r) { return 0; }
            if (n == r) { return 1; }
            long res = Fac(n);
            res = Div(res, Fac(r));
            res = Div(res, Fac(n - r));
            return res;
        }
        public Modulo() { }
    }
    public class SegmentTree<T>
    {
        //
        //
        // 0-indexed!!!!!!!!!!!!!!!!!!!!!!!
        // [l,r)は半開区間!!!!!!!!!!!!!!!!!!!
        //
        int n;
        T[] Tree;
        Func<T, T, T> f;
        T ex;
        public SegmentTree(int size, Func<T, T, T> fun, T exvalue)
        {
            f = fun;
            ex = exvalue;
            n = 1;
            while (n < size) n <<= 1;
            Tree = new T[(n << 1) - 1];
            for (var i = 0; i < Tree.Length; i++) Tree[i] = ex;
        }
        public SegmentTree(int size, Func<T, T, T> f, T exvalue, T initial) : this(size, f, exvalue)
        {
            for (var i = 0; i < size; i++) Tree[i + n - 1] = initial;
            Set_All();
        }

        public void Set_All()
        {
            for (var i = n - 2; i >= 0; i--)
            {
                Tree[i] = f(Tree[(i << 1) + 1], Tree[(i << 1) + 2]);
            }
        }

        public void Assign(int ind, T val)
        {
            Tree[ind + n - 1] = val;
        }
        public void Update(int ind)
        {
            int i = ind + n - 1;
            while (i > 0)
            {
                i = (i - 1) >> 1;
                Tree[i] = f(Tree[(i << 1) + 1], Tree[(i << 1) + 2]);
            }
        }

        public void Query_Update(int ind, T val)
        {
            Assign(ind, val);
            Update(ind);
        }
        public T Query_Answer(int l, int r) //[l,r)
        {
            return Scanning(l, r, 0, 0, n);
        }
        private T Scanning(int l, int r, int ind, int ind_l, int ind_r)
        {
            if (ind_r <= l || r <= ind_l) { return ex; }
            if (l <= ind_l && ind_r <= r) { return Tree[ind]; }
            return f(Scanning(l, r, (ind << 1) + 1, ind_l, (ind_l + ind_r) >> 1), Scanning(l, r, (ind << 1) + 2, (ind_l + ind_r) >> 1, ind_r));
        }

        public T Look(int ind)
        {
            return Tree[ind + n - 1];
        }
        public void Debug_Display_All()
        {
            for (var i = 0; i < n; i++) Console.Write($"{Tree[i + n - 1]} ");
            Console.WriteLine();
        }
    }
