    static void Main()
    {
        var NM = Console.ReadLine().Split().Select(int.Parse).ToArray();
        int N = NM[0], M = NM[1];
        string S = Console.ReadLine();

        int now = N;
        var ans = new List<int>();
        while (true)
        {
            bool frag = false;
            for (int i = M; i >= 1; i--)
            {
                int next = now - i;
                if (next < 0) continue;
                if (S[next] == '0')
                {
                    frag = true;
                    now = next;
                    ans.Add(i);
                    break;
                }
            }
            if (!frag)
