    class Solver
    {
        private long N;
        private long M;
        private string S;

        public void Solve()
        {
            Cin(out N, out M);
            Cin(out S);

            // あとi回でゴールに辿り着く出目のうち、最も大きい数字のリスト
            var dp = new List<long>();
            long cur = N;
            while (cur > 0)
            {
                //なるべく多く進む
                // 現在curにいるとき、最大限進んだ位置は max(cur - M, 0)
                long t = -1;
                for (int j = (int) Math.Max(cur - M, 0); j < cur; j++)
                {
                    if (S[j] == '1') continue;
                    t = j;
                    break;
                }

                //踏めるマスがない
                if (t == -1)
                {
                    Console.WriteLine(-1);
                    return;
                }

                dp.Add(cur - t);
                cur = t;
            }

            dp.Reverse();
            foreach (long l in dp)
            {
                Console.Write("" + l + " ");
            }

            Console.WriteLine();
        }
    }
}

