func exec(stdin *Stdin, stdout *Stdout) {
	n := stdin.ReadInt()
	m := stdin.ReadInt()
	s := stdin.Read()

	a := []int{}
	for i := 0; i < n+1; i++ {
		if s[i] == '0' {
			a = append(a, i)
		}
	}

	b := make([]int, n+1)
	for i := n; i >= 0; i-- {
		j := sort.Search(len(a), func(x int) bool {
			return a[x] >= i-m
		})
		b[i] = a[j]
	}

	c := []int{}
	x := n
	for x > 0 {
		if x == b[x] {
			stdout.Println(-1)
			return
		}
		c = append(c, x-b[x])
		x = b[x]
	}

	d := []string{}
	for i := len(c) - 1; i >= 0; i-- {
		d = append(d, strconv.Itoa(c[i]))
	}
	stdout.Println(strings.Join(d, " "))
}

