func dfs(N, M int, s []bool, a []int, cur int) []int {
	if cur == N {
		return a
	}

	for i := M; 0 < i; i-- {
		if cur+i <= N && s[cur+i] {
			res := dfs(N, M, s, append(a, i), cur+i)
			if res != nil {
				return res
			}
		}
	}
	return nil
}

