type IntPQ []int

func (pq IntPQ) Len() int           { return len(pq) }
func (pq IntPQ) Less(i, j int) bool { return pq[i] < pq[j] } // <: ASC, >: DESC
func (pq IntPQ) Swap(i, j int)      { pq[i], pq[j] = pq[j], pq[i] }
func (pq *IntPQ) Push(x interface{}) {
	*pq = append(*pq, x.(int))
}
func (pq *IntPQ) Pop() interface{} {
	old := *pq
	n := len(old)
	x := old[n-1]
	*pq = old[0 : n-1]
	return x
}

