var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  buffer := make([]byte, 0)
  for true {
    line, isPrefix, err := reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func NextInt() int {
  n, _ := strconv.Atoi(NextLine())
  return n
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func WriteIntVec(A []int) {
  S := make([]string, len(A))
  for i, a := range A {
    S[i] = strconv.Itoa(a)
  }
  Write(strings.Join(S, " "))
}
func Output() {
  _ = writer.Flush()
}

func Max(x, y int) int {
  if x < y { return y }
  return x
}
func Min(x, y int) int {
  if x < y { return x }
  return y
}

func main() {
  NM := NextIntVec()
  N, M := NM[0], NM[1]
  S := NextLine()
  D := make([]int, N + 1)
  for i := range D {
    D[i] = -1
  }
  now := N
  for 0 < now {
    next := now
    for i := 1; i <= M; i++ {
      if now < i { break }
      if S[now - i] == '1' { continue }
      D[now - i] = i
      next = now - i
    }
    if now == next { break }
    now = next
  }
  if D[0] < 0 {
    Write(-1)
  } else {
    A := make([]int, 0)
    pos := 0
    for pos < N {
      A = append(A, D[pos])
      pos += D[pos]
    }
    WriteIntVec(A)
  }
  Output()
}

