		state := h.pop()
		if state.p == N {
			for _, c := range state.path {
				fmt.Printf("%d ", c)
			}
			return
		}
		if S[state.p] == '1' {
			continue
		}
		for i := 1; i <= M; i++ {
			h.push(State{
				p:    state.p + i,
				c:    state.c + 1,
				path: append(append([]int{}, state.path...), i),
			})
		}
	}
	fmt.Println(-1)
}

type State struct {
	p    int
	c    int
	path []int
}

type HeapElement = State
type Heap []HeapElement

func (h Heap) Less(i, j int) bool {
	if h[i].c == h[j].c {
		for k := 0; k < len(h[i].path); k++ {
			ik, jk := h[i].path[k], h[j].path[k]
			if ik == jk {
				continue
			}
			return ik < jk
		}
	}
	return h[i].c < h[j].c
}
func (h Heap) Len() int              { return len(h) }
func (h Heap) Swap(i, j int)         { h[i], h[j] = h[j], h[i] }
func (h *Heap) Push(x interface{})   { *h = append(*h, x.(HeapElement)) }
func (h *Heap) Pop() (x interface{}) { *h, x = (*h)[:len(*h)-1], (*h)[len(*h)-1]; return }
func (h *Heap) push(v HeapElement)   { heap.Push(h, v) }
func (h *Heap) pop() HeapElement     { return heap.Pop(h).(HeapElement) }

