	}
	st := NewSegmentTree(n+1, f, INF_BIT30)
	st.Set(n, 0)
	st.Build()

	for i := n - 1; i >= 0; i-- {
		if S[i] == '1' {
			continue
		}
		minStep := st.Query(i, Min(i+m+1, n+1))
		st.Update(i, minStep+1)
	}
