const Inf = 1 << 62

func main() {
	N, M := ReadInt(), ReadInt()
	S := ReadString()
	dp := make([]int, N+1)
	for i := 0; i < N; i++ {
		dp[i] = Inf
	}
	dp[N] = 0
	// dpを平方分割
	blockSize := int(math.Sqrt(float64(N + 1)))
	blockNum := (N + 1 + blockSize - 1) / blockSize
	blocks := make([]int, blockNum)
	for i := 0; i < blockNum; i++ {
		blocks[i] = Inf
	}
	blocks[N/blockSize] = 0
	for i := N - 1; i >= 0; i-- {
		if S[i] == '1' {
			continue
		}
		l := i + 1
		r := Min(i+M, N) + 1
		min := Inf
		for l < r && l%blockSize > 0 {
			min = Min(min, dp[l])
			l++
		}
		for l < r && r%blockSize > 0 {
			r--
			min = Min(min, dp[r])
		}
		for l < r {
			min = Min(min, blocks[l/blockSize])
			l += blockSize
		}
		dp[i] = min + 1
		blocks[i/blockSize] = Min(blocks[i/blockSize], dp[i])
	}

	if dp[0] >= Inf {
		fmt.Println(-1)
		return
	}

	x := 0
	rest := dp[0]
	for x < N {
		rest--
		i := 1
		for dp[x+i] != rest {
			i++
		}
		fmt.Printf("%d ", i)
		x += i
	}
}

