void main()
{
    auto nm = readln.split.to!(int[]);
    auto N = nm[0];
    auto M = nm[1];
    auto S = readln.chomp;
    int[] rr;
    int i, j, last;
    foreach_reverse (c; S) {
        if (c == '0') last = i;
        if (i-j == M) {
            if (last == j) {
                writeln(-1);
                return;
            }
            rr ~= (last-j);
            j = last;
        }
        ++i;
    }
    if (j != N) rr ~= (N-j);
    rr.reverse();
    writeln(rr.array().to!(string[]).join(" "));
}

void main()
{
    int[] tmp = readln.split.to!(int[]);
    int n = tmp[0], m = tmp[1];
    string s = readln.chomp;

    int[] move;
    while (n > 0)
    {
        bool ok;
        foreach_reverse (i; 1 .. m+1)
        {
            if (n - i < 0) continue;

            if (s[n-i] == '0')
            {
                ok = true;
                n -= i;
                move ~= i;
                break;
            }
        }

        if (!ok)
        {
            break;
        }
    }

    if (n == 0)
    {
        reverse(move);
        move.to!(string[]).join(" ").writeln;
    }
    else
    {
        writeln(-1);
    }
}

