auto solve( Range )( Range input )
if( isInputRange!Range && is( ElementType!Range == string ) )
{
	auto n = 0L;
	auto m = 0L;
	input.front.formattedRead!"%s %s"( n, m );
	input.popFront;
	auto s = input.front.to!( dchar[] );

	long[] anss;
	auto i = n;
	LOOP: while( 0 < i )
	{
		foreach_reverse( j; 1L .. m + 1 )
		{
			if( 0 <= i - j && s[ i - j ] == '0' )
			{
				anss ~= j;
				i -= j;
				continue LOOP;
			}
		}
		return "-1";
	}
	return anss.to!( string[] ).retro.join( " " );
}

