        if (S[i] != S[i+1]) {
            A ~= tuple(tmp, i);
            tmp ^= 1;
        }
    }
    A ~= tuple(false, N);

    int ans = 0;
    int pos = 0;
    int idx = 0;
    int mov = M;
    int[] hoge;

    while (pos < N) {
        if (idx == A.length.to!int - 1) {
            if (mov < M) {
                pos += mov;
                hoge.back += mov;
                mov = M;
            } else {
                pos += M;
                ans += 1;
                hoge ~= M;
            }
        } else if (pos + mov <= A[idx][1]) {
            if (mov < M) {
