void main() {
    int N, M;
    scan(N, M);
    M = min(N, M);
    auto s = readln.chomp;
    auto over = s.map!(ch => ch == '1').array;
    auto dp = new int[](N + 1);
    dp[] = inf;
    dp[N] = 0;
    foreach (i ; N - M .. N) {
        if (over[i]) continue;
        dp[i] = 1;
    }

    auto st = SegmentTree!(int, min, inf)(N + 1);
    foreach (i ; N - M .. N + 1) {
        st.assign(i, dp[i]);
    }

    foreach_reverse (i ; 0 .. N - M) {
        if (over[i]) continue;
        dp[i] = st.query(i + 1, i + M + 1) + 1;
        st.assign(i, dp[i]);
    }

    debug {
        writeln(dp);
    }

    int[] ans;
    int pos = 0;

    while (pos < N) {
        bool canMove;

        foreach (i ; 1 .. M + 1) {
            if (dp[pos] - 1 == dp[pos + i]) {
                pos += i;
                ans ~= i;
                canMove = true;
                break;
            }
        }

        if (!canMove) {
            writeln(-1);
            return;
        }
    }

    writefln("%(%s %)", ans);
