auto solve( long m, long[] s )
{
	long[] anss;
	auto p = s.length.signed - 1;
	while( 0 < p )
	{
		auto d = min( m, p );
		while( 0 < d && s[ p - d ] ) d--;
		if( d == 0 ) return "-1";
		p -= d;
		anss ~= d;
	}
	return anss.to!( string[] ).retro.join( ' ' );
}

