    auto M = nm[1];
    auto S = readln.chomp;
    int[] rr;
    int i, j, last;
    foreach_reverse (c; S) {
        if (c == '0') last = i;
        if (i-j == M) {
            if (last == j) {
                writeln(-1);
                return;
            }
            rr ~= (last-j);
            j = last;
        }
        ++i;
    }
    if (j != N) rr ~= (N-j);
    writeln(rr.reverse.to!(string[]).join(" "));
}

