enum long INF = long.max/5;

void main() {
  long N, M;
  scanln(N, M);
  M.ch!min(N);
  bool[] as = readln.chomp.map!"a=='1'".array;

  struct P {
    long value;
    long index;
  }

  auto seg = SegTree!(
    P,
    (a, b) {
      if (a.index < 0) return b;
      if (b.index < 0) return a;
      if (a.value != b.value) {
        return a.value < b.value ? a : b;
      } else {
        return a.index < b.index ? a : b;
      }
    },
    P(INF, -1),
  )((N+1).iota.map!(i => P(i==0 ? 0 : INF, i)).array);
  long[] xs = new long[N+1];
  xs[0] = -1;

  foreach(i; 1..N+1) {
    if (as[i]) continue;
    auto p = seg.query(max(0, i-M), i);
    seg.update(
      i,
      P(p.value + 1, i)
    );
    xs[i] = p.index;
  }

  if (seg.get(N).value >= INF) {
    writeln(-1);
  } else {
    long i = N;
    long[] ys = [];
    while(xs[i] >= 0) {
      ys ~= i - xs[i];
      i = xs[i];
    }
    ys.retro.map!(to!string).join(" ").writeln;
  }
}

