proc main() =
  var n, m: int
  (n, m) = stdin.readLine.strip.split.map(parseInt)
  let s = stdin.readLine.strip

  var dp = newSeq[int](n + 1)
  const inf = 1000000000
  fill(dp, inf)
  dp[n] = 0
  var a = newSeq[int]()
  for i in 0..n:
    if s[i] == '0':
      a.add(i)
  for i in countdown(n - 1, 0):
    if s[i] == '1':
      dp[i] = dp[i + 1]
      continue
    let j = a.lowerBound(i + m + 1)
    if j >= 1:
      if a[j - 1] > i:
        dp[i] = dp[a[j - 1]] + 1
  let k = dp[0]
  if k == inf:
    echo -1
    return
  var
    cur = 0
    pos = newSeq[int]()
  pos.add(0)
  for i in 1..k:
    var
      ok = cur
      ng = n + 1
    while ng - ok > 1:
      let m = (ng + ok) div 2
      if dp[m] >= k - i:
        ok = m
      else:
        ng = m
    pos.add(ok)
    cur = ok
  var ans = newSeq[int]()
  for i in 1..k:
    ans.add(pos[i] - pos[i - 1])
  echo ans.mapIt($it).join(" ")

