@mt
def slv(N, M, S):
    def init():
        return [[INF, []] for _ in range(N+1)] 

    dp = init()
    dp[0] = [0, []]
    for i in range(N):
        tmp = deepcopy(dp)
        if S[i] == '1':
            continue
        for j in range(1, M+1):
            k = i + j
            if k > N:
                break
            if S[k] == '1':
                continue
            if dp[i][0] + 1 < dp[k][0]:
                c, s = dp[i]
                s = s[:]
                s.append(j)
                tmp[k] = [c + 1, s]
            elif dp[i][0] + 1 == dp[k][0]:
                c, s = dp[i]
                s1 = s[:]
                s2 = dp[k][1]
                for c1, c2 in zip(s1, s2):
                    if c1 > c2:
                        break
                else:
                    tmp[k] = [c + 1, s1]
        dp = tmp

    if dp[N][0] == INF:
        return -1
    return ' '.join(map(str, dp[N][1]))


