from heapq import heappop, heappush


def solve(n, m, s):
    q = [(0, 0)]
    curr = None
    for i in range(1, n + 1):
        if s[i] == '1':
            continue
        left_limit = max(0, i - m)
        while q and q[0][-1] < left_limit:
            heappop(q)
        if not q:
            return (-1,)
        prev = q[0]
        dice = i - prev[-1]
        curr = (prev[0] + 1,) + prev[1:-1] + (dice, i)
        heappush(q, curr)

    return curr[1:-1]


