import sys

def back_search(N, M, S):
    result=[]
    search_index = 0
    while(search_index < N):
        prev_search_index = search_index
        for m in reversed(range(1,M+1)):
            if search_index + m > N+1:
                continue
            if S[search_index + m] == '0':
                result.append(m)
                search_index += m
                break
        if prev_search_index == search_index:
            return []
    return result

def forward_search(N, M, S, index, depth):
    result=[]
    if depth is 0:
        if N-index > M:
            return -1
        else:
            result.append(N-index)
            return result
    else :
        search_max = min(M, N-index)+1
        for i in range(1,search_max):
            if S[index + i] is "0":
                sub_result = forward_search(N,M,S,index+i, depth-1)
                if not (sub_result is -1):
                    result.append(i)
                    result.extend(sub_result)
                    return result
        return -1


