                next[i] = next[i-1];
            }
        }
    }
    let mut now = 0;
    while now < n {
        if next[now] <= now {
            println!("-1");
            return;
        }
        let d = next[now] - now;
        now = next[now];
        ans.push(d);
    }
    ans.reverse();
    for i in 0..ans.len() {
        if i != 0 {
            print!(" ");
        }
        print!("{}", ans[i]);
    }
    println!();
}

