struct Solver {}

impl Solver {
    fn solve(&mut self) {
        let stdin = std::io::stdin();
        let mut scn = Scanner {
            stdin: stdin.lock(),
        };
        let n: usize = scn.read();
        let m: usize = scn.read();
        let s = scn.chars();
        let mut zeros: Vec<usize> = s
            .iter()
            .rev()
            .enumerate()
            .filter_map(|(idx, c)| if *c == '0' { Some(idx) } else { None })
            .collect();
        let mut paths = vec![];
        let mut pos = 0;
        while pos < n {
            let (left, right) = (pos + 1, pos + m);
            if right >= n {
                paths.push(n - pos);
                break;
            }
            let lower = zeros.lower_bound(&right);
            if lower.is_none() {
                println!("{}", -1);
                break;
            }
            let target = zeros[lower.unwrap()];
            if target == right {
                paths.push(m);
                pos = right;
            } else {
                //lower - 1
                let idx = lower.unwrap();
                if idx >= 1 {
                    if zeros[idx - 1] == pos {
                        println!("{}", -1);
                        break;
                    }
                    paths.push(zeros[idx - 1] - pos);
                    pos = zeros[idx - 1];
                } else {
                    println!("{}", -1);
                    break;
                }
            }
        }
        paths.reverse();
        for x in paths.iter() {
            print!("{} ", x);
        }
    }
}

