#[derive(Eq, PartialEq)]
struct Reverse(u32, usize);

impl Ord for Reverse {
    fn cmp(&self, other: &Reverse) -> Ordering {
        other.0.cmp(&self.0)
            .then_with(|| other.1.cmp(&self.1))
    }
}

impl PartialOrd for Reverse {
    fn partial_cmp(&self, other: &Reverse) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn main() {
    let (n, m): (usize, usize) = {
        let mut line = String::new();
        std::io::stdin().read_line(&mut line).unwrap();
        let mut iter = line.split_whitespace();
        (
            iter.next().unwrap().parse().unwrap(),
            iter.next().unwrap().parse().unwrap(),
        )
    };

    let s: Vec<char> = {
        let mut line = String::new();
        std::io::stdin().read_line(&mut line).unwrap();
        line.chars().collect()
    };

    let mut heap = BinaryHeap::new();
    heap.push(Reverse(0, n));

    let mut next: Vec<usize> = vec![0; n + 1];

    for i in (0..n).rev() {
        if s[i] == '1' { continue; }

        while let Some(Reverse(d, j)) = heap.pop() {
