const INF: i32 = 100000000;

fn main() {
    input! {
        n: usize, m: usize,
        s: chars
    };


    let mut seg = SegmentTree::new(n+m+16, INF, Rc::new(|a,b| min(a,b)), 0i32, Rc::new(|a,b| a+b));
    seg.apply_range(n, n+1, -INF);
    for i in (0..n).rev() {
        if s[i] == '1' {
            continue;
        }
        let w = seg.compute_range(i, i+1);
        let best = seg.compute_range(i+1, i+m+1)+1;
        if w > best {
            seg.apply_range(i, i+1, best-w);
        }
    }

    let mut te = seg.compute_range(0, 1);
    if te >= INF {
        println!("-1");
        return;
    }

    let mut w = vec![];
    let mut now = 0;
    while te >= 1 {
        let mut ng = now;
        let mut ok = now + m + 1;
        while ok - ng > 1 {
            let med = (ok + ng) / 2;
            if seg.compute_range(now+1, med) == te-1 {
                ok = med;
            } else {
                ng = med;
            }
        }
        w.push(ok-1-now);
        now = ok-1;
        te -= 1;
    }
    println!("{}", join!(w, " "));
}

use std::cmp::Ordering;

pub trait BinarySearch<T> {
    fn lower_bound(&self, x: &T) -> Option<usize>;
    fn upper_bound(&self, x: &T) -> Option<usize>;
}

impl<T: Ord> BinarySearch<T> for [T] {
    //greater than or equal
    fn lower_bound(&self, x: &T) -> Option<usize> {
        let mut left = 0;
        let mut right = self.len();
        let mut result = None;
        while left < right {
            let med = (left + right) / 2;
            match self[med].cmp(x) {
                Ordering::Less => {
                    left = med + 1;
                }
                Ordering::Equal | Ordering::Greater => {
                    result = Some(med);
                    right = med;
                }
            }
        }
        result
    }
    fn upper_bound(&self, x: &T) -> Option<usize> {
        let mut left = 0;
        let mut right = self.len();
        let mut result = None;
        while left < right {
            let med = (left + right) / 2;
            match self[med].cmp(x) {
                Ordering::Equal | Ordering::Less => {
                    left = med + 1;
                }
                Ordering::Greater => {
                    result = Some(med);
                    right = med;
                }
            }
        }
        result
    }
}

