fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);
    let mut ret = String::new();
    use std::fmt::Write;

    let n: usize = sc.read();
    let m: usize = sc.read();
    let s: Vec<char> = sc.get().chars().collect();

    let mut dem = Vec::new();

    let mut pos = n;
    while pos > 0 {
        let mut dm = 0;
        for d in 1..m+1 {
            if pos < d {
                break;
            }
            if s[pos-d] == '0' {
                dm = std::cmp::max(dm, d);
            }
        }
        if dm == 0 {
            return "-1\n".to_string();
        }
        dem.push(dm);
        pos -= dm;
    }

    while let Some(d) = dem.pop() {
        write!(&mut ret, "{} ", d).unwrap();
    }

    ret.pop();
    ret.push('\n');

    ret
}
