struct SegmentTree<T> {
   n: usize,
   tree: Vec<T>,
   identity: T,
   op: fn(T, T) -> T,
}
impl<T: Clone + Copy> SegmentTree<T> {
   fn new(_n: usize, identity: T, op: fn(T, T) -> T) -> Self {
      let mut n = 1;
      while n < _n {
         n *= 2;
      }
      let t = vec![identity; 2 * n - 1];
      SegmentTree {
         n: n,
         tree: t,
         identity: identity,
         op: op,
      }
   }
   fn update(&mut self, i: usize, v: T) {
      let mut now = self.n - 1 + i;
      let op = self.op;
      self.tree[now] = v;
      while now != 0 {
         now = (now - 1) / 2;
         self.tree[now] = op(self.tree[2 * now + 1], self.tree[2 * now + 2]);
      }
   }
   fn __get(&self, l: usize, r: usize, ln: usize, rn: usize, now: usize) -> T {
      if rn <= l || r <= ln {
         self.identity
      } else if l <= ln && rn <= r {
         self.tree[now]
      } else {
         let mid = (ln + rn) / 2;
         let op = self.op;
         op(
            self.__get(l, r, ln, mid, now * 2 + 1),
            self.__get(l, r, mid, rn, now * 2 + 2),
         )
      }
   }
   /// range => [l, r)
   fn get(&self, l: usize, r: usize) -> T { self.__get(l, r, 0, self.n, 0) }
}

