struct SegmentTree {
    n: usize,
    xs: Vec<(i64, usize)>,
}

impl SegmentTree {
    pub fn new(n: usize, ini: i64) -> SegmentTree {
        SegmentTree {
            n: n,
            xs: vec![(ini, 0); 2 * n],
        }
    }
    pub fn update(&mut self, i: usize, x: i64) {
        let mut i = i + self.n;
        self.xs[i] = (x, i - self.n);
        i = i / 2;
        while i != 0 {
            self.xs[i] = min(self.xs[2 * i], self.xs[2 * i + 1]);
            i /= 2;
        }
    }
    pub fn get_range_min(&self, l: usize, r: usize) -> (i64, usize) {
        let mut l = l + self.n;
        let mut r = r + self.n;
        let mut res = (1i64 << 50, 0);
        while l < r {
            if l & 1 != 0 {
                res = min(res, self.xs[l]);
                l += 1;
            }
            if r & 1 != 0 {
                r -= 1;
                res = min(res, self.xs[r]);
            }
            l /= 2;
            r /= 2;
        }
        res
    }
    pub fn get(&self, i: usize) -> (i64, usize) {
        let i = i + self.n;
        self.xs[i]
    }
}

fn main() {
    input! {
        n: usize,
        m: usize,
        s: chars,
    }
    let inf = 1i64 << 50;
    let mut segment = SegmentTree::new(18, inf);
    segment.update(n, 0);
    let mut next = vec![0; n + 1];
    for i in (0..n).rev() {
        if s[i] == '1' {
            continue;
        }
        let (min, min_i) = segment.get_range_min(i + 1, i + m + 1);
        // eprintln!("i = {}, min = {}, min_i = {}", i, min, min_i);
        next[i] = min_i;
        segment.update(i, min + 1);
    }
    if next[0] == 0 {
        println!("-1");
    } else {
        let mut p = 0;
        while p != n {
            print!("{} ", next[p] - p);
            p = next[p];
        }
        println!();
    }
}

