fn main() {
    let (N, M): (usize, usize) = {
        let mut line: String = String::new();
        std::io::stdin().read_line(&mut line).unwrap();
        let mut iter = line.split_whitespace();
        (
            iter.next().unwrap().parse().unwrap(),
            iter.next().unwrap().parse().unwrap(),
        )
    };
    let S: Vec<char> = {
        let mut line: String = String::new();
        std::io::stdin().read_line(&mut line).unwrap();
        line.trim().chars().collect()
    };

    const INF: usize = 1_000_000_000_000;
    let mut dp = vec![INF; N + 1];
    dp[N] = 0;
    let mut k = N;
    for i in (0..N).rev() {
        while k > i && (i + M < k || S[k] == '1') {
            k -= 1;
        }
        if S[i] == '0' {
            dp[i] = dp[k] + 1;
        }
    }
    if dp[0] < INF {
        let mut res = vec![];
        let mut j = dp[0] - 1;
        let mut prev = 0;
        for i in 1..(N + 1) {
            if dp[i] == j {
                res.push(i - prev);
                if j > 0 {
                    j -= 1;
                }
                prev = i;
            }
        }
        let ans = res
            .iter()
            .map(|&x| x.to_string())
            .collect::<Vec<_>>()
            .join(" ");
        println!("{}", ans);
    } else {
        println!("-1");
    }
}

