    s.reverse();
    rep_game_over.reverse();
    dbg!(&s);
    let mut ans = vec![];
    let mut i = 0;
    while i < n {
        let beg = i+1;
        let end = cmp::min(i+m+1, s.len());
        dbg!((beg, end));
        let n = rep_game_over[end-1];
        let next = end-1 - n;
        ans.push(next - (beg-1));
