use std::cmp::*;
use std::collections::BinaryHeap;

fn readln() -> Vec<String> {
    let mut buf = String::new();
    std::io::stdin().read_line(&mut buf).unwrap();
    buf.trim_right().split_whitespace().map(|s| s.to_owned()).collect()
}

fn main() {
    const INF: i32 = 1010101010;

    let input: Vec<i32> = readln().iter().map(|s| s.parse().unwrap()).collect();
    let n = input[0];
    let m = input[1];
    let s: Vec<char> = readln()[0].chars().collect();

    let mut steps = vec![INF; (n + 1) as usize];
    let pq = &mut BinaryHeap::<(i32, i32)>::new();
    pq.push((0, n));
    for i in 0..(n + 1) {
        let i = n - i;
        let mut step = INF;
        if s[i as usize] == '0' {
            while let Some(&(val, lim)) = pq.peek() {
                if lim <= i {
                    step = -val + 1;
                    break;
                }
                pq.pop();
            }
        }
        steps[i as usize] = step;
        if step != INF {
            pq.push((-step, i - m));
        }
    }

    if steps[0] == INF {
        println!("-1");
        return;
    }

    let mut pos = 0;
    let mut ans = vec![];
    while pos < n {
        let mut x = pos + 1;
        while steps[pos as usize] != steps[x as usize] + 1 {
            x += 1
        }
        ans.push((x - pos).to_string());
        pos = x;
    }
    println!("{}", ans.join(" "));
}

