#[derive(Eq, PartialEq, Clone, Debug)]
pub struct Rev<T>(pub T);
impl<T: PartialOrd> PartialOrd for Rev<T> {
    fn partial_cmp(&self, other: &Rev<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }
}
impl<T: Ord> Ord for Rev<T> {
    fn cmp(&self, other: &Rev<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

fn solve() {
    let (n,m) = get!(usize, usize);
    let s = get!(String).chars().map(|e| e == '1').collect::<Vec<_>>();

    let mut heap = BinaryHeap::new();
    let mut visited = vec![None; n+1];
    for i in 0..n+1 {
        if s[i] {
            visited[i] = Some(0);
        }
    }
    heap.push(Rev(n));
    visited[n] = Some(n);
    while let Some(Rev(node)) = heap.pop() {
        if node == 0 {
            break;
        }
        for i in 0..m {
            if node < i+1 {
                break;
            }
            let next = node-i-1;
            if visited[next].is_some() {
                continue;
            }
            heap.push(Rev(next));
            visited[next] = Some(node);
        }
    }
    if visited[0].is_none() {
        println!("-1");
        return;
    }
    let mut vec = Vec::new();
    vec.push(0);
    let mut current = 0;
    while let Some(after) = visited[current] {
        vec.push(after);
        if after == n {
            break;
        }
        current = after;
    }
    let res = vec.iter().zip(vec.iter().skip(1)).map(|(&e1, &e2)| e2-e1).collect::<Vec<_>>();
    for e in res {
        print!("{} ", e);
    }
    println!("");
}

