fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize, m: usize,
        s: chars,
    }
    const INF: i64 = 1 << 50;
    let mut dp = vec![INF; n + 1];
    dp[n] = 0;
    let mut st = vec![None; n + 1];
    st[0] = Some((n, n));
    let mut pos = 0;
    for i in (0..n).rev() {
        if s[i] == '1' { continue; }
        if pos == 0 { pos += 1; }
        while let Some((lo, _hi)) = st[pos - 1] {
            if lo <= i + m {
                break;
            }
            pos += 1;
        }
        if st[pos - 1].is_none() {
            puts!("-1\n");
            return;
        }
        let (x, y) = st[pos].unwrap_or((i, i));
        st[pos] = Some((min(x, i), y));
    }
    for i in (1..pos + 1).rev() {
        puts!("{} ", st[i - 1].unwrap().0 - st[i].unwrap().0);
    }
    puts!("\n");
}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

