fn scan<'a, I: Iterator<Item = &'a str>, T: std::str::FromStr>(tokens: &mut I) -> T {
    tokens.next().unwrap().parse().ok().unwrap()
}

fn main() {
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let n: usize = scan(tokens);
    let m: usize = scan(tokens);
    let s: String = scan(tokens);
    let s = s.into_bytes();
    let mut ans = Vec::new();
    let mut p = n;
    loop {
        if p <= m {
            print!("{}", p);
            for x in ans.into_iter().rev() {
                print!(" {}", x);
            }
            println!("");
            return;
        }
        let mut x = m;
        while x > 0 && s[p - x] == b'1' {
            x -= 1;
        }
        if x == 0 {
            println!("-1");
            return;
        }
        ans.push(x);
        p -= x;
    }
}

