  let (n, m) = (vs[0], vs[1]);
  let s: Vec<usize> = lines.next().unwrap().unwrap().chars().map(|x| x as usize - 48).collect();
  let o = find_shortest(&s, n, m);
  match o {
    None => println!("-1"),
    Some(l) => {
