use std::io::{self, BufRead};
use std::cmp::min;

fn find_shortest(s: &[usize], n: usize, m: usize) -> Option<usize> {
  let mut i = 0;
  let mut count = 0;
  while i < n {
    let beg = i + 1;
    let end = min(n + 1, i + m + 1);
    let hurdle = s[beg..end].iter().enumerate().rev().find(|x| *x.1 == 0);
    match hurdle {
      None => return None,
      Some(h) => i += 1 + h.0,
    }
    count += 1;
  }
  Some(count)
}

fn find_smallest(s: &[usize], n: usize, m: usize, c: usize) -> Vec<usize> {
  let mut res: Vec<usize> = vec![];
  let mut i = 0;
  let mut next = 1;
  while res.len() < c {
    if s[i+next] == 0 && n <= i + next + (c - 1 - res.len()) * m {
      res.push(next);
      i += next;
      next = 1;
    } else if m < next {
      match res.pop() {
        None => return vec![],
        Some(j) => {
          next = j;
          i -= next;
        },
      }
    } else {
      next += 1;
    }
  }
  res
}

