fn solve<R: BufRead, W: Write>(reader: R, mut writer: W) {
  let mut _scanner = spella::io::Scanner::new(reader);

  #[allow(unused_macros)]
  macro_rules! scan {
    ($T:ty) => {
      _scanner.next::<$T>().unwrap().unwrap()
    };
    ($($T:ty),+) => {
      ($(scan!($T)),+)
    };
    ($($T:ty),+; $n:expr $(; $m:expr)*) => {{
      (0..$n).map(|_| scan!($($T),+ $(; $m)*)).collect::<Vec<_>>()
    }};
  }

  #[allow(unused_macros)]
  macro_rules! scan_iter {
    ($($T:ty),+; $n:expr) => {
      (0..$n).map(|_| scan!($($T),+))
    };
  }

  #[allow(unused_macros)]
  macro_rules! print {
    ($fmt:expr) => {
      write!(writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      write!(writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! println {
    ($fmt:expr) => {
      writeln!(writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      writeln!(writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprint {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      write!(std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      write!(std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprintln {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      writeln!(std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      writeln!(std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! dbg {
    ($($x:expr),+) => {{
      eprintln!(concat!("[{}:{}] ", $(stringify!($x), " = {:?}; "),+), file!(), line!(), $($x),+);
    }};
  }

  let (n, m) = scan!(usize, usize);
  let s = scan!(ByteString);

  let mut a = vec![];
  {
    let mut cnt = 0;
    for i in 1..n + 1 {
      cnt += 1;
      if s[i].0 == b'0' {
        a.push(cnt);
        cnt = 0;
      }
    }
  }
  dbg!(a);

  let mut a_cumsum = vec![0; a.len() + 1];
  for i in 0..a.len() {
    a_cumsum[i + 1] = a_cumsum[i] + a[i];
  }
  dbg!(a_cumsum);

  fn f<F>(
    memo: &mut [Option<(usize, Vec<usize>)>],
    a_sum: &F,
    a_len: usize,
    m: usize,
    i: usize,
    max: usize,
  ) -> Option<Vec<usize>>
  where
    F: Fn(Range<usize>) -> usize,
  {
    if let Some((max_, ref ans)) = memo[i] {
      if max >= max_ {
        return Some(ans.clone());
      }
    }
    let ans = (|| {
      if i == a_len {
        return Some(vec![]);
      }
      if max == 1 {
        let s = a_sum(i..a_len);
        return if s <= m { Some(vec![s]) } else { None };
      }
      for d in 1..m + 1 {
        let s = a_sum(i..i + d);
        if s > m {
          break;
        }
        if let Some(mut rest) = f(memo, a_sum, a_len, m, i + d, max - 1) {
          rest.push(s);
          return Some(rest);
        }
      }
      None
    })();
    if let Some(ref ans) = ans {
      memo[i] = Some((max, ans.clone()));
    }
    ans
  }

  let mut memo = vec![None; a.len() + 1];
  let mut ng = 0;
  let mut ok = usize::MAX / 2;
  let mut ans = None;
  while ok - ng > 1 {
    let mid = (ng + ok) / 2;
    if let Some(t) = f(
      &mut memo,
      &|r| a_cumsum[r.end] - a_cumsum[r.start],
      a.len(),
      m,
      0,
      mid,
    ) {
      ans = Some(t);
      ok = mid;
    } else {
      ng = mid;
    }
  }

  dbg!(memo);

  if let Some(ans) = ans {
    for x in ans.into_iter().rev() {
      print!("{} ", x);
    }
    println!("");
  } else {
    println!("-1");
  }
}

