fn solve<R: Read, W: Write>(mut sc: Scanner<R>, mut w: BufWriter<W>) {
    let n: usize = sc.read();
    let m: usize = sc.read();
    let s: Vec<char> = sc.read_chars();
    let mut ok = vec![false; n + 1];
    for i in 0..n + 1 {
        ok[i] = s[i] == '0';
    }
    let mut next = vec![usize::max_value(); n + 1];
    let mut queue: BinaryHeap<Reverse<(usize, usize)>> = BinaryHeap::new();
    queue.push(Reverse((0, n)));
    for i in (0..n + 1).rev() {
        while let Some(&Reverse((_, idx))) = queue.peek() {
            if i + m >= idx {
                break;
            }
            queue.pop();
        }
        if ok[i] {
            if let Some(&Reverse((d, idx))) = queue.peek() {
                next[i] = idx;
                queue.push(Reverse((d + 1, i)));
            }
        }
    }
    if next[0] == usize::max_value() {
        writeln!(w, "-1");
    } else {
        let mut cur = 0;
        while cur != n {
            write!(w, "{} ", next[cur] - cur);
            cur = next[cur];
        }
    }
}

fn run() {
    let stdin = io::stdin();
    let stdout = io::stdout();

    let input = stdin.lock();
    let output = BufWriter::new(stdout.lock());

    solve(Scanner::new(input), output);
}

fn main() {
    std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap()
}

