        let mut line = String::new();
        std::io::stdin().read_line(&mut line).unwrap();
        line.chars().collect()
    };

    let mut heap = BinaryHeap::new();
    heap.push((Reverse(0), Reverse(n)));

    let mut next: Vec<usize> = vec![0; n + 1];

    for i in (0..n).rev() {
        if s[i] == '1' { continue; }

        while let Some((Reverse(d), Reverse(j))) = heap.pop() {
            if j - i > m { continue; }

            heap.push((Reverse(d), Reverse(j)));
            heap.push((Reverse(d + 1), Reverse(i)));
            next[i] = j;
            break;
        }
    }

