            if self.G[v][i] != p{
                let n = self.G[v][i];
                self.getP(n, v, d+1);
            }
        }
    }
    pub fn init(&mut self){
        let root = self.root;
        self.getP(root, 0, 0);
        let V = self.depth.len();
        let logN = f64::log2(V as f64) as usize + 2;
        for k in 0..logN-1{
            for v in 1..root+1{
                if self.parent[k][v] == 0{
                    self.parent[k+1][v] = 0;
                }
                else{
                    self.parent[k+1][v] = self.parent[k][self.parent[k][v]];
                }
            }
        }
    }
    fn ft(&self, f:usize, d:usize)->usize{
        let mut now = f;
        let mut now2 = 0;
        let V = self.depth.len();

        let logN = f64::log2(V as f64) as usize + 2;
        let mut v = f;
        for k in 0..logN{
            if (d >> k) & 1 == 1{
                v = self.parent[k][v];
            }
        }

        return v;
    }
    fn lca(&mut self,u:usize, v:usize)->usize{
        let mut u = u;
        let mut v = v;
        if self.depth[u] > self.depth[v]{
            mem::swap(&mut u, &mut v);
        }
        let mut V = self.depth.len();
        let logN = f64::log2(V as f64) as usize + 2;
        for k in 0..logN{
            if ((self.depth[v] - self.depth[u]) >> k)&1 == 1{
                v = self.parent[k][v];
            }
        }
        if u == v{return u;}
        for k in (0..logN).rev(){
            if self.parent[k][u] != self.parent[k][v]{
                u = self.parent[k][u];
                v = self.parent[k][v];
            }
        }
        return self.parent[0][u];
    }
}
fn fast_prime_factor_talbe(ma:usize)->Vec<usize>{
    let mut p = sieve(1001);
    let mut minf = vec![0;ma];
    for j in 0..p.1.len(){
        let P = p.1[j];
        let mut now = P;
        for i in 2..ma{
            if minf[now] ==0{
                minf[now] = P;
            }
            now+=P;
            if now>=ma{
                break;
            }
        }
    }
    return minf;
